window.VPT_DATA = {"dataAsOf":"2026-09-21","categories":[{"id":"client","label":"Client and case management"},{"id":"investigation","label":"Investigation and records requests"},{"id":"insurance","label":"Insurance claims and correspondence"},{"id":"medical","label":"Medical records and bills"},{"id":"liens","label":"Liens, Medicare, Medicaid and benefit recovery"},{"id":"demand","label":"Demands, negotiation and ADR"},{"id":"settlement","label":"Settlement documents and disbursement"},{"id":"pleadings","label":"Pleadings and service"},{"id":"discovery","label":"Discovery"},{"id":"motions","label":"Motions and orders"},{"id":"trial","label":"Pretrial and trial"},{"id":"post-trial-appeals","label":"Post-trial, judgment and appeals"}],"templates":[{"title":"Case Chronology","slug":"timeline","command":"/timeline","category":"client","category_label":"Client and case management","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Case Chronology for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/timeline.docx","reasoning":"../../reasoning/timeline.md","path":"templates/client/timeline.md","docx_path":"templates/client/docx/timeline.docx","reasoning_path":"reasoning/timeline.md","field_count":15,"md":"---\ntitle: \"Case Chronology\"\nslug: \"timeline\"\ncommand: \"/timeline\"\ncategory: \"client\"\ncategory_label: \"Client and case management\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Case Chronology for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/timeline.docx\"\nreasoning: \"../../reasoning/timeline.md\"\n---\n# Case Chronology\nMatter: [CASE NAME AND NUMBER]\nPrepared for: [AUTHORIZED RECIPIENT]    As of: [DATE]\nScope: [INCIDENT, TREATMENT, CLAIMS, PROCEDURE OR SPECIFIED COMBINATION]\n## Chronological events\n[EVENT DATE OR SUPPORTED DATE RANGE] — [EVENT]\nCategory: [INCIDENT / TREATMENT / CLAIM / PROCEDURE / OTHER].\nSource: [FILE ID, TITLE, DATE AND EXACT PAGE OR STRUCTURED RECORD REFERENCE].\nStatus: [DOCUMENTED FACT / ATTRIBUTED REPORT / DISPUTED FACT / INFERENCE CLEARLY LABELED].\nRelevance: [CONCISE CASE-SPECIFIC CONNECTION WITHOUT ADDING UNSOURCED FACTS].\n[REPEAT IN DATE ORDER. KEEP DOCUMENT CREATION DATE DISTINCT FROM THE DATE OF THE EVENT.]\n## Conflicts and gaps\n[CONFLICTING DATES OR ACCOUNTS WITH BOTH SOURCES. UNKNOWN DATES REMAIN UNKNOWN. IDENTIFY MISSING MATERIAL WITHOUT TREATING ABSENCE AS PROOF OF NONOCCURRENCE.]\n## Prospective dates if included\n[IDENTIFY EACH FUTURE DATE AS COURT-ORDERED, RULE-CALCULATED, AGREED OR PROPOSED, WITH THE ACTUAL SOURCE AND VERIFIED TRIGGER. DO NOT DESCRIBE A PROPOSED DATE AS AN ENTERED DEADLINE.]\nReviewer: [NAME]    Review date: [ACTUAL DATE]\n"},{"title":"Case Status Update","slug":"status","command":"/status","category":"client","category_label":"Client and case management","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Routine Virginia PI client communication; factual update, not a substitute for immediate deadline or offer communication.","docx":"docx/status.docx","reasoning":"../../reasoning/status.md","path":"templates/client/status.md","docx_path":"templates/client/docx/status.docx","reasoning_path":"reasoning/status.md","field_count":21,"md":"---\ntitle: \"Case Status Update\"\nslug: \"status\"\ncommand: \"/status\"\ncategory: \"client\"\ncategory_label: \"Client and case management\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Routine Virginia PI client communication; factual update, not a substitute for immediate deadline or offer communication.\"\ndocx: \"docx/status.docx\"\nreasoning: \"../../reasoning/status.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Case Status Update - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nThis is an update on [MATTER] as of [DATE]. The case is currently at [PROCEDURAL OR CLAIM STAGE].\nSince our last update, [VERIFIED DEVELOPMENTS WITH DATES]. Their practical effect is [EXPLANATION]. Issues still unresolved are [ISSUES AND WHAT WILL RESOLVE THEM].\nThe next steps are [ACTION, RESPONSIBLE PERSON AND EXPECTED TIMING]. The next confirmed deadline or event is [DATE, EVENT AND SOURCE]. An estimate is identified as an estimate rather than a court-set date.\nWe need the following from you: [SPECIFIC INFORMATION OR DECISION, WHY IT MATTERS AND RESPONSE DATE]. Please promptly forward any new legal papers, insurer communications or treatment information.\n[DESCRIBE ANY ACTUAL MATERIAL SETTLEMENT OFFER, RESPONSE DEADLINE AND DISCUSSION NEEDED, OR OMIT IF NONE]. No settlement decision will be made without the authority you provide. Please contact [PERSON AND METHOD] with questions.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Client Advice About Requested Medical Examination","slug":"ime-advice","command":"/ime-advice","category":"client","category_label":"Client and case management","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Virginia Circuit Court party examination under Rule 4:10 or an actual agreement; not an insurer’s unilateral unrestricted examination demand.","docx":"docx/ime-advice.docx","reasoning":"../../reasoning/ime-advice.md","path":"templates/client/ime-advice.md","docx_path":"templates/client/docx/ime-advice.docx","reasoning_path":"reasoning/ime-advice.md","field_count":19,"md":"---\ntitle: \"Client Advice About Requested Medical Examination\"\nslug: \"ime-advice\"\ncommand: \"/ime-advice\"\ncategory: \"client\"\ncategory_label: \"Client and case management\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia Circuit Court party examination under Rule 4:10 or an actual agreement; not an insurer’s unilateral unrestricted examination demand.\"\ndocx: \"docx/ime-advice.docx\"\nreasoning: \"../../reasoning/ime-advice.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Client Advice About Requested Medical Examination - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nThe other side has [REQUESTED / OBTAINED AN ORDER FOR] an examination concerning [CONDITION] by [EXAMINER] on [DATE] at [LOCATION]. The governing document is [ACTUAL REQUEST, AGREEMENT OR ORDER]. The confirmed scope and conditions are [DETAILS]. An unapproved proposal remains a proposal.\nThe examiner is evaluating you for the litigation and is not providing your ordinary treatment. Answer truthfully, describe symptoms and limitations accurately, and distinguish what you remember from what you do not know. Do not exaggerate or minimize symptoms.\nBefore the appointment, contact us about [MEDICAL NEEDS, LANGUAGE OR ACCESSIBILITY ARRANGEMENTS, TRANSPORTATION AND DOCUMENTS]. Continue following your treating clinician’s instructions; do not change medication or treatment for the examination without appropriate medical advice.\nAttendance, recording, observers and testing must follow the actual agreement or order. Do not assume you may record or bring an observer without authorization. If an issue arises outside the confirmed arrangements, contact [ATTORNEY AND NUMBER] promptly.\nAfterward, tell us the actual time spent, people present, tests performed and any concerns. We will address the report and follow-up under the applicable procedure.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Client Consent to a Specific Testimonial or Case Description","slug":"marketing-consent","command":"/marketing-consent","category":"client","category_label":"Client and case management","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Optional, limited permission for a particular firm communication; no general confidentiality waiver.","docx":"docx/marketing-consent.docx","reasoning":"../../reasoning/marketing-consent.md","path":"templates/client/marketing-consent.md","docx_path":"templates/client/docx/marketing-consent.docx","reasoning_path":"reasoning/marketing-consent.md","field_count":13,"md":"---\ntitle: \"Client Consent to a Specific Testimonial or Case Description\"\nslug: \"marketing-consent\"\ncommand: \"/marketing-consent\"\ncategory: \"client\"\ncategory_label: \"Client and case management\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Optional, limited permission for a particular firm communication; no general confidentiality waiver.\"\ndocx: \"docx/marketing-consent.docx\"\nreasoning: \"../../reasoning/marketing-consent.md\"\n---\n# CLIENT CONSENT TO A SPECIFIC TESTIMONIAL OR CASE DESCRIPTION\nClient: [NAME]    Firm: [FIRM]\nMatter: [REFERENCE]\n## Material and permitted use\nThe exact testimonial, photograph or case description proposed for use is [ATTACHMENT OR FULL APPROVED TEXT]. The information that would identify the client is [SPECIFIC NAME, IMAGE OR OTHER DETAILS]. Approved channels and duration are [SPECIFIC WEBSITE, PUBLICATION OR PLATFORM AND DATES]. No additional confidential details are authorized.\nThe material may become public, searchable and copied by others. Any settlement confidentiality, court restriction, protected third-party information or other limit is [IDENTIFIED LIMIT AND REQUIRED PERMISSION]. Publication may occur only if those restrictions are satisfied.\n## Voluntary choice\nConsent is optional. Refusing it does not affect legal services, fees, settlement advice or disbursement. Any compensation or benefit for the testimonial is [ACTUAL TERMS OR NONE]; the published communication must remain truthful and comply with applicable disclosure requirements.\nThe client may withdraw permission for future use by writing to [CONTACT]. The firm will cease future uses under its control as described in [REMOVAL PROCESS], but cannot promise retrieval of copies already distributed or made by third parties. This consent releases no legal claim and guarantees no result to another client.\n## Agreement\nClient choice: [CONSENT TO THE SPECIFIED MATERIAL AND USE OR DECLINE]\nClient signature: ____________________    Date: [DATE]\nAttorney name: [NAME CONFIRMING SCOPE]\n"},{"title":"Client File Retention and Disposition Instructions","slug":"file-retention","command":"/file-retention","category":"client","category_label":"Client and case management","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Client-facing retention/disposition instructions for a closed matter; no automatic destruction authorization.","docx":"docx/file-retention.docx","reasoning":"../../reasoning/file-retention.md","path":"templates/client/file-retention.md","docx_path":"templates/client/docx/file-retention.docx","reasoning_path":"reasoning/file-retention.md","field_count":13,"md":"---\ntitle: \"Client File Retention and Disposition Instructions\"\nslug: \"file-retention\"\ncommand: \"/file-retention\"\ncategory: \"client\"\ncategory_label: \"Client and case management\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Client-facing retention/disposition instructions for a closed matter; no automatic destruction authorization.\"\ndocx: \"docx/file-retention.docx\"\nreasoning: \"../../reasoning/file-retention.md\"\n---\n# CLIENT FILE RETENTION AND DISPOSITION INSTRUCTIONS\nClient: [NAME]    Matter: [MATTER]\nClosing date: [DATE]    Firm contact: [CONTACT]\n## Return and access\nThe original documents and property to be returned are [ITEMIZED LIST]. The delivery or collection arrangements are [DETAILS]. Available file copies and the process for requesting them are [DETAILS]. Unpaid fees do not justify withholding materials the client is entitled to receive.\n## Retention plan\nThe firm proposes to retain [DEFINED FILE MATERIAL] until no earlier than [REVIEWED RETENTION DATE]. This date is a firm plan, not a statement that every Virginia client file has the same statutory retention period. Originals, trust records, continuing legal obligations and any actual or reasonably anticipated claim may require separate or longer retention.\nBefore any destruction, the firm will review the file for client property, continuing needs and legal holds. Confidential material approved for destruction will be disposed of securely. The planned notice and response process is [SPECIFIC TERMS].\n## Client instructions\nPlease select and describe your instructions: [RETURN OR TRANSFER TO NAMED RECIPIENT] or [CONSENT TO THE DESCRIBED RETENTION AND LATER SECURE DISPOSITION]. Special exclusions or documents to retain are [LIST]. These instructions do not override a legal preservation obligation or waive a claim against the firm.\n## Agreement\nClient signature: ____________________    Date: [DATE]\nCurrent contact details: [CONTACT]\nAttorney name: [NAME ACKNOWLEDGING INSTRUCTIONS]\n"},{"title":"Conflict Disclosure and Consent","slug":"conflict","command":"/conflict","category":"client","category_label":"Client and case management","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Matter-specific disclosure for a consentable concurrent conflict under Virginia Rule 1.7.","docx":"docx/conflict.docx","reasoning":"../../reasoning/conflict.md","path":"templates/client/conflict.md","docx_path":"templates/client/docx/conflict.docx","reasoning_path":"reasoning/conflict.md","field_count":13,"md":"---\ntitle: \"Conflict Disclosure and Consent\"\nslug: \"conflict\"\ncommand: \"/conflict\"\ncategory: \"client\"\ncategory_label: \"Client and case management\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Matter-specific disclosure for a consentable concurrent conflict under Virginia Rule 1.7.\"\ndocx: \"docx/conflict.docx\"\nreasoning: \"../../reasoning/conflict.md\"\n---\n# CONFLICT DISCLOSURE AND CONSENT\nClient: [NAME]    Matter: [SCOPE]\nLawyer or firm: [NAME]\n## Conflict disclosed\nThe affected clients, other responsibilities or personal interests are [SPECIFIC IDENTITIES AND RELATIONSHIPS TO THE EXTENT LAWFULLY DISCLOSABLE]. The conflict arises because [CONCRETE ADVERSE INTEREST OR MATERIAL LIMITATION]. Its reasonably foreseeable effects on this representation are [SPECIFIC RISKS].\nAvailable alternatives include [SEPARATE COUNSEL, LIMITED SCOPE OR OTHER REAL OPTIONS]. Potential effects on confidentiality, privilege, allocation of recovery, negotiation and future withdrawal are [MATTER-SPECIFIC EXPLANATION]. Any proposed limits or safeguards are [ACTUAL TERMS].\n## Conditions for proceeding\nCounsel's assessment of competent and diligent representation is [REASONED ASSESSMENT]. The proposed representation must be lawful and cannot involve one represented client asserting a claim against another represented client in the same proceeding. If the conflict cannot lawfully be consented to, this document does not permit the representation.\nThe client may consult independent counsel before deciding. Questions and the consultation provided are [DESCRIPTION AND DATE]. Each affected client must separately consent after the required consultation; another client's signature is not inferred.\n## Agreement\nHaving considered the disclosed risks and alternatives, my decision is [CONSENT TO THIS SPECIFIC REPRESENTATION OR DECLINE]. Any agreed limitation is [TERMS]. This is not a waiver of undisclosed future conflicts or malpractice claims.\nClient signature: ____________________    Date: [DATE]\nAttorney name: [NAME]    Signature: ____________________    Date: [DATE]\n"},{"title":"File Closing Letter","slug":"closing","command":"/closing","category":"client","category_label":"Client and case management","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Closing an actually completed adult PI engagement; not terminating ongoing litigation without court leave.","docx":"docx/closing.docx","reasoning":"../../reasoning/closing.md","path":"templates/client/closing.md","docx_path":"templates/client/docx/closing.docx","reasoning_path":"reasoning/closing.md","field_count":22,"md":"---\ntitle: \"File Closing Letter\"\nslug: \"closing\"\ncommand: \"/closing\"\ncategory: \"client\"\ncategory_label: \"Client and case management\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Closing an actually completed adult PI engagement; not terminating ongoing litigation without court leave.\"\ndocx: \"docx/closing.docx\"\nreasoning: \"../../reasoning/closing.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: File Closing Letter - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nOur work on [DEFINED MATTER] has concluded because [ACTUAL RESOLUTION AND DATE]. The result is [ACCURATE OUTCOME]. Our representation for that agreed matter ends as of [DATE], subject to any remaining obligations stated below.\nThe documents for your records are [JUDGMENT, RELEASE, AGREEMENT, FINAL ACCOUNTING OR OTHER ACTUAL MATERIALS]. Funds and remaining obligations stand as follows: [ACTUAL PAYMENT, TRUST HOLDBACK, LIEN OR OTHER STATUS]. Any continuing work retained by the Firm is [SPECIFIC WORK OR NONE].\nPlease observe these remaining obligations or deadlines: [VERIFIED ITEMS AND RESPONSIBLE PERSON]. Any appeal or separate matter is [ACTUAL SCOPE AND DEADLINE ADVICE]. This letter does not imply that an unperformed payment or lien release has occurred.\nYour original documents are [RETURNED OR AVAILABLE BY STATED METHOD]. You may request the file materials to which you are entitled. Our applicable retention arrangements are [ACTUAL POLICY AND ANY AGREED NOTICE PROCESS]; no separate destruction authorization is created by this letter.\nThank you for allowing us to assist you. Contact [PERSON] if you need copies or clarification of the resolution.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Final Limitations Warning to Client","slug":"sol-final","command":"/sol-final","category":"client","category_label":"Client and case management","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Urgent final reminder based on independently verified deadlines and actual representation status.","docx":"docx/sol-final.docx","reasoning":"../../reasoning/sol-final.md","path":"templates/client/sol-final.md","docx_path":"templates/client/docx/sol-final.docx","reasoning_path":"reasoning/sol-final.md","field_count":22,"md":"---\ntitle: \"Final Limitations Warning to Client\"\nslug: \"sol-final\"\ncommand: \"/sol-final\"\ncategory: \"client\"\ncategory_label: \"Client and case management\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Urgent final reminder based on independently verified deadlines and actual representation status.\"\ndocx: \"docx/sol-final.docx\"\nreasoning: \"../../reasoning/sol-final.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[CLIENT]\n[RECIPIENT ADDRESS]\nRe: [MATTER] — action needed by [VERIFIED DATE]\nDear [RECIPIENT NAME]:\nWe write again regarding the approaching deadline for [SPECIFIC CLAIM OR REQUIRED ACTION]. Based on [VERIFIED FACTS AND APPLICABLE LAW], the deadline currently identified is [DATE AND ANY RELEVANT TIME]. Other claims, parties or notice requirements may have different deadlines: [SPECIFIC KNOWN ITEMS].\nOur earlier notices were sent on [ACTUAL DATES AND METHODS]. We still need [SPECIFIC INSTRUCTIONS, DOCUMENTS OR ACTION] by [PRACTICAL RESPONSE DATE] to address [NEXT STEP]. Negotiations and this correspondence do not themselves stop a limitations period.\nOur current representation and filing status is [ACCURATE SCOPE, WHETHER AN ACTION HAS BEEN FILED, AND ANY COURT-APPROVED WITHDRAWAL STATUS]. If this firm will not be filing or continuing the identified claim, [STATE THE ACTUAL TERMINATION OR DECLINATION AND PROMPT INSTRUCTIONS TO SEEK OTHER COUNSEL]. A failure to act in time may permanently prevent recovery.\nPlease contact [ATTORNEY AND DIRECT CONTACT] immediately. We can arrange prompt transfer of materials to replacement counsel as appropriate. This warning does not itself withdraw an appearance or extend any legal deadline.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Limitations Deadline Warning to Client","slug":"sol-warning","command":"/sol-warning","category":"client","category_label":"Client and case management","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Fact-specific urgent deadline communication; no automated two-year assumption or withdrawal.","docx":"docx/sol-warning.docx","reasoning":"../../reasoning/sol-warning.md","path":"templates/client/sol-warning.md","docx_path":"templates/client/docx/sol-warning.docx","reasoning_path":"reasoning/sol-warning.md","field_count":22,"md":"---\ntitle: \"Limitations Deadline Warning to Client\"\nslug: \"sol-warning\"\ncommand: \"/sol-warning\"\ncategory: \"client\"\ncategory_label: \"Client and case management\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Fact-specific urgent deadline communication; no automated two-year assumption or withdrawal.\"\ndocx: \"docx/sol-warning.docx\"\nreasoning: \"../../reasoning/sol-warning.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Limitations Deadline Warning to Client - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nA time limit requires your prompt attention in [MATTER]. Based on [VERIFIED FACTS AND GOVERNING PROVISION], the deadline presently identified for [SPECIFIC FILING OR NOTICE] is [DATE AND ANY RELEVANT TIME]. The date depends on [IDENTIFIED ASSUMPTIONS OR UNRESOLVED FACTS]. Other claims or required notices may have different deadlines.\nOur current representation and responsibility for this action are [PRECISE STATUS]. The action we need from you is [DECISION, INFORMATION OR SIGNATURE] by [REASONABLE RESPONSE DATE], so that [NEXT STEP] can be addressed before the legal deadline.\nIf the applicable deadline is missed, the claim may be barred. Negotiations, an insurer’s investigation or a request for records do not by themselves establish an extension. We will rely on an extension only after its legal effectiveness has been verified.\nPlease contact [ATTORNEY AND DIRECT NUMBER] promptly. [EXPLAIN THE ACTUAL ESCALATION OR ALTERNATIVE-COUNSEL ARRANGEMENT]. This letter does not by itself terminate an existing representation or transfer an undertaken filing duty to you.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Nonengagement Letter","slug":"declination","command":"/declination","category":"client","category_label":"Client and case management","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Prospective adult client where representation has not begun; not withdrawal from an existing case.","docx":"docx/declination.docx","reasoning":"../../reasoning/declination.md","path":"templates/client/declination.md","docx_path":"templates/client/docx/declination.docx","reasoning_path":"reasoning/declination.md","field_count":17,"md":"---\ntitle: \"Nonengagement Letter\"\nslug: \"declination\"\ncommand: \"/declination\"\ncategory: \"client\"\ncategory_label: \"Client and case management\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Prospective adult client where representation has not begun; not withdrawal from an existing case.\"\ndocx: \"docx/declination.docx\"\nreasoning: \"../../reasoning/declination.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Nonengagement Letter - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nThank you for contacting us regarding [MATTER]. After [ACTUAL EXTENT OF REVIEW], we will not undertake representation in this matter. [ACCURATE EXPLANATION, IF ONE IS TO BE PROVIDED]. This decision is not a determination of the merits of your claim.\nWe will not file a lawsuit, send a claim notice, appear at a hearing or take other action for you in this matter. Please promptly consult another lawyer if you wish to pursue it. Filing and notice deadlines may apply, and continuing discussions or insurance negotiations may not protect them.\n[IDENTIFY ANY VERIFIED DEADLINE, ITS BASIS AND URGENCY; OTHERWISE STATE CLEARLY THAT THE FIRM HAS NOT DETERMINED ALL APPLICABLE DEADLINES].\nThe materials you supplied are [RETURNED, AVAILABLE FOR RETURN OR OTHERWISE HANDLED AS ACTUALLY AGREED]. Please preserve relevant evidence and keep copies of any papers or notices. Contact [PERSON] about return of your materials.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Personal Injury Contingent Fee Agreement","slug":"retainer","command":"/retainer","category":"client","category_label":"Client and case management","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":2,"scope":"Ordinary adult Virginia PI contingent representation; no minors, class action, government-fee cap or outside-counsel split assumed.","docx":"docx/retainer.docx","reasoning":"../../reasoning/retainer.md","path":"templates/client/retainer.md","docx_path":"templates/client/docx/retainer.docx","reasoning_path":"reasoning/retainer.md","field_count":20,"md":"---\ntitle: \"Personal Injury Contingent Fee Agreement\"\nslug: \"retainer\"\ncommand: \"/retainer\"\ncategory: \"client\"\ncategory_label: \"Client and case management\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 2\nscope: \"Ordinary adult Virginia PI contingent representation; no minors, class action, government-fee cap or outside-counsel split assumed.\"\ndocx: \"docx/retainer.docx\"\nreasoning: \"../../reasoning/retainer.md\"\n---\n# PERSONAL INJURY CONTINGENT FEE AGREEMENT\nClient: [FULL NAME]    Firm: [FIRM NAME]\nMatter: [INCIDENT, DATE, PARTIES AND CLAIMS]\n## Services and scope\nThe Firm will represent the Client in [DEFINED SERVICES AND STAGES]. The following are excluded unless separately agreed in writing: [EXCLUSIONS]. Appeals are [INCLUDED ON STATED TERMS OR EXCLUDED]. The Firm makes no promise of a particular recovery.\n## Fee calculation\nThe fee is contingent on a recovery. The applicable rates are: settlement before [DEFINED STAGE], [PERCENT]%; after [DEFINED STAGE], [PERCENT]%; trial, [PERCENT]%; and any included appeal, [PERCENT]%. Only the rate applicable to the recovery stage applies; rates are not added together.\nThe fee base is [PRECISE DEFINITION OF RECOVERY]. Litigation and other expenses are deducted [BEFORE OR AFTER] calculating the contingent fee. The agreed calculation is [FORMULA AND ILLUSTRATIVE EXAMPLE USING THE AGREED RATES]. If there is no recovery, no contingent attorney fee is due.\n## Expenses and third-party claims\nExpenses include [AGREED CATEGORIES]. They will be advanced or paid by [PARTY] on [TERMS]. Responsibility for unpaid expenses if no recovery occurs is [EXPRESS AGREEMENT]. Approval requirements for major expenses are [TERMS]. Liens, reimbursement claims and unpaid treatment charges will be evaluated separately; they are not attorney fees and can reduce the Client’s net recovery.\n## Decisions and communication\nThe Client decides whether to settle. The Firm will explain material offers and developments. The Client will provide truthful information, preserve relevant evidence and promptly forward legal papers. The Firm will protect confidential information as required by applicable duties.\n## Completion and termination\nAt the conclusion of the matter, the Firm will provide a written outcome statement and, if money is recovered, a statement explaining the Client’s remittance and its calculation.\nThe Client may discharge the Firm. Withdrawal by the Firm is subject to applicable duties and any required court permission. Any fee or expense claim upon early termination must be lawful and reasonable; no unearned advanced fee is nonrefundable. The applicable arrangements are [LAWFUL TERMS]. Client property and file materials will be handled under applicable duties.\n## Agreement\nQuestions about scope, alternatives, rates, expenses and termination have been addressed as follows: [DETAILS OR OPEN ITEMS]. Any association or division of fees with outside counsel requires the disclosures and consent applicable to that arrangement. Changes to these terms will be documented in writing.\nClient signature: ____________________    Date: [DATE]\nPrinted name and capacity: [NAME AND CAPACITY]\nFirm signature: ____________________    Date: [DATE]\nAttorney name: [NAME]\n"},{"title":"Personal Injury Intake Questionnaire","slug":"intake","command":"/intake","category":"client","category_label":"Client and case management","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Prospective Virginia adult PI client; intake and conflict/deadline triage, not a fee agreement.","docx":"docx/intake.docx","reasoning":"../../reasoning/intake.md","path":"templates/client/intake.md","docx_path":"templates/client/docx/intake.docx","reasoning_path":"reasoning/intake.md","field_count":9,"md":"---\ntitle: \"Personal Injury Intake Questionnaire\"\nslug: \"intake\"\ncommand: \"/intake\"\ncategory: \"client\"\ncategory_label: \"Client and case management\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Prospective Virginia adult PI client; intake and conflict/deadline triage, not a fee agreement.\"\ndocx: \"docx/intake.docx\"\nreasoning: \"../../reasoning/intake.md\"\n---\n# PERSONAL INJURY INTAKE QUESTIONNAIRE\nClient or prospective client: [NAME]    Interview date: [DATE]\nCompleted by: [NAME AND ROLE]    Safe contact method: [METHOD]\n## Contact and representation\nPreferred name, mailing address, phone and email: [DETAILS]\nPeople or organizations involved, including employers and insurers: [NAMES]\nOther lawyers consulted or retained about this incident: [DETAILS]\n## Incident and deadlines\nDate, time and place: [DETAILS]\nWhat happened, in your own words: [ACCOUNT; DISTINGUISH OBSERVED FACTS FROM WHAT OTHERS SAID]\nAny lawsuit, government claim, hearing, notice or response deadline already received: [DETAILS AND COPIES]\n## Injuries and treatment\nSymptoms, injuries, providers, treatment dates and relevant prior conditions: [DETAILS]\nHealth coverage, Medicare, Medicaid or workers’ compensation involvement: [DETAILS]\n## Losses and evidence\nMissed work, lost income, expenses and property damage: [DETAILS]\nWitnesses, photographs, messages, video, reports and available insurance information: [IDENTIFY SOURCES AND LOCATIONS]\n## Goals and immediate needs\nMain concerns and requested outcome: [DETAILS]\nAccessibility, language, transportation or communication needs: [DETAILS]\nPreserve potentially relevant material. Use the firm’s secure process for records and sensitive identifiers. Completing this questionnaire does not itself promise that the firm will undertake representation; counsel will clarify whether and on what terms a relationship exists.\n"},{"title":"Representation Confirmation to Client","slug":"representation","command":"/representation","category":"client","category_label":"Client and case management","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Client-facing confirmation after an actual Virginia PI engagement; not notice to an insurer.","docx":"docx/representation.docx","reasoning":"../../reasoning/representation.md","path":"templates/client/representation.md","docx_path":"templates/client/docx/representation.docx","reasoning_path":"reasoning/representation.md","field_count":19,"md":"---\ntitle: \"Representation Confirmation to Client\"\nslug: \"representation\"\ncommand: \"/representation\"\ncategory: \"client\"\ncategory_label: \"Client and case management\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Client-facing confirmation after an actual Virginia PI engagement; not notice to an insurer.\"\ndocx: \"docx/representation.docx\"\nreasoning: \"../../reasoning/representation.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Representation Confirmation to Client - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe confirm our representation of [CLIENT] concerning [PRECISE MATTER] under the engagement agreement dated [DATE]. The agreed scope is [INCLUDED WORK]. Work outside that scope, including [ACTUAL EXCLUSIONS], requires a separate discussion and agreement.\nYour primary contact is [NAME, ROLE AND CONTACT DETAILS]. We will keep you informed of material developments and settlement proposals. Please tell us promptly about changed contact details, treatment, new documents, insurer communications and any papers served on you.\nOur immediate next steps are [ACTIONS, RESPONSIBLE PERSONS AND TARGET DATES]. Please provide [SPECIFIC REQUESTED ITEMS] by [DATE OR COORDINATED ARRANGEMENT]. Preserve relevant records, messages, photographs and other evidence.\nThe fee and expense terms remain those in the engagement agreement. This letter does not change them or guarantee a result. You decide whether to accept a settlement after discussing its terms with us.\nPlease contact us if this description differs from your understanding or you have questions about the next steps.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Authorized Prior Claims History Request","slug":"prior-claims","command":"/prior-claims","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Request to a verified claims-data custodian or insurer through a lawful individual-access or authorized-disclosure route.","docx":"docx/prior-claims.docx","reasoning":"../../reasoning/prior-claims.md","path":"templates/investigation/prior-claims.md","docx_path":"templates/investigation/docx/prior-claims.docx","reasoning_path":"reasoning/prior-claims.md","field_count":15,"md":"---\ntitle: \"Authorized Prior Claims History Request\"\nslug: \"prior-claims\"\ncommand: \"/prior-claims\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Request to a verified claims-data custodian or insurer through a lawful individual-access or authorized-disclosure route.\"\ndocx: \"docx/prior-claims.docx\"\nreasoning: \"../../reasoning/prior-claims.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Authorized Prior Claims History Request — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nWe represent [INDIVIDUAL], whose signed authorization is [ENCLOSED / VERIFIED REFERENCE]. We request the claims-history information that your applicable individual-access procedure permits concerning that person for [RELEVANT PERIOD AND CLAIM CATEGORY].\nPlease provide [SPECIFIC REPORT OR RECORDS], identify the data source, dates reported, claim numbers, carriers and disposition fields available, and explain any codes necessary to understand the report. We do not seek unrelated persons’ data or access outside the authorization.\nPlease identify the lawful identity-verification steps and secure submission channel. Sensitive identifiers will be supplied through that channel rather than included in ordinary correspondence. If the report is maintained by a different custodian or under a different access procedure, please identify the appropriate route without disclosing unauthorized information.\nPlease explain how the individual may dispute inaccurate or incomplete information and distinguish a reported allegation from a verified adjudication or payment. Any fee above $[AUTHORIZED CAP] requires approval before work proceeds. This is an access request, not a subpoena or an assertion of unrestricted access to a proprietary database.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Client Evidence and Social Media Preservation Advisory","slug":"socialmedia-client","command":"/socialmedia-client","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Client-side preservation advice for reasonably foreseeable Virginia PI litigation.","docx":"docx/socialmedia-client.docx","reasoning":"../../reasoning/socialmedia-client.md","path":"templates/investigation/socialmedia-client.md","docx_path":"templates/investigation/docx/socialmedia-client.docx","reasoning_path":"reasoning/socialmedia-client.md","field_count":16,"md":"---\ntitle: \"Client Evidence and Social Media Preservation Advisory\"\nslug: \"socialmedia-client\"\ncommand: \"/socialmedia-client\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Client-side preservation advice for reasonably foreseeable Virginia PI litigation.\"\ndocx: \"docx/socialmedia-client.docx\"\nreasoning: \"../../reasoning/socialmedia-client.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Client Evidence and Social Media Preservation Advisory - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nPlease preserve information that may relate to [INCIDENT OR CLAIM], including relevant social-media posts, comments, photographs, videos, messages and account records for [REASONABLE SCOPE AND PERIOD]. The same request applies to relevant material on phones, computers, cloud storage and other accounts within your control.\nDo not delete, edit, overwrite, conceal or ask someone else to remove relevant material. If an account or app automatically deletes messages, contact us promptly so preservation can be arranged without changing or losing existing evidence. Preserve original files and available dates and metadata.\nPlease tell us about [IDENTIFIED ACCOUNTS OR DEVICES], any lost material and any relevant content held by someone else. Use [SECURE METHOD] to coordinate collection; do not send passwords or grant anyone access without an agreed secure process.\nDiscuss proposed privacy-setting changes with us before acting. Do not assume private posts cannot be discoverable. Avoid discussing the case publicly, and do not contact witnesses or opposing parties in a way that could affect evidence.\nThis instruction is to preserve evidence, including material that may be unfavorable. Contact [ATTORNEY] if you are unsure whether an item should be retained.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"DMV Driver and Vehicle Records Request","slug":"dmv-records","command":"/dmv-records","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Cover request accompanying current DMV requirements; not a replacement for CRD-93 or authorization.","docx":"docx/dmv-records.docx","reasoning":"../../reasoning/dmv-records.md","path":"templates/investigation/dmv-records.md","docx_path":"templates/investigation/docx/dmv-records.docx","reasoning_path":"reasoning/dmv-records.md","field_count":22,"md":"---\ntitle: \"DMV Driver and Vehicle Records Request\"\nslug: \"dmv-records\"\ncommand: \"/dmv-records\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Cover request accompanying current DMV requirements; not a replacement for CRD-93 or authorization.\"\ndocx: \"docx/dmv-records.docx\"\nreasoning: \"../../reasoning/dmv-records.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[DMV CUSTOMER RECORDS UNIT]\n[RECIPIENT ADDRESS]\nRe: [SUBJECT NAME OR VEHICLE] — [MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nWe represent [CLIENT] in connection with [IDENTIFIED MATTER]. Please provide [SPECIFIC DRIVER TRANSCRIPT OR VEHICLE RECORD], limited to [RELEVANT PERIOD AND RECORD TYPE]. Subject and vehicle identifiers are supplied in [ENCLOSED CURRENT DMV FORM OR SECURE ATTACHMENT].\nOur authority to request these records is [SPECIFIC BASIS UNDER THE CURRENT VERSION OF VIRGINIA CODE § 46.2-208 AND ANY APPLICABLE FEDERAL REQUIREMENT]. The intended use is [PRECISE AUTHORIZED PURPOSE]. Enclosed are [ACTUALLY COMPLETED CRD-93, CLIENT AUTHORIZATION, CREDENTIALS AND REQUIRED FEE].\nIf we seek crash-related vehicle ownership information, the involved vehicle and incident are [IDENTIFIERS AND INCIDENT DETAILS]. That request is distinct from a request for another person's driving history.\nPlease supply [CERTIFIED OR ORDINARY COPY, AS NEEDED] through [SECURE DELIVERY METHOD]. If additional proof of authority is required, please identify it before processing. Sensitive identifiers are supplied only through the agency's accepted secure process.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Employee Safety and Exposure Records Request","slug":"osha-employer","command":"/osha-employer","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Authorized employee request to an employer for covered OSHA/VOSH records; separate voluntary requests from regulatory access rights.","docx":"docx/osha-employer.docx","reasoning":"../../reasoning/osha-employer.md","path":"templates/investigation/osha-employer.md","docx_path":"templates/investigation/docx/osha-employer.docx","reasoning_path":"reasoning/osha-employer.md","field_count":18,"md":"---\ntitle: \"Employee Safety and Exposure Records Request\"\nslug: \"osha-employer\"\ncommand: \"/osha-employer\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Authorized employee request to an employer for covered OSHA/VOSH records; separate voluntary requests from regulatory access rights.\"\ndocx: \"docx/osha-employer.docx\"\nreasoning: \"../../reasoning/osha-employer.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Employee Safety and Exposure Records Request — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nWe represent [CURRENT OR FORMER EMPLOYEE], who worked at [ESTABLISHMENT] during [DATES]. The written designation and any specific medical-record authorization are [ACTUAL ATTACHMENTS].\nFor records covered by 29 C.F.R. § 1904.35 or its applicable Virginia counterpart, please provide the relevant OSHA 300 logs for that establishment and the OSHA 301 report concerning this employee’s [IDENTIFIED INJURY]. Please apply the access rules for the employee or personal representative, including the applicable next-business-day requirement and privacy-case protections.\nFor records within 29 C.F.R. § 1910.1020 or its applicable Virginia counterpart, please provide [SPECIFIC EMPLOYEE EXPOSURE / MEDICAL RECORDS AND RELEVANT ANALYSES]. The medical authorization identifies the employee, records, recipient, purpose, signature date and expiration. If covered access cannot reasonably be provided within 15 working days, please provide the required explanation and earliest availability date within that period.\nSeparately, we request voluntarily [SPECIFIC INCIDENT INVESTIGATION, TRAINING OR EQUIPMENT RECORDS]. We do not represent that those additional records fall within the access provisions above. Please preserve relevant materials and send the response through [SECURE METHOD]. Advise in advance of any lawful charge.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Employment and Wage Verification","slug":"wage-verification","command":"/wage-verification","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Voluntary employer verification for wage-loss investigation; separate from the statutory retained-records request.","docx":"docx/wage-verification.docx","reasoning":"../../reasoning/wage-verification.md","path":"templates/investigation/wage-verification.md","docx_path":"templates/investigation/docx/wage-verification.docx","reasoning_path":"reasoning/wage-verification.md","field_count":14,"md":"---\ntitle: \"Employment and Wage Verification\"\nslug: \"wage-verification\"\ncommand: \"/wage-verification\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Voluntary employer verification for wage-loss investigation; separate from the statutory retained-records request.\"\ndocx: \"docx/wage-verification.docx\"\nreasoning: \"../../reasoning/wage-verification.md\"\n---\n# EMPLOYMENT AND WAGE VERIFICATION\nEmployee: [FULL NAME]    Employer: [LEGAL NAME]\nRequested period: [DATES]    Matter reference: [REFERENCE]\nPlease complete from records or personal knowledge and identify the source. Mark information not known or not maintained rather than estimating it as fact.\n## Employment and earnings\nEmployment dates: [DATES]    Job title and duties: [DETAILS]\nPay basis and rate during the relevant period: [HOURLY / SALARY / OTHER; AMOUNT AND EFFECTIVE DATES]\nUsual schedule and hours: [DETAILS]\nOvertime, bonuses or other variable pay: [AMOUNTS, BASIS AND SUPPORTING PERIOD]\n## Time away and payments\nDates or hours not worked: [ITEMIZED DATES AND HOURS]\nReason shown in the employer’s records: [RECORDED REASON; DO NOT INFER MEDICAL CAUSATION]\nWages actually paid during absence: $[AMOUNT AND CATEGORY]\nLeave, disability or other benefits used: [TYPE, HOURS AND PAYMENTS]\nReturn-to-work dates and recorded duty changes: [DETAILS]\n## Supporting records and verification\nRecords supporting the information: [PAYROLL, TIME, LEAVE OR OTHER RECORD IDENTIFIERS]\nCorrections or limitations: [DETAILS]\nCompleted by: [NAME, TITLE AND CONTACT]\nSignature: ____________________    Date: [DATE]\nThis is a factual verification from the identified source. It does not determine whether an amount is legally recoverable or attribute an absence to the incident beyond what the records establish.\n"},{"title":"Evidence Preservation Follow-Up and Spoliation Warning","slug":"spoliation","command":"/spoliation","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Targeted follow-up to a documented preservation concern; no assumed finding of misconduct.","docx":"docx/spoliation.docx","reasoning":"../../reasoning/spoliation.md","path":"templates/investigation/spoliation.md","docx_path":"templates/investigation/docx/spoliation.docx","reasoning_path":"reasoning/spoliation.md","field_count":16,"md":"---\ntitle: \"Evidence Preservation Follow-Up and Spoliation Warning\"\nslug: \"spoliation\"\ncommand: \"/spoliation\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Targeted follow-up to a documented preservation concern; no assumed finding of misconduct.\"\ndocx: \"docx/spoliation.docx\"\nreasoning: \"../../reasoning/spoliation.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT OR COUNSEL]\n[RECIPIENT ADDRESS]\nRe: [CLIENT] — [INCIDENT DATE AND LOCATION]\nDear [RECIPIENT NAME]:\nWe represent [CLIENT] concerning [INCIDENT]. Our earlier preservation notice dated [DATE] identified [EVIDENCE]. We write because [SPECIFIC FACTS CREATING A CURRENT LOSS OR ALTERATION CONCERN].\nPlease take reasonable steps now to preserve [PRECISE MATERIAL, CUSTODIANS, SYSTEMS AND DATE RANGE], including associated metadata and available originals. Suspend routine deletion or overwriting affecting this material. Preserve existing recoverable copies; do not alter a source in an attempt to recreate a missing item.\nPlease identify the responsible preservation contact and confirm the steps taken by [REQUESTED RESPONSE DATE]. If material has already been lost, describe what is unavailable, when and how that occurred, the retention policy involved, and available alternative sources. This request seeks preservation; production can be addressed through an appropriate agreement or discovery process.\nVirginia Code § 8.01-379.2:1 addresses preservation for reasonably foreseeable litigation and court remedies for loss of evidence. Any requested remedy will depend on the actual circumstances and the findings required by that statute. Please route this correspondence through counsel if you are represented.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Preservation of Evidence","slug":"preservation","command":"/preservation","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Virginia personal-injury matter; ordinary adult claimant.","docx":"docx/preservation.docx","reasoning":"../../reasoning/preservation.md","path":"templates/investigation/preservation.md","docx_path":"templates/investigation/docx/preservation.docx","reasoning_path":"reasoning/preservation.md","field_count":20,"md":"---\ntitle: \"Preservation of Evidence\"\nslug: \"preservation\"\ncommand: \"/preservation\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia personal-injury matter; ordinary adult claimant.\"\ndocx: \"docx/preservation.docx\"\nreasoning: \"../../reasoning/preservation.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION]\n[DELIVERY ADDRESS]\nRe: Preservation of Evidence — [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT] concerning the [DATE AND TIME] incident at [LOCATION]. Litigation concerning [IDENTIFIABLE DISPUTE] is reasonably foreseeable because [SUPPORTED CIRCUMSTANCES].\nPlease take reasonable steps to preserve the following relevant evidence within your possession, custody or control: [SPECIFIC ITEMS, CUSTODIANS, SYSTEMS AND DATE RANGES]. This includes [APPLICABLE VIDEO, DASHCAM, PHOTOGRAPHS, VEHICLE OR DEVICE DATA] and associated information needed to understand those materials.\nPlease suspend routine deletion or overwriting of the identified material. Preserve original files and available metadata, and avoid destructive testing or alteration of [SPECIFIC PHYSICAL EVIDENCE] while arrangements for inspection are discussed.\nVirginia Code section 8.01-379.2:1 addresses preservation of evidence relevant to reasonably foreseeable litigation. Please identify the person coordinating preservation and notify us promptly of any material at imminent risk of loss.\nWe request acknowledgment by [REQUESTED DATE]. Please contact us to discuss any practical limits on the preservation requested.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Request for Employment and Wage Records","slug":"employer-letter","command":"/employer-letter","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Statutory request by a current/former employee’s attorney for the specific retained employment records covered by § 8.01-413.1.","docx":"docx/employer-letter.docx","reasoning":"../../reasoning/employer-letter.md","path":"templates/investigation/employer-letter.md","docx_path":"templates/investigation/docx/employer-letter.docx","reasoning_path":"reasoning/employer-letter.md","field_count":20,"md":"---\ntitle: \"Request for Employment and Wage Records\"\nslug: \"employer-letter\"\ncommand: \"/employer-letter\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Statutory request by a current/former employee’s attorney for the specific retained employment records covered by § 8.01-413.1.\"\ndocx: \"docx/employer-letter.docx\"\nreasoning: \"../../reasoning/employer-letter.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Request for Employment and Wage Records - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CURRENT OR FORMER EMPLOYEE] concerning [MATTER]. Pursuant to Virginia Code section 8.01-413.1(B), please furnish retained records reflecting the employee’s dates of employment, wages or salary, job descriptions and titles, and injuries sustained during employment, for [RELEVANT PERIOD].\nThe identifying information reasonably needed to locate the records is [EMPLOYEE IDENTIFIER AND DETAILS]. Our authority and any supporting authorization are [ACTUAL DOCUMENTS]. Please send the records through [SECURE DELIVERY METHOD].\nSection 8.01-413.1(B) generally requires the specified retained records within 30 days after receipt of a written request. If you cannot meet that period, please give the written reason for delay and comply within the additional period allowed by the statute. Please advise us of any reasonable copying charge before incurring charges above [APPROVED AMOUNT].\nWe also request voluntary completion of the enclosed wage-verification questions concerning [SPECIFIC MISSED-WORK PERIOD], if your records permit. This separate request does not assert that the statute requires creation of new records or answers.\nPlease identify records not retained and direct questions to [CONTACT].\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Request for Virginia Crash Report","slug":"police","command":"/police","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Written request for a DMV-maintained Virginia crash report by an eligible person’s attorney; official application requirements still apply.","docx":"docx/police.docx","reasoning":"../../reasoning/police.md","path":"templates/investigation/police.md","docx_path":"templates/investigation/docx/police.docx","reasoning_path":"reasoning/police.md","field_count":20,"md":"---\ntitle: \"Request for Virginia Crash Report\"\nslug: \"police\"\ncommand: \"/police\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Written request for a DMV-maintained Virginia crash report by an eligible person’s attorney; official application requirements still apply.\"\ndocx: \"docx/police.docx\"\nreasoning: \"../../reasoning/police.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Request for Virginia Crash Report - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT], who was [INVOLVED / INJURED / OWNER OF INVOLVED PROPERTY] in the crash on [DATE AND TIME] at [LOCATION]. Known report details are [AGENCY, REPORT NUMBER, DRIVER NAMES AND VEHICLE IDENTIFIERS].\nAs counsel for a person authorized to obtain the report under Virginia Code section 46.2-380, we request a copy of the report maintained by the Department, including supplements maintained as part of that report. Evidence of our authority and any required application are [ACTUAL ENCLOSURES].\nPlease advise us of the lawful charge and provide the report through [DELIVERY METHOD]. If the report cannot be located, please identify additional information needed or the proper custodian.\nAny request for separately maintained photographs, recordings or investigative material is [SEPARATE REQUEST OR NONE] and should be evaluated under its own access requirements. This letter does not claim that every police investigative record is public or included in the crash report.\nPlease contact [PERSON] regarding processing requirements.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Social Media Preservation Demand","slug":"socialmedia-adverse","command":"/socialmedia-adverse","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Preservation of relevant adverse-party social-media material; not a demand for passwords or account access.","docx":"docx/socialmedia-adverse.docx","reasoning":"../../reasoning/socialmedia-adverse.md","path":"templates/investigation/socialmedia-adverse.md","docx_path":"templates/investigation/docx/socialmedia-adverse.docx","reasoning_path":"reasoning/socialmedia-adverse.md","field_count":16,"md":"---\ntitle: \"Social Media Preservation Demand\"\nslug: \"socialmedia-adverse\"\ncommand: \"/socialmedia-adverse\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Preservation of relevant adverse-party social-media material; not a demand for passwords or account access.\"\ndocx: \"docx/socialmedia-adverse.docx\"\nreasoning: \"../../reasoning/socialmedia-adverse.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[ADVERSE PARTY COUNSEL OR PROPER RECIPIENT]\n[RECIPIENT ADDRESS]\nRe: [CLIENT] — [INCIDENT]\nDear [RECIPIENT NAME]:\nWe represent [CLIENT] regarding [INCIDENT]. Please preserve relevant material associated with [IDENTIFIED ACCOUNTS, PLATFORMS AND CUSTODIANS] for [RELEVANT DATE RANGE], including [SPECIFIC POSTS, MESSAGES, PHOTOGRAPHS, VIDEO, COMMENTS OR LOCATION MATERIAL] relating to [DEFINED ISSUES].\nPlease preserve the original content and available metadata, account exports, edits, deletion history and existing backups to the extent relevant and reasonably available. Suspend automatic disappearance or deletion for the identified material where feasible, and preserve it before making account changes. No alteration, deletion or concealment of relevant content is requested.\nThis is a preservation request, not permission to access another person's account, obtain credentials, impersonate a user or disclose privileged communications. Appropriate scope, privacy protections and any production process can be addressed with counsel.\nPlease confirm the preservation contact and measures taken by [REQUESTED RESPONSE DATE]. If a category cannot be preserved, identify the obstacle and any available substitute source.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Traffic Signal Records Request","slug":"traffic-signal","command":"/traffic-signal","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Virginia public-records request for existing signal records from their actual public custodian.","docx":"docx/traffic-signal.docx","reasoning":"../../reasoning/traffic-signal.md","path":"templates/investigation/traffic-signal.md","docx_path":"templates/investigation/docx/traffic-signal.docx","reasoning_path":"reasoning/traffic-signal.md","field_count":19,"md":"---\ntitle: \"Traffic Signal Records Request\"\nslug: \"traffic-signal\"\ncommand: \"/traffic-signal\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia public-records request for existing signal records from their actual public custodian.\"\ndocx: \"docx/traffic-signal.docx\"\nreasoning: \"../../reasoning/traffic-signal.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[FOIA OFFICER AND PUBLIC BODY]\n[RECIPIENT ADDRESS]\nRe: [INTERSECTION] — [INCIDENT DATE AND TIME]\nDear [RECIPIENT NAME]:\nOn behalf of [CLIENT], we request the existing records below under the Virginia Freedom of Information Act. The requester's eligibility is [VIRGINIA CITIZEN OR OTHER VERIFIED STATUTORY BASIS]. The incident occurred at [INTERSECTION, APPROACH AND DIRECTION], on [DATE] at approximately [TIME AND TIME ZONE].\nPlease provide existing signal timing plans, phase and clearance intervals, controller/event logs, configuration changes, maintenance and malfunction reports, inspection records, and relevant video for [SPECIFIC DATE AND TIME RANGE]. The controller or signal identifier is [KNOWN IDENTIFIER]. We do not ask the agency to create an analysis or reconstruct a sequence that is not recorded.\nElectronic copies in their existing usable format are preferred. Please identify any withheld category and the specific statutory basis, and provide reasonably segregable nonexempt material. Before incurring charges above [APPROVED AMOUNT], please provide an estimate so we can discuss scope.\nPlease preserve potentially responsive records while this request is processed. If another office maintains them, please identify that custodian or forward the request if appropriate. Contact [NAME AND CONTACT] to clarify scope.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Vehicle Event Data Preservation and Access Request","slug":"blackbox","command":"/blackbox","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Post-incident preservation and proposed lawful access to vehicle data; not an owner-consent form or compulsory inspection order.","docx":"docx/blackbox.docx","reasoning":"../../reasoning/blackbox.md","path":"templates/investigation/blackbox.md","docx_path":"templates/investigation/docx/blackbox.docx","reasoning_path":"reasoning/blackbox.md","field_count":17,"md":"---\ntitle: \"Vehicle Event Data Preservation and Access Request\"\nslug: \"blackbox\"\ncommand: \"/blackbox\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Post-incident preservation and proposed lawful access to vehicle data; not an owner-consent form or compulsory inspection order.\"\ndocx: \"docx/blackbox.docx\"\nreasoning: \"../../reasoning/blackbox.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Vehicle Event Data Preservation and Access Request - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT] concerning the [DATE] collision involving [VEHICLE, VIN AND OWNER IF KNOWN]. Please preserve the vehicle, relevant recording devices and stored data, including [IDENTIFIED EDR, ECM OR OTHER RELEVANT SYSTEM], without unnecessary alteration, erasure or disposal.\nWe propose a coordinated inspection and data download under [IDENTIFIED OWNER AUTHORIZATION, AGREEMENT OR COURT AUTHORITY]. No access should occur without the authority required by Virginia Code section 46.2-1088.6. This request does not itself supply consent or authorize a download.\nPlease identify the vehicle’s present location, owner, custodian, anticipated repair or disposal and any prior download. Preserve existing reports, native data, tools/version information and chain-of-custody records from any earlier authorized access.\nThe proposed protocol is [EXPERT, NONDESTRUCTIVE METHOD, NOTICE, PARTICIPANTS AND COPY-SHARING TERMS]. Please advise us before any action that could destroy relevant data so that an appropriate preservation arrangement can be addressed.\nPlease contact [ATTORNEY] promptly to coordinate. No opinion about the availability or contents of the data is assumed.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Video Preservation and Copy Request","slug":"surveillance","command":"/surveillance","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Targeted pre-suit surveillance request to a business or other custodian; not an unlimited demand for all footage.","docx":"docx/surveillance.docx","reasoning":"../../reasoning/surveillance.md","path":"templates/investigation/surveillance.md","docx_path":"templates/investigation/docx/surveillance.docx","reasoning_path":"reasoning/surveillance.md","field_count":19,"md":"---\ntitle: \"Video Preservation and Copy Request\"\nslug: \"surveillance\"\ncommand: \"/surveillance\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Targeted pre-suit surveillance request to a business or other custodian; not an unlimited demand for all footage.\"\ndocx: \"docx/surveillance.docx\"\nreasoning: \"../../reasoning/surveillance.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Video Preservation and Copy Request - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT] regarding [INCIDENT] at [LOCATION] on [DATE AND TIME, INCLUDING TIME ZONE IF RELEVANT]. Video from [IDENTIFIED CAMERAS OR VIEWS] may show [SPECIFIC RELEVANT EVENT]. Please preserve recordings for [REASONABLE START AND END TIMES], including any offset between system time and actual time.\nPlease prevent routine overwriting of the identified material and preserve original recordings, available metadata, export logs and any player or codec needed to view the files. We request a voluntary copy in its native or other usable format, without editing or alteration.\nPlease identify the custodian, retention period and any other location where the material is stored. If relevant footage is unavailable, please explain what is known about its disposition and whether another person holds a copy.\nWe are requesting preservation and voluntary cooperation. Any compulsory production will be pursued through the appropriate process. This request does not authorize entry into your systems or disclosure of unrelated private footage.\nPlease contact [ATTORNEY] promptly, particularly if the recording may soon be overwritten.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Voluntary Request for Incident Records","slug":"incident-report","command":"/incident-report","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Pre-suit request to a private premises owner or business about a specific incident; no automatic FOIA or compulsory-production power.","docx":"docx/incident-report.docx","reasoning":"../../reasoning/incident-report.md","path":"templates/investigation/incident-report.md","docx_path":"templates/investigation/docx/incident-report.docx","reasoning_path":"reasoning/incident-report.md","field_count":19,"md":"---\ntitle: \"Voluntary Request for Incident Records\"\nslug: \"incident-report\"\ncommand: \"/incident-report\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Pre-suit request to a private premises owner or business about a specific incident; no automatic FOIA or compulsory-production power.\"\ndocx: \"docx/incident-report.docx\"\nreasoning: \"../../reasoning/incident-report.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Voluntary Request for Incident Records - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT] concerning the incident at [LOCATION] on [DATE AND TIME]. Please preserve relevant incident reports, photographs, video, witness information, inspection records and related communications for [REASONABLE PERIOD AND SPECIFIC SUBJECT].\nWe request voluntary copies of [SPECIFIC REPORTS OR OTHER RECORDS], including available supplements and the identities of persons who created or maintain them. Please preserve originals and associated metadata. If copies can be provided, use [SECURE METHOD] and identify the source and date range.\nPlease let us know whether relevant records are maintained by another custodian and whether any automatic retention or deletion process may affect them. If you decline voluntary production, please state your position so that appropriate formal procedures can be evaluated.\nThis letter is a preservation notice and voluntary request. It is not a subpoena, discovery order or assertion that protected material must be disclosed without a proper basis.\nPlease contact [ATTORNEY] by [REQUESTED DATE] to coordinate preservation and any voluntary production.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Workplace Safety Public Records Request","slug":"osha-foia","command":"/osha-foia","category":"investigation","category_label":"Investigation and records requests","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Virginia DOLI/VOSH records request, with a separately selected federal OSHA alternative.","docx":"docx/osha-foia.docx","reasoning":"../../reasoning/osha-foia.md","path":"templates/investigation/osha-foia.md","docx_path":"templates/investigation/docx/osha-foia.docx","reasoning_path":"reasoning/osha-foia.md","field_count":19,"md":"---\ntitle: \"Workplace Safety Public Records Request\"\nslug: \"osha-foia\"\ncommand: \"/osha-foia\"\ncategory: \"investigation\"\ncategory_label: \"Investigation and records requests\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia DOLI/VOSH records request, with a separately selected federal OSHA alternative.\"\ndocx: \"docx/osha-foia.docx\"\nreasoning: \"../../reasoning/osha-foia.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Workplace Safety Public Records Request — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nUnder [VIRGINIA FOIA, § 2.2-3700 ET SEQ. / FEDERAL FOIA, 5 U.S.C. § 552 — SELECT THE LAW APPLICABLE TO THE RECIPIENT], we request existing records concerning [EMPLOYER, WORKSITE, INCIDENT DATE AND INSPECTION NUMBER] for [DATE RANGE].\nThe requested records are [SPECIFIC INSPECTION REPORTS, CITATIONS, PHOTOGRAPHS, FINAL ORDERS, ABATEMENT RECORDS OR OTHER IDENTIFIED CATEGORIES]. Please provide electronic copies in their existing reasonably usable format. This request does not ask the agency to create a new record or answer interrogatories.\n[FOR VIRGINIA FOIA, STATE THE REQUESTER’S ACTUAL ELIGIBLE STATUS AND ADDRESS]. [FOR FEDERAL FOIA, IDENTIFY THE APPLICABLE REQUESTER FEE CATEGORY AND FACTUAL BASIS]. We authorize charges up to $[CAP]; please provide an estimate before exceeding that amount. Any fee-waiver or expedited-processing request is supported by [SPECIFIC LEGAL BASIS AND FACTS, IF ACTUALLY REQUESTED].\nIf any portion is withheld, please identify the applicable legal basis and release reasonably segregable nonexempt material. Please explain any applicable review or appeal procedure. We understand that active investigations, personal medical information and protected business information may be subject to lawful withholding.\nPlease acknowledge receipt and direct communications to [CONTACT].\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Affidavit Concerning an Unknown Motorist","slug":"umuim-affidavit-hit-and-run","command":"/umuim-affidavit-hit-and-run","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Supporting Virginia UM/UIM factual affidavit; no automatic coverage determination or substitute for statutory service.","docx":"docx/umuim-affidavit-hit-and-run.docx","reasoning":"../../reasoning/umuim-affidavit-hit-and-run.md","path":"templates/insurance/umuim-affidavit-hit-and-run.md","docx_path":"templates/insurance/docx/umuim-affidavit-hit-and-run.docx","reasoning_path":"reasoning/umuim-affidavit-hit-and-run.md","field_count":20,"md":"---\ntitle: \"Affidavit Concerning an Unknown Motorist\"\nslug: \"umuim-affidavit-hit-and-run\"\ncommand: \"/umuim-affidavit-hit-and-run\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Supporting Virginia UM/UIM factual affidavit; no automatic coverage determination or substitute for statutory service.\"\ndocx: \"docx/umuim-affidavit-hit-and-run.docx\"\nreasoning: \"../../reasoning/umuim-affidavit-hit-and-run.md\"\n---\n# AFFIDAVIT CONCERNING AN UNKNOWN MOTORIST\nI, [AFFIANT NAME], being duly sworn, state:\n1. I am [AFFIANT NAME], [ROLE AND BASIS OF PERSONAL KNOWLEDGE]. On [DATE AND TIME] at [LOCATION], I was [DESCRIBE ACTIVITY AND VEHICLE].\n2. The occurrence was [PERSONAL OBSERVATIONS OF THE OTHER VEHICLE, CONDUCT AND RESULTING INCIDENT]. Physical contact [DID / DID NOT] occur as follows: [SPECIFIC FACTS].\n3. The other vehicle’s driver, owner and identifying information known to me are [FACTS; DISTINGUISH UNKNOWN FROM UNCONFIRMED]. Efforts actually made to identify them were [STEPS, DATES AND RESULTS].\n4. I reported the occurrence to [INSURER OR LAW-ENFORCEMENT OFFICER] on [DATE, TIME AND METHOD], reference [NUMBER]. [STATE FACTS EXPLAINING THE TIMING OF ANY REPORT].\n5. Witnesses and supporting materials known to me are [NAMES, CONTACT METHOD, REPORTS AND ACTUAL ATTACHMENTS]. I do not claim personal knowledge of facts learned only from others; those sources are [IDENTIFY].\nThe foregoing is true and correct to the best of my personal knowledge as stated.\nSignature: ____________________\nPrinted name: [AFFIANT NAME]\nCOMMONWEALTH / STATE OF [STATE]\nCITY / COUNTY OF [LOCALITY]\nSubscribed and sworn to before me on [ACTUAL DATE] by [AFFIANT NAME].\nNotary signature: ____________________\nNotary registration number: [NUMBER]\nCommission expires: [DATE]\n"},{"title":"Affidavit Concerning Available Motor Vehicle Insurance","slug":"umuim-affidavit-named","command":"/umuim-affidavit-named","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Supporting Virginia UM/UIM factual affidavit; no automatic coverage determination or substitute for statutory service.","docx":"docx/umuim-affidavit-named.docx","reasoning":"../../reasoning/umuim-affidavit-named.md","path":"templates/insurance/umuim-affidavit-named.md","docx_path":"templates/insurance/docx/umuim-affidavit-named.docx","reasoning_path":"reasoning/umuim-affidavit-named.md","field_count":16,"md":"---\ntitle: \"Affidavit Concerning Available Motor Vehicle Insurance\"\nslug: \"umuim-affidavit-named\"\ncommand: \"/umuim-affidavit-named\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Supporting Virginia UM/UIM factual affidavit; no automatic coverage determination or substitute for statutory service.\"\ndocx: \"docx/umuim-affidavit-named.docx\"\nreasoning: \"../../reasoning/umuim-affidavit-named.md\"\n---\n# AFFIDAVIT CONCERNING AVAILABLE MOTOR VEHICLE INSURANCE\nI, [AFFIANT NAME], being duly sworn, state:\n1. I am [AFFIANT NAME], [DRIVER / OWNER / OTHER CAPACITY], with personal knowledge from [BASIS]. This statement concerns [VEHICLE, OWNER, DRIVER, INCIDENT DATE AND LOCATION].\n2. The vehicle’s ownership, registration, permitted use and purpose of travel were [FACTS, INCLUDING ANY EMPLOYMENT OR BUSINESS USE].\n3. Liability policies, other vehicles’ policies, household coverage, commercial coverage, umbrella coverage or self-insurance potentially applicable to me or this vehicle are [IDENTIFY EACH KNOWN SOURCE OR STATE THE PRECISE LIMITS OF MY KNOWLEDGE].\n4. I reviewed [ACTUAL POLICIES, CANCELLATION NOTICES, INSURER COMMUNICATIONS OR OTHER RECORDS] and made [ACTUAL INQUIRIES]. The results were [FACTS AND DATES].\n5. Based on that inquiry, my statement about the absence or availability of coverage is [PRECISE FACTUAL STATEMENT]. [IDENTIFY ATTACHED INSURER DENIALS OR DMV CERTIFICATION, IF ACTUALLY OBTAINED].\nThe foregoing is true and correct to the best of my personal knowledge as stated.\nSignature: ____________________\nPrinted name: [AFFIANT NAME]\nCOMMONWEALTH / STATE OF [STATE]\nCITY / COUNTY OF [LOCALITY]\nSubscribed and sworn to before me on [ACTUAL DATE] by [AFFIANT NAME].\nNotary signature: ____________________\nNotary registration number: [NUMBER]\nCommission expires: [DATE]\n"},{"title":"Diminished Vehicle Value Demand","slug":"diminished","command":"/diminished","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Evidence-based Virginia tort demand for residual vehicle value loss after repair.","docx":"docx/diminished.docx","reasoning":"../../reasoning/diminished.md","path":"templates/insurance/diminished.md","docx_path":"templates/insurance/docx/diminished.docx","reasoning_path":"reasoning/diminished.md","field_count":22,"md":"---\ntitle: \"Diminished Vehicle Value Demand\"\nslug: \"diminished\"\ncommand: \"/diminished\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Evidence-based Virginia tort demand for residual vehicle value loss after repair.\"\ndocx: \"docx/diminished.docx\"\nreasoning: \"../../reasoning/diminished.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[LIABILITY ADJUSTER OR COUNSEL]\n[RECIPIENT ADDRESS]\nRe: [CLIENT] — [VEHICLE AND LOSS DATE]\nDear [RECIPIENT NAME]:\nWe represent [CLIENT] regarding [VEHICLE] damaged in [INCIDENT]. Following [REPAIRS AND COMPLETION DATE], the vehicle's remaining collision-related loss in value is [SUPPORTED AMOUNT]. We request payment of that amount, subject to the accounting below.\nThe valuation rests on [QUALIFIED APPRAISAL OR OTHER COMPETENT MARKET EVIDENCE], comparing [PRE-LOSS CONDITION AND VALUE] with [POST-REPAIR CONDITION AND VALUE]. Relevant mileage, prior damage, repair quality and comparable transactions are [FACTS]. The supporting material is [ACTUALLY ENCLOSED DOCUMENTS].\nThe applicable measure must account for repairability, reasonable repair cost and any supported depreciation under Virginia law. The reconciliation of repair payments, residual diminution and other recoveries is [ACCOUNTING SHOWING NO DUPLICATE RECOVERY]. No fixed percentage or unexplained formula is assumed.\nPlease respond by [REQUESTED DATE] with payment or the factual and valuation basis for any disagreement. This letter addresses the identified property-damage component; any proposed broader release requires separate client approval.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Notice of Representation to First Party Insurer","slug":"rep-first","command":"/rep-first","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Notice to the client’s own insurer; coverage and cooperation depend on the actual policy and law.","docx":"docx/rep-first.docx","reasoning":"../../reasoning/rep-first.md","path":"templates/insurance/rep-first.md","docx_path":"templates/insurance/docx/rep-first.docx","reasoning_path":"reasoning/rep-first.md","field_count":16,"md":"---\ntitle: \"Notice of Representation to First Party Insurer\"\nslug: \"rep-first\"\ncommand: \"/rep-first\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Notice to the client’s own insurer; coverage and cooperation depend on the actual policy and law.\"\ndocx: \"docx/rep-first.docx\"\nreasoning: \"../../reasoning/rep-first.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Notice of Representation to First Party Insurer - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT AND INSURED STATUS] concerning the [DATE] incident at [LOCATION]. The known policy and claim identifiers are [NUMBERS]. Please direct communications about this represented claim to [ATTORNEY AND CONTACT DETAILS].\nPlease acknowledge the claim, identify the assigned adjuster and provide the complete policy in effect, including declarations, endorsements and any applicable coverage elections. Potential coverages for evaluation are [COVERAGES SUPPORTED BY THE FACTS]. We do not assume that every listed coverage applies.\nPlease identify any requested proof, policy condition, examination, statement or deadline, together with its asserted basis and proposed arrangements. We will coordinate a response consistent with the insured’s actual obligations and applicable law.\nPreserve relevant claim communications, recorded statements and materials concerning this incident. Please advise us of any coverage position or reservation and provide the specific policy provisions and factual basis relied upon.\nThis letter gives notice and seeks information. It is not a release, settlement acceptance or representation that all prerequisites for coverage have been met.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Notice of Representation to Liability Insurer","slug":"rep-adverse","command":"/rep-adverse","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Virginia personal-injury matter; ordinary adult claimant.","docx":"docx/rep-adverse.docx","reasoning":"../../reasoning/rep-adverse.md","path":"templates/insurance/rep-adverse.md","docx_path":"templates/insurance/docx/rep-adverse.docx","reasoning_path":"reasoning/rep-adverse.md","field_count":17,"md":"---\ntitle: \"Notice of Representation to Liability Insurer\"\nslug: \"rep-adverse\"\ncommand: \"/rep-adverse\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia personal-injury matter; ordinary adult claimant.\"\ndocx: \"docx/rep-adverse.docx\"\nreasoning: \"../../reasoning/rep-adverse.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION]\n[DELIVERY ADDRESS]\nRe: Notice of Representation to Liability Insurer — [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT FULL NAME] concerning injuries arising from the [DATE OF LOSS] incident at [LOCATION] involving your insured, [INSURED NAME]. Your claim number is [CLAIM NUMBER, IF ASSIGNED].\nPlease direct communications concerning this claim to our office and identify the adjuster handling the matter, the claim number and the appropriate address for future correspondence.\nPlease preserve materials in your possession, custody or control relating to this incident, including [SPECIFIC KNOWN RECORDS OR RECORDINGS]. Our client will provide supporting claim material as it becomes available and is authorized for disclosure.\nPlease acknowledge receipt and advise whether additional identifying information is needed.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Pre-Suit Policy Limits Disclosure Request","slug":"limits","command":"/limits","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Pre-suit Virginia motor-vehicle personal-injury disclosure under § 8.01-417(C); excludes wrongful-death subsection D.","docx":"docx/limits.docx","reasoning":"../../reasoning/limits.md","path":"templates/insurance/limits.md","docx_path":"templates/insurance/docx/limits.docx","reasoning_path":"reasoning/limits.md","field_count":20,"md":"---\ntitle: \"Pre-Suit Policy Limits Disclosure Request\"\nslug: \"limits\"\ncommand: \"/limits\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Pre-suit Virginia motor-vehicle personal-injury disclosure under § 8.01-417(C); excludes wrongful-death subsection D.\"\ndocx: \"docx/limits.docx\"\nreasoning: \"../../reasoning/limits.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION]\n[DELIVERY ADDRESS]\nRe: Pre-Suit Policy Limits Disclosure Request — [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [INJURED PERSON] concerning injuries from the motor-vehicle accident on [DATE] involving [ALLEGED TORTFEASOR]. Notice of our representation was provided on [DATE]. The claim number is [NUMBER, IF AVAILABLE], and the tortfeasor's last known address reported to us is [ADDRESS OR NOT REPORTED].\nBefore filing a civil action, we request the limits of each motor-vehicle liability or personal-injury liability policy that may apply to this claim, as provided in Virginia Code section 8.01-417(C). Please also provide the insured's physical address if it has not previously been reported to us, subject to any applicable statutory alternative.\nThe supporting material consists of [ACCIDENT REPORT IF ANY], [MEDICAL RECORDS], [MEDICAL BILLS] and [WAGE-LOSS DOCUMENTATION IF APPLICABLE]. The basis for mandatory limits disclosure is [VERIFIED TOTAL AT LEAST $12,500 OR QUALIFYING CHARGE AND SAME-INCIDENT INJURIES].\nPlease provide the disclosure within the period required by section 8.01-417(C) after receipt of this qualifying request, including limits in effect on the accident date, even if applicability is disputed.\nPlease identify any missing information needed to evaluate this request. This letter requests disclosure; it does not make a settlement offer.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Request for Claim Materials and Adjuster Records","slug":"claims-file","command":"/claims-file","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Voluntary request for defined insurer-held materials; not an assertion that the entire claims file is discoverable.","docx":"docx/claims-file.docx","reasoning":"../../reasoning/claims-file.md","path":"templates/insurance/claims-file.md","docx_path":"templates/insurance/docx/claims-file.docx","reasoning_path":"reasoning/claims-file.md","field_count":19,"md":"---\ntitle: \"Request for Claim Materials and Adjuster Records\"\nslug: \"claims-file\"\ncommand: \"/claims-file\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Voluntary request for defined insurer-held materials; not an assertion that the entire claims file is discoverable.\"\ndocx: \"docx/claims-file.docx\"\nreasoning: \"../../reasoning/claims-file.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[INSURER OR COUNSEL]\n[RECIPIENT ADDRESS]\nRe: [CLIENT] — [CLAIM AND LOSS DATE]\nDear [RECIPIENT NAME]:\nWe represent [CLIENT], whose relationship to this claim is [INSURED, CLAIMANT OR OTHER VERIFIED CAPACITY]. Please provide nonprivileged materials concerning [DEFINED CLAIM, ISSUES AND DATE RANGE], including [SPECIFIC STATEMENTS, PHOTOGRAPHS, ESTIMATES, CORRESPONDENCE OR PAYMENT RECORDS].\nWe also request [IDENTIFIED ADJUSTER NOTES OR INVESTIGATIVE MATERIAL] relating to [SPECIFIC ISSUE]. Please distinguish documents withheld on a stated privilege or protection ground from documents not held or not located. This voluntary request does not imply waiver of a valid protection or authorize disclosure of unrelated personal information.\nWhere disclosure requires client authorization, it is [ACTUALLY ENCLOSED AUTHORIZATION]. If the requested material must instead be pursued through formal discovery or a subpoena, please identify that position so the appropriate process can be considered.\nPlease preserve responsive materials and provide your response by [REQUESTED DATE]. Any production can be subject to [AGREED SECURE DELIVERY OR CONFIDENTIALITY TERMS].\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Request for Policy and Coverage Documents","slug":"declarations","command":"/declarations","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"First-party or otherwise authorized policy-document request; not statutory third-party limits disclosure under /limits.","docx":"docx/declarations.docx","reasoning":"../../reasoning/declarations.md","path":"templates/insurance/declarations.md","docx_path":"templates/insurance/docx/declarations.docx","reasoning_path":"reasoning/declarations.md","field_count":20,"md":"---\ntitle: \"Request for Policy and Coverage Documents\"\nslug: \"declarations\"\ncommand: \"/declarations\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"First-party or otherwise authorized policy-document request; not statutory third-party limits disclosure under /limits.\"\ndocx: \"docx/declarations.docx\"\nreasoning: \"../../reasoning/declarations.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Request for Policy and Coverage Documents - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT] in connection with [INCIDENT OR CLAIM]. Our client’s relationship to the policy is [INSURED / AUTHORIZED REPRESENTATIVE / OTHER ACTUAL CAPACITY]. Relevant identifiers are [POLICY, CLAIM, INSURED AND DATE OF LOSS].\nPlease provide the declarations and complete policy applicable on [DATE], including all endorsements, coverage schedules, forms incorporated by reference and changes affecting that period. Please include [SPECIFIC RELEVANT ELECTION, REJECTION OR LIMITS DOCUMENTS].\nPlease confirm the named insured, policy period and the adjuster responsible for [IDENTIFIED COVERAGE QUESTION]. If any requested document is unavailable or you dispute our entitlement to it, identify the document and explain the basis of your position.\nOur authority or authorization is [ACTUAL BASIS AND ENCLOSURE, IF NEEDED]. Please use [SECURE DELIVERY METHOD]. This request does not concede the application of an exclusion, limit, offset or reservation.\nPlease respond by [REQUESTED DATE] or let us know when the documents can be supplied.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Response to Bodily Injury Claim Denial","slug":"claim-rejection-bi","command":"/claim-rejection-bi","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Reconsideration request to a liability carrier addressing its actual denial grounds.","docx":"docx/claim-rejection-bi.docx","reasoning":"../../reasoning/claim-rejection-bi.md","path":"templates/insurance/claim-rejection-bi.md","docx_path":"templates/insurance/docx/claim-rejection-bi.docx","reasoning_path":"reasoning/claim-rejection-bi.md","field_count":17,"md":"---\ntitle: \"Response to Bodily Injury Claim Denial\"\nslug: \"claim-rejection-bi\"\ncommand: \"/claim-rejection-bi\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Reconsideration request to a liability carrier addressing its actual denial grounds.\"\ndocx: \"docx/claim-rejection-bi.docx\"\nreasoning: \"../../reasoning/claim-rejection-bi.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[LIABILITY INSURER AND ADJUSTER]\n[RECIPIENT ADDRESS]\nRe: [CLIENT] — [CLAIM NUMBER AND INCIDENT]\nDear [RECIPIENT NAME]:\nWe represent [CLIENT]. We request reconsideration of your denial dated [DATE], which states [ACCURATE SUMMARY OF EACH GROUND].\nThe evidence bearing on the disputed ground is [SPECIFIC DOCUMENTS, TESTIMONY OR PHOTOGRAPHS WITH REFERENCES]. In particular, [EXPLAIN HOW THE EVIDENCE ADDRESSES LIABILITY, CAUSATION OR THE IDENTIFIED ISSUE]. Known adverse facts are [FACTS AND SUPPORTED RESPONSE].\nPlease review [ACTUALLY ENCLOSED MATERIAL] and identify any factual premise you continue to dispute. If your position rests on a coverage issue, distinguish that issue from liability and identify the policy language and insured relationship on which you rely, to the extent disclosure is authorized.\nWe request your written position by [REQUESTED DATE]. The client has not agreed to extend any limitation period or release a claim. Please direct substantive communications concerning the represented client to this office. This request does not assume a direct bad-faith cause of action against the liability insurer.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Response to Third Party Recorded Statement Request","slug":"recorded-stmt","command":"/recorded-stmt","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Response to adverse liability insurer’s voluntary statement request, not a blanket refusal of first-party cooperation.","docx":"docx/recorded-stmt.docx","reasoning":"../../reasoning/recorded-stmt.md","path":"templates/insurance/recorded-stmt.md","docx_path":"templates/insurance/docx/recorded-stmt.docx","reasoning_path":"reasoning/recorded-stmt.md","field_count":13,"md":"---\ntitle: \"Response to Third Party Recorded Statement Request\"\nslug: \"recorded-stmt\"\ncommand: \"/recorded-stmt\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Response to adverse liability insurer’s voluntary statement request, not a blanket refusal of first-party cooperation.\"\ndocx: \"docx/recorded-stmt.docx\"\nreasoning: \"../../reasoning/recorded-stmt.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Response to Third Party Recorded Statement Request - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT] concerning the [DATE] incident and your claim [NUMBER]. We received your request dated [DATE] for a recorded statement.\nAt this time, our client does not agree to the proposed voluntary recorded interview with the adverse liability carrier. Please direct your questions and the asserted basis for the request to us in writing. We are available to discuss a suitable method for providing supported claim information.\nPlease preserve any statement already taken from our client, including the complete recording, transcript and related identifying information, and provide a copy or identify the basis for declining that request.\nThis response concerns the voluntary third-party interview described above. It does not refuse compliance with a subpoena, court order or an obligation under a policy issued to or covering our client. If you contend such an obligation applies, identify the specific provision and proposed arrangements so it can be addressed.\nPlease contact [ATTORNEY] to coordinate further communication.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Substitute Vehicle and Rental Reimbursement Request","slug":"rental","command":"/rental","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Virginia vehicle loss-of-use request tied to actual reasonable rental expense.","docx":"docx/rental.docx","reasoning":"../../reasoning/rental.md","path":"templates/insurance/rental.md","docx_path":"templates/insurance/docx/rental.docx","reasoning_path":"reasoning/rental.md","field_count":21,"md":"---\ntitle: \"Substitute Vehicle and Rental Reimbursement Request\"\nslug: \"rental\"\ncommand: \"/rental\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia vehicle loss-of-use request tied to actual reasonable rental expense.\"\ndocx: \"docx/rental.docx\"\nreasoning: \"../../reasoning/rental.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[ADJUSTER OR RESPONSIBLE PARTY COUNSEL]\n[RECIPIENT ADDRESS]\nRe: [CLIENT] — [LOSS DATE AND CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nWe represent [CLIENT] concerning damage to [VEHICLE] caused by [INCIDENT]. The vehicle has been unavailable from [DATE] because [REPAIR OR TOTAL-LOSS FACTS].\nWe request [ARRANGEMENT OF A COMPARABLE SUBSTITUTE VEHICLE OR REIMBURSEMENT OF ACTUAL RENTAL EXPENSE]. The relevant rental period is [DATES], the comparable vehicle class is [CLASS], and the reasonable daily charge and supported total are [AMOUNTS]. Enclosed are [ACTUAL AGREEMENT, INVOICES, PROOF OF PAYMENT AND REPAIR OR REPLACEMENT TIMELINE]. Prior payments or credits are [AMOUNTS].\nVirginia Code § 8.01-66 addresses reasonable actual substitute-vehicle expense during a reasonable repair or replacement period, subject to mitigation. Our request is based on [SUPPORTED DURATION AND COMPARABILITY FACTS].\nPlease identify any disputed dates, rates or charges and your supporting basis. We request a response by [REQUESTED DATE]. This request does not state that enhanced statutory damages have already accrued or that liability has been adjudicated.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"UM or UIM Claim Opening Notice","slug":"umuim","command":"/umuim","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Virginia UM/UIM opening notice, with no assumption of coverage, exhaustion, stacking or consent.","docx":"docx/umuim.docx","reasoning":"../../reasoning/umuim.md","path":"templates/insurance/umuim.md","docx_path":"templates/insurance/docx/umuim.docx","reasoning_path":"reasoning/umuim.md","field_count":19,"md":"---\ntitle: \"UM or UIM Claim Opening Notice\"\nslug: \"umuim\"\ncommand: \"/umuim\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia UM/UIM opening notice, with no assumption of coverage, exhaustion, stacking or consent.\"\ndocx: \"docx/umuim.docx\"\nreasoning: \"../../reasoning/umuim.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: UM or UIM Claim Opening Notice - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT] concerning injuries arising from the [DATE] collision at [LOCATION]. Please open or identify the [UNINSURED / UNDERINSURED] motorist claim under [POLICY, NAMED INSURED AND POLICY PERIOD].\nThe present basis for the claim is [SUPPORTED FACTS ABOUT THE ADVERSE VEHICLE, DRIVER, INSURANCE AND CLIENT’S INSURED STATUS]. The available liability-insurance information is [IDENTIFIED SOURCE AND LIMITS OR UNKNOWN]. Further coverage investigation remains [STATUS].\nPlease provide the declarations, complete applicable policy and endorsements, UM/UIM limits and any relevant election or rejection documents. Identify other information reasonably requested to evaluate coverage and the claim.\nThe litigation status is [NO SUIT / CASE AND COURT]. Required service of process and statutory notice will be handled separately as applicable; this letter is not a substitute for them. Any proposed settlement with another person will be evaluated under the governing coverage and subrogation procedure before a release is executed.\nPlease identify the adjuster, claim number and any asserted policy or statutory deadline. We will supplement with supported liability, treatment and damages materials as they become available.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"UM or UIM Consent to Settle Request","slug":"umuim-consent","command":"/umuim-consent","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Request for insurer position before an identified settlement; not a substitute for a statutory release package.","docx":"docx/umuim-consent.docx","reasoning":"../../reasoning/umuim-consent.md","path":"templates/insurance/umuim-consent.md","docx_path":"templates/insurance/docx/umuim-consent.docx","reasoning_path":"reasoning/umuim-consent.md","field_count":20,"md":"---\ntitle: \"UM or UIM Consent to Settle Request\"\nslug: \"umuim-consent\"\ncommand: \"/umuim-consent\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Request for insurer position before an identified settlement; not a substitute for a statutory release package.\"\ndocx: \"docx/umuim-consent.docx\"\nreasoning: \"../../reasoning/umuim-consent.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[UM OR UIM INSURER AND ADJUSTER]\n[RECIPIENT ADDRESS]\nRe: [INSURED] — [POLICY, CLAIM AND LOSS DATE]\nDear [RECIPIENT NAME]:\nWe represent [INSURED] concerning [INCIDENT]. [TORTFEASOR OR LIABILITY INSURER] has proposed settlement of [IDENTIFIED CLAIM] for [AMOUNT]. Proposed release terms and the offer are [ACTUALLY ENCLOSED MATERIAL]. No consent or waiver by your company is assumed.\nThe potentially applicable UM/UIM coverage is [POLICY AND COVERAGE PERIOD], with [RELEVANT ENDORSEMENTS OR COVERAGE ELECTIONS]. Before acceptance or execution, please state whether you consent to the described settlement and release, whether you assert any preservation or subrogation requirement, and the policy or statutory basis for your position.\nThe proposed treatment of the tortfeasor, any continuing cooperation obligations, UIM claims and credited payments is [SPECIFIC TERMS]. If a procedure under Virginia Code § 38.2-2206 applies, the required notices, signatures, payments and other conditions will be addressed in the applicable documents.\nPlease respond by [REQUESTED DATE] and identify any additional information needed promptly. This letter alone neither releases a party nor waives a coverage or subrogation issue.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"UM/UIM Dispute and Voluntary Arbitration Proposal","slug":"claim-rejection-umuim","command":"/claim-rejection-umuim","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Original dispute/reconsideration letter with an expressly voluntary arbitration proposal. It does not compel arbitration, create consent or preserve a deadline. If the client does not authorize proposing arbitration, use the ordinary UM/UIM claim correspondence instead.","docx":"docx/claim-rejection-umuim.docx","reasoning":"../../reasoning/claim-rejection-umuim.md","path":"templates/insurance/claim-rejection-umuim.md","docx_path":"templates/insurance/docx/claim-rejection-umuim.docx","reasoning_path":"reasoning/claim-rejection-umuim.md","field_count":19,"md":"---\ntitle: \"UM/UIM Dispute and Voluntary Arbitration Proposal\"\nslug: \"claim-rejection-umuim\"\ncommand: \"/claim-rejection-umuim\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Original dispute/reconsideration letter with an expressly voluntary arbitration proposal. It does not compel arbitration, create consent or preserve a deadline. If the client does not authorize proposing arbitration, use the ordinary UM/UIM claim correspondence instead.\"\ndocx: \"docx/claim-rejection-umuim.docx\"\nreasoning: \"../../reasoning/claim-rejection-umuim.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\n[TELEPHONE AND EMAIL]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[RECIPIENT MAILING ADDRESS]\nRe: [INSURED] — claim [CLAIM NUMBER], policy [POLICY NUMBER]\nDear [RECIPIENT]:\nWe represent [INSURED] concerning the collision on [DATE]. Your coverage or claim position dated [DATE] states [PRECISE POSITION]. Please reconsider that position in light of [SPECIFIC POLICY PROVISIONS, FACTS AND ENCLOSED MATERIAL]. The relief sought is [RELIEF AND SUPPORTED AMOUNT, IF ANY].\nVirginia Code § 38.2-2206(H) does not permit required arbitration in the UM/UIM coverage governed by that section. This letter does not assert a unilateral right to compel arbitration. The policy’s governing jurisdiction and the basis for this proposal are [VERIFIED BASIS].\nSubject to a separate written agreement, our client proposes voluntary arbitration of [PRECISE ISSUES]. Proposed terms are [BINDING OR NONBINDING EFFECT, NEUTRAL SELECTION, RULES, VENUE, COST ALLOCATION AND SCOPE OF REVIEW]. Issues and defenses not submitted would be [RESERVED MATTERS].\nPlease respond by [REQUESTED DATE]. No arbitration agreement, tolling agreement, extension, waiver of service or settlement is created by this proposal. Applicable suit, service and policy requirements remain for separate compliance unless lawfully changed by an executed agreement or court order.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Vehicle Inspection and Property Damage Estimate Request","slug":"prop-damage","command":"/prop-damage","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Inspection/estimate request with limited authority; not a repair contract or release.","docx":"docx/prop-damage.docx","reasoning":"../../reasoning/prop-damage.md","path":"templates/insurance/prop-damage.md","docx_path":"templates/insurance/docx/prop-damage.docx","reasoning_path":"reasoning/prop-damage.md","field_count":17,"md":"---\ntitle: \"Vehicle Inspection and Property Damage Estimate Request\"\nslug: \"prop-damage\"\ncommand: \"/prop-damage\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Inspection/estimate request with limited authority; not a repair contract or release.\"\ndocx: \"docx/prop-damage.docx\"\nreasoning: \"../../reasoning/prop-damage.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[ADJUSTER OR REPAIR FACILITY]\n[RECIPIENT ADDRESS]\nRe: [CLIENT] — [VEHICLE AND LOSS DATE]\nDear [RECIPIENT NAME]:\nWe represent [CLIENT], [OWNER OR OTHER VERIFIED CAPACITY] of [VEHICLE]. Please arrange an inspection at [LOCATION] with [CONTACT] and provide a written, itemized estimate addressing collision-related damage from [INCIDENT].\nPlease identify labor, parts, rates, taxes, supplements, diagnostic findings and any proposed total-loss valuation, salvage deduction or betterment. Provide supporting photographs and the basis for disputed or excluded items. Please distinguish preexisting damage from the damage attributed to this event.\nThe authority requested or granted is limited to [SPECIFIC INSPECTION ACCESS]. No repair, destructive testing, disposal, transfer of title or release of claims is authorized by this letter. Preserve the vehicle, removed parts and electronic evidence relevant to the incident; coordinate any necessary changes before they occur.\nPlease explain the expected inspection/estimate schedule and any storage or other accruing charges. Settlement, payment allocation and any release remain subject to the client's separate approval.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Virginia Tort Claims Act Notice","slug":"govtclaim","command":"/govtclaim","category":"insurance","category_label":"Insurance claims and correspondence","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Notice for a potentially cognizable VTCA claim against the Commonwealth or a transportation district; recipient depends on the agency.","docx":"docx/govtclaim.docx","reasoning":"../../reasoning/govtclaim.md","path":"templates/insurance/govtclaim.md","docx_path":"templates/insurance/docx/govtclaim.docx","reasoning_path":"reasoning/govtclaim.md","field_count":21,"md":"---\ntitle: \"Virginia Tort Claims Act Notice\"\nslug: \"govtclaim\"\ncommand: \"/govtclaim\"\ncategory: \"insurance\"\ncategory_label: \"Insurance claims and correspondence\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Notice for a potentially cognizable VTCA claim against the Commonwealth or a transportation district; recipient depends on the agency.\"\ndocx: \"docx/govtclaim.docx\"\nreasoning: \"../../reasoning/govtclaim.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Virginia Tort Claims Act Notice — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nThis is written notice under Virginia Code § 8.01-195.6 of the claim of [CLAIMANT NAME AND CAPACITY] arising from the following occurrence.\nTime: [PRECISE DATE AND TIME]. Place: [SPECIFIC LOCATION SUFFICIENT TO IDENTIFY THE OCCURRENCE]. Agency or agencies alleged to be liable: [EXACT NAMES]. Nature of claim: [FACTUAL ACTS OR OMISSIONS, PERSONS INVOLVED IF KNOWN, INJURY AND CAUSAL CONNECTION].\nThe claimant’s injuries and losses presently known are [SUPPORTED DESCRIPTION]. Available identifying information includes [INCIDENT / REPORT NUMBER AND RELEVANT CONTACTS]. The cause of action accrued on [VERIFIED DATE]; any asserted disability or other timeliness basis is [SUPPORTED BASIS].\nThis notice is directed to [VERIFIED STATUTORY OFFICIAL AND OFFICE]: the Director of the Division of Risk Management or Attorney General for the applicable Commonwealth claim; the Commissioner of Highways for a claim alleging Department of Transportation liability; or the transportation district commission chairman for a district claim, as applicable.\nPlease acknowledge actual receipt, including date and office. The claimant reserves available rights and requests that communications be directed to [COUNSEL CONTACT]. This notice does not represent that immunity is waived beyond the statute or that a lawsuit has been filed.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Authorization to Disclose Health Information","slug":"hipaa","command":"/hipaa","category":"medical","category_label":"Medical records and bills","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Ordinary authorization to disclose defined health information to counsel; psychotherapy notes and Part 2 records excluded.","docx":"docx/hipaa.docx","reasoning":"../../reasoning/hipaa.md","path":"templates/medical/hipaa.md","docx_path":"templates/medical/docx/hipaa.docx","reasoning_path":"reasoning/hipaa.md","field_count":12,"md":"---\ntitle: \"Authorization to Disclose Health Information\"\nslug: \"hipaa\"\ncommand: \"/hipaa\"\ncategory: \"medical\"\ncategory_label: \"Medical records and bills\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Ordinary authorization to disclose defined health information to counsel; psychotherapy notes and Part 2 records excluded.\"\ndocx: \"docx/hipaa.docx\"\nreasoning: \"../../reasoning/hipaa.md\"\n---\n# AUTHORIZATION TO DISCLOSE HEALTH INFORMATION\nPatient name: [FULL NAME]\nDate of birth or secure patient identifier: [IDENTIFIER]\n## Information and recipients\nI authorize [SPECIFIC PROVIDER, PLAN OR DEFINED CLASS OF RECORD HOLDERS] to disclose [SPECIFIC RECORD TYPES AND SUBJECT MATTER] for [DATE RANGE] to [ATTORNEY OR FIRM NAME, ADDRESS AND SECURE DELIVERY DETAILS]. The purpose is [LEGAL REPRESENTATION PURPOSE OR AT THE REQUEST OF THE INDIVIDUAL].\nThis authorization excludes psychotherapy notes and substance-use-disorder records subject to 42 C.F.R. Part 2. Any separately protected category requiring additional consent must be addressed separately.\n## Expiration and revocation\nThis authorization expires on [SPECIFIC DATE OR EVENT RELATED TO THE PATIENT OR PURPOSE]. I may revoke it at any time by sending a written revocation to [RECORD HOLDER CONTACT AND ADDRESS]. Revocation does not affect action already taken in reliance on this authorization.\n## My choices and understanding\nSigning is voluntary. My treatment, payment, health-plan enrollment and eligibility for benefits will not be conditioned on signing this ordinary records-release authorization. I understand that information disclosed to the recipient may be disclosed again and may no longer be protected by HIPAA. This does not override applicable state-law limits on redisclosure.\nI may keep a copy of this signed authorization. This document authorizes only the disclosure described above; it does not authorize settlement or release legal claims.\n## Agreement\nPatient or authorized personal representative signature: ____________________\nPrinted name: [NAME]    Date: [DATE]\nRepresentative's authority, if applicable: [DESCRIPTION AND SUPPORTING DOCUMENT]\n"},{"title":"Health Insurance and Explanation of Benefits Records Request","slug":"eob","command":"/eob","category":"medical","category_label":"Medical records and bills","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Authorized request for a client-specific health-plan claim/payment record.","docx":"docx/eob.docx","reasoning":"../../reasoning/eob.md","path":"templates/medical/eob.md","docx_path":"templates/medical/docx/eob.docx","reasoning_path":"reasoning/eob.md","field_count":17,"md":"---\ntitle: \"Health Insurance and Explanation of Benefits Records Request\"\nslug: \"eob\"\ncommand: \"/eob\"\ncategory: \"medical\"\ncategory_label: \"Medical records and bills\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Authorized request for a client-specific health-plan claim/payment record.\"\ndocx: \"docx/eob.docx\"\nreasoning: \"../../reasoning/eob.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[HEALTH PLAN RECORDS CUSTODIAN]\n[RECIPIENT ADDRESS]\nRe: [CLIENT] — [PLAN OR MEMBER REFERENCE]\nDear [RECIPIENT NAME]:\nWe represent [CLIENT]. Under the enclosed authorization, please provide the health-plan records identified below for [SERVICE DATE RANGE] concerning [INCIDENT OR TREATMENT SCOPE]. Member identifiers are included in [SECURE ATTACHMENT].\nPlease include explanations of benefits, claim-line payment and adjustment histories, provider/service dates, billed and allowed amounts, payments, contractual adjustments, member responsibility, denial/reversal notices and correspondence about the identified claims. Please identify whether each listed amount is paid, denied, pending or subsequently adjusted.\nThis request does not concede that any payment creates a valid reimbursement right. Please separately identify any asserted recovery claim, its holder and its supporting plan language; do not substitute a recovery demand for the requested payment records.\nPlease send readable electronic copies through [SECURE METHOD]. If the authorization or scope needs clarification, contact [CONTACT]. Please advise of any proposed copying charge above [APPROVED LIMIT] before incurring it.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Life Care Planner Engagement Letter","slug":"lifecare-engagement","command":"/lifecare-engagement","category":"medical","category_label":"Medical records and bills","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Defined noncontingent expert engagement for a Virginia injury matter.","docx":"docx/lifecare-engagement.docx","reasoning":"../../reasoning/lifecare-engagement.md","path":"templates/medical/lifecare-engagement.md","docx_path":"templates/medical/docx/lifecare-engagement.docx","reasoning_path":"reasoning/lifecare-engagement.md","field_count":20,"md":"---\ntitle: \"Life Care Planner Engagement Letter\"\nslug: \"lifecare-engagement\"\ncommand: \"/lifecare-engagement\"\ncategory: \"medical\"\ncategory_label: \"Medical records and bills\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Defined noncontingent expert engagement for a Virginia injury matter.\"\ndocx: \"docx/lifecare-engagement.docx\"\nreasoning: \"../../reasoning/lifecare-engagement.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[LIFE CARE PLANNER]\n[RECIPIENT ADDRESS]\nRe: [CLIENT] — [MATTER]\nDear [RECIPIENT NAME]:\nWe propose engaging you to [CONSULT, EVALUATE OR PROVIDE TRIAL TESTIMONY] concerning [CLIENT'S IDENTIFIED FUTURE-CARE ISSUES]. Please confirm qualifications, availability and any conflict before accepting materials or work.\nThe assignment is [SPECIFIC QUESTIONS AND DELIVERABLES], based on [RECORDS, TREATING RECOMMENDATIONS AND OTHER IDENTIFIED INPUTS]. Please distinguish medical recommendations, independent assumptions, service frequency, duration, unit costs and the sources/date of pricing. Identify information still needed and limits outside your expertise.\nCompensation is [ACTUAL HOURLY OR FIXED TERMS], with [RETAINER, EXPENSE AND INVOICE TERMS]. Compensation is not contingent on a favorable opinion, settlement or litigation result. Work above [BUDGET OR AUTHORIZED SCOPE] requires prior approval.\nPlease deliver [REPORT OR CONSULTING PRODUCT] by [AGREED DATE] and coordinate any examination through this office. Maintain confidentiality and preserve relied-on materials. Disclosure and deposition obligations depend on the role ultimately designated and applicable orders; no blanket privilege is promised.\nPlease confirm your acceptance of the scope and terms in writing.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Medical Records Summary","slug":"medsummary","command":"/medsummary","category":"medical","category_label":"Medical records and bills","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Medical Records Summary for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/medsummary.docx","reasoning":"../../reasoning/medsummary.md","path":"templates/medical/medsummary.md","docx_path":"templates/medical/docx/medsummary.docx","reasoning_path":"reasoning/medsummary.md","field_count":15,"md":"---\ntitle: \"Medical Records Summary\"\nslug: \"medsummary\"\ncommand: \"/medsummary\"\ncategory: \"medical\"\ncategory_label: \"Medical records and bills\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Medical Records Summary for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/medsummary.docx\"\nreasoning: \"../../reasoning/medsummary.md\"\n---\n# Medical Records Summary\nPatient: [NAME]    Matter: [CASE REFERENCE]\nPrepared for: [AUTHORIZED RECIPIENT]    As of: [DATE]\nScope: [QUICK SUMMARY / FULL TREATMENT HISTORY, DATE RANGE AND INCLUDED PROVIDERS]\n## Source coverage\n[LIST EACH REVIEWED FILE, VERSION, PROVIDER AND DATE RANGE. IDENTIFY MISSING RECORDS, UNREADABLE PAGES, DUPLICATES AND MATERIAL LIMITATIONS.]\n## Treatment history\n[DATE OR DOCUMENTED APPROXIMATION] — [PROVIDER AND ENCOUNTER TYPE]\nReported symptoms: [ATTRIBUTED PATIENT REPORT WITH SOURCE PAGE].\nFindings and assessment: [DOCUMENTED CLINICIAN FINDINGS AND DIAGNOSES WITH SOURCE PAGE].\nTreatment and plan: [DOCUMENTED PROCEDURES, MEDICATIONS, REFERRALS AND FOLLOW-UP WITH SOURCE PAGE].\n[REPEAT CHRONOLOGICALLY FOR THE SELECTED SCOPE.]\n## Current documented status\n[LAST DOCUMENTED STATUS, RESTRICTIONS, PROGNOSIS AND FUTURE-CARE OPINIONS, ATTRIBUTED TO THE ACTUAL PROVIDER AND DATE. DISTINGUISH INJURY HISTORY FROM A PROVIDER’S CAUSATION OPINION.]\n## Open questions\n[CONFLICTING RECORDS, UNEXPLAINED GAPS AND ITEMS NEEDING FOLLOW-UP. A GAP IN THE AVAILABLE FILES IS NOT PROOF THAT NO CARE OCCURRED.]\nReviewer: [NAME]    Review date: [ACTUAL DATE]\n"},{"title":"Request for Itemized Medical Bills","slug":"medbills","command":"/medbills","category":"medical","category_label":"Medical records and bills","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Virginia personal-injury matter; ordinary adult claimant.","docx":"docx/medbills.docx","reasoning":"../../reasoning/medbills.md","path":"templates/medical/medbills.md","docx_path":"templates/medical/docx/medbills.docx","reasoning_path":"reasoning/medbills.md","field_count":20,"md":"---\ntitle: \"Request for Itemized Medical Bills\"\nslug: \"medbills\"\ncommand: \"/medbills\"\ncategory: \"medical\"\ncategory_label: \"Medical records and bills\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia personal-injury matter; ordinary adult claimant.\"\ndocx: \"docx/medbills.docx\"\nreasoning: \"../../reasoning/medbills.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION]\n[DELIVERY ADDRESS]\nRe: Request for Itemized Medical Bills — [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [PATIENT FULL NAME], date of birth [DATE], regarding [CLAIM]. Please provide the patient's itemized listing of charges and current account balance for services from [START DATE] through [END DATE]. The account number, if known, is [ACCOUNT NUMBER].\nPlease identify dates of service, services billed and charges, together with payment and adjustment information maintained in the account records, so that charges can be reconciled with the current balance.\nUnder Virginia Code section 8.01-413(B5), a patient's account balance or itemized listing of charges must be supplied without charge to the patient or the patient's attorney up to three times in a 12-month period. [STATE VERIFIED REQUEST HISTORY OR REQUEST CONFIRMATION OF PRIOR REQUESTS].\nThe patient's authorization is [ENCLOSURE IDENTIFIER]. Please send the material to [AUTHORIZED SECURE DESTINATION] in [FORMAT]. If any requested detail is not maintained, please identify what is available.\nThis request seeks billing information; it does not promise payment, assign proceeds or create a letter of protection.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Request for Medical Records","slug":"medrecords","command":"/medrecords","category":"medical","category_label":"Medical records and bills","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Virginia adult patient records requested by the patient’s authorized attorney for anticipated or pending litigation.","docx":"docx/medrecords.docx","reasoning":"../../reasoning/medrecords.md","path":"templates/medical/medrecords.md","docx_path":"templates/medical/docx/medrecords.docx","reasoning_path":"reasoning/medrecords.md","field_count":23,"md":"---\ntitle: \"Request for Medical Records\"\nslug: \"medrecords\"\ncommand: \"/medrecords\"\ncategory: \"medical\"\ncategory_label: \"Medical records and bills\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia adult patient records requested by the patient’s authorized attorney for anticipated or pending litigation.\"\ndocx: \"docx/medrecords.docx\"\nreasoning: \"../../reasoning/medrecords.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION]\n[DELIVERY ADDRESS]\nRe: Request for Medical Records — [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [PATIENT FULL NAME] in connection with [CLAIM]. The patient's date of birth is [DATE OF BIRTH]; the patient or account identifier, if needed, is [IDENTIFIER].\nPursuant to Virginia Code section 8.01-413(B), please provide the health records for treatment from [START DATE] through [END DATE], including [RELEVANT RECORD CATEGORIES]. [IDENTIFY ANY SPECIFICALLY REQUESTED AUDIT TRAIL OR IMAGING STUDIES].\nThe patient's signed authorization identifying the records and permitted recipient is [ENCLOSURE IDENTIFIER]. Please deliver the requested records in [REQUESTED FORMAT] to [AUTHORIZED SECURE DESTINATION].\nPlease advise us of the most cost-effective production method and any expected lawful charge before incurring charges above [APPROVED AMOUNT]. If the requested electronic format is unavailable, please identify the available format.\nSection 8.01-413(B) generally requires production within 30 days after receipt of a compliant request. If you cannot meet that period, please send the written reason for delay and comply within the additional period the statute permits.\nPlease identify any requested records not maintained by your office and the appropriate custodian, if known.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Conditional Proposal to Resolve Medical Payments Claim","slug":"medpay-response-negotiate","command":"/medpay-response-negotiate","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Conditional Proposal to Resolve Medical Payments Claim for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/medpay-response-negotiate.docx","reasoning":"../../reasoning/medpay-response-negotiate.md","path":"templates/liens/medpay-response-negotiate.md","docx_path":"templates/liens/docx/medpay-response-negotiate.docx","reasoning_path":"reasoning/medpay-response-negotiate.md","field_count":17,"md":"---\ntitle: \"Conditional Proposal to Resolve Medical Payments Claim\"\nslug: \"medpay-response-negotiate\"\ncommand: \"/medpay-response-negotiate\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Conditional Proposal to Resolve Medical Payments Claim for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/medpay-response-negotiate.docx\"\nreasoning: \"../../reasoning/medpay-response-negotiate.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Conditional Proposal to Resolve Medical Payments Claim — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nWe respond to the asserted recovery claim of $[AMOUNT] for [CLIENT, POLICY AND INCIDENT]. The presently verified basis, if any, on which recovery is legally available is [EXACT AUTHORITY, POLICY PROVISION AND SCOPE FACTS]. Our objections and reservations are [SPECIFIC GROUNDS].\nWith the client’s authority and without admitting an unsupported recovery right, we offer $[AMOUNT] to resolve [PRECISE CLAIM AND PAYMENT PERIOD]. The factual basis for this proposal is [ACTUAL RECOVERY, DOCUMENTED LOSSES, FEES, COSTS AND OTHER RELEVANT CONSTRAINTS].\nAny claimed entitlement to a fee allocation or other reduction is based on [SPECIFIC APPLICABLE LAW OR WRITTEN TERM]. No automatic made-whole or common-fund deduction is assumed.\nAcceptance must be in writing by an authorized representative and state the covered claim, payment deadline, authorized payee and agreed satisfaction or release terms. No payment is authorized by this proposal alone. If Virginia law bars the asserted recovery right, please withdraw the claim rather than treating this proposal as an admission of liability.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Dispute of Medicare Conditional Payments","slug":"medicare-dispute","command":"/medicare-dispute","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Dispute of Medicare Conditional Payments for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/medicare-dispute.docx","reasoning":"../../reasoning/medicare-dispute.md","path":"templates/liens/medicare-dispute.md","docx_path":"templates/liens/docx/medicare-dispute.docx","reasoning_path":"reasoning/medicare-dispute.md","field_count":22,"md":"---\ntitle: \"Dispute of Medicare Conditional Payments\"\nslug: \"medicare-dispute\"\ncommand: \"/medicare-dispute\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Dispute of Medicare Conditional Payments for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/medicare-dispute.docx\"\nreasoning: \"../../reasoning/medicare-dispute.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Dispute of Medicare Conditional Payments — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nWe dispute the following entries in [CPL / CPN OR OTHER INTERIM STATEMENT, DATE] for [BENEFICIARY], BCRC case [CASE ID], incident [DATE]. Our proof of representation is [REFERENCE].\nDisputed entry: [CLAIM IDENTIFIER, PROVIDER, SERVICE DATE, DESCRIPTION AND PAID AMOUNT]. Requested correction: [REMOVE OR CORRECT SPECIFIC ENTRY]. Factual basis: [WHY THIS SERVICE IS UNRELATED OR THE ENTRY IS INCORRECT]. Supporting record: [DOCUMENT TITLE, DATE AND EXACT PAGE].\n[REPEAT FOR EACH DISPUTED ENTRY, WITHOUT REMOVING UNDISPUTED ITEMS]. Total specifically disputed: $[VERIFIED SUM]. This figure describes this submission and is not a final Medicare recovery calculation.\nPlease review the enclosed support, correct the identified entries as warranted and provide an updated statement and written determination. Current settlement status and any requested supporting settlement documents are [ACTUAL STATUS AND ATTACHMENTS].\nThis submission concerns [IDENTIFIED INTERIM DISPUTE PROCEDURE]. If a formal demand has issued, the demand’s appeal procedures and deadlines must be separately addressed; this letter does not represent that an appeal, waiver or extension has been filed.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Health Plan Governing Documents Request","slug":"erisa-plan-docs","command":"/erisa-plan-docs","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Participant-authorized ERISA document request to the plan administrator; not a benefits appeal.","docx":"docx/erisa-plan-docs.docx","reasoning":"../../reasoning/erisa-plan-docs.md","path":"templates/liens/erisa-plan-docs.md","docx_path":"templates/liens/docx/erisa-plan-docs.docx","reasoning_path":"reasoning/erisa-plan-docs.md","field_count":16,"md":"---\ntitle: \"Health Plan Governing Documents Request\"\nslug: \"erisa-plan-docs\"\ncommand: \"/erisa-plan-docs\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Participant-authorized ERISA document request to the plan administrator; not a benefits appeal.\"\ndocx: \"docx/erisa-plan-docs.docx\"\nreasoning: \"../../reasoning/erisa-plan-docs.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[NAMED PLAN ADMINISTRATOR]\n[RECIPIENT ADDRESS]\nRe: [PARTICIPANT] — [PLAN AND PLAN YEAR]\nDear [RECIPIENT NAME]:\nWe represent [PARTICIPANT OR BENEFICIARY], whose authorization is [ENCLOSED OR ALREADY ACCEPTED]. On that person's behalf, we request the documents subject to 29 U.S.C. § 1024(b)(4), including the latest updated summary plan description, latest annual report, any terminal report, and the bargaining agreement, trust agreement, contract or other instruments under which the plan is established or operated.\nPlease include the governing instruments and amendments applicable to [RELEVANT BENEFIT AND INCIDENT DATES], particularly provisions addressing subrogation, reimbursement, reductions, allocation and recovery from third-party proceeds. If you contend an item is outside the statutory request, identify that item and your position; we also request it voluntarily to evaluate [SPECIFIC ASSERTED CLAIM].\nPlease identify the named administrator and the plan's funding arrangement. Any request for a payment ledger or claim-specific recovery calculation is supplemental and should be identified separately from the governing-document production.\nPlease provide electronic copies through [SECURE METHOD], or advise of a lawful copying charge in advance. This request neither acknowledges a valid lien nor assumes that a summary alone establishes every asserted recovery term.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Health Plan Recovery Claim Notice","slug":"erisa","command":"/erisa","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Notice to the asserted ERISA recovery claimant and request for its position; distinct from the plan-administrator statutory document request.","docx":"docx/erisa.docx","reasoning":"../../reasoning/erisa.md","path":"templates/liens/erisa.md","docx_path":"templates/liens/docx/erisa.docx","reasoning_path":"reasoning/erisa.md","field_count":16,"md":"---\ntitle: \"Health Plan Recovery Claim Notice\"\nslug: \"erisa\"\ncommand: \"/erisa\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Notice to the asserted ERISA recovery claimant and request for its position; distinct from the plan-administrator statutory document request.\"\ndocx: \"docx/erisa.docx\"\nreasoning: \"../../reasoning/erisa.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Health Plan Recovery Claim Notice — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nWe represent [PARTICIPANT / BENEFICIARY] concerning [INCIDENT AND DATE]. The plan and member identifiers are [MINIMUM NECESSARY IDENTIFIERS]. Our authority to communicate about the claim is [AUTHORIZATION REFERENCE].\nPlease advise whether [PLAN] asserts subrogation or reimbursement against this matter’s recovery. Identify the claimant, fiduciary or agent authorized to act, the governing plan and effective provisions, funding status, and the precise contractual and legal basis for the claimed interest.\nPlease provide an itemized ledger of related amounts actually paid, with service dates, providers, adjustments, refunds and the current claimed balance. Identify disputed or unrelated charges separately and explain any future-payment component or continuing reporting request.\nPlease direct claim communications to [CONTACT] and identify the person empowered to resolve the asserted interest. This notice neither concedes an enforceable lien nor promises payment before entitlement and amount are resolved. Protected funds will be handled in accordance with applicable duties; any plan-document request to the named administrator is separate.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Health Plan Recovery Compromise Proposal","slug":"erisa-negotiation","command":"/erisa-negotiation","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Negotiated ERISA recovery resolution based on verified plan terms and settlement economics.","docx":"docx/erisa-negotiation.docx","reasoning":"../../reasoning/erisa-negotiation.md","path":"templates/liens/erisa-negotiation.md","docx_path":"templates/liens/docx/erisa-negotiation.docx","reasoning_path":"reasoning/erisa-negotiation.md","field_count":23,"md":"---\ntitle: \"Health Plan Recovery Compromise Proposal\"\nslug: \"erisa-negotiation\"\ncommand: \"/erisa-negotiation\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Negotiated ERISA recovery resolution based on verified plan terms and settlement economics.\"\ndocx: \"docx/erisa-negotiation.docx\"\nreasoning: \"../../reasoning/erisa-negotiation.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Health Plan Recovery Compromise Proposal — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nWe write concerning [PLAN’S] asserted recovery of $[AMOUNT] for [PARTICIPANT AND INCIDENT]. The governing documents reviewed are [EXACT DOCUMENTS, DATES AND PROVISIONS]. The current payment ledger is [DATE], subject to [SPECIFIC DISPUTED ITEMS].\nThe proposed third-party recovery is $[GROSS]. Supported attorney fees are $[FEES], costs $[COSTS], other claims $[AMOUNT], and the projected client recovery before this claim is $[AMOUNT]. The material liability, collection and damages limitations are [FACTS AND SUPPORT].\nOur position on enforceability, allocation and any fee contribution is [PLAN-TEXT AND LAW-BASED ANALYSIS]. Independently of any contested entitlement to a reduction, the participant proposes a negotiated payment of $[OFFER] in full satisfaction of [PRECISELY DEFINED RECOVERY INTEREST].\nPlease confirm written approval by an authorized decision-maker, the exact claims and payment period released, the payoff deadline and method, and the treatment of future benefits or reimbursement demands. No acceptance, release or payment is represented as complete by this proposal. We request a response by [REASONABLE DATE].\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Health Plan Recovery Payment Transmittal","slug":"erisa-payment","command":"/erisa-payment","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Transmit an actually authorized ERISA payoff; a separate signed satisfaction controls release.","docx":"docx/erisa-payment.docx","reasoning":"../../reasoning/erisa-payment.md","path":"templates/liens/erisa-payment.md","docx_path":"templates/liens/docx/erisa-payment.docx","reasoning_path":"reasoning/erisa-payment.md","field_count":22,"md":"---\ntitle: \"Health Plan Recovery Payment Transmittal\"\nslug: \"erisa-payment\"\ncommand: \"/erisa-payment\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Transmit an actually authorized ERISA payoff; a separate signed satisfaction controls release.\"\ndocx: \"docx/erisa-payment.docx\"\nreasoning: \"../../reasoning/erisa-payment.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Health Plan Recovery Payment Transmittal — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nUnder [WRITTEN PAYOFF AGREEMENT / RELEASE, DATE AND SIGNATORY], the agreed payment for [PARTICIPANT, PLAN AND INCIDENT] is $[AMOUNT]. The agreement resolves [EXACT RECOVERY INTEREST AND PERIOD], subject to [ACTUAL CONDITIONS].\nPayment status is [ENCLOSED CHECK / VERIFIED TRANSFER / OTHER ACTUAL STATUS], reference [IDENTIFIER], payable to [INDEPENDENTLY VERIFIED PAYEE]. A copy of the governing payoff approval is [ACTUAL ENCLOSURE]. This letter does not state that funds have cleared unless confirmed by [ACTUAL EVIDENCE].\nPlease apply the payment to the identified claim and return written confirmation of receipt and satisfaction consistent with the agreement. Identify any discrepancy immediately. The treatment of future related payments or benefits is [EXACT AGREED TREATMENT]; no broader waiver is inferred.\nPlease send the confirmation securely to [CONTACT]. This transmittal does not amend the agreed payoff or create a new undertaking beyond the identified written terms.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Hospital Lien Payment and Release Request","slug":"hospital-payment","command":"/hospital-payment","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Payment transmittal under a verified hospital-lien compromise; no fictional payment receipt.","docx":"docx/hospital-payment.docx","reasoning":"../../reasoning/hospital-payment.md","path":"templates/liens/hospital-payment.md","docx_path":"templates/liens/docx/hospital-payment.docx","reasoning_path":"reasoning/hospital-payment.md","field_count":18,"md":"---\ntitle: \"Hospital Lien Payment and Release Request\"\nslug: \"hospital-payment\"\ncommand: \"/hospital-payment\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Payment transmittal under a verified hospital-lien compromise; no fictional payment receipt.\"\ndocx: \"docx/hospital-payment.docx\"\nreasoning: \"../../reasoning/hospital-payment.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[HOSPITAL LIEN HOLDER OR AUTHORIZED AGENT]\n[RECIPIENT ADDRESS]\nRe: [PATIENT] — [ACCOUNT AND LIEN REFERENCE]\nDear [RECIPIENT NAME]:\nWe write concerning your lien for [IDENTIFIED SERVICES] and the written payoff agreement dated [DATE]. The agreed amount is [AMOUNT], and the payment status is [ENCLOSED CHECK DETAILS OR VERIFIED ELECTRONIC PAYMENT REFERENCE AND DATE].\nPlease apply the payment only to [IDENTIFIED ACCOUNTS] under that agreement. The agreed treatment of the remaining balance is [EXACT RELEASE OR BALANCE TERMS]. Enclosed are [ACTUAL AGREEMENT AND PAYMENT DOCUMENTS].\nUpon satisfaction of the agreed payment condition, please provide a signed release/satisfaction of the identified lien, a final account statement reflecting the agreed balance and confirmation of any required notice or record update. Please identify any additional document needed to complete that process.\nThis transmittal does not extend the compromise to other accounts, other creditors or a separate governmental claim. If the payment details or account allocation differ from your records, contact [CONTACT] before applying or returning the funds.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Hospital Lien Payoff Cover Letter","slug":"lien-payoff-docs-hospital","command":"/lien-payoff-docs-hospital","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Final document and payment package for an identified private hospital lien; distinguishes lien satisfaction from patient-account debt.","docx":"docx/lien-payoff-docs-hospital.docx","reasoning":"../../reasoning/lien-payoff-docs-hospital.md","path":"templates/liens/lien-payoff-docs-hospital.md","docx_path":"templates/liens/docx/lien-payoff-docs-hospital.docx","reasoning_path":"reasoning/lien-payoff-docs-hospital.md","field_count":22,"md":"---\ntitle: \"Hospital Lien Payoff Cover Letter\"\nslug: \"lien-payoff-docs-hospital\"\ncommand: \"/lien-payoff-docs-hospital\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Final document and payment package for an identified private hospital lien; distinguishes lien satisfaction from patient-account debt.\"\ndocx: \"docx/lien-payoff-docs-hospital.docx\"\nreasoning: \"../../reasoning/lien-payoff-docs-hospital.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Hospital Lien Payoff Cover Letter — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nWe transmit the closing package for [PATIENT, INCIDENT AND HOSPITAL ACCOUNT], under [EXECUTED PAYOFF AGREEMENT OR ORDER, DATE AND SIGNATORY]. The agreed payoff is $[AMOUNT], subject to [ACTUAL CONDITIONS AND DEADLINE].\nThe package contains [ACTUAL CHECK / PAYMENT CONFIRMATION], [PAYOFF APPROVAL], and [PROPOSED OR EXECUTED SATISFACTION, ACCURATELY LABELED]. Payment status is [VERIFIED STATUS AND REFERENCE], with payee [VERIFIED LEGAL NAME].\nPlease apply the payment as agreed and return written confirmation releasing [EXACT STATUTORY LIEN AND RECOVERY INTEREST]. The patient-account balance is treated as follows: [EXPRESS AGREED DISCHARGE OR RESERVED DEBT]. Satisfaction of a limited statutory lien alone is not represented as cancellation of a larger patient debt.\nPlease confirm any required notice of satisfaction to [IDENTIFIED RECIPIENTS] and identify any discrepancy before closing the file. No Commonwealth, Medicaid, unrelated provider or other third-party interest is released by this transmittal.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Hospital Lien Verification Request","slug":"hospital-lien","command":"/hospital-lien","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Verification of a hospital’s asserted interest before allocation of a Virginia PI recovery; private-provider and Commonwealth claims kept distinct.","docx":"docx/hospital-lien.docx","reasoning":"../../reasoning/hospital-lien.md","path":"templates/liens/hospital-lien.md","docx_path":"templates/liens/docx/hospital-lien.docx","reasoning_path":"reasoning/hospital-lien.md","field_count":17,"md":"---\ntitle: \"Hospital Lien Verification Request\"\nslug: \"hospital-lien\"\ncommand: \"/hospital-lien\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Verification of a hospital’s asserted interest before allocation of a Virginia PI recovery; private-provider and Commonwealth claims kept distinct.\"\ndocx: \"docx/hospital-lien.docx\"\nreasoning: \"../../reasoning/hospital-lien.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Hospital Lien Verification Request - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [PATIENT] in connection with [INCIDENT] and treatment account [NUMBER]. We received [IDENTIFIED LIEN NOTICE OR COMMUNICATION] asserting $[AMOUNT]. Please identify the claimant’s exact legal name and the statutory, contractual or assignment basis asserted.\nPlease provide the notice relied upon, the date and method by which it was given, and the persons to whom it was delivered. Provide an itemized statement of relevant services, dates, charges, payments, adjustments and current balance.\nIf you rely on Virginia Code section 8.01-66.2, identify the qualifying provider category and amount claimed under that provision. If a Commonwealth, public-institution or program claim under section 8.01-66.9 or another law is asserted, identify that separate basis and the responsible agency or office.\nPlease explain the relationship between the asserted lien amount and any remaining patient debt, and provide the current payoff and conditions for a written satisfaction. No acknowledgment of validity, priority or amount is made by requesting this information.\nWe will evaluate the asserted interest and handle protected funds in accordance with applicable duties. Please send the records through [SECURE METHOD] to [CONTACT].\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Letter of Protection","slug":"lop","command":"/lop","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Limited negotiated undertaking concerning provider payment from identified recovery funds; no personal fee guarantee.","docx":"docx/lop.docx","reasoning":"../../reasoning/lop.md","path":"templates/liens/lop.md","docx_path":"templates/liens/docx/lop.docx","reasoning_path":"reasoning/lop.md","field_count":8,"md":"---\ntitle: \"Letter of Protection\"\nslug: \"lop\"\ncommand: \"/lop\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Limited negotiated undertaking concerning provider payment from identified recovery funds; no personal fee guarantee.\"\ndocx: \"docx/lop.docx\"\nreasoning: \"../../reasoning/lop.md\"\n---\n# LETTER OF PROTECTION\nDate: [DATE]\nPatient/client: [NAME]    Provider: [LEGAL NAME]\nMatter: [INCIDENT AND CLAIM]\n## Limited undertaking\nWith the client's authorization below, [FIRM] agrees, upon actual receipt of recovery funds for this matter, to protect the provider's properly supported claim for [IDENTIFIED SERVICES AND DATES], subject to applicable law, superior interests, the client's rights and any written compromise. The current itemized balance is [AMOUNT AND STATEMENT DATE].\nThis undertaking concerns funds actually received and legally available for the claim. It is not a guarantee of a recovery, a promise by the firm to pay from its own funds, or an admission that every charge or asserted lien is valid. No unrelated treatment or future charge is included without a further written agreement.\nThe provider agrees to [PRECISE BILLING, COLLECTION-FORBEARANCE AND NOTICE TERMS]. Any reduction or satisfaction of the patient's remaining debt must be separately stated in writing. A limitation on a statutory lien does not itself eliminate the underlying bill.\nIf entitlement is disputed, the disputed portion will be held and handled as required by law and professional obligations while the dispute is resolved. Undisputed funds will not be withheld merely to obtain a concession.\n## Agreement\nClient authorization and signature: ____________________    Date: [DATE]\nProvider acceptance and authorized signer: ____________________    Date: [DATE]\nAttorney name: [NAME]    Signature: ____________________    Date: [DATE]\n"},{"title":"Letter of Protection Payoff Confirmation Request","slug":"lop-payoff-confirmation","command":"/lop-payoff-confirmation","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Verification of an existing actual LOP or contractual undertaking; not creation of a new promise by the lawyer.","docx":"docx/lop-payoff-confirmation.docx","reasoning":"../../reasoning/lop-payoff-confirmation.md","path":"templates/liens/lop-payoff-confirmation.md","docx_path":"templates/liens/docx/lop-payoff-confirmation.docx","reasoning_path":"reasoning/lop-payoff-confirmation.md","field_count":18,"md":"---\ntitle: \"Letter of Protection Payoff Confirmation Request\"\nslug: \"lop-payoff-confirmation\"\ncommand: \"/lop-payoff-confirmation\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Verification of an existing actual LOP or contractual undertaking; not creation of a new promise by the lawyer.\"\ndocx: \"docx/lop-payoff-confirmation.docx\"\nreasoning: \"../../reasoning/lop-payoff-confirmation.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Letter of Protection Payoff Confirmation Request - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT] concerning [MATTER] and treatment account [NUMBER]. The letter of protection or other payment undertaking dated [DATE] is [IDENTIFIER AND ACTUAL SIGNATORIES].\nPlease provide an itemized payoff statement as of [DATE], showing original charges, insurance payments, contractual adjustments, other credits, prior payments and the remaining balance. Identify any interest or charge and the provision authorizing it.\nPlease confirm whether $[PROPOSED OR REPORTED PAYOFF] would satisfy [PRECISE OBLIGATION] if paid by [DATE], and identify any amount or claim that would remain. Please provide the release or acknowledgment to be furnished after actual payment.\nThe status of settlement funds is [ACTUAL STATUS]. This request does not change the underlying agreement, guarantee a recovery, admit a disputed balance or create a new personal payment obligation by counsel.\nPlease send your confirmation and supporting records through [SECURE METHOD]. Payment instructions will be verified independently before any transfer.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Letter of Protection Reduction Proposal","slug":"lop-payoff-reduction","command":"/lop-payoff-reduction","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Negotiation to modify an existing LOP; obligations depend on its actual terms and signatories.","docx":"docx/lop-payoff-reduction.docx","reasoning":"../../reasoning/lop-payoff-reduction.md","path":"templates/liens/lop-payoff-reduction.md","docx_path":"templates/liens/docx/lop-payoff-reduction.docx","reasoning_path":"reasoning/lop-payoff-reduction.md","field_count":22,"md":"---\ntitle: \"Letter of Protection Reduction Proposal\"\nslug: \"lop-payoff-reduction\"\ncommand: \"/lop-payoff-reduction\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Negotiation to modify an existing LOP; obligations depend on its actual terms and signatories.\"\ndocx: \"docx/lop-payoff-reduction.docx\"\nreasoning: \"../../reasoning/lop-payoff-reduction.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Letter of Protection Reduction Proposal - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT] regarding [MATTER]. The existing letter of protection dated [DATE] concerns [PROVIDER, ACCOUNT AND IDENTIFIED SERVICES]. We request a negotiated modification of the balance or payment obligation described below.\nThe verified balance is $[AMOUNT], with credits and adjustments shown in [SOURCE]. The claim’s recovery and available funds are [SUPPORTED STATUS]. The reasons for the proposed reduction are [SPECIFIC FINANCIAL, LIABILITY, CAUSATION OR OTHER SUPPORTED FACTS].\nWith the client’s authority, we propose payment of $[AMOUNT] on [TERMS] in satisfaction of [EXACT DEBT, LIEN OR UNDERTAKING]. Please state in writing whether this would also discharge the remaining patient balance and any obligation asserted against counsel, and identify any exception.\nThe existing undertaking is not modified until the persons whose agreement is needed actually agree. We do not represent that silence accepts this proposal, that payment has occurred or that the original undertaking permits unilateral reduction.\nPlease provide written acceptance or a counterproposal, including the promised satisfaction document, to [CONTACT] by [REQUESTED DATE].\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Medical Provider Balance and Lien Reduction Request","slug":"provider-lien","command":"/provider-lien","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Negotiation with a private medical provider about its identified bill/lien; not Medicare, Medicaid, ERISA or Commonwealth lien compromise.","docx":"docx/provider-lien.docx","reasoning":"../../reasoning/provider-lien.md","path":"templates/liens/provider-lien.md","docx_path":"templates/liens/docx/provider-lien.docx","reasoning_path":"reasoning/provider-lien.md","field_count":23,"md":"---\ntitle: \"Medical Provider Balance and Lien Reduction Request\"\nslug: \"provider-lien\"\ncommand: \"/provider-lien\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Negotiation with a private medical provider about its identified bill/lien; not Medicare, Medicaid, ERISA or Commonwealth lien compromise.\"\ndocx: \"docx/provider-lien.docx\"\nreasoning: \"../../reasoning/provider-lien.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Medical Provider Balance and Lien Reduction Request - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT] regarding treatment for [INCIDENT] and account [IDENTIFIER]. Your asserted balance or lien is $[AMOUNT], based on [ACTUAL NOTICE OR STATEMENT]. Please confirm the current itemization, payments, adjustments and legal or contractual basis for the amount claimed.\nThe proposed resolution of the injury claim is [SUPPORTED SETTLEMENT OR RECOVERY STATUS]. Relevant limits on available funds and disputed issues are [FACTS]. Subject to the client’s authority and a written agreement, we request acceptance of $[OFFER] in [EXACT PROPOSED SATISFACTION OR REDUCTION].\nPlease state whether acceptance would discharge the identified lien, the underlying patient balance, both, or a specified portion only. Identify any remaining claim and any required release. Payment timing and conditions proposed are [TERMS].\nThis is a request for a negotiated reduction. It does not represent that a statutory cap on a lien necessarily extinguishes the remaining patient debt or that funds have been paid. We will handle protected funds according to applicable duties while the issue is resolved.\nPlease provide your written response to [CONTACT] by [REQUESTED DATE].\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Medical Provider Protection Agreement Payoff Cover Letter","slug":"lien-payoff-docs-lop","command":"/lien-payoff-docs-lop","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Closing package under an actual letter of protection or provider agreement; no invented statutory lien or personal guaranty.","docx":"docx/lien-payoff-docs-lop.docx","reasoning":"../../reasoning/lien-payoff-docs-lop.md","path":"templates/liens/lien-payoff-docs-lop.md","docx_path":"templates/liens/docx/lien-payoff-docs-lop.docx","reasoning_path":"reasoning/lien-payoff-docs-lop.md","field_count":21,"md":"---\ntitle: \"Medical Provider Protection Agreement Payoff Cover Letter\"\nslug: \"lien-payoff-docs-lop\"\ncommand: \"/lien-payoff-docs-lop\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Closing package under an actual letter of protection or provider agreement; no invented statutory lien or personal guaranty.\"\ndocx: \"docx/lien-payoff-docs-lop.docx\"\nreasoning: \"../../reasoning/lien-payoff-docs-lop.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Medical Provider Protection Agreement Payoff Cover Letter — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nFor [PATIENT, INCIDENT AND PROVIDER ACCOUNT], we enclose the documents supporting payment under [ACTUAL LETTER OF PROTECTION / PAYOFF AGREEMENT AND DATE]. The agreed amount is $[AMOUNT], resolving [EXACT SERVICES, DATES AND INTEREST].\nThe package includes [ACTUAL PAYMENT OR VERIFIED PAYMENT REFERENCE], [SIGNED PAYOFF TERMS] and [SATISFACTION DOCUMENT WITH ACTUAL SIGNATURE STATUS]. Payment is [VERIFIED STATUS] to [AUTHORIZED PAYEE].\nPlease confirm application to the identified account and release of the obligations described in the payoff agreement. The treatment of the remaining patient balance, any recovery interest and any firm undertaking is [PRECISE AGREED TERMS]. No additional personal guaranty, assignment or promise to pay unrelated charges is made by this letter.\nPlease return the agreed written satisfaction and notify [CONTACT] of any discrepancy. Obligations not within the actual negotiated release remain governed by their existing terms and applicable law.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Medicare MSP Claim Notification","slug":"medicare-notice","command":"/medicare-notice","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Medicare MSP Claim Notification for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/medicare-notice.docx","reasoning":"../../reasoning/medicare-notice.md","path":"templates/liens/medicare-notice.md","docx_path":"templates/liens/docx/medicare-notice.docx","reasoning_path":"reasoning/medicare-notice.md","field_count":21,"md":"---\ntitle: \"Medicare MSP Claim Notification\"\nslug: \"medicare-notice\"\ncommand: \"/medicare-notice\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Medicare MSP Claim Notification for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/medicare-notice.docx\"\nreasoning: \"../../reasoning/medicare-notice.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Medicare MSP Claim Notification — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nWe report a potential Medicare Secondary Payer recovery matter for [BENEFICIARY NAME, DATE OF BIRTH, ADDRESS AND TELEPHONE]. Medicare identifier: [MBI THROUGH AN AUTHORIZED SECURE CHANNEL]. Date of incident: [DATE].\nThe incident involved [LIABILITY / NO-FAULT / WORKERS COMPENSATION, WITH FACTUAL DESCRIPTION]. Claimed injuries, body parts and treatment are [SUPPORTED DESCRIPTION]. The potentially responsible insurer or entity is [LEGAL NAME, ADDRESS, CLAIM NUMBER AND CONTACT]. The insured or responsible party is [NAME AND CONTACT IF KNOWN].\nThe claim is [ACTUAL STATUS]. Any settlement, judgment, award or other payment is [VERIFIED STATUS, DATE AND AMOUNT]; any ongoing responsibility for medical expenses is [KNOWN STATUS OR UNKNOWN]. Related recovery matters or prior reports are [CASE IDs AND REFERENCES / NONE KNOWN AFTER REVIEW].\nProof of representation is [ACTUAL ATTACHMENT OR EXISTING BCRC REFERENCE]. Please confirm creation or association of the recovery case, identify missing information and provide current conditional-payment information to the authorized recipient.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Medicare Notice of Representation","slug":"medicare-bcrc","command":"/medicare-bcrc","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Medicare Notice of Representation for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/medicare-bcrc.docx","reasoning":"../../reasoning/medicare-bcrc.md","path":"templates/liens/medicare-bcrc.md","docx_path":"templates/liens/docx/medicare-bcrc.docx","reasoning_path":"reasoning/medicare-bcrc.md","field_count":21,"md":"---\ntitle: \"Medicare Notice of Representation\"\nslug: \"medicare-bcrc\"\ncommand: \"/medicare-bcrc\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Medicare Notice of Representation for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/medicare-bcrc.docx\"\nreasoning: \"../../reasoning/medicare-bcrc.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Medicare Notice of Representation — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nWe represent [BENEFICIARY NAME] concerning [INCIDENT AND DATE]. Medicare identifier: [MBI THROUGH AN AUTHORIZED SECURE CHANNEL]. BCRC recovery case ID: [EXISTING CASE ID / NOT YET ASSIGNED]. The beneficiary’s contact information is [VERIFIED ADDRESS AND TELEPHONE].\nEnclosed or uploaded is [SIGNED AND DATED PROOF OF REPRESENTATION, IDENTIFYING DOCUMENT AND DATE], establishing [ACTUAL SCOPE OF AUTHORITY]. Please associate counsel with this recovery case and direct authorized correspondence to [COUNSEL CONTACT AND SECURE DELIVERY INFORMATION].\nThe current claim status is [PENDING / SETTLED, WITH ACCURATE DATE AND REFERENCE]. Prior reporting is [DATE, METHOD AND CONFIRMATION]. Please identify any additional information needed to establish representation and provide the current recovery correspondence within the authority granted.\nThis transmittal does not substitute for the beneficiary’s executed authorization. If an estate is involved, the representative’s authority and supporting documents are [ACTUAL AUTHORITY AND ENCLOSURES].\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Medicare Recovery Payment Transmittal","slug":"medicare-clearance-bcrc","command":"/medicare-clearance-bcrc","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Medicare Recovery Payment Transmittal for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/medicare-clearance-bcrc.docx","reasoning":"../../reasoning/medicare-clearance-bcrc.md","path":"templates/liens/medicare-clearance-bcrc.md","docx_path":"templates/liens/docx/medicare-clearance-bcrc.docx","reasoning_path":"reasoning/medicare-clearance-bcrc.md","field_count":21,"md":"---\ntitle: \"Medicare Recovery Payment Transmittal\"\nslug: \"medicare-clearance-bcrc\"\ncommand: \"/medicare-clearance-bcrc\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Medicare Recovery Payment Transmittal for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/medicare-clearance-bcrc.docx\"\nreasoning: \"../../reasoning/medicare-clearance-bcrc.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Medicare Recovery Payment Transmittal — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nFor [BENEFICIARY NAME] and BCRC case [CASE ID], the controlling demand or written resolution is [DATE AND REFERENCE]. The amount to be paid is $[VERIFIED AMOUNT], with the treatment of interest determined by [ACTUAL DEMAND OR SUBSEQUENT CONFIRMATION].\nPayment status is [ENCLOSED CHECK / VERIFIED ELECTRONIC PAYMENT / OTHER ACCURATE STATUS], reference [NUMBER], in the amount of $[AMOUNT]. The payee and delivery instructions were verified against [CURRENT DEMAND OR AUTHENTICATED INSTRUCTIONS].\nPlease apply this payment to the identified recovery case and provide written confirmation of receipt and the resulting balance or closure. Supporting documents are [ACTUAL ATTACHMENTS]. Any unresolved discrepancy is [SPECIFIC ISSUE / NONE KNOWN AFTER REVIEW].\nThis letter does not state that funds have cleared or that Medicare has released its recovery claim unless separately confirmed. Please send the response to [AUTHORIZED CONTACT AND SECURE CHANNEL].\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Medicare Recovery Status to Client","slug":"medicare-clearance-client","command":"/medicare-clearance-client","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Medicare Recovery Status to Client for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/medicare-clearance-client.docx","reasoning":"../../reasoning/medicare-clearance-client.md","path":"templates/liens/medicare-clearance-client.md","docx_path":"templates/liens/docx/medicare-clearance-client.docx","reasoning_path":"reasoning/medicare-clearance-client.md","field_count":20,"md":"---\ntitle: \"Medicare Recovery Status to Client\"\nslug: \"medicare-clearance-client\"\ncommand: \"/medicare-clearance-client\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Medicare Recovery Status to Client for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/medicare-clearance-client.docx\"\nreasoning: \"../../reasoning/medicare-clearance-client.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Medicare Recovery Status to Client — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nWe are updating you on Medicare’s recovery claim connected with [INCIDENT]. The controlling demand or written decision is dated [DATE] and states [AMOUNT AND MATERIAL TERMS]. A copy is [ACTUAL ENCLOSURE OR PREVIOUS DELIVERY REFERENCE].\nOur records show the following payment status: [PAYMENT DATE, AMOUNT, REFERENCE AND WHETHER RECEIPT OR CLEARANCE IS VERIFIED]. Medicare’s written confirmation of the remaining balance or closure is [DATE AND EXACT STATUS / NOT YET RECEIVED].\nThe amount still held for this recovery matter is $[ACTUAL AMOUNT], supported by [CURRENT CLIENT ACCOUNTING]. Any additional amount proposed for distribution is $[AMOUNT], subject to [SPECIFIC REMAINING CONDITIONS]. This update concerns only the identified Medicare recovery case.\nThe next step is [ACTUAL ACTION, RESPONSIBLE PERSON AND EXPECTED UPDATE DATE]. Please forward any new Medicare correspondence promptly. This status letter does not determine future medical coverage, other benefit-program claims or an obligation to establish a future-care arrangement.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Medicare Settlement Reporting Letter","slug":"medicare-settlement-report","command":"/medicare-settlement-report","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Medicare Settlement Reporting Letter for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/medicare-settlement-report.docx","reasoning":"../../reasoning/medicare-settlement-report.md","path":"templates/liens/medicare-settlement-report.md","docx_path":"templates/liens/docx/medicare-settlement-report.docx","reasoning_path":"reasoning/medicare-settlement-report.md","field_count":23,"md":"---\ntitle: \"Medicare Settlement Reporting Letter\"\nslug: \"medicare-settlement-report\"\ncommand: \"/medicare-settlement-report\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Medicare Settlement Reporting Letter for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/medicare-settlement-report.docx\"\nreasoning: \"../../reasoning/medicare-settlement-report.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Medicare Settlement Reporting Letter — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nFor [BENEFICIARY NAME], BCRC case [CASE ID] and incident [DATE], we report [SETTLEMENT / JUDGMENT / AWARD / OTHER PAYMENT] reached on [ACTUAL DATE]. The gross amount is $[AMOUNT]. The payer, insurer and claim reference are [VERIFIED DETAILS].\nThe beneficiary’s attorney fees are $[ACTUAL AMOUNT] and separately itemized procurement costs are $[ACTUAL AMOUNT]. Supporting settlement documents and the fee/cost accounting are [ACTUAL ATTACHMENTS OR PORTAL REFERENCES]. Costs are not double counted as attorney fees.\nRelated settlements or payments, amounts and dates are [VERIFIED DETAILS / VERIFIED NONE]; any additional pending recovery is [ACTUAL STATUS]. The treatment of ongoing medical responsibility and relevant liability allocation is [SUPPORTED INFORMATION].\nProof of representation is [REFERENCE]. Any remaining disputed conditional-payment entries and supporting materials are [SPECIFIC ITEMS / NONE AFTER REVIEW]. Please issue the applicable recovery determination and payment instructions to the authorized contact.\nThis is beneficiary-side recovery reporting, not a representation that an insurer’s separate Section 111 reporting duties have been discharged.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Notice of Existing Letter of Protection","slug":"lop-notice","command":"/lop-notice","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Notice of Existing Letter of Protection for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/lop-notice.docx","reasoning":"../../reasoning/lop-notice.md","path":"templates/liens/lop-notice.md","docx_path":"templates/liens/docx/lop-notice.docx","reasoning_path":"reasoning/lop-notice.md","field_count":19,"md":"---\ntitle: \"Notice of Existing Letter of Protection\"\nslug: \"lop-notice\"\ncommand: \"/lop-notice\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Notice of Existing Letter of Protection for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/lop-notice.docx\"\nreasoning: \"../../reasoning/lop-notice.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Notice of Existing Letter of Protection — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nWe give notice of the existing letter of protection dated [DATE] concerning [CLIENT], [PROVIDER] and [SPECIFIC SERVICES / INCIDENT]. A copy of the executed agreement is [ACTUAL ENCLOSURE OR IDENTIFIED PRIOR DELIVERY].\nThe relevant undertaking and any known limitations are [ACCURATE SUMMARY OF THE SIGNED TERMS]. The provider’s presently documented claim is $[AMOUNT AS OF DATE], subject to [IDENTIFIED DISPUTES, PAYMENTS OR WRITTEN ADJUSTMENTS].\nPlease direct communications concerning this agreement and any proposed payment affecting it to [AUTHORIZED CONTACT]. The action requested of you is [SPECIFIC REQUEST WITH ITS CONTRACTUAL OR LEGAL BASIS]. We do not represent that this notice alone creates a statutory lien, binds a nonsignatory, or enlarges counsel’s obligations.\nPlease identify any inconsistent claim or payment information. The agreement and applicable law control priority, disputed funds and satisfaction; no recovery or payment from the firm’s own funds is guaranteed.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Notice of Proposed Third-Party Settlement","slug":"wc-notice","command":"/wc-notice","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Notice of an actual proposed or reached settlement to a Virginia compensation carrier; no retroactive implied consent.","docx":"docx/wc-notice.docx","reasoning":"../../reasoning/wc-notice.md","path":"templates/liens/wc-notice.md","docx_path":"templates/liens/docx/wc-notice.docx","reasoning_path":"reasoning/wc-notice.md","field_count":21,"md":"---\ntitle: \"Notice of Proposed Third-Party Settlement\"\nslug: \"wc-notice\"\ncommand: \"/wc-notice\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Notice of an actual proposed or reached settlement to a Virginia compensation carrier; no retroactive implied consent.\"\ndocx: \"docx/wc-notice.docx\"\nreasoning: \"../../reasoning/wc-notice.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Notice of Proposed Third-Party Settlement — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nWe notify you of [PROPOSED / EXECUTED SUBJECT TO IDENTIFIED CONDITIONS] settlement of [EMPLOYEE’S] claim against [THIRD PARTY] arising from [INCIDENT]. The gross recovery is $[AMOUNT], with terms in [ACTUAL OFFER OR AGREEMENT].\nThe proposed accounting is: attorney fees $[AMOUNT]; reasonable expenses $[AMOUNT]; your asserted accrued lien $[AMOUNT AS OF DATE]; proposed fee/cost allocation $[AMOUNT AND FORMULA]; lien payment $[AMOUNT]; other identified interests $[AMOUNT]; projected employee proceeds $[AMOUNT]. Supporting records are [ENCLOSURES].\nPlease confirm the final incident-related ledger, your position on the allocation under §§ 65.2-310 and 65.2-311, and any required consent or approval. Future-benefit treatment under § 65.2-313 is [PROPOSED ACCOUNTING OR IDENTIFIED OPEN ISSUE].\nThe intended closing date is [DATE]. We request a written response by [REASONABLE DATE], identifying unresolved issues. This notice does not by itself release the lien, establish consent, settle compensation benefits or authorize suspension of an award.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Objection to Medical Payments Recovery Demand","slug":"medpay-response-decline","command":"/medpay-response-decline","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Objection to Medical Payments Recovery Demand for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/medpay-response-decline.docx","reasoning":"../../reasoning/medpay-response-decline.md","path":"templates/liens/medpay-response-decline.md","docx_path":"templates/liens/docx/medpay-response-decline.docx","reasoning_path":"reasoning/medpay-response-decline.md","field_count":17,"md":"---\ntitle: \"Objection to Medical Payments Recovery Demand\"\nslug: \"medpay-response-decline\"\ncommand: \"/medpay-response-decline\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Objection to Medical Payments Recovery Demand for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/medpay-response-decline.docx\"\nreasoning: \"../../reasoning/medpay-response-decline.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Objection to Medical Payments Recovery Demand — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nWe dispute the recovery demand dated [DATE] for $[AMOUNT], involving [CLIENT, POLICY AND INCIDENT]. The payments identified in your demand are [ITEMIZED AMOUNTS AND DATES].\nOur objection is based on [EXACT POLICY LANGUAGE, APPLICABLE LAW AND FACTS]. To the extent Virginia Code § 38.2-2209 controls, the supporting facts concerning issuance or delivery, the insurer and the vehicle’s principal garaging or use are [VERIFIED FACTS]. Any additional ground is [SPECIFIC VERIFIED BASIS], not an assumed general rule.\nPlease withdraw the demand and confirm that no recovery claim will be pursued on the stated basis. If you disagree, provide the precise contractual and legal authority and identify any different factual premise.\nThis letter does not admit the validity or amount of the claim. The handling of any funds genuinely in dispute remains subject to [ACTUAL APPLICABLE OBLIGATION]; we do not represent that a disputed claim has been released without confirmation.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Provider Letter of Protection Release and Satisfaction","slug":"lop-payoff-release","command":"/lop-payoff-release","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Provider-executed release limited to a specified protection undertaking and defined accounts.","docx":"docx/lop-payoff-release.docx","reasoning":"../../reasoning/lop-payoff-release.md","path":"templates/liens/lop-payoff-release.md","docx_path":"templates/liens/docx/lop-payoff-release.docx","reasoning_path":"reasoning/lop-payoff-release.md","field_count":13,"md":"---\ntitle: \"Provider Letter of Protection Release and Satisfaction\"\nslug: \"lop-payoff-release\"\ncommand: \"/lop-payoff-release\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Provider-executed release limited to a specified protection undertaking and defined accounts.\"\ndocx: \"docx/lop-payoff-release.docx\"\nreasoning: \"../../reasoning/lop-payoff-release.md\"\n---\n# PROVIDER LETTER OF PROTECTION RELEASE AND SATISFACTION\nProvider: [LEGAL NAME]    Patient: [NAME]\nMatter and protection letter: [IDENTIFIERS AND DATE]\nAccounts and service dates: [EXACT SCOPE]\n## Payment and release\nIn consideration of [AGREED PAYMENT AMOUNT AND TERMS], [PROVIDER] agrees that, upon [ACTUAL RECEIPT OF CLEARED FUNDS OR OTHER EXPRESSLY AGREED CONDITION], the identified letter-of-protection claim is fully satisfied and released as to the listed accounts.\nThe treatment of any remaining patient balance is [EXPRESS FULL DISCHARGE OR PRECISE AMOUNT AND BASIS OF ANY BALANCE THAT REMAINS]. No broader debt discharge is implied where the parties have not agreed to it.\nUpon the stated condition, the provider will update the listed accounts and send written confirmation to [RECIPIENT]. Any separate recorded or statutory lien is addressed as follows: [IDENTIFIED RELEASE STEPS OR EXPRESS EXCLUSION].\nThe signer represents authority to bind the named provider regarding these accounts. This instrument does not release another creditor's rights or unrelated treatment claims. Payment is not certified as received before the stated condition occurs.\n## Agreement\nProvider authorized signature: ____________________    Date: [DATE]\nPrinted name and capacity: [NAME AND TITLE]\nAttorney name: [RECIPIENT COUNSEL IF ACKNOWLEDGMENT IS REQUIRED]\n"},{"title":"Release and Satisfaction of Identified Lien","slug":"lien-payoff-docs-release","command":"/lien-payoff-docs-release","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Private lienholder’s limited satisfaction instrument; government and statutory special-release procedures excluded.","docx":"docx/lien-payoff-docs-release.docx","reasoning":"../../reasoning/lien-payoff-docs-release.md","path":"templates/liens/lien-payoff-docs-release.md","docx_path":"templates/liens/docx/lien-payoff-docs-release.docx","reasoning_path":"reasoning/lien-payoff-docs-release.md","field_count":19,"md":"---\ntitle: \"Release and Satisfaction of Identified Lien\"\nslug: \"lien-payoff-docs-release\"\ncommand: \"/lien-payoff-docs-release\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Private lienholder’s limited satisfaction instrument; government and statutory special-release procedures excluded.\"\ndocx: \"docx/lien-payoff-docs-release.docx\"\nreasoning: \"../../reasoning/lien-payoff-docs-release.md\"\n---\n# RELEASE AND SATISFACTION OF IDENTIFIED LIEN\nLienholder: [EXACT LEGAL NAME]\nPatient / claimant: [NAME]    Incident: [DATE]\nAccount / lien reference: [IDENTIFIER]\n## Interest and consideration\nThe lienholder asserts [EXACT STATUTORY, CONTRACTUAL OR OTHER INTEREST], evidenced by [NOTICE / AGREEMENT AND DATE], concerning [SERVICES, PERIOD AND RECOVERY]. The agreed consideration is $[AMOUNT] under [PAYOFF AGREEMENT OR ORDER].\nPayment status and effective trigger: [ACTUAL RECEIPT AND CLEARANCE, OR EXPRESS CONDITION THAT THIS RELEASE TAKES EFFECT ONLY UPON IDENTIFIED PAYMENT]. No receipt is acknowledged before it occurs.\n## Satisfaction and scope\nUpon the stated effective trigger, the lienholder releases and satisfies [PRECISE LIEN, REIMBURSEMENT OR PROCEEDS INTEREST] against [IDENTIFIED PERSONS, FUND AND MATTER], to the extent described here.\nTreatment of any remaining underlying account debt: [EXPRESS DISCHARGE OR PRECISE RESERVED BALANCE]. Treatment of any separate letter-of-protection or counsel obligation: [EXPRESS TERMS].\nThis instrument does not release another person’s claim, unrelated treatment, or an interest outside the signer’s authority. Additional exclusions, if agreed: [SPECIFIC EXCLUSIONS]. Required notice, filing or delivery of satisfaction: [ACTUAL PROCEDURE AND RESPONSIBLE PERSON].\n## Execution by lienholder\nThe signer confirms authority to act for the identified lienholder as to this interest.\nAuthorized signature: ____________________    Date: ____________\nPrinted name: [NAME]    Capacity: [TITLE / AUTHORITY]\nLienholder contact and address: [DETAILS]\n[ADD ACKNOWLEDGMENT OR OTHER FORMALITY ONLY IF REQUIRED BY THE PARTICULAR RECORDED INTEREST OR APPLICABLE LAW].\n"},{"title":"Request for Health Plan Recovery Satisfaction Documents","slug":"lien-payoff-docs-erisa","command":"/lien-payoff-docs-erisa","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Request for Health Plan Recovery Satisfaction Documents for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/lien-payoff-docs-erisa.docx","reasoning":"../../reasoning/lien-payoff-docs-erisa.md","path":"templates/liens/lien-payoff-docs-erisa.md","docx_path":"templates/liens/docx/lien-payoff-docs-erisa.docx","reasoning_path":"reasoning/lien-payoff-docs-erisa.md","field_count":17,"md":"---\ntitle: \"Request for Health Plan Recovery Satisfaction Documents\"\nslug: \"lien-payoff-docs-erisa\"\ncommand: \"/lien-payoff-docs-erisa\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Request for Health Plan Recovery Satisfaction Documents for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/lien-payoff-docs-erisa.docx\"\nreasoning: \"../../reasoning/lien-payoff-docs-erisa.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Request for Health Plan Recovery Satisfaction Documents — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nFor [PARTICIPANT], [PLAN] and recovery file [NUMBER], the governing resolution is [SIGNED AGREEMENT OR OTHER CONTROLLING DOCUMENT, DATE]. Its scope is [IDENTIFIED BENEFITS, INCIDENT AND PERIOD].\nPayment information is [AMOUNT, DATE, REFERENCE AND ACTUAL RECEIPT STATUS]. Please provide the documents establishing [RECEIPT, SATISFACTION, RELEASE OR OTHER SPECIFIC AGREED CLOSEOUT], consistent with the governing terms.\nPlease identify any asserted remaining balance, reserved future-paid benefits, participant obligation or condition that prevents closure, with its precise contractual and factual basis. If the agreement resolves only a particular equitable recovery claim, the confirmation should accurately state that limited scope.\nThe requested recipient is [AUTHORIZED CONTACT]. This request does not concede that the plan has a statutory lien or that every ERISA plan has the same reimbursement rights; any unresolved entitlement remains governed by the actual plan and applicable law.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Request for Medicare Recovery Closure Documents","slug":"lien-payoff-docs-medicare","command":"/lien-payoff-docs-medicare","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Request for Medicare Recovery Closure Documents for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/lien-payoff-docs-medicare.docx","reasoning":"../../reasoning/lien-payoff-docs-medicare.md","path":"templates/liens/lien-payoff-docs-medicare.md","docx_path":"templates/liens/docx/lien-payoff-docs-medicare.docx","reasoning_path":"reasoning/lien-payoff-docs-medicare.md","field_count":18,"md":"---\ntitle: \"Request for Medicare Recovery Closure Documents\"\nslug: \"lien-payoff-docs-medicare\"\ncommand: \"/lien-payoff-docs-medicare\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Request for Medicare Recovery Closure Documents for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/lien-payoff-docs-medicare.docx\"\nreasoning: \"../../reasoning/lien-payoff-docs-medicare.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Request for Medicare Recovery Closure Documents — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nFor [BENEFICIARY] and BCRC case [CASE ID], the demand or accepted resolution is [DATE AND REFERENCE]. The incident is [DATE AND DESCRIPTION].\nPayment information is [AMOUNT, PAYMENT DATE, REFERENCE AND CONFIRMED RECEIPT STATUS]. Please provide the current written balance and any closure or satisfaction confirmation supported by the recovery record.\nThe prior payment and correspondence are [ACTUAL ENCLOSURES OR PORTAL REFERENCES]. If the record shows a difference, please identify the principal, interest or other component and the action required to reconcile it.\nPlease send the response through [AUTHORIZED CHANNEL] under the existing proof of representation [REFERENCE]. This letter requests agency confirmation; it is not a CMS release, a determination about future Medicare coverage or proof that another benefits recovery claim is resolved.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Request for Medicare Recovery Relief","slug":"medicare-compromise","command":"/medicare-compromise","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Request for Medicare Recovery Relief for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/medicare-compromise.docx","reasoning":"../../reasoning/medicare-compromise.md","path":"templates/liens/medicare-compromise.md","docx_path":"templates/liens/docx/medicare-compromise.docx","reasoning_path":"reasoning/medicare-compromise.md","field_count":20,"md":"---\ntitle: \"Request for Medicare Recovery Relief\"\nslug: \"medicare-compromise\"\ncommand: \"/medicare-compromise\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Request for Medicare Recovery Relief for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/medicare-compromise.docx\"\nreasoning: \"../../reasoning/medicare-compromise.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Request for Medicare Recovery Relief — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nWe request [WAIVER OF RECOVERY / COMPROMISE OFFER / BOTH AS SEPARATELY EXPLAINED] for [BENEFICIARY], BCRC case [CASE ID], concerning the demand dated [DATE] for $[AMOUNT]. Settlement information was provided by [METHOD, DATE AND REFERENCE]. Proof of representation is [REFERENCE].\n## Waiver grounds if requested\n[EXPLAIN WITH SUPPORT WHY THE BENEFICIARY WAS NOT AT FAULT FOR THE CONDITIONAL PAYMENTS AND WHY REPAYMENT WOULD CAUSE FINANCIAL HARDSHIP OR OTHERWISE BE UNFAIR. IDENTIFY ACTUAL INCOME, ASSETS, EXPENSES AND SUPPORTING DOCUMENTS; OMIT THIS SECTION IF NO WAIVER IS REQUESTED.]\n## Compromise grounds if requested\n[STATE THE SPECIFIC OFFER, ABILITY TO PAY, COLLECTION OR LITIGATION CONSIDERATIONS AND SUPPORTING FACTS. IDENTIFY THE SETTLEMENT AMOUNT, FEES, COSTS, OTHER CLAIMS AND NET FUNDS. OMIT IF NO COMPROMISE IS REQUESTED.]\nPlease consider the stated grounds and identify any required financial form or additional evidence. The enclosed support is [ACTUAL LIST]. A compromise is subject to authorized acceptance; no reduction is assumed.\nThe demanded amount, payment deadline, interest and any separately preserved appeal rights are being addressed as follows: [ACTUAL STATUS]. This request does not assert that interest stops or that a demand appeal has been perfected.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Request for Updated Conditional Payment Information","slug":"medicare-cpl","command":"/medicare-cpl","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Request for Updated Conditional Payment Information for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/medicare-cpl.docx","reasoning":"../../reasoning/medicare-cpl.md","path":"templates/liens/medicare-cpl.md","docx_path":"templates/liens/docx/medicare-cpl.docx","reasoning_path":"reasoning/medicare-cpl.md","field_count":18,"md":"---\ntitle: \"Request for Updated Conditional Payment Information\"\nslug: \"medicare-cpl\"\ncommand: \"/medicare-cpl\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Request for Updated Conditional Payment Information for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/medicare-cpl.docx\"\nreasoning: \"../../reasoning/medicare-cpl.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Request for Updated Conditional Payment Information — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nFor [BENEFICIARY NAME], BCRC case [CASE ID] and incident [DATE], please provide the current conditional payment letter and payment summary reflecting related claims identified to date. The latest information available to us is [DOCUMENT DATE AND INTERIM AMOUNT / NO PRIOR STATEMENT RECEIVED].\nOur authority to receive and discuss this information is established by [PROOF OF REPRESENTATION REFERENCE]. The claim is [ACTUAL PENDING OR RESOLVED STATUS]. Relevant updates since the prior statement are [TREATMENT, INSURER OR CLAIM STATUS UPDATES].\nPlease identify the service dates, providers and payments included so we can evaluate incident-relatedness. Please send the information through [AUTHORIZED SECURE CHANNEL]. Documents supporting this request are [ACTUAL ENCLOSURES OR PORTAL REFERENCES].\nThis request seeks CMS’s current information; it does not state a final recovery amount or create a CMS-issued conditional payment letter. Any final-amount procedure must be separately selected and completed under its applicable conditions.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Request for Virginia Medicaid Satisfaction Documents","slug":"lien-payoff-docs-medicaid","command":"/lien-payoff-docs-medicaid","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Request for Virginia Medicaid Satisfaction Documents for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/lien-payoff-docs-medicaid.docx","reasoning":"../../reasoning/lien-payoff-docs-medicaid.md","path":"templates/liens/lien-payoff-docs-medicaid.md","docx_path":"templates/liens/docx/lien-payoff-docs-medicaid.docx","reasoning_path":"reasoning/lien-payoff-docs-medicaid.md","field_count":16,"md":"---\ntitle: \"Request for Virginia Medicaid Satisfaction Documents\"\nslug: \"lien-payoff-docs-medicaid\"\ncommand: \"/lien-payoff-docs-medicaid\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Request for Virginia Medicaid Satisfaction Documents for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/lien-payoff-docs-medicaid.docx\"\nreasoning: \"../../reasoning/lien-payoff-docs-medicaid.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Request for Virginia Medicaid Satisfaction Documents — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nFor [MEMBER] and DMAS recovery file [NUMBER], the applicable final demand, compromise or order is [DATE AND REFERENCE]. The incident and services addressed are [EXACT SCOPE].\nThe recorded payment is [AMOUNT, DATE, REFERENCE AND VERIFIED RECEIPT STATUS]. Please provide written confirmation of receipt and the resulting balance, satisfaction or release under that controlling document.\nIf additional action or information is needed, identify it specifically and explain any remaining or later-paid charges and the basis for including them. Relevant prior reporting, signed authorization and portal references are [ACTUAL REFERENCES].\nPlease deliver confirmation through [AUTHORIZED SECURE CHANNEL]. This request does not assume that a draft check closed the file, enlarge an agreed compromise or declare unrelated benefits and obligations resolved.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Request to Substantiate Out-of-State PIP Recovery","slug":"pip-coordination-nofault","command":"/pip-coordination-nofault","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"This reusable original requests evidence and preserves an unresolved position; it is not a multistate no-fault legal opinion. The requested policy and governing-state authority must be reviewed before adding substantive arguments or admissions.","docx":"docx/pip-coordination-nofault.docx","reasoning":"../../reasoning/pip-coordination-nofault.md","path":"templates/liens/pip-coordination-nofault.md","docx_path":"templates/liens/docx/pip-coordination-nofault.docx","reasoning_path":"reasoning/pip-coordination-nofault.md","field_count":18,"md":"---\ntitle: \"Request to Substantiate Out-of-State PIP Recovery\"\nslug: \"pip-coordination-nofault\"\ncommand: \"/pip-coordination-nofault\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"This reusable original requests evidence and preserves an unresolved position; it is not a multistate no-fault legal opinion. The requested policy and governing-state authority must be reviewed before adding substantive arguments or admissions.\"\ndocx: \"docx/pip-coordination-nofault.docx\"\nreasoning: \"../../reasoning/pip-coordination-nofault.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\n[TELEPHONE AND EMAIL]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[RECIPIENT MAILING ADDRESS]\nRe: [CLIENT] — out-of-state PIP recovery assertion [REFERENCE]\nDear [RECIPIENT]:\nWe represent [CLIENT] in connection with [INCIDENT DATE AND LOCATION]. We received your [DATE] assertion of [REIMBURSEMENT, SUBROGATION OR INTERCOMPANY LOSS TRANSFER] in the amount of [AMOUNT]. The precise remedy and party against whom it is asserted remain [KNOWN OR DISPUTED FACTS].\nPlease provide the complete policy and endorsements, insured and vehicle information, policy issuance and delivery state, itemized payment record and the statute or agreement authorizing the particular remedy. Identify any eligibility threshold, permitted recovery source, coordination provision and deadline on which you rely.\nThe Virginia litigation setting does not establish the law governing an out-of-state no-fault policy. Before responding on the merits, we need to resolve [GOVERNING-LAW AND COVERAGE QUESTIONS]. If Virginia Code § 38.2-2209 is implicated, please address its actual policy and vehicle predicates.\nPlease identify any duplicate payments, offsets and claim-resolution arrangements that affect the stated balance. Our client’s present position is [SUPPORTED POSITION]; any proposed reduction or satisfaction is [AUTHORIZED CONDITIONAL PROPOSAL OR NONE].\nNo statutory threshold, benefit exhaustion, reduction entitlement or liability for payment is conceded. Please provide the supporting material by [REQUESTED DATE]. This correspondence does not extend any limitation, arbitration, notice or response period.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Response to Asserted Medical Payments Reimbursement Claim","slug":"medpay","command":"/medpay","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Response to Asserted Medical Payments Reimbursement Claim for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/medpay.docx","reasoning":"../../reasoning/medpay.md","path":"templates/liens/medpay.md","docx_path":"templates/liens/docx/medpay.docx","reasoning_path":"reasoning/medpay.md","field_count":16,"md":"---\ntitle: \"Response to Asserted Medical Payments Reimbursement Claim\"\nslug: \"medpay\"\ncommand: \"/medpay\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Response to Asserted Medical Payments Reimbursement Claim for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/medpay.docx\"\nreasoning: \"../../reasoning/medpay.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Response to Asserted Medical Payments Reimbursement Claim — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nWe represent [CLIENT] concerning [INCIDENT] and respond to your asserted recovery claim dated [DATE], reference [NUMBER], for $[AMOUNT]. The benefits and policy involved are [IDENTIFIED BENEFITS, INSURED, POLICY AND PERIOD].\nPlease provide the complete policy and endorsements, itemized payments, exact contractual provision, asserted legal basis and facts supporting application of that law. Please identify the policy’s place of issuance or delivery and the vehicle’s principal garaging or use at the relevant time.\nVirginia Code § 38.2-2209 restricts subrogation rights in qualifying motor-vehicle medical-benefit coverage. Our present analysis of its applicability is [VERIFIED POLICY AND VEHICLE FACTS, WITH ANY MATERIAL UNCERTAINTY]. No valid lien or reimbursement obligation is conceded by this request.\nThe current settlement and payment status relevant to this inquiry is [ACCURATE LIMITED INFORMATION]. Please explain your position in writing and identify any asserted deadline. Any proposed resolution will require client authorization and written terms specific to a legally supportable claim.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Response to Asserted PIP or Medical Benefits Recovery Claim","slug":"pip-coordination-atfault","command":"/pip-coordination-atfault","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Virginia-matter coverage inquiry and conditional response. The incident state alone does not establish policy law; no unsupported common-fund, made-whole, no-fault or reimbursement rule is asserted. Statutory health-plan liens use their distinct routes.","docx":"docx/pip-coordination-atfault.docx","reasoning":"../../reasoning/pip-coordination-atfault.md","path":"templates/liens/pip-coordination-atfault.md","docx_path":"templates/liens/docx/pip-coordination-atfault.docx","reasoning_path":"reasoning/pip-coordination-atfault.md","field_count":18,"md":"---\ntitle: \"Response to Asserted PIP or Medical Benefits Recovery Claim\"\nslug: \"pip-coordination-atfault\"\ncommand: \"/pip-coordination-atfault\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia-matter coverage inquiry and conditional response. The incident state alone does not establish policy law; no unsupported common-fund, made-whole, no-fault or reimbursement rule is asserted. Statutory health-plan liens use their distinct routes.\"\ndocx: \"docx/pip-coordination-atfault.docx\"\nreasoning: \"../../reasoning/pip-coordination-atfault.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\n[TELEPHONE AND EMAIL]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[RECIPIENT MAILING ADDRESS]\nRe: [CLIENT] — asserted benefit recovery claim [REFERENCE]\nDear [RECIPIENT]:\nWe represent [CLIENT] concerning the incident on [DATE]. Your demand dated [DATE] seeks [AMOUNT] for benefits described as [BENEFIT TYPE]. Please identify the insurer or plan, complete policy and endorsements, policy issuance and delivery state, vehicle garaging facts, and the governing law relied upon.\nProvide an itemized payment ledger and the precise contractual and statutory basis for any claimed lien, reimbursement or subrogation right, including how each payment relates to this incident. The present record establishes [VERIFIED FACTS] and leaves unresolved [QUESTIONS].\nVirginia Code § 38.2-2209 restricts subrogation in motor vehicle medical-benefit policies meeting its terms. Whether that provision applies here depends on [VERIFIED ISSUANCE, DELIVERY, INSURER AND VEHICLE FACTS]. We do not concede a recovery right merely because this matter is described as arising in an at-fault state.\nSubject to verification of a lawful claim and client approval, the proposed resolution is [AUTHORIZED AMOUNT AND CONDITIONS OR REQUEST FOR WITHDRAWAL WITH BASIS]. Any fee-sharing or equitable reduction is supported by [ACTUAL APPLICABLE AUTHORITY OR AGREEMENT]; none is presumed.\nPlease respond with the requested support by [REQUESTED DATE]. This letter does not acknowledge an enforceable lien, promise payment from client funds or alter any legal deadline.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Third-Party Recovery Credit Agreement","slug":"wc-credit","command":"/wc-credit","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Virginia § 65.2-313 accounting agreement subject to applicable Commission authority; not a blanket suspension of benefits.","docx":"docx/wc-credit.docx","reasoning":"../../reasoning/wc-credit.md","path":"templates/liens/wc-credit.md","docx_path":"templates/liens/docx/wc-credit.docx","reasoning_path":"reasoning/wc-credit.md","field_count":16,"md":"---\ntitle: \"Third-Party Recovery Credit Agreement\"\nslug: \"wc-credit\"\ncommand: \"/wc-credit\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Virginia § 65.2-313 accounting agreement subject to applicable Commission authority; not a blanket suspension of benefits.\"\ndocx: \"docx/wc-credit.docx\"\nreasoning: \"../../reasoning/wc-credit.md\"\n---\n# THIRD-PARTY RECOVERY CREDIT AGREEMENT\nEmployee: [NAME]    Employer: [NAME]    Carrier: [NAME]\nCommission claim: [NUMBER]    Injury date: [DATE]\n## Recovery and accrued lien\nGross third-party recovery: $[G]. Reasonable recovery expenses and fees: $[E]. The resulting expense percentage is [E ÷ G × 100]%, subject to [VERIFIED ALLOCATION AND APPROVAL].\nAccrued lien asserted: $[L]. Amount established after disputes: $[AMOUNT]. Fee/cost allocation under § 65.2-311: $[AMOUNT]. Actual agreed payment to employer/carrier: $[AMOUNT]. Any additional compromise and its effect on the credit calculation: [EXPRESS TERMS AND LEGAL BASIS].\n## Future entitlements and accounting\nUnder § 65.2-313, the employer/carrier will pay the employee the applicable recovery-expense percentage of each further entitlement as it is submitted, until accrued post-recovery entitlement reaches [VERIFIED GROSS RECOVERY LESS THE STATUTORILY APPLICABLE LIEN AMOUNT]. The calculation and starting date are [DETAILS].\nA third-party recovery or credit alone will not suspend, modify or terminate an award. Continuing indemnity payments and medical-expense reimbursements will be handled in accordance with the current statute and controlling awards. The employer/carrier’s payment of its applicable proportion of reasonable fees and costs will continue as required.\nLedger exchange frequency, responsible contacts and dispute procedure: [TERMS]. No entry will count the same fee, lien payment or entitlement twice.\n## Scope and approvals\nThis agreement does not settle future compensation benefits or alter an award beyond lawful Commission authority. Required approvals and effective-date conditions are [IDENTIFY]. Any separate release is limited to [EXACT INTEREST].\nEmployee / authorized representative: ____________________\nName / capacity: [NAME]    Date: [DATE]\nEmployer/carrier authorized representative: ____________________\nName / capacity: [NAME]    Date: [DATE]\nCommission approval, if required: [SEPARATE ACTUAL ORDER REFERENCE]\n"},{"title":"TRICARE Recovery Payment Transmittal","slug":"tricare-payment-tricare","command":"/tricare-payment-tricare","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"TRICARE Recovery Payment Transmittal for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/tricare-payment-tricare.docx","reasoning":"../../reasoning/tricare-payment-tricare.md","path":"templates/liens/tricare-payment-tricare.md","docx_path":"templates/liens/docx/tricare-payment-tricare.docx","reasoning_path":"reasoning/tricare-payment-tricare.md","field_count":19,"md":"---\ntitle: \"TRICARE Recovery Payment Transmittal\"\nslug: \"tricare-payment-tricare\"\ncommand: \"/tricare-payment-tricare\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"TRICARE Recovery Payment Transmittal for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/tricare-payment-tricare.docx\"\nreasoning: \"../../reasoning/tricare-payment-tricare.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: TRICARE Recovery Payment Transmittal — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nFor [BENEFICIARY], recovery file [NUMBER] and incident [DATE], we transmit payment under [FINAL DEMAND OR AUTHORIZED WRITTEN COMPROMISE, DATE AND REFERENCE]. The covered recovery interest and service period are [EXACT SCOPE].\nPayment status is [ENCLOSED CHECK / VERIFIED TRANSFER], reference [NUMBER], for $[AMOUNT]. Payee and delivery instructions were independently verified with [AUTHORIZED RECOVERY OFFICE AND REFERENCE]. Supporting approval and accounting are [ACTUAL ENCLOSURES].\nPlease confirm receipt, application to the identified file, and satisfaction or remaining balance under the written terms. Any pending additional charges or reserved issues are [ACTUAL TERMS]. No broader release or cleared-payment status is assumed.\nPlease send confirmation to [AUTHORIZED CONTACT AND SECURE CHANNEL]. This payment concerns the identified TRICARE recovery matter and is not proof of resolution of a separate Veterans Affairs or Medicare claim.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"TRICARE Third Party Recovery Notice","slug":"tricare-notice","command":"/tricare-notice","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"TRICARE Third Party Recovery Notice for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/tricare-notice.docx","reasoning":"../../reasoning/tricare-notice.md","path":"templates/liens/tricare-notice.md","docx_path":"templates/liens/docx/tricare-notice.docx","reasoning_path":"reasoning/tricare-notice.md","field_count":20,"md":"---\ntitle: \"TRICARE Third Party Recovery Notice\"\nslug: \"tricare-notice\"\ncommand: \"/tricare-notice\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"TRICARE Third Party Recovery Notice for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/tricare-notice.docx\"\nreasoning: \"../../reasoning/tricare-notice.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: TRICARE Third Party Recovery Notice — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nWe represent [BENEFICIARY NAME] in connection with [INCIDENT AND DATE]. The beneficiary and sponsor identifiers needed for this matter are [VERIFIED IDENTIFIERS TRANSMITTED SECURELY]. The treating providers and injury description are [SUPPORTED DETAILS].\nThe potentially responsible third party and insurer are [NAMES, CONTACTS AND CLAIM REFERENCES]. The personal-injury claim is [ACTUAL STATUS]; any settlement, judgment or payment is [VERIFIED DETAILS].\nProof of authority to represent the beneficiary is [ACTUAL ENCLOSURE]. The status of DD Form 2527 is [REQUEST DATE, SIGNED RETURN DATE AND DELIVERY CONFIRMATION / NOT YET COMPLETED]. This letter does not replace that form or represent that a required return has occurred.\nPlease identify the responsible recovery office and file number, provide an itemized statement of incident-related payments within our authority, and advise of the current process for reporting updates and resolving the federal recovery claim. Please direct correspondence securely to [CONTACT].\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Veterans Affairs Recovery Payment Transmittal","slug":"tricare-payment-va","command":"/tricare-payment-va","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Veterans Affairs Recovery Payment Transmittal for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/tricare-payment-va.docx","reasoning":"../../reasoning/tricare-payment-va.md","path":"templates/liens/tricare-payment-va.md","docx_path":"templates/liens/docx/tricare-payment-va.docx","reasoning_path":"reasoning/tricare-payment-va.md","field_count":20,"md":"---\ntitle: \"Veterans Affairs Recovery Payment Transmittal\"\nslug: \"tricare-payment-va\"\ncommand: \"/tricare-payment-va\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Veterans Affairs Recovery Payment Transmittal for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/tricare-payment-va.docx\"\nreasoning: \"../../reasoning/tricare-payment-va.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Veterans Affairs Recovery Payment Transmittal — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nFor [VETERAN NAME], VA recovery file [NUMBER] and incident [DATE], the controlling demand or approved resolution is [DATE, ISSUING OFFICE AND REFERENCE]. It resolves [EXACT SERVICES AND RECOVERY INTEREST] upon [ACTUAL TERMS].\nPayment status is [ENCLOSED CHECK / VERIFIED TRANSFER], reference [NUMBER], for $[AMOUNT]. The payee and delivery instructions were confirmed with [REVENUE LAW GROUP CONTACT OR OTHER AUTHORIZED OFFICE]. The supporting approval is [ACTUAL ENCLOSURE].\nPlease confirm receipt and application to the identified recovery claim and state the resulting balance or satisfaction consistent with the approved terms. Any additional or disputed bills are [SPECIFIC STATUS].\nThis transmittal does not create a compromise or release beyond the authorized written decision. It does not represent that payment to the injured person extinguished VA’s separate recovery interest. Please direct confirmation securely to [CONTACT].\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Virginia Medicaid Lien Compromise Request","slug":"medicaid-reduction","command":"/medicaid-reduction","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Good-faith DMAS compromise proposal with current regulatory supporting material; no automatic judicial reduction.","docx":"docx/medicaid-reduction.docx","reasoning":"../../reasoning/medicaid-reduction.md","path":"templates/liens/medicaid-reduction.md","docx_path":"templates/liens/docx/medicaid-reduction.docx","reasoning_path":"reasoning/medicaid-reduction.md","field_count":19,"md":"---\ntitle: \"Virginia Medicaid Lien Compromise Request\"\nslug: \"medicaid-reduction\"\ncommand: \"/medicaid-reduction\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Good-faith DMAS compromise proposal with current regulatory supporting material; no automatic judicial reduction.\"\ndocx: \"docx/medicaid-reduction.docx\"\nreasoning: \"../../reasoning/medicaid-reduction.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Virginia Medicaid Lien Compromise Request — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nWe request compromise of the $[AMOUNT] lien asserted for [MEMBER, INCIDENT AND RECOVERY FILE] to $[PROPOSED PAYOFF], under §§ 8.01-66.9 and 2.2-514.\nThe proposed gross recovery is $[AMOUNT]; attorney fees are $[AMOUNT]; costs $[AMOUNT]; voluntary fee/cost reductions $[AMOUNT]; other liens $[AMOUNT]; and the projected member recovery is $[AMOUNT]. The itemized accounting and current lien statement are [REFERENCES]. Unrelated-charge disputes are separately identified and supported in [SUBMISSION].\nThe requested reduction is supported by [SPECIFIC LIABILITY, COLLECTION, DAMAGES AND EQUITABLE FACTS]. The member’s prognosis, future treatment expense, disability rating if applicable, income, resources and employment are [SUPPORTED SUMMARY].\nThe portal submission includes [ACTUAL MATERIALS]: available liability policies and payments by policyholder, settlement terms and signed agreements, lawsuit identification and pleadings, medical-payments coverage, other liens, itemized fees/costs and supporting evidence. Required authorizations are [REFERENCES AND DATES].\nPlease provide a written decision by the authorized official, the exact satisfied interest, payoff deadline and payment instructions. We will update changed information. This is a compromise proposal; it does not represent approval, invoke deemed acceptance without statutory prerequisites, or itself obtain a court order reducing the lien.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Virginia Medicaid Lien Itemization Request","slug":"medicaid-conditional","command":"/medicaid-conditional","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"DMAS itemization request with an expressly selected provisional or qualified final-demand posture.","docx":"docx/medicaid-conditional.docx","reasoning":"../../reasoning/medicaid-conditional.md","path":"templates/liens/medicaid-conditional.md","docx_path":"templates/liens/docx/medicaid-conditional.docx","reasoning_path":"reasoning/medicaid-conditional.md","field_count":17,"md":"---\ntitle: \"Virginia Medicaid Lien Itemization Request\"\nslug: \"medicaid-conditional\"\ncommand: \"/medicaid-conditional\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"DMAS itemization request with an expressly selected provisional or qualified final-demand posture.\"\ndocx: \"docx/medicaid-conditional.docx\"\nreasoning: \"../../reasoning/medicaid-conditional.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Virginia Medicaid Lien Itemization Request — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nFor [MEMBER AND RECOVERY FILE], we request an itemized statement of incident-related health care expenses paid by DMAS programs concerning [INCIDENT]. Please show provider, date of service, paid amount, adjustments and current total.\nThe request status is [PROVISIONAL ITEMIZATION / FINAL DEMAND UNDER § 8.01-66.9:2(A)]. [FOR THE FINAL-DEMAND ROUTE ONLY, STATE THE VERIFIED BASIS THAT ALL RELATED HEALTH CARE CLAIMS HAVE BEEN SUBMITTED TO AND PROCESSED FOR POTENTIAL PAYMENT BY DMAS]. Under that qualified route, we also request the sum-specific demand for full and final resolution required by the statute within 60 days of receipt.\nThe portal submission and required authorization/information are [ACTUAL REFERENCE AND DATE]. Any requested exclusions are identified by [EXACT CHARGES AND SUPPORTING EVIDENCE], with the materials required by 12VAC30-20-200(9), including relevant medical-damages submissions to third parties.\nPlease confirm receipt and identify missing information. A provisional itemization is not a final payoff, and the title “conditional” does not invoke Medicare’s conditional-payment process. Please direct the response through [AUTHORIZED SECURE CONTACT].\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Virginia Medicaid Lien Payment Transmittal","slug":"medicaid-payment-agency","command":"/medicaid-payment-agency","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Payment to DMAS or its verified authorized recipient under an actual final demand or compromise.","docx":"docx/medicaid-payment-agency.docx","reasoning":"../../reasoning/medicaid-payment-agency.md","path":"templates/liens/medicaid-payment-agency.md","docx_path":"templates/liens/docx/medicaid-payment-agency.docx","reasoning_path":"reasoning/medicaid-payment-agency.md","field_count":20,"md":"---\ntitle: \"Virginia Medicaid Lien Payment Transmittal\"\nslug: \"medicaid-payment-agency\"\ncommand: \"/medicaid-payment-agency\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Payment to DMAS or its verified authorized recipient under an actual final demand or compromise.\"\ndocx: \"docx/medicaid-payment-agency.docx\"\nreasoning: \"../../reasoning/medicaid-payment-agency.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Virginia Medicaid Lien Payment Transmittal — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nFor [MEMBER AND RECOVERY FILE], the controlling payoff is [FINAL DEMAND / WRITTEN COMPROMISE / COURT ORDER, DATE AND REFERENCE]. It requires $[AMOUNT] by [DATE] to resolve [EXACT INCIDENT-RELATED INTEREST AND CONDITIONS].\nPayment status is [ACTUAL ENCLOSED CHECK / VERIFIED TRANSFER], reference [NUMBER], payable to [INDEPENDENTLY VERIFIED PAYEE]. Supporting approval and accounting are [ACTUAL ENCLOSURES / PORTAL REFERENCES]. Please apply the payment to this recovery file.\nPlease confirm receipt and full satisfaction of the interest identified in the controlling document, or identify any discrepancy. The treatment of additional or later-paid claims is [EXACT APPROVED TERMS]; this transmittal does not enlarge the settlement’s scope.\nWe have [ACTUAL PORTAL UPDATE OR OTHER REQUIRED REPORTING STATUS]. Please send the confirmation to the authorized contact [NAME AND SECURE CHANNEL]. No cleared-payment or satisfaction status is asserted without actual confirmation.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Virginia Medicaid Recovery Status to Client","slug":"medicaid-payment-client","command":"/medicaid-payment-client","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Client explanation of the actual DMAS resolution and its effect on distribution; no unverified promise that the lien is closed.","docx":"docx/medicaid-payment-client.docx","reasoning":"../../reasoning/medicaid-payment-client.md","path":"templates/liens/medicaid-payment-client.md","docx_path":"templates/liens/docx/medicaid-payment-client.docx","reasoning_path":"reasoning/medicaid-payment-client.md","field_count":21,"md":"---\ntitle: \"Virginia Medicaid Recovery Status to Client\"\nslug: \"medicaid-payment-client\"\ncommand: \"/medicaid-payment-client\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Client explanation of the actual DMAS resolution and its effect on distribution; no unverified promise that the lien is closed.\"\ndocx: \"docx/medicaid-payment-client.docx\"\nreasoning: \"../../reasoning/medicaid-payment-client.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Virginia Medicaid Recovery Status to Client — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nWe are updating you on the Virginia Medicaid recovery claim connected with your [INCIDENT DATE] matter. DMAS originally asserted $[AMOUNT]. Its current approved payoff is $[AMOUNT], based on [WRITTEN AGREEMENT, DEMAND OR ORDER AND DATE].\nThe payment status is [NOT YET SENT / SENT ON DATE / RECEIPT CONFIRMED], supported by [ACTUAL RECORD]. The satisfaction status is [WRITTEN CONFIRMATION RECEIVED / AWAITING CONFIRMATION / OTHER ACCURATE STATUS]. The resolution covers [EXACT INTEREST]; any remaining issue is [IDENTIFY].\nThe enclosed settlement accounting shows the gross recovery, attorney fees, expenses, lien payments, any funds still held and the amount available for you. Your available distribution is $[AMOUNT]; the remaining reserve is $[AMOUNT] for [SPECIFIC REASON]. We will update you when [OUTSTANDING STEP] is resolved.\nThis letter addresses the recovery claim only. Any separate effect of settlement funds on benefit eligibility has [ACTUAL ADVICE OR REFERRAL STATUS]. Please contact us about any question or new agency correspondence before relying on an unconfirmed payoff or satisfaction.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Virginia Medicaid Third-Party Claim Notice","slug":"medicaid-notice","command":"/medicaid-notice","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"DMAS portal cover letter and initial recovery notification; required portal fields and supporting records remain part of the submission.","docx":"docx/medicaid-notice.docx","reasoning":"../../reasoning/medicaid-notice.md","path":"templates/liens/medicaid-notice.md","docx_path":"templates/liens/docx/medicaid-notice.docx","reasoning_path":"reasoning/medicaid-notice.md","field_count":19,"md":"---\ntitle: \"Virginia Medicaid Third-Party Claim Notice\"\nslug: \"medicaid-notice\"\ncommand: \"/medicaid-notice\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"DMAS portal cover letter and initial recovery notification; required portal fields and supporting records remain part of the submission.\"\ndocx: \"docx/medicaid-notice.docx\"\nreasoning: \"../../reasoning/medicaid-notice.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Virginia Medicaid Third-Party Claim Notice — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nWe represent [MEDICAID MEMBER] concerning injuries from [INCIDENT DATE AND LOCATION] involving [IDENTIFIED PARTIES]. The member’s injuries are [DESCRIPTION]. The claim and litigation status are [CLAIM / CASE NUMBER, COURT AND STATUS].\nThis cover letter accompanies submission through the DMAS-designated portal. The submission includes [ACTUAL SIGNED REPRESENTATION DOCUMENT AND DATE], [HIPAA RELEASE AND DATE AUTHORIZING DMAS AND THE ATTORNEY GENERAL], the member’s full legal name and required identifiers, both sides of the insurance card, injury description, itemized medical damages and bills, and the available police report.\nPlease establish or identify the recovery file and provide the current incident-related payment itemization and the contact authorized to address it. The person authorized to receive communications is [FULL NAME, MAILING ADDRESS, TELEPHONE AND EMAIL], as identified in the release.\nKnown missing items are [ITEMS AND PLAN TO SUPPLY THEM]. We will update material information as required. This initial notice does not represent that all medical claims have been processed or that a final lien amount has been established. Sensitive identifiers are supplied through the secure portal, not in this correspondence.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Workers’ Compensation Lien Compromise Proposal","slug":"wc-compromise","command":"/wc-compromise","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Negotiation of a Virginia compensation lien and related third-party recovery allocation.","docx":"docx/wc-compromise.docx","reasoning":"../../reasoning/wc-compromise.md","path":"templates/liens/wc-compromise.md","docx_path":"templates/liens/docx/wc-compromise.docx","reasoning_path":"reasoning/wc-compromise.md","field_count":21,"md":"---\ntitle: \"Workers’ Compensation Lien Compromise Proposal\"\nslug: \"wc-compromise\"\ncommand: \"/wc-compromise\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Negotiation of a Virginia compensation lien and related third-party recovery allocation.\"\ndocx: \"docx/wc-compromise.docx\"\nreasoning: \"../../reasoning/wc-compromise.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Workers’ Compensation Lien Compromise Proposal — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nThe verified lien asserted for [EMPLOYEE AND INCIDENT] is $[AMOUNT], itemized in [LEDGER AND DATE]. We dispute [SPECIFIC ITEMS AND REASONS], leaving $[AMOUNT] for purposes of this proposal.\nThe proposed gross third-party recovery is $[AMOUNT]. The reasonable recovery expenses and attorney fees are $[AMOUNTS], supported by [RECORDS]. The proposed statutory allocation under § 65.2-311 is [FORMULA AND CALCULATION]; any additional voluntary compromise is separately $[AMOUNT].\nWe propose $[PAYOFF] to resolve [PRECISE ACCRUED LIEN], based on [LIABILITY, COLLECTION, DAMAGES OR OTHER SUPPORTED FACTS]. Future entitlements and any § 65.2-313 credit would be treated as follows: [SEPARATELY NEGOTIATED TERMS OR EXPRESSLY UNRESOLVED STATUS].\nPlease provide approval from the authorized employer/carrier representative and identify any required Commission or other approval. Acceptance must state the satisfied interest, covered payment period, remaining rights, payment conditions and written-release obligation. Until those terms and required approvals are complete, this is a proposal only.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Workers’ Compensation Lien Payment Transmittal","slug":"wc-payment","command":"/wc-payment","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Payment of an approved Virginia compensation lien resolution; future rights separately recorded.","docx":"docx/wc-payment.docx","reasoning":"../../reasoning/wc-payment.md","path":"templates/liens/wc-payment.md","docx_path":"templates/liens/docx/wc-payment.docx","reasoning_path":"reasoning/wc-payment.md","field_count":19,"md":"---\ntitle: \"Workers’ Compensation Lien Payment Transmittal\"\nslug: \"wc-payment\"\ncommand: \"/wc-payment\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Payment of an approved Virginia compensation lien resolution; future rights separately recorded.\"\ndocx: \"docx/wc-payment.docx\"\nreasoning: \"../../reasoning/wc-payment.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Workers’ Compensation Lien Payment Transmittal — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nWe transmit payment of $[AMOUNT] under [EXECUTED LIEN AGREEMENT / ORDER AND DATE] for [EMPLOYEE, INJURY DATE AND CLAIM NUMBER]. The payment resolves [EXACT ACCRUED LIEN AND THROUGH-DATE], after the agreed allocation of fees and costs.\nPayment is [ACTUAL ENCLOSED CHECK OR VERIFIED TRANSFER STATUS], reference [NUMBER], to [VERIFIED AUTHORIZED PAYEE]. The calculation and governing approval are [ACTUAL ENCLOSURES].\nPlease confirm receipt, application and written satisfaction of the identified lien. Future compensation entitlements, credit and expense sharing remain governed by [ACTUAL AGREEMENT, ORDER AND § 65.2-313 TERMS]. This payment is not a release of the employee’s remaining compensation rights or authority to suspend an award.\nPlease identify any discrepancy immediately and return the signed satisfaction or equivalent written confirmation to [CONTACT]. No statement of cleared funds or executed release is made beyond the actual supporting records.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Workers’ Compensation Third-Party Claim Notice","slug":"workers","command":"/workers","category":"liens","category_label":"Liens, Medicare, Medicaid and benefit recovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Initial notice to the compensation employer/carrier of a Virginia third-party claim and request for lien information.","docx":"docx/workers.docx","reasoning":"../../reasoning/workers.md","path":"templates/liens/workers.md","docx_path":"templates/liens/docx/workers.docx","reasoning_path":"reasoning/workers.md","field_count":15,"md":"---\ntitle: \"Workers’ Compensation Third-Party Claim Notice\"\nslug: \"workers\"\ncommand: \"/workers\"\ncategory: \"liens\"\ncategory_label: \"Liens, Medicare, Medicaid and benefit recovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Initial notice to the compensation employer/carrier of a Virginia third-party claim and request for lien information.\"\ndocx: \"docx/workers.docx\"\nreasoning: \"../../reasoning/workers.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Workers’ Compensation Third-Party Claim Notice — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nWe represent [EMPLOYEE] concerning injuries sustained on [DATE] and a potential claim against [THIRD PARTY]. Compensation claim and Commission identifiers are [NUMBERS]. This notice concerns the third-party claim, not an agreement to compromise compensation benefits.\nPlease identify the employer, carrier and authorized recovery representative, and provide all relevant awards and the current itemized payment ledger. Separate medical payments, indemnity, refunds, disputed charges and amounts asserted as attributable to this incident.\nPlease state your claimed lien and supporting basis under Virginia Code § 65.2-309, any steps taken to protect it, and your position on participation, expense allocation and any necessary consent. Identify any applicable future-entitlement issues under §§ 65.2-311 and 65.2-313.\nThe present third-party status is [INVESTIGATION / ACTION AND NUMBER / OTHER VERIFIED STATUS]. No settlement or lien amount is conceded by this notice. Please preserve relevant records and direct further communications to [CONTACT].\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Agreement Not to Plead Limitations","slug":"tolling","command":"/tolling","category":"demand","category_label":"Demands, negotiation and ADR","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Virginia § 8.01-232(A) written promise for an accrued claim while settlement is pursued; not a universal suspension of statutory deadlines.","docx":"docx/tolling.docx","reasoning":"../../reasoning/tolling.md","path":"templates/demand/tolling.md","docx_path":"templates/demand/docx/tolling.docx","reasoning_path":"reasoning/tolling.md","field_count":8,"md":"---\ntitle: \"Agreement Not to Plead Limitations\"\nslug: \"tolling\"\ncommand: \"/tolling\"\ncategory: \"demand\"\ncategory_label: \"Demands, negotiation and ADR\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Virginia § 8.01-232(A) written promise for an accrued claim while settlement is pursued; not a universal suspension of statutory deadlines.\"\ndocx: \"docx/tolling.docx\"\nreasoning: \"../../reasoning/tolling.md\"\n---\n# AGREEMENT NOT TO PLEAD THE STATUTE OF LIMITATIONS\nPromisee / claimant: [NAME]\nPromisor / responding party: [NAME AND CAPACITY]\nIdentified accrued claim: [TRANSACTION, DATE AND PRECISE CLAIM]\n## Purpose and promise\nTo avoid or defer litigation while the parties pursue settlement of the identified accrued claim, the Promisor agrees in writing not to assert the otherwise applicable statute-of-limitations defense based on the passage of time covered by this promise, provided the Promisee commences the identified action within the deadline stated below and the requirements of Virginia Code § 8.01-232(A) are satisfied.\nDate this written promise is made: [ACTUAL DATE].\nApplicable limitations period for the identified claim: [PERIOD AND VERIFIED AUTHORITY].\nLatest filing date permitted by § 8.01-232(A): [COMPUTED DATE].\nAgreed filing deadline, no later than that statutory limit: [DATE AND TIME].\n## Limits and reserved matters\nThis promise applies only to the stated parties and claim. It does not revive a claim already barred when the promise was made, bind another person, waive a statute of repose, extend a notice-of-claim or appeal deadline, or establish liability. All other defenses are reserved except as expressly stated: [ANY NEGOTIATED EXCEPTION].\nThis agreement has no automatic renewal or early termination. Any replacement promise must be separately signed and legally sufficient before reliance on it. Nothing authorizes an estate representative or joint contractor to bind others contrary to § 8.01-232(B) or (C).\nPromisor / authorized agent: [NAME AND CAPACITY]\nSignature: ____________________    Date: _______________\nPromisee / authorized agent: [NAME AND CAPACITY]\nSignature: ____________________    Date: _______________\n"},{"title":"Agreement to Mediate","slug":"mediation-agreement","command":"/mediation-agreement","category":"demand","category_label":"Demands, negotiation and ADR","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Private Virginia civil mediation engagement; not a settlement agreement or court referral order.","docx":"docx/mediation-agreement.docx","reasoning":"../../reasoning/mediation-agreement.md","path":"templates/demand/mediation-agreement.md","docx_path":"templates/demand/docx/mediation-agreement.docx","reasoning_path":"reasoning/mediation-agreement.md","field_count":13,"md":"---\ntitle: \"Agreement to Mediate\"\nslug: \"mediation-agreement\"\ncommand: \"/mediation-agreement\"\ncategory: \"demand\"\ncategory_label: \"Demands, negotiation and ADR\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Private Virginia civil mediation engagement; not a settlement agreement or court referral order.\"\ndocx: \"docx/mediation-agreement.docx\"\nreasoning: \"../../reasoning/mediation-agreement.md\"\n---\n# AGREEMENT TO MEDIATE\nMatter: [CASE / CLAIM]    Effective date: [DATE]\nParticipants: [PARTIES AND CAPACITIES]\nMediator: [NAME AND ORGANIZATION]\n## Process and authority\nThe participants agree to mediate [DEFINED DISPUTE] on [DATE] at [LOCATION / REMOTE PLATFORM]. The mediator facilitates discussion and does not decide the dispute. Each participant will arrange attendance by [AGREED PERSONS WITH APPROPRIATE SETTLEMENT AUTHORITY], subject to any required further approval.\nParticipation does not obligate anyone to settle. Any court-ordered attendance obligations remain governed by the actual referral order. Settlement terms become binding only as provided in an actual agreement satisfying applicable law and any required approval.\n## Confidentiality and permitted use\nMediation communications will receive the protection afforded by applicable Virginia law, including its exceptions. This agreement does not make independently discoverable evidence unavailable, guarantee secrecy of a signed settlement, or restrict disclosures required by law. Additional agreed confidentiality terms are [PRECISE TERMS, IF ANY].\n## Practical arrangements\nFees, allocation, deposits and cancellation terms: [AGREED TERMS].\nExchange of mediation materials and attendance arrangements: [TERMS].\nThe mediator will disclose [REQUIRED CONFLICT INFORMATION]; any informed consent is [ACTUAL WRITTEN CONSENT]. No participant will record the session without the agreement of all participants and any required legal authorization.\n## Agreement\nParty / authorized representative: [NAME AND CAPACITY]\nSignature: ____________________    Date: _______________\nOther party / authorized representative: [NAME AND CAPACITY]\nSignature: ____________________    Date: _______________\nMediator: ____________________    Date: _______________\n"},{"title":"Demand Exhibit Index","slug":"demand-exhibits","command":"/demand-exhibits","category":"demand","category_label":"Demands, negotiation and ADR","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Demand Exhibit Index for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/demand-exhibits.docx","reasoning":"../../reasoning/demand-exhibits.md","path":"templates/demand/demand-exhibits.md","docx_path":"templates/demand/docx/demand-exhibits.docx","reasoning_path":"reasoning/demand-exhibits.md","field_count":17,"md":"---\ntitle: \"Demand Exhibit Index\"\nslug: \"demand-exhibits\"\ncommand: \"/demand-exhibits\"\ncategory: \"demand\"\ncategory_label: \"Demands, negotiation and ADR\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Demand Exhibit Index for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/demand-exhibits.docx\"\nreasoning: \"../../reasoning/demand-exhibits.md\"\n---\n# Demand Exhibit Index\nClaimant: [NAME]    Claim: [NUMBER]\nIncident: [DATE]    Prepared: [DATE]\nDemand version: [IDENTIFIED LETTER AND DATE]\n## Selected exhibits\nExhibit [LETTER] — [DOCUMENT TITLE AND DATE]\nSource: [EXACT DOSSIER FILE IDENTIFIER AND VERSION]\nIncluded pages: [ACTUAL PAGE RANGE]\nPurpose: [FACT SUPPORTED WITH EXACT SOURCE PAGE]\nDisclosure review: [ACTUAL AUTHORIZATION, REDACTIONS AND EXCLUDED PAGES]\n[REPEAT FOR EACH APPROVED EXHIBIT IN FINAL PACKET ORDER.]\n## Packet reconciliation\nThe physical packet’s exhibit labels and included pages are [VERIFIED AGAINST THE FINAL PACKET / NOT YET VERIFIED]. Missing or excluded material is [SPECIFIC STATUS]. A listed document is described as attached only after its inclusion is confirmed.\nLetter references requiring correction are [EXACT LOCATIONS / NONE AFTER REVIEW]. Source statements quoted in the demand have been checked against [EXACT DOCUMENT AND PAGE REFERENCES].\n## Completion\nReviewed by: [NAME]    Review date: [ACTUAL DATE]\nFinal packet filename and version: [ACTUAL OUTPUT / NOT YET ASSEMBLED]\nThis index records the selected materials; it is not itself the attached records or proof of delivery.\n"},{"title":"Judicial Settlement Conference Statement","slug":"msc","command":"/msc","category":"demand","category_label":"Demands, negotiation and ADR","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"DOCUMENT","pages":1,"scope":"Circuit Court civil conference under an actual referral or authorized procedure. The original mandatory-settlement label is not a universal filing requirement. Use the actual neutral’s exchange/confidentiality rules; do not add a routine service certificate or claim blanket privilege.","docx":"docx/msc.docx","reasoning":"../../reasoning/msc.md","path":"templates/demand/msc.md","docx_path":"templates/demand/docx/msc.docx","reasoning_path":"reasoning/msc.md","field_count":20,"md":"---\ntitle: \"Judicial Settlement Conference Statement\"\nslug: \"msc\"\ncommand: \"/msc\"\ncategory: \"demand\"\ncategory_label: \"Demands, negotiation and ADR\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Circuit Court civil conference under an actual referral or authorized procedure. The original mandatory-settlement label is not a universal filing requirement. Use the actual neutral’s exchange/confidentiality rules; do not add a routine service certificate or claim blanket privilege.\"\ndocx: \"docx/msc.docx\"\nreasoning: \"../../reasoning/msc.md\"\n---\n# JUDICIAL SETTLEMENT CONFERENCE STATEMENT\nFor: [SETTLEMENT JUDGE OR NEUTRAL]\nCase: [CASE STYLE, CIRCUIT COURT AND NUMBER]\nSubmitted for: [PARTY]    Conference: [DATE AND METHOD]\nDistribution: [RECIPIENTS REQUIRED BY ACTUAL ORDER OR CONFERENCE INSTRUCTIONS]\n## Conference authority and status\nThe referring order or agreed procedure is [ORDER DATE OR AGREEMENT]. The judge’s instructions concerning submission, exchange and confidentiality are [ACTUAL INSTRUCTIONS]. This statement is submitted for the conference under those instructions; it is not designated for filing on the public docket unless required.\n## Material facts and issues\n[CONCISE FACTUAL BACKGROUND AND DISPUTED FACTS]. The principal liability and defense issues are [ISSUES WITH RELEVANT EVIDENCE]. The legal positions and material uncertainties are [VERIFIED AUTHORITIES AND RISKS].\n## Damages and litigation posture\nClaimed damages are [ITEMIZED AMOUNTS AND SUPPORT]; disputed causation, mitigation and valuation issues are [ISSUES]. Discovery completed, material remaining work, pending motions and trial date are [ACTUAL STATUS].\n## Settlement history and obstacles\nOffers and demands authorized for disclosure are [ACCURATE DATES, AMOUNTS AND TERMS]. Remaining barriers include [DISPUTED TERMS, COVERAGE, LIENS, APPROVALS OR OTHER ISSUES]. Any information reserved for separate caucus is to be supplied separately under the neutral’s instructions.\n## Participants and proposed resolution\nParticipants and the source or limits of settlement authority are [NAMES, CAPACITIES AND ACTUAL AUTHORITY]. The proposed monetary and nonmonetary terms are [AUTHORIZED PROPOSAL]. Required approvals, payment timing and unresolved allocation issues are [DETAILS].\nSubmitted by: [COUNSEL NAME, VSB NUMBER AND CONTACT DETAILS]\nSignature: ________________________________  Date: [DATE]\n"},{"title":"Mediation Statement","slug":"mediation-brief","command":"/mediation-brief","category":"demand","category_label":"Demands, negotiation and ADR","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Mediation submission in an ordinary Virginia PI dispute; shared versus confidential submission must be selected.","docx":"docx/mediation-brief.docx","reasoning":"../../reasoning/mediation-brief.md","path":"templates/demand/mediation-brief.md","docx_path":"templates/demand/docx/mediation-brief.docx","reasoning_path":"reasoning/mediation-brief.md","field_count":19,"md":"---\ntitle: \"Mediation Statement\"\nslug: \"mediation-brief\"\ncommand: \"/mediation-brief\"\ncategory: \"demand\"\ncategory_label: \"Demands, negotiation and ADR\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Mediation submission in an ordinary Virginia PI dispute; shared versus confidential submission must be selected.\"\ndocx: \"docx/mediation-brief.docx\"\nreasoning: \"../../reasoning/mediation-brief.md\"\n---\n# MEDIATION STATEMENT\nMatter: [PARTIES AND CLAIM OR CASE]\nMediator: [NAME]    Mediation date: [DATE]\nSubmission status: [SHARED WITH PARTIES / MEDIATOR ONLY UNDER ACTUAL ARRANGEMENT]\n## Dispute and requested resolution\nThis matter concerns [CONCISE DESCRIPTION]. The submitting party seeks [RELIEF OR SETTLEMENT OBJECTIVE]. The current procedural posture and significant pending events are [VERIFIED STATUS].\n## Material facts and evidence\n[CHRONOLOGICAL FACTS WITH DOCUMENT OR TESTIMONY REFERENCES]. Facts agreed by the parties are [ACTUAL AGREEMENTS]; disputed facts are [ISSUES AND COMPETING POSITIONS].\n## Liability and defenses\n[CLAIMS, ELEMENTS, MATERIAL DEFENSES AND APPLICABLE AUTHORITIES]. The principal strengths and risks are [CANDID ASSESSMENT SUPPORTED BY THE RECORD].\n## Damages and coverage\n[ITEMIZED SUPPORTED LOSSES, CAUSATION ISSUES, RELEVANT COVERAGE AND KNOWN LIENS]. The requested recovery and its calculation are [DETAILS]. Separate established amounts from estimates and disputed amounts.\n## Negotiations and practical issues\nPrior offers and demands authorized for disclosure are [ACTUAL HISTORY]. Issues affecting resolution include [PAYMENT, RELEASE, LIENS, OTHER CLAIMS OR APPROVALS]. Participants and authority arrangements are [VERIFIED DETAILS].\n## Proposed path to agreement\n[PROPOSED TERMS, DOCUMENTS NEEDED AND REMAINING DECISIONS]. The client retains the settlement decision. This submission does not itself execute a settlement or establish unlimited negotiating authority.\nAttachments actually furnished: [LIST]. Confidentiality and permitted distribution are governed by applicable law and the mediation arrangements.\n"},{"title":"Policy Limits Settlement Demand","slug":"policylimits","command":"/policylimits","category":"demand","category_label":"Demands, negotiation and ADR","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Third-party limits settlement offer; distinct from the statutory policy-limits disclosure request.","docx":"docx/policylimits.docx","reasoning":"../../reasoning/policylimits.md","path":"templates/demand/policylimits.md","docx_path":"templates/demand/docx/policylimits.docx","reasoning_path":"reasoning/policylimits.md","field_count":26,"md":"---\ntitle: \"Policy Limits Settlement Demand\"\nslug: \"policylimits\"\ncommand: \"/policylimits\"\ncategory: \"demand\"\ncategory_label: \"Demands, negotiation and ADR\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Third-party limits settlement offer; distinct from the statutory policy-limits disclosure request.\"\ndocx: \"docx/policylimits.docx\"\nreasoning: \"../../reasoning/policylimits.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: Policy Limits Settlement Demand - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT] concerning the [DATE] incident involving [INSURED]. This is a client-authorized offer to settle [PRECISE CLAIMS] for [IDENTIFIED AVAILABLE LIABILITY LIMITS AND DOLLAR AMOUNT], subject to the material terms below.\nLiability is supported by [MATERIAL FACTS AND IDENTIFIED EVIDENCE]. The injuries, treatment and losses are [SUPPORTED SUMMARY], with documented amounts and source references in [ACTUAL ENCLOSURES]. Disputed issues and relevant contrary information are [ACCURATE DESCRIPTION].\nThe proposed settlement includes [NAMED RELEASED PARTIES AND EXACT RELEASE SCOPE], payment by [METHOD AND TIMING], and [AGREED OR PROPOSED LIEN, COST AND OTHER MATERIAL TERMS]. Rights expressly reserved are [IDENTIFY RIGHTS]. If UM/UIM coverage is implicated, the appropriate statutory settlement and notice terms must be resolved before execution; this offer does not supply an omitted statutory notice or insured signature.\nPlease respond by [REASONABLE DATE AND TIME] through [METHOD]. Identify promptly any information reasonably needed to evaluate this offer or any proposed change to its terms. The actual materials furnished are [ENCLOSURE LIST].\nPlease communicate this proposal to the appropriate decision makers. Any assertion of extra-contractual liability would require its own supported legal and factual basis; it is not established merely by this letter.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Proposal for Mediation","slug":"adr-notice","command":"/adr-notice","category":"demand","category_label":"Demands, negotiation and ADR","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Proposal for Mediation for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/adr-notice.docx","reasoning":"../../reasoning/adr-notice.md","path":"templates/demand/adr-notice.md","docx_path":"templates/demand/docx/adr-notice.docx","reasoning_path":"reasoning/adr-notice.md","field_count":18,"md":"---\ntitle: \"Proposal for Mediation\"\nslug: \"adr-notice\"\ncommand: \"/adr-notice\"\ncategory: \"demand\"\ncategory_label: \"Demands, negotiation and ADR\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Proposal for Mediation for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/adr-notice.docx\"\nreasoning: \"../../reasoning/adr-notice.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Proposal for Mediation — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nWe propose mediation of [IDENTIFIED CLAIMS] in [CASE OR CLAIM]. The proposed mediator or selection process is [NAME / ACTUAL PROPOSAL], and proposed dates, duration and location or remote format are [DETAILS].\nParticipants and settlement authority would be [IDENTIFIED PARTIES, INSURERS AND AUTHORITY ARRANGEMENT]. Proposed allocation of mediator fees, submission dates and cancellation terms is [SPECIFIC TERMS], subject to written agreement and any governing court order.\nCurrent scheduling obligations and any requested change are [ACTUAL DEADLINES AND SEPARATE REQUEST]. This proposal alone does not continue a trial, stay discovery or waive any claim or defense.\nPlease state your position by [PROPOSED RESPONSE DATE]. Confidentiality is governed by applicable Virginia law, its exceptions and the parties’ valid agreement; we do not claim that every underlying document becomes confidential by being used in mediation. A mediation date will be confirmed after actual agreement or court direction.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Settlement Counteroffer","slug":"counter","command":"/counter","category":"demand","category_label":"Demands, negotiation and ADR","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Virginia personal-injury matter; ordinary adult claimant.","docx":"docx/counter.docx","reasoning":"../../reasoning/counter.md","path":"templates/demand/counter.md","docx_path":"templates/demand/docx/counter.docx","reasoning_path":"reasoning/counter.md","field_count":23,"md":"---\ntitle: \"Settlement Counteroffer\"\nslug: \"counter\"\ncommand: \"/counter\"\ncategory: \"demand\"\ncategory_label: \"Demands, negotiation and ADR\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia personal-injury matter; ordinary adult claimant.\"\ndocx: \"docx/counter.docx\"\nreasoning: \"../../reasoning/counter.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION]\n[DELIVERY ADDRESS]\nRe: Settlement Counteroffer — [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe write concerning your [DATE] proposal of $[OFFER AMOUNT] to resolve [IDENTIFIED CLAIM]. After consultation with our client, we propose $[AUTHORIZED COUNTEROFFER] on the terms stated below.\nThe principal issues supporting this proposal are [SUPPORTED LIABILITY, CAUSATION OR DAMAGES POINTS]. [IDENTIFY NEW INFORMATION OR A SPECIFIC CORRECTION TO THE PRIOR EVALUATION].\nOur proposal concerns [PARTIES AND CLAIMS] and includes [AUTHORIZED MATERIAL TERMS]. The treatment of [LIENS, RELEASE SCOPE, PAYMENT TIMING OR OTHER MATERIAL TERM] is [CLIENT-AUTHORIZED POSITION]. [IDENTIFY ANY EXPRESSLY RESERVED CLAIM OR COVERAGE RIGHT].\nPlease respond by [REQUESTED DATE AND TIME]. Please direct any proposed changes to our office for review with our client.\n[IDENTIFY ACTUAL ENCLOSURES, IF ANY].\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Settlement Demand","slug":"demand","command":"/demand","category":"demand","category_label":"Demands, negotiation and ADR","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Virginia personal-injury matter; ordinary adult claimant.","docx":"docx/demand.docx","reasoning":"../../reasoning/demand.md","path":"templates/demand/demand.md","docx_path":"templates/demand/docx/demand.docx","reasoning_path":"reasoning/demand.md","field_count":25,"md":"---\ntitle: \"Settlement Demand\"\nslug: \"demand\"\ncommand: \"/demand\"\ncategory: \"demand\"\ncategory_label: \"Demands, negotiation and ADR\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia personal-injury matter; ordinary adult claimant.\"\ndocx: \"docx/demand.docx\"\nreasoning: \"../../reasoning/demand.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION]\n[DELIVERY ADDRESS]\nRe: Settlement Demand — [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [CLIENT] concerning the [DATE] incident involving [INSURED OR RESPONSIBLE PARTY], claim number [NUMBER]. Our client proposes to resolve [IDENTIFIED CLAIMS] for $[AUTHORIZED DEMAND].\n## Liability\n[CONCISE SUPPORTED INCIDENT FACTS AND BASIS OF RESPONSIBILITY]. [ADDRESS MATERIAL CONTRARY EVIDENCE OR LIABILITY ISSUES AS APPROPRIATE].\n## Injuries and damages\n[SUPPORTED INJURIES, TREATMENT COURSE AND CURRENT CONDITION]. The documented losses are [ITEMIZED SUPPORTED LOSSES, WITH CLEAR DISTINCTION BETWEEN CHARGES, PAYMENTS AND BALANCES]. [SUPPORTED NON-ECONOMIC OR FUTURE-DAMAGE CONTENT, IF APPLICABLE].\n## Proposed resolution\nThe proposed resolution covers [PARTIES AND CLAIMS] on [AUTHORIZED MATERIAL TERMS]. [IDENTIFY RESERVED CLAIMS OR COVERAGE RIGHTS AND ANY TERMS REQUIRING FURTHER AGREEMENT]. Please respond by [REQUESTED DATE AND TIME].\nThe materials supplied for evaluation are [ACTUAL ENCLOSURE LIST]. Please contact us concerning any information needed to evaluate this proposal.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Settlement Opportunity and Claims-Handling Notice","slug":"badfaith","command":"/badfaith","category":"demand","category_label":"Demands, negotiation and ADR","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Virginia liability-insurer settlement-opportunity letter; no assumed direct third-party bad-faith cause of action.","docx":"docx/badfaith.docx","reasoning":"../../reasoning/badfaith.md","path":"templates/demand/badfaith.md","docx_path":"templates/demand/docx/badfaith.docx","reasoning_path":"reasoning/badfaith.md","field_count":22,"md":"---\ntitle: \"Settlement Opportunity and Claims-Handling Notice\"\nslug: \"badfaith\"\ncommand: \"/badfaith\"\ncategory: \"demand\"\ncategory_label: \"Demands, negotiation and ADR\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia liability-insurer settlement-opportunity letter; no assumed direct third-party bad-faith cause of action.\"\ndocx: \"docx/badfaith.docx\"\nreasoning: \"../../reasoning/badfaith.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Settlement Opportunity and Claims-Handling Notice — [CLIENT / CLAIM NUMBER]\nDear [RECIPIENT NAME]:\nWe represent [CLAIMANT] concerning the [DATE] incident involving your insured, [INSURED]. This letter addresses the settlement opportunity described in [ACTUAL DEMAND AND DATE]. The offer remains governed by [PRECISE TERMS AND VERIFIED DEADLINE]; this letter changes those terms only as expressly stated here: [ANY CHANGE].\nThe evidence supporting liability is [SPECIFIC FACTS AND RECORDS]. Documented damages and the potential exposure are [SUPPORTED SUMMARY], with [MATERIALS ACTUALLY PROVIDED]. Please identify any additional information reasonably needed to evaluate the claim and any coverage issue affecting your response.\nPlease give the insured timely information about the demand and material exposure, evaluate the available settlement opportunity, and respond through [CONTACT] by [REASONABLE DATE]. Our client’s actual position on release scope, payment and other settlement conditions is [TERMS].\nThis notice preserves the claimant’s position without asserting that a third-party claimant automatically possesses the insured’s contractual rights. Any claim for statutory remedies would require its own standing, prerequisites and proof. [IF A SPECIFIC STATUTORY NOTICE IS INTENDED, IDENTIFY THE APPLICABLE SUBSECTION, REQUIRED CONTENT AND VERIFIED COMPLIANCE BEFORE INCLUDING THAT DEMAND].\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"UM or UIM Benefits Demand","slug":"umuim-demand","command":"/umuim-demand","category":"demand","category_label":"Demands, negotiation and ADR","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Demand under an identified Virginia UM/UIM policy; requires the actual coverage regime, insured status and loss calculation.","docx":"docx/umuim-demand.docx","reasoning":"../../reasoning/umuim-demand.md","path":"templates/demand/umuim-demand.md","docx_path":"templates/demand/docx/umuim-demand.docx","reasoning_path":"reasoning/umuim-demand.md","field_count":27,"md":"---\ntitle: \"UM or UIM Benefits Demand\"\nslug: \"umuim-demand\"\ncommand: \"/umuim-demand\"\ncategory: \"demand\"\ncategory_label: \"Demands, negotiation and ADR\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Demand under an identified Virginia UM/UIM policy; requires the actual coverage regime, insured status and loss calculation.\"\ndocx: \"docx/umuim-demand.docx\"\nreasoning: \"../../reasoning/umuim-demand.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION OR CLIENT ADDRESS]\n[DELIVERY ADDRESS]\nRe: UM or UIM Benefits Demand - [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe represent [INSURED CLAIMANT] under [POLICY, NAMED INSURED AND EFFECTIVE DATES] for the [DATE] collision at [LOCATION]. We request $[AMOUNT] in [UM / UIM] benefits on the grounds below.\nThe basis for insured status and applicable coverage is [POLICY TERMS, ELECTIONS AND SUPPORTING FACTS]. The adverse vehicle’s insurance status and available liability coverage are [SUPPORTED DETAILS]. Other policies, payments, releases and relevant proceedings are [IDENTIFIED DETAILS].\nThe evidence of the adverse driver’s legal responsibility is [FACTS AND SOURCES]. Our client’s injuries, treatment and resulting losses are [SUPPORTED SUMMARY AND ITEMIZATION]. The amount demanded is calculated as [CASE-SPECIFIC CALCULATION UNDER THE APPLICABLE POLICY AND LAW], without assuming a universal offset or exhaustion rule.\nPrior liability settlement and required statutory steps, if any, are [ACTUAL STATUS AND DOCUMENTS]. This demand does not replace service of process, required signatures or notices. Any unresolved coverage or causation issue is [ISSUE AND SUPPORTING POSITION].\nPlease evaluate the enclosed [ACTUAL MATERIALS] and respond by [REQUESTED DATE]. If further information or a policy condition is asserted, identify the request and its basis so it can be addressed. All proposed settlement and release terms remain [SPECIFIC TERMS OR SUBJECT TO FURTHER CLIENT APPROVAL].\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Client Decision on Settlement Planning","slug":"snt-waiver","command":"/snt-waiver","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Replaces the misleading general waiver label with a record of actual informed choices. It is neither a release nor permission to ignore benefit, Medicare, fiduciary or court requirements. Do not fabricate a consultation or capable consent.","docx":"docx/snt-waiver.docx","reasoning":"../../reasoning/snt-waiver.md","path":"templates/settlement/snt-waiver.md","docx_path":"templates/settlement/docx/snt-waiver.docx","reasoning_path":"reasoning/snt-waiver.md","field_count":19,"md":"---\ntitle: \"Client Decision on Settlement Planning\"\nslug: \"snt-waiver\"\ncommand: \"/snt-waiver\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Replaces the misleading general waiver label with a record of actual informed choices. It is neither a release nor permission to ignore benefit, Medicare, fiduciary or court requirements. Do not fabricate a consultation or capable consent.\"\ndocx: \"docx/snt-waiver.docx\"\nreasoning: \"../../reasoning/snt-waiver.md\"\n---\n# CLIENT DECISION ON SETTLEMENT PLANNING\nClient: [CLIENT NAME]    Matter: [MATTER]\nConference date: [ACTUAL DATE]    Participants: [NAMES AND CAPACITIES]\n## Advice and available choices\nThe settlement funds and expected payment date are [AMOUNT AND DATE]. Benefits currently received or applied for are [PROGRAMS AND KNOWN STATUS]. The client’s authority and ability to make this decision are [VERIFIED CAPACITY OR REPRESENTATIVE AUTHORITY].\nThe planning option discussed was [SPECIFIC TRUST, POOLED TRUST OR FUTURE-MEDICAL ARRANGEMENT]. Advice actually given, anticipated costs, alternatives and unresolved questions were [DESCRIPTION]. The specialist consulted or offered was [NAME AND CONSULTATION STATUS].\nThe identified consequences of declining that option are [CASE-SPECIFIC BENEFIT, ASSET, ADMINISTRATION AND FUTURE-MEDICAL CONSEQUENCES]. A special needs trust and a Medicare set-aside address different issues; declining one does not resolve the other.\n## Client’s decision\nI choose [PRECISE OPTION ACCEPTED OR DECLINED] for these reasons: [CLIENT’S STATED REASONS]. I have had [ACTUAL OPPORTUNITY] to ask questions and obtain independent advice. Questions still unresolved are [QUESTIONS OR NONE]. The next steps and responsible persons are [STEPS, RESPONSIBLE PERSONS AND DATES].\nMy decision does not waive Medicare’s rights, change benefit-program rules, authorize disbursement contrary to an order, or release my lawyer from professional duties or liability. Any required court or fiduciary approval must still be obtained.\nClient or authorized representative: [NAME AND CAPACITY]\nSignature: ________________________________  Date: [DATE]\nCounsel’s record of advice and follow-up: [ACTUAL RECORD LOCATION]\n"},{"title":"Client Distribution Authorization and Record","slug":"client-check","command":"/client-check","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Virginia settlement disbursement record; planned authorization, actual transfer and client acknowledgment kept separate.","docx":"docx/client-check.docx","reasoning":"../../reasoning/client-check.md","path":"templates/settlement/client-check.md","docx_path":"templates/settlement/docx/client-check.docx","reasoning_path":"reasoning/client-check.md","field_count":15,"md":"---\ntitle: \"Client Distribution Authorization and Record\"\nslug: \"client-check\"\ncommand: \"/client-check\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Virginia settlement disbursement record; planned authorization, actual transfer and client acknowledgment kept separate.\"\ndocx: \"docx/client-check.docx\"\nreasoning: \"../../reasoning/client-check.md\"\n---\n# CLIENT DISTRIBUTION AUTHORIZATION AND RECORD\nClient: [NAME]    Matter: [IDENTIFIER]\nAccounting statement: [DATE / VERSION]\n## Distribution authorized\nCleared funds available: $[AMOUNT]. Approved fees and costs: $[AMOUNT]. Authorized third-party payments: $[AMOUNT]. Required reserve: $[AMOUNT AND PURPOSE]. Net amount for this distribution: $[AMOUNT].\nPayee: [EXACT AUTHORIZED NAME AND CAPACITY]. Method: [CHECK / WIRE]. Delivery instructions: [VERIFIED ADDRESS OR SECURE INSTRUCTION REFERENCE; NO FULL ACCOUNT DETAILS HERE].\nI approve the distribution shown in the identified accounting, subject to its stated reserves and unresolved matters. This authorization is not a release of unrelated rights or acknowledgment of funds not yet received.\nClient / authorized representative signature: ____________________\nName and capacity: [NAME]    Date: [ACTUAL DATE]\n## Firm verification and actual transaction\nAuthority and cleared-funds verification: [PERSON, DATE AND RECORD].\nPayment instructions independently verified through: [KNOWN CONTACT METHOD, PERSON AND DATE].\nActual amount sent: $[AMOUNT]. Date: [DATE]. Check / transfer reference: [REFERENCE]. Transaction status: [ISSUED / DELIVERED / CLEARED / OTHER VERIFIED STATUS].\nRecorded by: [NAME]    Date: [DATE]\n## Receipt acknowledgment, if obtained\nI acknowledge actual receipt of [CHECK / FUNDS AND AMOUNT] on [DATE]. Receipt of a check does not itself establish clearance.\nRecipient signature: ____________________    Date: ____________\n"},{"title":"Client Settlement Authorization","slug":"settlement-auth","command":"/settlement-auth","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Competent adult client’s specific settlement instruction; not a release to the opposing party or court approval for a protected claimant.","docx":"docx/settlement-auth.docx","reasoning":"../../reasoning/settlement-auth.md","path":"templates/settlement/settlement-auth.md","docx_path":"templates/settlement/docx/settlement-auth.docx","reasoning_path":"reasoning/settlement-auth.md","field_count":20,"md":"---\ntitle: \"Client Settlement Authorization\"\nslug: \"settlement-auth\"\ncommand: \"/settlement-auth\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Competent adult client’s specific settlement instruction; not a release to the opposing party or court approval for a protected claimant.\"\ndocx: \"docx/settlement-auth.docx\"\nreasoning: \"../../reasoning/settlement-auth.md\"\n---\n# CLIENT SETTLEMENT AUTHORIZATION\nClient: [FULL NAME]    Matter: [CASE OR CLAIM]\nDate of discussion: [DATE]    Attorney: [NAME]\n## Proposal considered\nThe proposal from [COUNTERPARTY] is payment of $[GROSS AMOUNT] in exchange for [EXACT RELEASED CLAIMS AND MATERIAL TERMS]. Payment timing is [TERMS]. The release form or proposed agreement reviewed is [IDENTIFIER AND VERSION].\nClaims and persons excluded from the release are [EXCLUSIONS]. Conditions needing resolution before acceptance are [CONDITIONS].\n## Financial explanation\nEstimated attorney fee: $[AMOUNT AND AGREED METHOD]. Estimated expenses: $[AMOUNT]. Known liens or reimbursement demands: [ITEMIZED AMOUNTS AND STATUS]. Proposed holdback: $[AMOUNT AND PURPOSE]. Estimated net to Client: $[AMOUNT AND CALCULATION]. An estimate is not a guarantee of final lien resolution or net payment.\n## Client decision\nAfter discussing the proposal, material risks and alternatives, I instruct the Firm to [ACCEPT THE IDENTIFIED PROPOSAL / REJECT IT / MAKE THE SPECIFIC COUNTEROFFER], subject only to [EXPRESS CONDITIONS]. Delete unselected alternatives before signing. This authority does not extend to materially different terms without further consultation.\nQuestions or unresolved matters: [DETAILS]. I understand that a binding release can end the claims it covers and that other benefits, lien or coverage consequences identified to me are [DETAILS].\nClient signature: ____________________    Date: [DATE]\nPrinted name and capacity: [NAME AND CAPACITY]\nAttorney acknowledgment of discussion: ____________________    Date: [DATE]\n"},{"title":"Client Trust Ledger and Settlement Accounting","slug":"trust-ledger","command":"/trust-ledger","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"A client-specific record and reconciliation template; not a substitute for required account-wide journals and bank reconciliation.","docx":"docx/trust-ledger.docx","reasoning":"../../reasoning/trust-ledger.md","path":"templates/settlement/trust-ledger.md","docx_path":"templates/settlement/docx/trust-ledger.docx","reasoning_path":"reasoning/trust-ledger.md","field_count":20,"md":"---\ntitle: \"Client Trust Ledger and Settlement Accounting\"\nslug: \"trust-ledger\"\ncommand: \"/trust-ledger\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"A client-specific record and reconciliation template; not a substitute for required account-wide journals and bank reconciliation.\"\ndocx: \"docx/trust-ledger.docx\"\nreasoning: \"../../reasoning/trust-ledger.md\"\n---\n# CLIENT TRUST LEDGER AND SETTLEMENT ACCOUNTING\nClient and matter: [IDENTIFIERS]\nTrust account reference: [MASKED ACCOUNT IDENTIFIER]\nReporting period: [DATES]    Prepared by: [NAME]\n## Opening balance\nBalance carried forward: [AMOUNT], reconciled to [PRIOR LEDGER DATE AND SOURCE].\n## Transaction entry [NUMBER]\nTransaction date: [DATE]    Receipt or disbursement: [TYPE]\nPayor or payee: [NAME]    Amount: [AMOUNT]\nSource of receipt or purpose of payment: [DESCRIPTION]\nMethod and source-document reference: [CHECK, DEPOSIT OR TRANSFER REFERENCE]\nRunning client balance after this entry: [AMOUNT]\n[REPEAT THE COMPLETE ENTRY FOR EVERY ACTUAL TRANSACTION IN CHRONOLOGICAL ORDER].\n## Period reconciliation\nOpening balance [AMOUNT] plus actual receipts [AMOUNT] less actual disbursements [AMOUNT] equals closing client balance [AMOUNT]. Outstanding client-specific items and their status are [ITEMS]. The supporting bank/journal reconciliation reference is [REFERENCE].\nFunds retained for identified unresolved claims are [AMOUNT, CLAIMANT AND BASIS]. Undisputed amount available for delivery is [VERIFIED AMOUNT]. Planned payments are listed separately as [PLANS] and are not counted as completed disbursements.\n## Review\nSource documents checked: [REFERENCES]. Discrepancies and resolution: [DETAILS OR NONE].\nReviewer: [NAME]    Review date: [DATE]\nClient accounting delivered on: [ACTUAL DATE AND METHOD OR NOT YET DELIVERED]\n"},{"title":"Confidentiality Agreement","slug":"nda","command":"/nda","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Negotiated private Virginia civil disclosure agreement; not a court protective order, employment NDA or public-agency secrecy promise.","docx":"docx/nda.docx","reasoning":"../../reasoning/nda.md","path":"templates/settlement/nda.md","docx_path":"templates/settlement/docx/nda.docx","reasoning_path":"reasoning/nda.md","field_count":11,"md":"---\ntitle: \"Confidentiality Agreement\"\nslug: \"nda\"\ncommand: \"/nda\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Negotiated private Virginia civil disclosure agreement; not a court protective order, employment NDA or public-agency secrecy promise.\"\ndocx: \"docx/nda.docx\"\nreasoning: \"../../reasoning/nda.md\"\n---\n# CONFIDENTIALITY AGREEMENT\nEffective date: [DATE]\nDisclosing party: [NAME]    Receiving party: [NAME]\nPurpose: [SPECIFIC EVALUATION OR NEGOTIATION]\n## Covered information and permitted use\n“Confidential Information” means [PRECISELY IDENTIFIED MATERIALS AND DESIGNATION METHOD] disclosed for the stated purpose. The receiving party may use it only for that purpose and disclose it only to [DEFINED REPRESENTATIVES] who need access and are subject to appropriate confidentiality duties.\nInformation is excluded to the extent it was lawfully known without restriction, becomes public without breach, is independently developed, or is lawfully received from another source without a confidentiality duty.\n## Legal obligations and protection\nThe receiving party will use [AGREED REASONABLE SAFEGUARDS]. If disclosure is required by law or process, it may disclose what is legally required, providing lawful advance notice where permitted and a reasonable opportunity to seek protection. No provision restricts legally protected reporting, cooperation with authorities, truthful testimony or compliance with professional duties.\nThis agreement creates no court sealing order and changes no discovery obligation. It does not establish privilege for otherwise unprotected material or constitute a release of claims.\n## Duration and disposition\nThe duties continue for [DEFINED PERIOD AND ANY LAWFUL EXCEPTION]. On [TRIGGER], materials will be [RETURNED OR DESTROYED], subject to identified legal retention, backup and counsel-record exceptions with continued protection.\nGoverning law and agreed forum: [TERMS]. Any remedy must satisfy applicable law; no automatic injunction, penalty or fee shift is implied. Changes require a signed writing. Each signer confirms authority to bind the identified party.\nDisclosing party signature: ____________________    Date: _______\nName / capacity: [NAME AND CAPACITY]\nReceiving party signature: ____________________    Date: _______\nName / capacity: [NAME AND CAPACITY]\n"},{"title":"Covenant Not to Sue","slug":"covenant","command":"/covenant","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Covenant Not to Sue for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/covenant.docx","reasoning":"../../reasoning/covenant.md","path":"templates/settlement/covenant.md","docx_path":"templates/settlement/docx/covenant.docx","reasoning_path":"reasoning/covenant.md","field_count":14,"md":"---\ntitle: \"Covenant Not to Sue\"\nslug: \"covenant\"\ncommand: \"/covenant\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Covenant Not to Sue for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/covenant.docx\"\nreasoning: \"../../reasoning/covenant.md\"\n---\n# Covenant Not to Sue\nDate: [DATE]\nCovenanting claimant: [EXACT NAME AND CAPACITY]\nProtected party: [EXACT NAME AND CAPACITY]\nIncident and claims: [PRECISE DESCRIPTION]\n## Consideration and effective conditions\nIn exchange for [ACTUAL CONSIDERATION AND PAYMENT TERMS], and effective upon [VERIFIED CONDITION], the claimant agrees not to commence or maintain [PRECISE DEFINED CLAIMS] against the protected party arising from [DEFINED INCIDENT].\nThis covenant extends only to [IDENTIFIED PERSONS AND CLAIMS]. Reserved claims and parties are [EXPLICIT RESERVATIONS]. The treatment of any pending action is [ACTUAL AGREED DISMISSAL OR OTHER PROCEDURE], requiring any necessary separate court filing or approval.\n## Other claims and statutory effect\nThe parties intend a good-faith resolution within the applicable provisions of Virginia Code § 8.01-35.1. Any reduction of claims against others and contribution consequences are governed by the statute and actual agreement; this document does not guarantee preservation of every recovery right or bind a nonsignatory.\nOutstanding medical, governmental, benefit-plan and other third-party interests are addressed by [EXACT AGREED TERMS]. No personal undertaking by counsel or waiver by a third party is implied.\n## Agreement\nAuthority, any required approval and conditions to performance are [ACTUAL BASIS]. Changes require [AGREED WRITING AND SIGNATURES].\nClaimant signature: ____________________    Date: [DATE]\nProtected party signature: ____________________    Date: [DATE]\nAuthorized capacities: [ACTUAL CAPACITIES]\n"},{"title":"Itemized Closing Statement","slug":"itemized-bill","command":"/itemized-bill","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Virginia client fee/expense and settlement statement; distinct from a court bill of taxable costs.","docx":"docx/itemized-bill.docx","reasoning":"../../reasoning/itemized-bill.md","path":"templates/settlement/itemized-bill.md","docx_path":"templates/settlement/docx/itemized-bill.docx","reasoning_path":"reasoning/itemized-bill.md","field_count":24,"md":"---\ntitle: \"Itemized Closing Statement\"\nslug: \"itemized-bill\"\ncommand: \"/itemized-bill\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Virginia client fee/expense and settlement statement; distinct from a court bill of taxable costs.\"\ndocx: \"docx/itemized-bill.docx\"\nreasoning: \"../../reasoning/itemized-bill.md\"\n---\n# ITEMIZED CLOSING STATEMENT\nClient: [NAME]    Matter: [IDENTIFIER]    Statement date: [DATE]\nFee agreement: [DATE AND CONTROLLING TERMS]\n## Recovery and fees\nGross recovery: $[GROSS]. Funds actually received: $[RECEIVED]. Funds cleared: $[CLEARED]. Any amount still due: $[AMOUNT AND SOURCE].\nFee basis: [CONTINGENT PERCENTAGE / HOURLY / OTHER AGREED BASIS]. Calculation: [BASE, RATE, HOURS IF APPLICABLE, AND ORDER OF COST DEDUCTIONS UNDER THE AGREEMENT]. Fee charged: $[FEE]. Adjustments or credits: $[AMOUNT AND REASON].\n## Itemized expenses\n[FOR EACH ACTUAL EXPENSE: DATE; PAYEE; DESCRIPTION; AMOUNT; PAYMENT STATUS; CLIENT ALLOCATION].\nTotal expenses: $[EXPENSES]. Refunds or reimbursements: $[AMOUNT]. Net expenses charged: $[NET EXPENSES].\n## Liens, reserves and client distribution\n[FOR EACH THIRD-PARTY INTEREST: CLAIMANT; AUTHORITY; AGREED AMOUNT; PAYMENT STATUS; REMAINING RESERVE].\nTotal third-party payments: $[PAYMENTS]. Remaining protected reserves: $[RESERVES AND PURPOSES]. Prior client distributions: $[PRIOR].\nNet amount presently distributable: $[CLEARED FUNDS LESS FEES, NET EXPENSES, PAYMENTS, RESERVES AND PRIOR DISTRIBUTIONS, WITH CREDITS APPLIED ONCE].\nReconciliation to trust ledger: [DATE, BALANCE AND ANY EXPLAINED DIFFERENCE]. Unresolved items and next accounting date: [DETAILS].\n## Client review\nPlease review the itemized statement and contact [PERSON] about any question or discrepancy. A receipt acknowledgment is separate from authorization and actual payment.\nPrepared by: [NAME]    Date: [DATE]\nClient acknowledgment of receiving this statement, if obtained:\nSignature: ____________________    Date: _______________\n"},{"title":"Limited Settlement Indemnity Agreement","slug":"hold-harmless","command":"/hold-harmless","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Limited Settlement Indemnity Agreement for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/hold-harmless.docx","reasoning":"../../reasoning/hold-harmless.md","path":"templates/settlement/hold-harmless.md","docx_path":"templates/settlement/docx/hold-harmless.docx","reasoning_path":"reasoning/hold-harmless.md","field_count":16,"md":"---\ntitle: \"Limited Settlement Indemnity Agreement\"\nslug: \"hold-harmless\"\ncommand: \"/hold-harmless\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Limited Settlement Indemnity Agreement for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/hold-harmless.docx\"\nreasoning: \"../../reasoning/hold-harmless.md\"\n---\n# Limited Settlement Indemnity Agreement\nAgreement date: [DATE]\nIndemnitor: [EXACT LEGAL NAME AND CAPACITY]\nIndemnitee: [EXACT LEGAL NAME AND CAPACITY]\nRelated settlement: [PARTIES, INCIDENT AND SIGNED AGREEMENT]\n## Defined obligation\nIn consideration of [ACTUAL CONSIDERATION], the indemnitor agrees to reimburse the indemnitee only for [PRECISE IDENTIFIED THIRD-PARTY CLAIMS AND COVERED LOSSES], to the extent [EXACT CAUSAL AND LEGAL CONDITIONS]. The agreed monetary limit is [AMOUNT OR EXPRESS AGREED LIMIT], and the covered period is [DATES OR DEFINED EVENTS]. No unspecified claim is included.\n## Notice and resolution\nThe indemnitee must provide [AGREED PROMPT NOTICE AND SUPPORTING RECORDS]. Control of defense, counsel selection, cooperation and settlement consent are [SPECIFIC AGREED TERMS]. Defense costs are included only to the extent expressly stated in [IDENTIFIED CLAUSE].\nExcluded obligations are [ACTUAL EXCLUSIONS, INCLUDING ANY LOSS CAUSED BY THE INDEMNITEE IF AGREED]. The indemnitor retains [SPECIFIC DEFENSES AND REVIEW RIGHTS]. This agreement does not bind a government, benefit plan or other nonsignatory or release its independent rights.\n## Agreement\nThis undertaking is made by the identified indemnitor. Counsel’s signature acknowledging preparation or receipt does not create an attorney or law-firm guarantee. Amendments require [AGREED FORM AND SIGNATURES]. Governing law and dispute forum are [ACTUAL AGREEMENT, SUBJECT TO ENFORCEABILITY].\nIndemnitor signature: ____________________    Date: [DATE]\nIndemnitee signature: ____________________    Date: [DATE]\nAuthorized capacities: [ACTUAL TITLES AND AUTHORITY]\n"},{"title":"Motion to Appoint Guardian ad Litem","slug":"gal-appointment","command":"/gal-appointment","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Circuit Court appointment motion only. The original catalog combined appointment and report; an actual GAL must investigate and author the report. Do not generate findings, consent, a completed appointment or unsupported mandatory appointment.","docx":"docx/gal-appointment.docx","reasoning":"../../reasoning/gal-appointment.md","path":"templates/settlement/gal-appointment.md","docx_path":"templates/settlement/docx/gal-appointment.docx","reasoning_path":"reasoning/gal-appointment.md","field_count":26,"md":"---\ntitle: \"Motion to Appoint Guardian ad Litem\"\nslug: \"gal-appointment\"\ncommand: \"/gal-appointment\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Circuit Court appointment motion only. The original catalog combined appointment and report; an actual GAL must investigate and author the report. Do not generate findings, consent, a completed appointment or unsupported mandatory appointment.\"\ndocx: \"docx/gal-appointment.docx\"\nreasoning: \"../../reasoning/gal-appointment.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION TO APPOINT GUARDIAN AD LITEM\n[MOVING PARTY] moves for appointment of a guardian ad litem for [PERSON UNDER DISABILITY] and states:\n1. The person’s role in this action is [PLAINTIFF OR DEFENDANT AND REPRESENTATIVE CAPACITY]. The disability and its supported basis are [FACTS AND RECORD REFERENCES]. Existing counsel, next friend or fiduciary and their authority are [NAMES, ROLES AND RECORD].\n2. Appointment is requested under [APPLICABLE PROVISION OF § 8.01-9 OR OTHER VERIFIED AUTHORITY]. The existing representation and any exception under § 8.01-9(B) have been considered. Appointment is needed because [SPECIFIC CONFLICT, UNPROTECTED INTEREST OR OTHER GROUNDS].\n3. The proposed appointee is [NAME, QUALIFICATIONS AND CONTACT INFORMATION]. Availability and any known conflict are [VERIFIED FACTS]. The requested duties are [SPECIFIC ISSUES, ACCESS AND INVESTIGATION], subject to the Court’s direction.\n4. If a report is requested, the proposed deadline and recipients are [DATE AND RECIPIENTS]. The appointee must conduct the actual investigation before making findings or recommendations. No report or recommendation is supplied by this motion.\n5. The proposed compensation, payment source and legal basis are [TERMS AND AUTHORITY], subject to the Court’s determination. Notice has been or will be provided as follows: [ACTUAL NOTICE AND HEARING ARRANGEMENTS].\nThe movant requests appointment on the terms determined by the Court, with any necessary directions protecting the represented person’s interests.\nRespectfully submitted,\n[PARTY NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL DATE], a copy of this document was served on [NAMES, REPRESENTED PARTIES AND SERVICE ADDRESSES] by [ACTUAL AUTHORIZED METHOD].\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Personal Injury Settlement Agreement","slug":"settlement","command":"/settlement","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Negotiated adult private PI settlement; not a complete minor, wrongful-death, structured-settlement or statutory UIM package.","docx":"docx/settlement.docx","reasoning":"../../reasoning/settlement.md","path":"templates/settlement/settlement.md","docx_path":"templates/settlement/docx/settlement.docx","reasoning_path":"reasoning/settlement.md","field_count":26,"md":"---\ntitle: \"Personal Injury Settlement Agreement\"\nslug: \"settlement\"\ncommand: \"/settlement\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Negotiated adult private PI settlement; not a complete minor, wrongful-death, structured-settlement or statutory UIM package.\"\ndocx: \"docx/settlement.docx\"\nreasoning: \"../../reasoning/settlement.md\"\n---\n# PERSONAL INJURY SETTLEMENT AGREEMENT\nThis agreement is between [CLAIMANT, CAPACITY] and [SETTLING PARTY, CAPACITY] concerning [DEFINED INCIDENT AND CLAIMS]. The effective date is [DATE OR EXECUTION CONDITION].\n## Consideration and payment\n[PAYOR] will pay $[AMOUNT] to [PAYEES] by [DATE OR PRECISE TRIGGER] through [AGREED METHOD]. Payment and delivery instructions will be independently confirmed. Any condition precedent is [SPECIFIC CONDITION OR NONE]. Receipt of funds is not acknowledged before it occurs.\n## Release and reserved matters\nThe release to be executed is [ATTACHED AGREED FORM AND VERSION OR COMPLETE RELEASE TERMS]. It covers only [IDENTIFIED PARTIES, CLAIMS AND SCOPE]. Expressly reserved matters are [CLAIMS, PARTIES OR RIGHTS]. The parties’ agreement concerning unknown injuries or later consequences is [EXPRESS NEGOTIATED TERM].\n## Liens and obligations\nKnown liens, reimbursement claims and unpaid charges are [IDENTIFIED ITEMS AND STATUS]. Responsibility, holdbacks and required releases are [EXACT AGREED TERMS]. No insurer, government agency or other nonparty is bound by this agreement without an independent legal basis. No general tax or benefits assurance is made.\n## Litigation and costs\nUpon [PERFORMANCE TRIGGER], [PARTY] will seek dismissal of [SPECIFIC CLAIMS AND PARTIES] on [WITH-PREJUDICE OR OTHER EXPRESS TERMS]. Treatment of court costs and attorney fees between the settling parties is [AGREEMENT]. Other pending claims are [STATUS]. Entry of any court order remains for the court.\n## Remaining terms\nThe settlement compromises disputed claims and is not an admission of liability. Confidentiality, indemnity, payment security or other additional obligations are [EXPRESS TERMS OR NONE]; no such obligation is implied by an empty field.\nRequired approvals or statutory settlement provisions are [IDENTIFY AND INCORPORATE IF APPLICABLE]. All material terms are contained in this agreement and its identified attachments; changes require the parties’ agreement in writing. Each signer must have authority for the stated capacity.\nClaimant signature: ____________________    Date: [DATE]\nPrinted name and capacity: [DETAILS]\nSettling party signature: ____________________    Date: [DATE]\nPrinted name and capacity: [DETAILS]\n"},{"title":"Proposed Order for Protected Deposit of Minor Settlement","slug":"blocked-account","command":"/blocked-account","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Circuit Court only; use solely the qualified-fiduciary route after approval of the compromise. A bank account by itself is not a statutory substitute for qualification, bond inquiry or the approval order. Institution acceptance and restrictions require case review; this is not a universally mandated Virginia blocked-account form.","docx":"docx/blocked-account.docx","reasoning":"../../reasoning/blocked-account.md","path":"templates/settlement/blocked-account.md","docx_path":"templates/settlement/docx/blocked-account.docx","reasoning_path":"reasoning/blocked-account.md","field_count":21,"md":"---\ntitle: \"Proposed Order for Protected Deposit of Minor Settlement\"\nslug: \"blocked-account\"\ncommand: \"/blocked-account\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Circuit Court only; use solely the qualified-fiduciary route after approval of the compromise. A bank account by itself is not a statutory substitute for qualification, bond inquiry or the approval order. Institution acceptance and restrictions require case review; this is not a universally mandated Virginia blocked-account form.\"\ndocx: \"docx/blocked-account.docx\"\nreasoning: \"../../reasoning/blocked-account.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PROPOSED ORDER FOR PROTECTED DEPOSIT\nThis matter came before the Court on [MOTION AND HEARING DATE]. The Court considered [ACTUAL EVIDENCE AND NOTICE]. The compromise was approved in [ORDER DATE AND REFERENCE].\n1. The net sum of [AMOUNT] belongs to [MINOR NAME]. Under Virginia Code § 8.01-424(D)(3), payment shall be made to [DULY QUALIFIED FIDUCIARY AND CAPACITY], after the Court’s inquiry into the adequacy of the fiduciary’s bond. Qualification and bond are established by [RECORD AND FINDINGS].\n2. The fiduciary shall deposit the sum at [INSTITUTION] in an account titled [FIDUCIARY CAPACITY AND BENEFICIARY]. The institution’s written acceptance of the ordered restrictions shall be obtained before transfer. The complete account number shall be maintained through [AUTHORIZED NONPUBLIC RECORD].\n3. No withdrawal, pledge, transfer or change of beneficial ownership is authorized except upon further written order of this Court. Interest shall remain in the account. The fiduciary shall obtain statements and preserve the funds subject to all applicable fiduciary duties.\n4. By [DATE], the fiduciary shall provide proof of deposit and the institution’s acknowledgment through [REQUIRED FILING OR DELIVERY METHOD]. Required inventories and accountings remain due to [PROPER AUTHORITY]; this Order does not excuse them.\n5. Attainment of majority does not itself authorize the bank to disregard this Order. Distribution and discharge shall occur pursuant to [SPECIFIC FURTHER-ORDER PROCEDURE], consistent with the beneficiary’s rights and applicable law.\nENTERED: ________________________________\n________________________________\nJUDGE\n## Endorsements and presentation\nPresented by: [PARTY AND COUNSEL]\nCounsel signature: ________________________________\nAttorney name: [NAME, VSB NUMBER AND COMPLETE CONTACT DETAILS]\nNotice or endorsements under Rule 1:13: [ACTUAL COMPLIANCE]\n"},{"title":"Proposed Order of Dismissal After Settlement","slug":"order-dismissal","command":"/order-dismissal","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Dismissal order implementing an actual settlement disposition in Circuit Court; not a unilateral notice of dismissal or a nonsuit motion.","docx":"docx/order-dismissal.docx","reasoning":"../../reasoning/order-dismissal.md","path":"templates/settlement/order-dismissal.md","docx_path":"templates/settlement/docx/order-dismissal.docx","reasoning_path":"reasoning/order-dismissal.md","field_count":18,"md":"---\ntitle: \"Proposed Order of Dismissal After Settlement\"\nslug: \"order-dismissal\"\ncommand: \"/order-dismissal\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Dismissal order implementing an actual settlement disposition in Circuit Court; not a unilateral notice of dismissal or a nonsuit motion.\"\ndocx: \"docx/order-dismissal.docx\"\nreasoning: \"../../reasoning/order-dismissal.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PROPOSED ORDER OF DISMISSAL AFTER SETTLEMENT\nUpon [ACTUAL JOINT REQUEST OR OTHER PROPER BASIS], and based on [SETTLEMENT PERFORMANCE OR OTHER CONDITION THAT HAS ACTUALLY OCCURRED], it is ORDERED:\n1. The claims of [PARTY] against [PARTY], specifically [IDENTIFIED CLAIMS OR COUNTS], are dismissed [WITH PREJUDICE / WITHOUT PREJUDICE AS ACTUALLY REQUESTED AND LEGALLY AVAILABLE].\n2. Court costs and attorney fees as between these parties are [ACTUAL AGREED OR ADJUDICATED TREATMENT].\n3. [IDENTIFY ALL COUNTERCLAIMS, CROSS-CLAIMS, THIRD-PARTY CLAIMS OR OTHER CLAIMS THAT REMAIN, OR STATE THAT ALL HAVE BEEN RESOLVED ONLY IF VERIFIED].\n[ACCURATE FINALITY OR RETAINED-ISSUE LANGUAGE FOR THE ACTUAL DISPOSITION].\nThis proposed order does not acknowledge an unpaid settlement as paid and does not dismiss unlisted claims or bind a nonparty. The judicial signature and entry date remain for the Court.\nENTERED: ____________________\n____________________________\nJUDGE\n## Endorsements and presentation\n[ACTUAL COUNSEL ENDORSEMENTS, INCLUDING THE POSITION TAKEN, OR THE REQUIRED NOTICE OF PRESENTATION / COURT DISPENSATION UNDER RULE 1:13]\nSubmitted by: [ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]    Email: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\nCounsel signature: ____________________\n"},{"title":"Release of Identified Personal Injury Claims","slug":"release","command":"/release","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Adult claimant’s defined release in an ordinary private PI settlement; no automatic universal release of all persons or all unrelated claims.","docx":"docx/release.docx","reasoning":"../../reasoning/release.md","path":"templates/settlement/release.md","docx_path":"templates/settlement/docx/release.docx","reasoning_path":"reasoning/release.md","field_count":16,"md":"---\ntitle: \"Release of Identified Personal Injury Claims\"\nslug: \"release\"\ncommand: \"/release\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Adult claimant’s defined release in an ordinary private PI settlement; no automatic universal release of all persons or all unrelated claims.\"\ndocx: \"docx/release.docx\"\nreasoning: \"../../reasoning/release.md\"\n---\n# RELEASE OF IDENTIFIED PERSONAL INJURY CLAIMS\nReleasor: [FULL NAME AND CAPACITY]\nReleased persons: [EXACT NAMES AND CAPACITIES]\nIncident and claims: [SPECIFIC EVENT, DATE AND CLAIMS]\n## Consideration and effectiveness\nIn consideration of $[AMOUNT] payable by [PAYOR] on [TERMS], Releasor agrees to the release below. This release becomes effective upon [ACTUAL AGREED CONDITION]. This document does not acknowledge receipt of funds before receipt occurs.\n## Released claims\nReleasor releases the identified released persons from [PRECISE CLAIMS AND DAMAGES ARISING FROM THE IDENTIFIED INCIDENT]. The agreed treatment of unknown injuries or future consequences is [EXPRESS SCOPE AND CLIENT ELECTION]. No unrelated claim or unnamed person is released merely because of a generic description.\nExpressly excluded claims, persons and rights are [IDENTIFY OR STATE NONE]. Any remaining UM/UIM, derivative, property or other claim must be addressed expressly under the governing policy and law before execution.\n## Liens and other interests\nThe agreed treatment of liens, reimbursement rights, assignments and unpaid charges is [EXACT TERMS]. This release does not bind a nonparty lienholder or government agency merely by describing that person’s interest. Any indemnity is limited to [SPECIFIC NEGOTIATED OBLIGATION OR NONE].\n## Understanding and execution\nThe parties compromise a disputed claim without an admission of liability. Releasor has reviewed the identified terms and has had the opportunity to obtain advice. No promise of a particular medical, tax or public-benefits consequence is made here.\nRelated settlement agreement and incorporated attachments: [IDENTIFIERS]. Additional approval or statutory terms required for this transaction: [DETAILS]. Sign only after all selected terms are complete.\nReleasor signature: ____________________    Date: [DATE]\nPrinted name and capacity: [DETAILS]\nAdditional required signatory: ____________________    Date: [DATE]\nName, capacity and reason required: [DETAILS OR OMIT IF INAPPLICABLE]\n"},{"title":"Settlement Allocation Addendum","slug":"tax-allocation","command":"/tax-allocation","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Use only supported, genuinely agreed allocations. Do not invent a tax-advantaged split, a tax indemnity or a representation that the IRS accepts the allocation. Court approval and tax counsel review depend on the actual case.","docx":"docx/tax-allocation.docx","reasoning":"../../reasoning/tax-allocation.md","path":"templates/settlement/tax-allocation.md","docx_path":"templates/settlement/docx/tax-allocation.docx","reasoning_path":"reasoning/tax-allocation.md","field_count":12,"md":"---\ntitle: \"Settlement Allocation Addendum\"\nslug: \"tax-allocation\"\ncommand: \"/tax-allocation\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Use only supported, genuinely agreed allocations. Do not invent a tax-advantaged split, a tax indemnity or a representation that the IRS accepts the allocation. Court approval and tax counsel review depend on the actual case.\"\ndocx: \"docx/tax-allocation.docx\"\nreasoning: \"../../reasoning/tax-allocation.md\"\n---\n# SETTLEMENT ALLOCATION ADDENDUM\nMatter: [MATTER AND CLAIMANTS]\nUnderlying agreement: [DATE AND PARTIES]\n## Agreed allocation\n[IDENTIFIED PARTIES] agree that the total consideration of [TOTAL AMOUNT] is allocated as follows, based on the asserted claims and supporting record:\n1. [COMPONENT ONE, AMOUNT, UNDERLYING CLAIM AND FACTUAL BASIS].\n2. [COMPONENT TWO, AMOUNT, UNDERLYING CLAIM AND FACTUAL BASIS].\n3. [ADDITIONAL COMPONENTS, INCLUDING ANY WAGES, INTEREST, PUNITIVE DAMAGES OR ATTORNEY PAYMENTS; DELETE UNUSED ITEMS].\nThe component amounts total [TOTAL AMOUNT]. Fees, costs, withholding and the recipient of each payment are separately stated in [PAYMENT SCHEDULE]. Any fee amount already included in a component is not added a second time.\n## Reporting and tax treatment\nEach payer remains responsible for the information returns, wage reporting and withholding applicable to its payments. The parties will provide reasonably necessary taxpayer information through an agreed secure method. No Social Security number belongs in a publicly filed copy of this addendum.\nThis allocation records the parties’ agreed resolution of disputed claims. It does not bind a taxing authority, create an exclusion from income, or guarantee the recipient’s tax treatment. Each party remains responsible for its own tax advice and legally required reporting. No party is required to submit an inaccurate return.\n## Effect and execution\nThis addendum changes only [SPECIFIED ALLOCATION PROVISIONS] of the underlying agreement. Its effectiveness depends on [REQUIRED SIGNATURES AND ANY COURT APPROVAL]. If an amount or component remains disputed, the parties must resolve it before execution.\nParty: [NAME AND CAPACITY]  Signature: __________________  Date: [DATE]\nParty: [NAME AND CAPACITY]  Signature: __________________  Date: [DATE]\n"},{"title":"Settlement Disbursement Statement","slug":"disbursement","command":"/disbursement","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"Matter-specific contingent-fee closing accounting; not an actual payment instruction or substitute for trust-ledger reconciliation.","docx":"docx/disbursement.docx","reasoning":"../../reasoning/disbursement.md","path":"templates/settlement/disbursement.md","docx_path":"templates/settlement/docx/disbursement.docx","reasoning_path":"reasoning/disbursement.md","field_count":14,"md":"---\ntitle: \"Settlement Disbursement Statement\"\nslug: \"disbursement\"\ncommand: \"/disbursement\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"Matter-specific contingent-fee closing accounting; not an actual payment instruction or substitute for trust-ledger reconciliation.\"\ndocx: \"docx/disbursement.docx\"\nreasoning: \"../../reasoning/disbursement.md\"\n---\n# SETTLEMENT DISBURSEMENT STATEMENT\nClient: [NAME]    Matter: [REFERENCE]\nStatement date: [DATE]    Status: [PROPOSED / FINAL]\n## Recovery and funds received\nSettlement or judgment amount: $[AMOUNT]\nFunds actually received: $[AMOUNT] on [DATES], from [PAYORS]\nFunds available for disbursement after clearance and required conditions: $[AMOUNT]\nAmounts still unpaid or otherwise unavailable: $[AMOUNT AND REASON]\n## Attorney fee and expenses\nAgreed fee method and stage: [TERMS FROM ENGAGEMENT]\nFee base: $[AMOUNT]    Applied rate: [PERCENT]%    Fee: $[AMOUNT]\nExpenses deducted before fee calculation, if agreed: $[AMOUNT]\nOther reimbursable expenses: [ITEMIZED PAYEE, PURPOSE, DATE AND AMOUNT]\nTotal expenses: $[AMOUNT]. An expense is counted once in the final distribution, regardless of where it enters the fee calculation.\n## Other payments and reserves\nLiens or agreed third-party payments: [EACH PAYEE, VERIFIED PAYOFF, AMOUNT AND BASIS]\nTotal third-party payments: $[AMOUNT]\nTrust reserve: $[AMOUNT], for [SPECIFIC UNRESOLVED CLAIM OR PURPOSE]\n## Client distribution and reconciliation\nGross funds available minus the attorney fee, expenses, third-party payments and retained reserve equals the current Client distribution of $[AMOUNT].\nAfter the proposed payments, the matter’s trust balance will be $[AMOUNT], consisting of [ITEMIZED RESERVES OR OTHER REMAINING FUNDS]. Amounts already paid are identified as paid and are not deducted a second time.\nThe Client is provided this accounting and may ask for supporting records. A signature acknowledges the stated accounting and any expressly authorized distribution; it does not waive a disputed fee, lien or other legal right.\nClient signature, if requested: ____________________    Date: [DATE]\nPrepared and reviewed by: [NAME]    Date: [DATE]\n"},{"title":"Settlement Information for Virginia Tax Review","slug":"state-tax","command":"/state-tax","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Limited to an authorized factual transmittal to a tax adviser. It is not a Virginia agency notification, return, allocation opinion or universal tax clearance.","docx":"docx/state-tax.docx","reasoning":"../../reasoning/state-tax.md","path":"templates/settlement/state-tax.md","docx_path":"templates/settlement/docx/state-tax.docx","reasoning_path":"reasoning/state-tax.md","field_count":19,"md":"---\ntitle: \"Settlement Information for Virginia Tax Review\"\nslug: \"state-tax\"\ncommand: \"/state-tax\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Limited to an authorized factual transmittal to a tax adviser. It is not a Virginia agency notification, return, allocation opinion or universal tax clearance.\"\ndocx: \"docx/state-tax.docx\"\nreasoning: \"../../reasoning/state-tax.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\n[TELEPHONE AND EMAIL]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[RECIPIENT MAILING ADDRESS]\nRe: [CLIENT NAME] — settlement information for tax year [YEAR]\nDear [RECIPIENT]:\nAt [CLIENT NAME]’s authorization, we provide the following settlement information for your preparation or review of the client’s tax returns. This is a factual transmittal to the client’s tax adviser, not a notice filed with Virginia Tax.\nThe matter is [MATTER]; the operative agreement is dated [DATE]. The payer is [PAYER]. Gross consideration is [AMOUNT], with payments actually received on [DATES AND AMOUNTS]. The client’s residence and any relevant changes during the tax year are [KNOWN RESIDENCY FACTS].\nThe agreement identifies these components: [COMPONENT, AMOUNT AND SUPPORTING PROVISION FOR EACH]. Attorney fees, costs, withholding and net disbursement are [SEPARATE AMOUNTS AND SOURCES]. We do not treat net proceeds as the measure of taxable income.\nRecords furnished with this letter are [ACTUAL AGREEMENT, DISBURSEMENT STATEMENT AND TAX FORMS ENCLOSED]. Unresolved allocation or reporting questions are [QUESTIONS]. Please assess federal treatment and applicable Virginia additions, subtractions, residency and filing obligations for the correct tax year.\nNo representation is made that a component is excluded from income merely because the agreement labels it as damages. Please direct any factual questions to our office.\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Structured Settlement Payment Addendum","slug":"structured-settlement","command":"/structured-settlement","category":"settlement","category_label":"Settlement documents and disbursement","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"DOCUMENT","pages":1,"scope":"This is an original payment addendum, not an issuer’s annuity confirmation or assignment form. Obtain actual provider documents and individualized tax and benefits advice. Never describe a quoted product as issued or funded.","docx":"docx/structured-settlement.docx","reasoning":"../../reasoning/structured-settlement.md","path":"templates/settlement/structured-settlement.md","docx_path":"templates/settlement/docx/structured-settlement.docx","reasoning_path":"reasoning/structured-settlement.md","field_count":18,"md":"---\ntitle: \"Structured Settlement Payment Addendum\"\nslug: \"structured-settlement\"\ncommand: \"/structured-settlement\"\ncategory: \"settlement\"\ncategory_label: \"Settlement documents and disbursement\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"DOCUMENT\"\npages: 1\nscope: \"This is an original payment addendum, not an issuer’s annuity confirmation or assignment form. Obtain actual provider documents and individualized tax and benefits advice. Never describe a quoted product as issued or funded.\"\ndocx: \"docx/structured-settlement.docx\"\nreasoning: \"../../reasoning/structured-settlement.md\"\n---\n# STRUCTURED SETTLEMENT PAYMENT ADDENDUM\nMatter: [MATTER]    Agreement date: [DATE]\nClaimant: [NAME AND CAPACITY]    Current payment obligor: [LEGAL NAME]\n## Payment obligations\nThe parties agree to the following payment schedule as part of the settlement consideration. List each guaranteed payment and each life-contingent payment separately.\n1. Immediate payment: [AMOUNT, DUE DATE, PAYEE AND RESPONSIBLE OBLIGOR].\n2. Periodic payments: [AMOUNT, FREQUENCY, FIRST AND LAST DATES, GUARANTEED PERIOD, LIFE CONTINGENCY AND PAYEE].\n3. Future lump sums: [EACH AMOUNT, DUE DATE, GUARANTEED OR CONTINGENT STATUS AND PAYEE].\n4. Death before completion: [BENEFICIARY FOR GUARANTEED PAYMENTS, DESIGNATION PROCEDURE AND TREATMENT OF CONTINGENT PAYMENTS].\n## Funding and assignment\nThe proposed annuity issuer and quoted contract are [ISSUER AND QUOTE IDENTIFIER]. The annuity owner will be [OWNER], and the claimant’s rights against the obligor and issuer are [PRECISE AGREED RIGHTS]. The purchase price is [PRICE]; it is not represented as the present value or guaranteed total of payments.\nAny proposed qualified assignment is governed by a separate agreement identifying [ASSIGNOR, ASSIGNEE AND ASSUMED OBLIGATION]. No assignment, release of the original obligor or funding is represented as complete by this addendum. Effectiveness and the consequence of failed or late funding are [AGREED CONDITIONS AND REMEDY].\nIf the parties intend an assignment under 26 U.S.C. § 130, the assumed payments must satisfy its requirements, including fixed and determinable terms and no recipient right to accelerate, defer, increase or decrease them. The applicable tax and eligibility analysis is [ACTUAL ADVICE OR UNRESOLVED ISSUE]. No tax result is guaranteed here.\n## Approval and completion\nRequired court approval, payee capacity, fiduciary authority and funding-security conditions are [CASE-SPECIFIC REQUIREMENTS]. For a Virginia disability compromise, the applicable requirements of § 8.01-424 remain controlling. The executed assignment, issued annuity, payment schedule and approval order must be reconciled before closing.\nThis addendum controls [IDENTIFIED PAYMENT TERMS] only; other settlement terms remain as stated in [AGREEMENT].\nParty: [NAME AND CAPACITY]  Signature: __________________  Date: [DATE]\nParty: [NAME AND CAPACITY]  Signature: __________________  Date: [DATE]\n"},{"title":"Affidavit and Return of Service","slug":"proof-service-summons","command":"/proof-service-summons","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia private process-server factual affidavit; sheriff and statutory special-service forms require adaptation.","docx":"docx/proof-service-summons.docx","reasoning":"../../reasoning/proof-service-summons.md","path":"templates/pleadings/proof-service-summons.md","docx_path":"templates/pleadings/docx/proof-service-summons.docx","reasoning_path":"reasoning/proof-service-summons.md","field_count":23,"md":"---\ntitle: \"Affidavit and Return of Service\"\nslug: \"proof-service-summons\"\ncommand: \"/proof-service-summons\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia private process-server factual affidavit; sheriff and statutory special-service forms require adaptation.\"\ndocx: \"docx/proof-service-summons.docx\"\nreasoning: \"../../reasoning/proof-service-summons.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# AFFIDAVIT AND RETURN OF SERVICE\nI, [SERVER NAME], being duly sworn, state:\n1. I am [SERVER NAME], age [AGE], and am qualified to serve this process under Virginia Code § 8.01-293 because [PRECISE QUALIFICATIONS, INCLUDING REQUIRED DISINTEREST AND NONPARTY STATUS].\n2. On [DATE] at [TIME AND PLACE], I served [EXACT PERSON OR ENTITY] with [SUMMONS, COMPLAINT AND OTHER ACTUAL PAPERS].\n3. Service was made by [SPECIFIC AUTHORIZED METHOD AND ITS FACTS]. [IDENTIFY RECIPIENT, RELATIONSHIP / CAPACITY AND THE STATUTORY BASIS; FOR SUBSTITUTED OR POSTED SERVICE STATE EACH REQUIRED PREDICATE].\n4. [STATE ANY ACTUAL ADDITIONAL MAILING, DATE, ADDRESS AND CERTIFICATION REQUIRED FOR THE SELECTED METHOD; IDENTIFY WHO PERFORMED IT]. The supporting records are [ACTUAL REFERENCES].\n5. The return is being made to [CLERK AND COURT] on [ACTUAL RETURN DATE].\n## Private server verification\nPRIVATE SERVER\nName: [SERVER NAME]\nAddress: [SERVER ADDRESS]\nTelephone: [SERVER NUMBER]\nSignature: ____________________\nPrinted name: [AFFIANT NAME]\nCOMMONWEALTH / STATE OF [STATE]\nCITY / COUNTY OF [LOCALITY]\nSubscribed and sworn to before me on [ACTUAL DATE] by [AFFIANT NAME].\nNotary signature: ____________________\nNotary registration number: [NUMBER]\nCommission expires: [DATE]\n"},{"title":"Affidavit of Non-Service","slug":"non-service","command":"/non-service","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia private process-server factual affidavit; sheriff and statutory special-service forms require adaptation.","docx":"docx/non-service.docx","reasoning":"../../reasoning/non-service.md","path":"templates/pleadings/non-service.md","docx_path":"templates/pleadings/docx/non-service.docx","reasoning_path":"reasoning/non-service.md","field_count":24,"md":"---\ntitle: \"Affidavit of Non-Service\"\nslug: \"non-service\"\ncommand: \"/non-service\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia private process-server factual affidavit; sheriff and statutory special-service forms require adaptation.\"\ndocx: \"docx/non-service.docx\"\nreasoning: \"../../reasoning/non-service.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# AFFIDAVIT OF NON-SERVICE\nI, [SERVER NAME], being duly sworn, state:\n1. I am [SERVER NAME], [QUALIFICATIONS AND CAPACITY]. I received [IDENTIFIED PROCESS] on [DATE] for service on [PERSON OR ENTITY].\n2. I attempted service at [EXACT ADDRESS] on [DATE AND TIME]. I observed [FACTS] and took [ACTUAL ACTIONS]. [REPEAT FOR EACH ATTEMPT, WITHOUT CHARACTERIZING AN ATTEMPT AS COMPLETED SERVICE].\n3. Information obtained about the intended recipient’s location was [INFORMATION, SOURCE, DATE AND RELIABILITY]. Further steps actually taken were [DETAILS].\n4. As of [DATE AND TIME], I have not served the identified process on [RECIPIENT]. The unserved process is returned with this affidavit. [IDENTIFY ACTUAL ATTACHED ATTEMPT LOG].\n## Private server verification\nPRIVATE SERVER\nName: [SERVER NAME]\nAddress: [SERVER ADDRESS]\nTelephone: [SERVER NUMBER]\nSignature: ____________________\nPrinted name: [AFFIANT NAME]\nCOMMONWEALTH / STATE OF [STATE]\nCITY / COUNTY OF [LOCALITY]\nSubscribed and sworn to before me on [ACTUAL DATE] by [AFFIANT NAME].\nNotary signature: ____________________\nNotary registration number: [NUMBER]\nCommission expires: [DATE]\n"},{"title":"Affirmative Defenses","slug":"affirmative-defenses","command":"/affirmative-defenses","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Identified defense module accompanying a proper Virginia responsive pleading.","docx":"docx/affirmative-defenses.docx","reasoning":"../../reasoning/affirmative-defenses.md","path":"templates/pleadings/affirmative-defenses.md","docx_path":"templates/pleadings/docx/affirmative-defenses.docx","reasoning_path":"reasoning/affirmative-defenses.md","field_count":26,"md":"---\ntitle: \"Affirmative Defenses\"\nslug: \"affirmative-defenses\"\ncommand: \"/affirmative-defenses\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Identified defense module accompanying a proper Virginia responsive pleading.\"\ndocx: \"docx/affirmative-defenses.docx\"\nreasoning: \"../../reasoning/affirmative-defenses.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# AFFIRMATIVE DEFENSES\n[DEFENDANT] asserts the following affirmative defenses to [OPERATIVE PLEADING]. This filing [ACCOMPANIES THE ANSWER FILED DATE OR IS PERMITTED BY THE ORDER DATED DATE].\n## First defense — [IDENTIFIED DEFENSE]\n1. This defense applies to [COUNTS OR CLAIMS]. Its factual basis is [CASE-SUPPORTED FACTS], and its legal effect is [SPECIFIC BAR OR LIMITATION ON RELIEF].\n## Second defense — [IDENTIFIED DEFENSE IF SUPPORTED]\n2. [STATE THE DEFENSE, AFFECTED CLAIM AND ACTUAL BASIS; REMOVE THIS SECTION IF INAPPLICABLE].\n## Scope of defenses\nThe defenses asserted are limited to those supported by the present factual and legal inquiry. [IF CONTRIBUTORY NEGLIGENCE IS ASSERTED, IDENTIFY IT EXPRESSLY]. [IF LIMITATIONS IS ASSERTED, IDENTIFY THE CLAIM AND SUPPORTING ACCRUAL/TIMING BASIS].\nAny request to add or amend a defense will be made through the applicable procedure. This pleading does not purport to reserve an unrestricted right to add unknown defenses without leave.\n## Relief requested\nDefendant requests [DENIAL OR LIMITATION OF THE IDENTIFIED RELIEF] and such other relief as the Court may properly award.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Amended Complaint","slug":"amended","command":"/amended","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Complete amended ordinary Virginia Circuit Court motor-vehicle negligence complaint; not merely a list of changes.","docx":"docx/amended.docx","reasoning":"../../reasoning/amended.md","path":"templates/pleadings/amended.md","docx_path":"templates/pleadings/docx/amended.docx","reasoning_path":"reasoning/amended.md","field_count":34,"md":"---\ntitle: \"Amended Complaint\"\nslug: \"amended\"\ncommand: \"/amended\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Complete amended ordinary Virginia Circuit Court motor-vehicle negligence complaint; not merely a list of changes.\"\ndocx: \"docx/amended.docx\"\nreasoning: \"../../reasoning/amended.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# AMENDED COMPLAINT\nPlaintiff [NAME], by counsel and pursuant to [ACTUAL LEAVE ORDER OR PROCEDURAL AUTHORITY], files this amended complaint concerning the [DATE] motor-vehicle collision. This pleading states the claims being pursued in full.\n## Parties and jurisdiction\n1. Plaintiff is [IDENTITY, CAPACITY AND RESIDENCE].\n2. Defendant is [IDENTITY AND LAST KNOWN ADDRESS].\n3. This Court has subject-matter and personal jurisdiction because [FACTS AND BASIS]. Venue is proper in [LOCALITY] under [APPLICABLE PROVISION] because [VENUE FACTS].\n## Negligence\n4. On [DATE], at [LOCATION], Plaintiff was [ACTIVITY] when [MATERIAL COLLISION FACTS].\n5. Defendant owed Plaintiff [APPLICABLE DUTY].\n6. Defendant breached that duty by [SUPPORTED NEGLIGENT ACTS OR OMISSIONS].\n7. The breach proximately caused [COLLISION OR EVENT] and Plaintiff’s injuries.\n8. Plaintiff sustained [SUPPORTED INJURIES] and [SUPPORTED CATEGORIES OF LOSS].\n9. [ADDITIONAL MATERIAL ALLEGATIONS NEEDED FOR THE ACTUAL CLAIM, WITHOUT UNSUPPORTED INJURY OR DAMAGE ASSUMPTIONS].\nWHEREFORE, Plaintiff demands judgment against Defendant for $[SPECIFIC COMPENSATORY AMOUNT], together with costs as allowed by law and [OTHER RELIEF WITH AN IDENTIFIED LEGAL BASIS, IF ANY].\n[JURY DEMAND IF TIMELY, REQUESTED AND AVAILABLE; IDENTIFY ANY EXISTING DEMAND OR REQUIRED LEAVE].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Answer to Complaint","slug":"answer","command":"/answer","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Paragraph-by-paragraph answer to the actual Virginia Circuit Court complaint; not a general denial.","docx":"docx/answer.docx","reasoning":"../../reasoning/answer.md","path":"templates/pleadings/answer.md","docx_path":"templates/pleadings/docx/answer.docx","reasoning_path":"reasoning/answer.md","field_count":22,"md":"---\ntitle: \"Answer to Complaint\"\nslug: \"answer\"\ncommand: \"/answer\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Paragraph-by-paragraph answer to the actual Virginia Circuit Court complaint; not a general denial.\"\ndocx: \"docx/answer.docx\"\nreasoning: \"../../reasoning/answer.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# ANSWER TO COMPLAINT\nDefendant [NAME], by counsel, answers the [EXACT OPERATIVE COMPLAINT AND FILING DATE] as follows. Each numbered response corresponds to the allegation or paragraph identified.\n## Responses to allegations\nParagraph [ORIGINAL NUMBER]: [ADMIT, DENY, OR STATE THE ACTUAL LACK OF KNOWLEDGE SUFFICIENT TO FORM A BELIEF; FOR A PARTIAL ADMISSION, IDENTIFY PRECISELY THE ADMITTED AND DENIED PORTIONS].\n[REPEAT FOR EVERY PARAGRAPH OF THE OPERATIVE COMPLAINT, PRESERVING ITS ORIGINAL NUMBERING AND ADDRESSING EACH MATERIAL ALLEGATION].\n## Affirmative defenses\n[SEPARATELY IDENTIFY EACH ACTUALLY APPLICABLE DEFENSE AND ANY FACTS OR PARTICULARS APPROPRIATE TO IT].\n[IF CONTRIBUTORY NEGLIGENCE IS ASSERTED, STATE THE DEFENSE BASED ON THE ACTUAL RECORD. OMIT UNSUPPORTED DEFENSES AND ANY GENERIC RESERVATION THAT PURPORTS TO ASSERT UNPLEADED DEFENSES].\n## Requested disposition\nDefendant requests that Plaintiff take no relief except that established as legally due, that judgment be entered consistent with the adjudicated issues, and that costs be awarded as permitted by law.\n[JURY DEMAND ONLY IF REQUESTED AND PROCEDURALLY AVAILABLE].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Attorney Issued Subpoena Transmittal to Clerk","slug":"subpoena-transmittal","command":"/subpoena-transmittal","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"LETTER","pages":1,"scope":"Virginia circuit court clerk cover letter for copies of attorney-issued civil subpoenas. Sheriff transmittal sheet and actual subpoena remain separate; no changes to existing official-form routes.","docx":"docx/subpoena-transmittal.docx","reasoning":"../../reasoning/subpoena-transmittal.md","path":"templates/pleadings/subpoena-transmittal.md","docx_path":"templates/pleadings/docx/subpoena-transmittal.docx","reasoning_path":"reasoning/subpoena-transmittal.md","field_count":20,"md":"---\ntitle: \"Attorney Issued Subpoena Transmittal to Clerk\"\nslug: \"subpoena-transmittal\"\ncommand: \"/subpoena-transmittal\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Virginia circuit court clerk cover letter for copies of attorney-issued civil subpoenas. Sheriff transmittal sheet and actual subpoena remain separate; no changes to existing official-form routes.\"\ndocx: \"docx/subpoena-transmittal.docx\"\nreasoning: \"../../reasoning/subpoena-transmittal.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE OF TRANSMITTAL]\nClerk of the Circuit Court of [LOCALITY]\n[CLERK MAILING ADDRESS]\nRe: [CASE STYLE], Case No. [CASE NUMBER]\nAttorney issued subpoena transmittal\nDear Clerk:\nPlease place the enclosed copies of the attorney-issued subpoenas in this case file. The subpoenas were issued on [ACTUAL ISSUE DATE] by [ISSUING ATTORNEY NAME], an active member of the Virginia State Bar, No. [NUMBER].\nThe enclosed copies concern [WITNESS OR RECORDS CUSTODIAN NAME, SUBPOENA TYPE, AND APPEARANCE OR PRODUCTION DATE FOR EACH SUBPOENA]. They are transmitted to your office by [MAILING OR DELIVERY METHOD] on [ACTUAL TRANSMITTAL DATE].\nService is to be performed by [SHERIFF AND JURISDICTION OR AUTHORIZED PRIVATE PROCESS SERVER]. [FOR SHERIFF SERVICE, IDENTIFY THE ACTUAL SERVICE FEE REMITTANCE ENCLOSED FOR THE CLERK, INCLUDING AMOUNT AND PAYMENT REFERENCE. OMIT IF INAPPLICABLE.]\n[FOR AN ATTORNEY-ISSUED SUBPOENA DUCES TECUM, IDENTIFY THE ACCOMPANYING CERTIFICATE OF SERVICE ON COUNSEL OF RECORD AND UNREPRESENTED PARTIES UNDER RULES 4:9A AND 1:12.]\nPlease contact our office at [CONTACT INFORMATION] if additional filing information is needed.\nSincerely,\n________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME]\nEnclosures: [ACTUAL SUBPOENA COPIES, CERTIFICATE, AND ANY FEE REMITTANCE]\n"},{"title":"Certificate of Service of Subsequent Papers","slug":"proof-service-docs","command":"/proof-service-docs","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":1,"scope":"Virginia circuit court certificate under Rule 1:12 for papers after initial process; append to the served paper. Not an initial-process return or appellate certificate.","docx":"docx/proof-service-docs.docx","reasoning":"../../reasoning/proof-service-docs.md","path":"templates/pleadings/proof-service-docs.md","docx_path":"templates/pleadings/docx/proof-service-docs.docx","reasoning_path":"reasoning/proof-service-docs.md","field_count":18,"md":"---\ntitle: \"Certificate of Service of Subsequent Papers\"\nslug: \"proof-service-docs\"\ncommand: \"/proof-service-docs\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 1\nscope: \"Virginia circuit court certificate under Rule 1:12 for papers after initial process; append to the served paper. Not an initial-process return or appellate certificate.\"\ndocx: \"docx/proof-service-docs.docx\"\nreasoning: \"../../reasoning/proof-service-docs.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF NAME], Plaintiff | Case No. [CASE NUMBER]\nv. |\n[DEFENDANT NAME], Defendant |\n# Certificate of service\nI certify that on [ACTUAL SERVICE DATE], I served a copy of [DOCUMENT TITLE AND DATE], including [IDENTIFIED ATTACHMENTS, IF ANY], on each counsel of record and each unrepresented party identified below by [ACTUAL AUTHORIZED METHOD OF SERVICE].\n[RECIPIENT NAME AND REPRESENTED PARTY]\n[MAILING ADDRESS OR ELECTRONIC SERVICE ADDRESS]\n[DATE AND METHOD IF DIFFERENT FOR THIS RECIPIENT]\n[REPEAT FOR EACH REQUIRED RECIPIENT]\n[IF SERVICE WAS BY EMAIL UNDER RULE 1:12, STATE THE APPLICABLE RULE 1:17 AUTHORITY OR SIGNED WRITTEN CONSENT, AND THE ACTUAL MAIL OR FAX TRANSMITTAL OF THIS CERTIFICATE REQUIRED BY RULE 1:12, SUBJECT TO RULE 1:17.]\n________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\nCounsel for [PARTY]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\n"},{"title":"Complaint","slug":"complaint","command":"/complaint","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Initial Virginia Circuit Court complaint for ordinary motor-vehicle negligence, one adult individual plaintiff and one individual defendant, represented by Virginia counsel. No special statutory claim, minor, estate, government defendant, medical malpractice, or additional liability count.","docx":"docx/complaint.docx","reasoning":"../../reasoning/complaint.md","path":"templates/pleadings/complaint.md","docx_path":"templates/pleadings/docx/complaint.docx","reasoning_path":"reasoning/complaint.md","field_count":23,"md":"---\ntitle: \"Complaint\"\nslug: \"complaint\"\ncommand: \"/complaint\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Initial Virginia Circuit Court complaint for ordinary motor-vehicle negligence, one adult individual plaintiff and one individual defendant, represented by Virginia counsel. No special statutory claim, minor, estate, government defendant, medical malpractice, or additional liability count.\"\ndocx: \"docx/complaint.docx\"\nreasoning: \"../../reasoning/complaint.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. __________________\n[DEFENDANT FULL NAME], Defendant |\n# COMPLAINT\nPlaintiff [FULL NAME], by counsel, alleges:\n## Parties and venue\n1. Plaintiff [FULL NAME] is an individual residing in [CITY OR COUNTY, STATE].\n2. Defendant [FULL NAME] is an individual whose last known address is [FULL ADDRESS].\n3. This Court has jurisdiction over this action and Defendant because [JURISDICTIONAL FACTS AND BASIS].\n4. Venue is proper in [LOCALITY] under Virginia Code section 8.01-262([SUBSECTION]) because [VENUE FACTS].\n## Negligence\n5. On [DATE], at [LOCATION], Plaintiff was [ACTIVITY AND POSITION] when [MATERIAL COLLISION FACTS].\n6. Defendant owed Plaintiff a duty to exercise reasonable care in operating a motor vehicle under the circumstances.\n7. Defendant breached that duty by [SUPPORTED NEGLIGENT ACTS OR OMISSIONS].\n8. Defendant's negligence proximately caused the collision and Plaintiff's injuries.\n9. As a result, Plaintiff sustained [INJURIES] and suffered [SUPPORTED CATEGORIES OF DAMAGES].\nWHEREFORE, Plaintiff demands judgment against Defendant for $[SPECIFIC AMOUNT] in compensatory damages, together with costs as allowed by law.\nPlaintiff demands trial by jury on all issues triable of right by a jury.\nRespectfully submitted,\n[PLAINTIFF FULL NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n"},{"title":"Counterclaim","slug":"counterclaim","command":"/counterclaim","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Cause of action asserted by a defendant against a plaintiff under Virginia Rule 3:9.","docx":"docx/counterclaim.docx","reasoning":"../../reasoning/counterclaim.md","path":"templates/pleadings/counterclaim.md","docx_path":"templates/pleadings/docx/counterclaim.docx","reasoning_path":"reasoning/counterclaim.md","field_count":31,"md":"---\ntitle: \"Counterclaim\"\nslug: \"counterclaim\"\ncommand: \"/counterclaim\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Cause of action asserted by a defendant against a plaintiff under Virginia Rule 3:9.\"\ndocx: \"docx/counterclaim.docx\"\nreasoning: \"../../reasoning/counterclaim.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# COUNTERCLAIM\n[COUNTERCLAIMANT], by counsel, asserts this counterclaim against [COUNTERCLAIM DEFENDANT].\n## Parties and procedural basis\n1. Counterclaimant is [IDENTITY AND CAPACITY]; counterclaim defendant is [IDENTITY AND CAPACITY].\n2. The Court has jurisdiction over this claim because [SUPPORTED BASIS]. The counterclaim is filed within [APPLICABLE RULE 3:9 PERIOD OR EXTENSION ORDER].\n## Material facts\n3. On [DATE], at [LOCATION], [CHRONOLOGICAL FACTS SUPPORTING THE CLAIM].\n4. [IDENTIFY THE COUNTERCLAIM DEFENDANT'S ACTS, DUTIES OR AGREEMENT, AND THE RESULTING INJURY].\n## Count [NUMBER] — [CAUSE OF ACTION]\n5. Counterclaimant incorporates only paragraphs [RELEVANT PARAGRAPHS].\n6. [ALLEGE EACH REQUIRED ELEMENT THROUGH CASE-SUPPORTED FACTS].\n7. Those acts caused [SPECIFIC INJURY AND RECOVERABLE LOSS].\n## Relief requested\nCounterclaimant requests judgment against [NAME] for [SUPPORTED AMOUNT OR OTHER RELIEF], together with [INTEREST, COSTS OR FEES ONLY TO THE EXTENT AUTHORIZED, WITH BASIS], and other appropriate relief. [INCLUDE A TIMELY JURY DEMAND ONLY IF INTENDED AND AVAILABLE].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Cross-Claim","slug":"crossclaim","command":"/crossclaim","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Defendant claim against a co-defendant arising from a matter pleaded in the complaint.","docx":"docx/crossclaim.docx","reasoning":"../../reasoning/crossclaim.md","path":"templates/pleadings/crossclaim.md","docx_path":"templates/pleadings/docx/crossclaim.docx","reasoning_path":"reasoning/crossclaim.md","field_count":28,"md":"---\ntitle: \"Cross-Claim\"\nslug: \"crossclaim\"\ncommand: \"/crossclaim\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Defendant claim against a co-defendant arising from a matter pleaded in the complaint.\"\ndocx: \"docx/crossclaim.docx\"\nreasoning: \"../../reasoning/crossclaim.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# CROSS-CLAIM\n[CROSS-CLAIMANT], by counsel, asserts this cross-claim against [CO-DEFENDANT].\n## Parties and relationship to the action\n1. Cross-claimant and cross-claim defendant are defendants in this action, in the following capacities: [CAPACITIES].\n2. This claim grows out of [SPECIFIC MATTER PLEADED IN THE COMPLAINT], as follows: [RELATIONSHIP]. Its filing is timely under [RULE 3:10 OR ACTUAL EXTENSION ORDER].\n## Facts supporting the cross-claim\n3. [STATE THE RELEVANT TRANSACTION, OCCURRENCE OR LEGAL RELATIONSHIP].\n4. [IDENTIFY THE CO-DEFENDANT'S RELEVANT ACTS OR OBLIGATIONS].\n## Count [NUMBER] — [CAUSE OF ACTION]\n5. [ALLEGE THE REQUIRED ELEMENTS AND SUPPORTING FACTS].\n6. If this is a claim for contingent liability, the basis on which the cross-claim defendant is or may be liable for all or part of the claim against cross-claimant is [SPECIFIC INDEMNITY, CONTRIBUTION OR OTHER BASIS].\n## Relief requested\nCross-claimant requests [PRECISE DIRECT OR CONTINGENT RELIEF], with [AUTHORIZED COSTS OR OTHER RELIEF]. This claim does not admit the plaintiff's allegations except as expressly stated in [ACTUAL ADMISSION, IF ANY].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Demand for Jury Trial","slug":"jury-demand","command":"/jury-demand","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Written Virginia Circuit Court jury demand on issues triable of right; no imported jury-fee-posting procedure.","docx":"docx/jury-demand.docx","reasoning":"../../reasoning/jury-demand.md","path":"templates/pleadings/jury-demand.md","docx_path":"templates/pleadings/docx/jury-demand.docx","reasoning_path":"reasoning/jury-demand.md","field_count":18,"md":"---\ntitle: \"Demand for Jury Trial\"\nslug: \"jury-demand\"\ncommand: \"/jury-demand\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Written Virginia Circuit Court jury demand on issues triable of right; no imported jury-fee-posting procedure.\"\ndocx: \"docx/jury-demand.docx\"\nreasoning: \"../../reasoning/jury-demand.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# DEMAND FOR JURY TRIAL\n[DEMANDING PARTY], by counsel, demands trial by jury under Rule 3:21 on [ALL ISSUES TRIABLE OF RIGHT BY A JURY / SPECIFIC IDENTIFIED ISSUES].\nThe procedural basis for this demand is [TIMELY DEMAND BASED ON THE ACTUAL LAST PLEADING DIRECTED TO THE ISSUE, AN EXPRESS COURT-SET DATE, OR ACTUAL LEAVE OF COURT]. Any prior jury demand relevant to these issues is [IDENTIFY OR NONE].\nThis demand is limited to issues for which a jury trial is available. It does not represent that an amended pleading automatically renewed an expired demand period or that any required leave has already been granted.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Demurrer","slug":"demurrer","command":"/demurrer","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Specific challenge to legal sufficiency of an identified Virginia Circuit Court pleading; not a generic federal plausibility motion.","docx":"docx/demurrer.docx","reasoning":"../../reasoning/demurrer.md","path":"templates/pleadings/demurrer.md","docx_path":"templates/pleadings/docx/demurrer.docx","reasoning_path":"reasoning/demurrer.md","field_count":25,"md":"---\ntitle: \"Demurrer\"\nslug: \"demurrer\"\ncommand: \"/demurrer\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Specific challenge to legal sufficiency of an identified Virginia Circuit Court pleading; not a generic federal plausibility motion.\"\ndocx: \"docx/demurrer.docx\"\nreasoning: \"../../reasoning/demurrer.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# DEMURRER\n[DEMURRING PARTY], by counsel, demurs to [EXACT PLEADING, COUNT OR COUNTS] on the specific grounds stated below under Virginia Code section 8.01-273. The procedural basis for filing this demurrer at this stage is [TIMELY INITIAL RESPONSE OR ACTUAL LEAVE / OTHER AUTHORITY].\n## Specific grounds\n1. [IDENTIFY THE PARTICULAR LEGAL DEFECT IN THE TARGETED COUNT AND THE RELEVANT ALLEGATIONS OR OMISSION].\n2. [STATE EACH ADDITIONAL DISTINCT GROUND WITH THE AFFECTED COUNT; OMIT IF NONE].\n## Legal basis\n[STATE THE APPLICABLE VIRGINIA STANDARD AND SUPPORTING AUTHORITIES]. For purposes of testing legal sufficiency, [EXPLAIN WHY THE ALLEGED MATERIAL FACTS AND PROPER INFERENCES DO NOT SUPPORT THE REQUESTED RELIEF].\n[ADDRESS DOCUMENTS PROPERLY PART OF THE PLEADING OR RECORD FOR THIS PROCEDURE, IF APPLICABLE]. No factual contest requiring evidence is resolved merely by asserting a contrary account in this demurrer.\n## Relief requested\nThe demurring party requests that the Court sustain the demurrer as to [SPECIFIED COUNTS OR RELIEF] and enter [PRECISE REQUESTED DISPOSITION]. Any requested limitation on leave to amend must rest on [SUPPORTED BASIS], rather than an assumed automatic dismissal with prejudice.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Demurrer to Amended Complaint","slug":"demurrer-amended","command":"/demurrer-amended","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Specific legal-sufficiency challenge to the current amended complaint.","docx":"docx/demurrer-amended.docx","reasoning":"../../reasoning/demurrer-amended.md","path":"templates/pleadings/demurrer-amended.md","docx_path":"templates/pleadings/docx/demurrer-amended.docx","reasoning_path":"reasoning/demurrer-amended.md","field_count":29,"md":"---\ntitle: \"Demurrer to Amended Complaint\"\nslug: \"demurrer-amended\"\ncommand: \"/demurrer-amended\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Specific legal-sufficiency challenge to the current amended complaint.\"\ndocx: \"docx/demurrer-amended.docx\"\nreasoning: \"../../reasoning/demurrer-amended.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# DEMURRER TO AMENDED COMPLAINT\n[DEFENDANT] demurs to [SPECIFIED COUNTS] of the [IDENTIFIED AMENDED COMPLAINT] filed [DATE].\n## Procedural posture\n1. The amendment was permitted by [ORDER OR OTHER VALID BASIS]. The applicable response date is [DATE AND SOURCE]. Prior responsive pleadings and rulings are [ACTUAL HISTORY].\n2. This filing is [THE INITIAL RESPONSE TO THIS AMENDED COMPLAINT OR AUTHORIZED BY SPECIFIC LEAVE OR RULE].\n## Specific grounds\n3. Count [NUMBER] fails to state [CLAIM OR REQUIRED ELEMENT] because [PRECISE DEFECT IN THE AMENDED ALLEGATIONS, WITH PARAGRAPH REFERENCES AND AUTHORITY].\n4. The relevant change from the prior complaint is [CHANGE], which [EXPLAIN EFFECT ON THE LEGAL DEFECT].\n5. [STATE EACH ADDITIONAL GROUND SEPARATELY; DO NOT INCORPORATE UNSPECIFIED PRIOR GROUNDS].\n## Requested disposition\nDefendant requests that the Court sustain the demurrer as to [COUNTS] and enter [SPECIFIC DISPOSITION, INCLUDING ANY POSITION ON LEAVE TO AMEND]. This challenge concerns legal sufficiency under the applicable Virginia standard; it does not ask the Court to resolve disputed evidence.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Grounds of Defense","slug":"grounds","command":"/grounds","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"GENERAL_DISTRICT","court":"Virginia General District Court","layout":"COURT","pages":2,"scope":"Grounds of Defense for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/grounds.docx","reasoning":"../../reasoning/grounds.md","path":"templates/pleadings/grounds.md","docx_path":"templates/pleadings/docx/grounds.docx","reasoning_path":"reasoning/grounds.md","field_count":22,"md":"---\ntitle: \"Grounds of Defense\"\nslug: \"grounds\"\ncommand: \"/grounds\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"GENERAL_DISTRICT\"\ncourt: \"Virginia General District Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Grounds of Defense for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/grounds.docx\"\nreasoning: \"../../reasoning/grounds.md\"\n---\nVIRGINIA: IN THE GENERAL DISTRICT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# Grounds of Defense\n[DEFENDANT] submits these grounds of defense in response to [IDENTIFIED WARRANT, COMPLAINT OR BILL OF PARTICULARS] and the Court’s order dated [DATE], under Rule 7B:2.\n## Responses and facts\n1. [IDENTIFY EACH MATERIAL ALLEGATION OR NUMBERED PARTICULAR AND THE ACCURATE ADMISSION, DENIAL OR QUALIFIED RESPONSE].\n2. [STATE THE FACTS SUPPORTING THE DEFENSE, WITH SUFFICIENT DETAIL TO IDENTIFY THE DISPUTE].\n[REPEAT FOR THE ACTUAL ISSUES, WITHOUT AN UNSUPPORTED BLANKET DENIAL.]\n## Specific defenses\n[STATE EACH FACTUALLY AND LEGALLY SUPPORTED DEFENSE THAT MUST OR SHOULD BE RAISED, INCLUDING ITS SUPPORTING FACTS. DO NOT LIST INCOMPATIBLE BOILERPLATE WITHOUT A BASIS.]\n<!-- pagebreak -->\nDefendant requests [SPECIFIC RELIEF]. Any counterclaim or request for affirmative recovery is [SEPARATELY FILED IDENTIFIER / NOT ASSERTED HERE]; this response does not silently create one.\nRespectfully submitted,\n[PARTY NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL DATE], a copy of this document was served on [NAMES, REPRESENTED PARTIES AND SERVICE ADDRESSES] by [ACTUAL AUTHORIZED METHOD].\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Notice of Related Proceeding","slug":"related-case","command":"/related-case","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Notice of Related Proceeding for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/related-case.docx","reasoning":"../../reasoning/related-case.md","path":"templates/pleadings/related-case.md","docx_path":"templates/pleadings/docx/related-case.docx","reasoning_path":"reasoning/related-case.md","field_count":22,"md":"---\ntitle: \"Notice of Related Proceeding\"\nslug: \"related-case\"\ncommand: \"/related-case\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Notice of Related Proceeding for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/related-case.docx\"\nreasoning: \"../../reasoning/related-case.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# Notice of Related Proceeding\n[FILING PARTY] identifies the following proceeding under [ACTUAL COURT ORDER, LOCAL REQUIREMENT OR OTHER STATED PURPOSE]:\n1. Related case: [FULL STYLE, COURT, CASE NUMBER, ASSIGNED JUDGE IF KNOWN AND CURRENT STATUS].\n2. Relationship: [SHARED PARTIES, TRANSACTION, FACTS OR ISSUES], supported by [IDENTIFIED PLEADINGS OR ORDERS]. The material differences are [SPECIFIC DISTINCTIONS].\n3. Potential scheduling or adjudication concern: [ACTUAL RISK OF OVERLAPPING DISCOVERY, INCONSISTENT RULINGS OR OTHER ISSUE].\n<!-- pagebreak -->\nThe requested action is [NOTICE ONLY / SPECIFIC RELIEF PRESENTED BY SEPARATE MOTION]. This notice does not represent that the cases have been consolidated, transferred or reassigned. Relevant documents actually submitted are [LIST].\nRespectfully submitted,\n[PARTY NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL DATE], a copy of this document was served on [NAMES, REPRESENTED PARTIES AND SERVICE ADDRESSES] by [ACTUAL AUTHORIZED METHOD].\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Third-Party Complaint","slug":"third-party","command":"/third-party","category":"pleadings","category_label":"Pleadings and service","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Derivative claim against a nonparty who may owe all or part of the defending party’s liability.","docx":"docx/third-party.docx","reasoning":"../../reasoning/third-party.md","path":"templates/pleadings/third-party.md","docx_path":"templates/pleadings/docx/third-party.docx","reasoning_path":"reasoning/third-party.md","field_count":27,"md":"---\ntitle: \"Third-Party Complaint\"\nslug: \"third-party\"\ncommand: \"/third-party\"\ncategory: \"pleadings\"\ncategory_label: \"Pleadings and service\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Derivative claim against a nonparty who may owe all or part of the defending party’s liability.\"\ndocx: \"docx/third-party.docx\"\nreasoning: \"../../reasoning/third-party.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# THIRD-PARTY COMPLAINT\nThird-party plaintiff: [DEFENDING PARTY AND CAPACITY]\nThird-party defendant: [NEW PARTY AND CAPACITY]\n[THIRD-PARTY PLAINTIFF], by counsel, alleges:\n## Parties and authority\n1. The plaintiff asserts [IDENTIFIED CLAIM] against third-party plaintiff in the pending action.\n2. Third-party defendant is [ENTITY OR PERSON, CAPACITY AND RELEVANT LOCATION]. Jurisdiction and service authority are [SPECIFIC BASIS].\n3. This third-party complaint is filed [WITHIN 21 DAYS AFTER SERVICE OF THE ORIGINAL RESPONSIVE PLEADING OR UNDER THE LEAVE ORDER DATED DATE].\n## Derivative claim\n4. [STATE THE FACTS AND LEGAL RELATIONSHIP SUPPORTING INDEMNITY, CONTRIBUTION OR OTHER DERIVATIVE LIABILITY].\n5. If third-party plaintiff is held liable to plaintiff on [CLAIM], third-party defendant is or may be liable to third-party plaintiff for [ALL OR DEFINED PART] because [SUPPORTED ELEMENTS AND FACTS].\n6. The governing agreement or other material instrument is [IDENTIFY AND ADDRESS ACTUAL ATTACHMENT IF APPLICABLE].\n## Relief requested\nThird-party plaintiff requests [SPECIFIC CONTINGENT JUDGMENT OR OTHER AUTHORIZED RELIEF]. This pleading does not concede liability on the plaintiff's claim. Initial process for the new third-party defendant is requested through the applicable issuance and service procedure; service on existing counsel alone is not service of that initial process.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Application for Letter Rogatory","slug":"letter-rogatory","command":"/letter-rogatory","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia application for judicial assistance to take evidence outside the Commonwealth; destination requirements separately verified.","docx":"docx/letter-rogatory.docx","reasoning":"../../reasoning/letter-rogatory.md","path":"templates/discovery/letter-rogatory.md","docx_path":"templates/discovery/docx/letter-rogatory.docx","reasoning_path":"reasoning/letter-rogatory.md","field_count":31,"md":"---\ntitle: \"Application for Letter Rogatory\"\nslug: \"letter-rogatory\"\ncommand: \"/letter-rogatory\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia application for judicial assistance to take evidence outside the Commonwealth; destination requirements separately verified.\"\ndocx: \"docx/letter-rogatory.docx\"\nreasoning: \"../../reasoning/letter-rogatory.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# APPLICATION FOR LETTER ROGATORY\n[MOVANT] applies under Rule 4:5(a1)(iii) for a letter rogatory directed to [APPROPRIATE AUTHORITY IN DESTINATION COUNTRY OR JURISDICTION].\n1. The action concerns [CLAIMS AND POSTURE]. Evidence is sought from [WITNESS / CUSTODIAN, ADDRESS AND LOCATION]. The requested testimony and records concern [SPECIFIC SUBJECTS AND RELEVANCE].\n2. The proposed examination is [ORAL / WRITTEN QUESTIONS], before [QUALIFIED PERSON OR AUTHORITY], with [OATH, RECORDING, INTERPRETER AND PARTICIPATION TERMS]. The actual proposed questions and record requests are [ATTACHMENT REFERENCES].\n3. The destination’s applicable treaty, reservations and local requirements are [VERIFIED ROUTE, LANGUAGE, COMPULSION AND TRANSMISSION REQUIREMENTS]. [IDENTIFY ANY REQUIRED HAGUE REQUEST FORM OR TRANSLATION].\n4. Notice of this application and proposed procedure was given to [PARTIES, DATE AND METHOD]. The proposed terms preserve each party’s right to [ATTEND, OBJECT AND EXAMINE AS APPROPRIATE].\n5. Movant proposes that the requested evidence be returned by [METHOD] with [REQUIRED CERTIFICATION AND SEAL / AUTHENTICATION]. Expenses will be handled by [LAWFUL ARRANGEMENT].\nWHEREFORE, Movant requests issuance on the stated just and appropriate terms. The proposed letter for judicial signature is [ACTUAL ATTACHMENT]; no judicial request is represented as issued before the Court acts.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Business Records Subpoena Duces Tecum","slug":"subpoena-biz","command":"/subpoena-biz","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Attorney-issued Virginia Rule 4:9A nonparty business-records discovery; excludes medical records, trial-only process and specially protected officials.","docx":"docx/subpoena-biz.docx","reasoning":"../../reasoning/subpoena-biz.md","path":"templates/discovery/subpoena-biz.md","docx_path":"templates/discovery/docx/subpoena-biz.docx","reasoning_path":"reasoning/subpoena-biz.md","field_count":18,"md":"---\ntitle: \"Business Records Subpoena Duces Tecum\"\nslug: \"subpoena-biz\"\ncommand: \"/subpoena-biz\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Attorney-issued Virginia Rule 4:9A nonparty business-records discovery; excludes medical records, trial-only process and specially protected officials.\"\ndocx: \"docx/subpoena-biz.docx\"\nreasoning: \"../../reasoning/subpoena-biz.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# SUBPOENA DUCES TECUM — BUSINESS RECORDS\nTO: [NONPARTY CUSTODIAN, ENTITY AND SERVICE ADDRESS]\nYou are commanded under Rule 4:9A to produce the designated materials in your possession, custody or control for inspection and copying at [PLACE / AGREED SECURE DELIVERY], on [DATE AND TIME], for [REASONABLE PRODUCTION PERIOD]. This request does not command personal testimony.\n## Materials requested\n1. [PRECISE RECORD CATEGORY, TRANSACTION / SUBJECT, CUSTODIAN AND RELEVANT DATE RANGE].\n2. [ADDITIONAL DISTINCT CATEGORY AND LIMITS].\nElectronic information is requested in [SPECIFIED REASONABLY USABLE FORMAT]. Documents may be produced as ordinarily kept or organized and labeled to match the requests. Duplicate electronic production in multiple forms is not required.\n## Recipient protections\nIf compliance with this attorney-issued subpoena is required less than 14 days after service, you may serve the issuing party with written objections stating your grounds. Upon such objection, production may be compelled only by court order. Rule 4:9A(c) also provides procedures to seek prompt protection from undue burden or expense, to address inaccessible electronic sources, and to request appropriate cost allocation. Nonparty financial or attorney-client protected records receive the protections of § 8.01-420.9 where applicable.\nQuestions, objections and requests to arrange production should be directed to the issuing attorney below.\nIssued on: [ACTUAL DATE]\n____________________________\n[ISSUING ATTORNEY NAME] (VSB No. [NUMBER])\n[ADDRESS]\nTelephone: [NUMBER]    Email: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Issuance and service certificate\nI certify that on [ACTUAL ISSUANCE DATE], a copy was mailed or delivered to the clerk of this Court, and copies were served under Rule 1:12 on [COUNSEL AND UNREPRESENTED PARTIES, ADDRESSES, METHOD AND DATE].\n____________________________\n[ISSUING ATTORNEY NAME]\n"},{"title":"Discovery Deficiency and Conference Request","slug":"meet-confer-deficient","command":"/meet-confer-deficient","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"LETTER","pages":1,"scope":"Good-faith correspondence concerning Virginia Circuit Court civil discovery.","docx":"docx/meet-confer-deficient.docx","reasoning":"../../reasoning/meet-confer-deficient.md","path":"templates/discovery/meet-confer-deficient.md","docx_path":"templates/discovery/docx/meet-confer-deficient.docx","reasoning_path":"reasoning/meet-confer-deficient.md","field_count":21,"md":"---\ntitle: \"Discovery Deficiency and Conference Request\"\nslug: \"meet-confer-deficient\"\ncommand: \"/meet-confer-deficient\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Good-faith correspondence concerning Virginia Circuit Court civil discovery.\"\ndocx: \"docx/meet-confer-deficient.docx\"\nreasoning: \"../../reasoning/meet-confer-deficient.md\"\n---\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[ORGANIZATION]\n[DELIVERY ADDRESS]\nRe: Discovery Deficiency and Conference Request — [CLIENT / CASE / CLAIM]\nDear [RECIPIENT]:\nWe write concerning [PARTY]'s responses to [DISCOVERY TITLE AND SET], served on [DATE]. We seek to resolve the following issues without court action.\n## Specific deficiencies\nRequest No. [NUMBER]: [EXACT OR CLEARLY IDENTIFIED REQUEST].\nResponse: [ACCURATE RESPONSE OR FAILURE TO RESPOND].\nIssue and requested cure: [SPECIFIC DEFICIENCY, APPLICABLE RULE AND PROPOSED NARROW REMEDY].\n[REPEAT FOR EACH DISPUTED REQUEST; IDENTIFY ACTUAL CORRESPONDENCE OR PRODUCTION].\nPlease provide your position and availability for a conference by [REQUESTED DATE]. We propose [DATES, TIMES AND METHOD] and request [SPECIFIC SUPPLEMENT OR PRODUCTION] by [PROPOSED DATE], subject to discussion.\nPlease identify any information or practical limitation that would help resolve these issues. If they remain unresolved, our client may seek appropriate relief from the court.\nSincerely,\n____________________________\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Expert Witness Disclosure","slug":"expert","command":"/expert","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Circuit Court civil personal-injury litigation.","docx":"docx/expert.docx","reasoning":"../../reasoning/expert.md","path":"templates/discovery/expert.md","docx_path":"templates/discovery/docx/expert.docx","reasoning_path":"reasoning/expert.md","field_count":21,"md":"---\ntitle: \"Expert Witness Disclosure\"\nslug: \"expert\"\ncommand: \"/expert\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Circuit Court civil personal-injury litigation.\"\ndocx: \"docx/expert.docx\"\nreasoning: \"../../reasoning/expert.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# EXPERT WITNESS DISCLOSURE\n[DISCLOSING PARTY] identifies the following expected trial expert in response to [DISCOVERY REQUEST OR SCHEDULING ORDER] under Rule 4:1(b)(4)(A)(i).\n## Expert identity and subject\n[EXPERT FULL NAME, ADDRESS AND RELEVANT QUALIFICATIONS]. The expected testimony concerns [SPECIFIC SUBJECT MATTER].\n## Facts and opinions\n[SUBSTANCE OF THE FACTS AND EACH OPINION THE EXPERT IS EXPECTED TO GIVE].\n## Grounds for the opinions\n[SUMMARY OF THE GROUNDS FOR EACH OPINION, TIED TO THE MATERIALS AND METHODS ACTUALLY RELIED ON].\n[IDENTIFY ANY ACTUALLY SUPPLIED REPORT OR CV REQUIRED BY THE REQUEST OR ORDER]. Any supplementation will be made as required by Rule 4:1(e) and the governing scheduling order.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Interrogatories Concerning Trial Experts","slug":"expert-demand","command":"/expert-demand","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Circuit Court civil discovery. Not an automatic federal Rule 26 exchange or California demand. Count all parts/subparts with prior interrogatories against Rule 4:8(g)’s 30 limit; normally serve without filing under 4:8(c). No unsupported demand for an expert report, protected draft or consultant.","docx":"docx/expert-demand.docx","reasoning":"../../reasoning/expert-demand.md","path":"templates/discovery/expert-demand.md","docx_path":"templates/discovery/docx/expert-demand.docx","reasoning_path":"reasoning/expert-demand.md","field_count":19,"md":"---\ntitle: \"Interrogatories Concerning Trial Experts\"\nslug: \"expert-demand\"\ncommand: \"/expert-demand\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Circuit Court civil discovery. Not an automatic federal Rule 26 exchange or California demand. Count all parts/subparts with prior interrogatories against Rule 4:8(g)’s 30 limit; normally serve without filing under 4:8(c). No unsupported demand for an expert report, protected draft or consultant.\"\ndocx: \"docx/expert-demand.docx\"\nreasoning: \"../../reasoning/expert-demand.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# INTERROGATORIES CONCERNING TRIAL EXPERTS\nTo: [RESPONDING PARTY], through [COUNSEL]\n[REQUESTING PARTY] serves these interrogatories under Rules 4:1(b)(4)(A)(i) and 4:8. The response deadline is [VERIFIED DATE UNDER RULES AND ENTERED ORDERS]. The applicable expert-disclosure order is [ORDER DATE AND PROVISION, IF ANY].\nRestate each question and answer separately and fully under oath. State each objection specifically and answer any portion not objected to. Supplement as required by Rule 4:1(e) and applicable orders. These requests concern expected trial experts, not undisclosed consulting experts, protected drafts or privileged attorney communications.\n1. Identify each person whom you expect to call as an expert witness at trial.\n2. For each identified person, state the subject matter on which the expert is expected to testify.\n3. For each identified person, state the substance of the facts to which the expert is expected to testify.\n4. For each identified person, state the substance of the opinions to which the expert is expected to testify.\n5. For each opinion, summarize the grounds supporting that opinion.\nThese interrogatories are served subject to the cumulative limit in Rule 4:8(g) and any leave or order applicable to this case. The prior interrogatory count and any leave relied upon are [COUNT AND ORDER].\nRespectfully submitted,\n[PARTY NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL DATE], a copy of this document was served on [NAMES, REPRESENTED PARTIES AND SERVICE ADDRESSES] by [ACTUAL AUTHORIZED METHOD].\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Motion for Discovery Sanctions","slug":"sanctions","command":"/sanctions","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"A supported Rule 4:12 discovery-sanctions request, with the applicable route expressly identified.","docx":"docx/sanctions.docx","reasoning":"../../reasoning/sanctions.md","path":"templates/discovery/sanctions.md","docx_path":"templates/discovery/docx/sanctions.docx","reasoning_path":"reasoning/sanctions.md","field_count":32,"md":"---\ntitle: \"Motion for Discovery Sanctions\"\nslug: \"sanctions\"\ncommand: \"/sanctions\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"A supported Rule 4:12 discovery-sanctions request, with the applicable route expressly identified.\"\ndocx: \"docx/sanctions.docx\"\nreasoning: \"../../reasoning/sanctions.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION FOR DISCOVERY SANCTIONS\n[MOVANT] seeks [SPECIFIC SANCTION OR EXPENSE AWARD] under Rule 4:12([APPLICABLE SUBSECTION]).\n## Conduct and procedural basis\n1. The discovery at issue is [EXACT REQUEST, NOTICE OR ORDER], served or entered on [DATE]. The obligation and deadline were [TERMS].\n2. The noncompliance was [SPECIFIC ACT OR OMISSION], shown by [RECORD REFERENCES]. Any prior order, service of that order and opportunity to comply are [ACTUAL FACTS].\n3. The selected subsection applies because [REQUIRED PREDICATES]. If no prior compel order was entered, the basis for a remedy without that order is [SPECIFIC RULE PROVISION AND SUPPORTING FACTS].\n## Prejudice and proportionate relief\n4. The resulting prejudice or expense is [SUPPORTED DESCRIPTION]. The requested remedy addresses it by [EXPLANATION]; narrower alternatives and any proposed cure are [ANALYSIS].\n5. Any monetary request is [ITEMIZED REASONABLE EXPENSE AND CAUSAL CONNECTION]. Known substantial-justification or other fairness arguments are [ACCURATE POSITION AND RESPONSE].\n## Conference and requested ruling\nCounsel's actual good-faith conference or attempt, where required, was [DATE, PARTICIPANTS, METHOD AND RESULT]. Movant requests notice and an opportunity to be heard for affected parties/persons, followed by [EXACT RELIEF]. No unperformed conference or automatic entitlement is certified.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion for Physical or Mental Examination","slug":"ime-demand","command":"/ime-demand","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Rule 4:10 motion seeking a defined examination on good cause; not a unilateral command to attend.","docx":"docx/ime-demand.docx","reasoning":"../../reasoning/ime-demand.md","path":"templates/discovery/ime-demand.md","docx_path":"templates/discovery/docx/ime-demand.docx","reasoning_path":"reasoning/ime-demand.md","field_count":27,"md":"---\ntitle: \"Motion for Physical or Mental Examination\"\nslug: \"ime-demand\"\ncommand: \"/ime-demand\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Rule 4:10 motion seeking a defined examination on good cause; not a unilateral command to attend.\"\ndocx: \"docx/ime-demand.docx\"\nreasoning: \"../../reasoning/ime-demand.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION FOR PHYSICAL OR MENTAL EXAMINATION\n[MOVANT] requests an order requiring [PERSON AND CAPACITY] to submit to the examination described below under Rule 4:10.\n## Condition in controversy and good cause\n1. The condition placed in controversy is [SPECIFIC PHYSICAL OR MENTAL CONDITION], as shown by [PLEADING, CLAIM OR OTHER RECORD].\n2. Good cause exists because [CASE-SPECIFIC NEED FOR THIS EXAMINATION, ITS RELEVANCE AND WHY AVAILABLE INFORMATION IS INSUFFICIENT].\n## Proposed examination\n3. Examiner: [NAME, PROFESSION, QUALIFICATIONS AND LICENSURE]. The examiner's Virginia residence or office is [LOCATION], or the requested basis for the Court to permit an out-of-state examiner is [ENDS-OF-JUSTICE FACTS].\n4. Date/time and place: [DETAILS]. Manner, conditions and scope: [SPECIFIC EXAMINATION, TESTS, DURATION AND LIMITATIONS].\n5. Proposed safeguards and disputed conditions are [ACTUAL POSITIONS CONCERNING RECORDING, ATTENDANCE, INVASIVE TESTS OR OTHER ISSUES]. No disputed condition is represented as already agreed.\n## Requested order\nMovant requests the stated examination and an order fixing [DATE] for the examiner's detailed report to be filed with the clerk and furnished to each party. Notice to the examinee and all parties is [ACTUAL NOTICE STATUS].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion for Protective Order","slug":"protective","command":"/protective","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Circuit Court civil personal-injury litigation.","docx":"docx/protective.docx","reasoning":"../../reasoning/protective.md","path":"templates/discovery/protective.md","docx_path":"templates/discovery/docx/protective.docx","reasoning_path":"reasoning/protective.md","field_count":24,"md":"---\ntitle: \"Motion for Protective Order\"\nslug: \"protective\"\ncommand: \"/protective\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Circuit Court civil personal-injury litigation.\"\ndocx: \"docx/protective.docx\"\nreasoning: \"../../reasoning/protective.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION FOR PROTECTIVE ORDER\n[MOVANT] requests a protective order under Rule 4:1(c) concerning [SPECIFIC DISCOVERY].\n## Discovery and good cause\n1. [IDENTIFY REQUESTS, NOTICE OR EXAMINATION, PARTIES AND RELEVANT DATES].\n2. Good cause exists because [SPECIFIC FACTS SHOWING ANNOYANCE, EMBARRASSMENT, OPPRESSION, UNDUE BURDEN OR EXPENSE]. The supporting evidence is [ACTUAL DECLARATION, RECORD OR EXHIBIT].\n3. [ADDRESS RELEVANCE, PRIVILEGE, ACCESSIBILITY OR OTHER ISSUE ACTUALLY RAISED, INCLUDING PRACTICAL ALTERNATIVES].\n## Requested protection\n4. Movant requests [NARROW SCOPE LIMIT, METHOD, CONDITIONS, TIMING OR OTHER PRECISE PROTECTION] because [HOW IT ADDRESSES THE IDENTIFIED HARM].\n5. [IDENTIFY ANY SEPARATELY REQUESTED INTERIM RELIEF AND ITS BASIS].\n## Good-faith certification\nCounsel certifies that [ACTUAL CONFERENCE OR ATTEMPT, DATES, PARTICIPANTS, METHOD AND RESULT] was undertaken in good faith to resolve this dispute without court action.\nWHEREFORE, Movant requests entry of the specified protective relief.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion to Compel Discovery","slug":"compel","command":"/compel","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Circuit Court civil personal-injury litigation.","docx":"docx/compel.docx","reasoning":"../../reasoning/compel.md","path":"templates/discovery/compel.md","docx_path":"templates/discovery/docx/compel.docx","reasoning_path":"reasoning/compel.md","field_count":29,"md":"---\ntitle: \"Motion to Compel Discovery\"\nslug: \"compel\"\ncommand: \"/compel\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Circuit Court civil personal-injury litigation.\"\ndocx: \"docx/compel.docx\"\nreasoning: \"../../reasoning/compel.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION TO COMPEL DISCOVERY\n[MOVANT] moves under Rule 4:12(a) for an order requiring [RESPONDING PARTY] to provide the discovery identified below.\n## Background and disputed discovery\n1. Movant served [IDENTIFIED DISCOVERY] on [DATE] by [METHOD]. Responses were due on [VERIFIED DATE AND BASIS, INCLUDING EXTENSIONS OR ORDERS].\n2. [DESCRIBE THE ACTUAL RESPONSE OR FAILURE TO RESPOND, WITH DATES].\n3. The disputed items are [REQUEST NUMBERS, RELEVANT REQUEST AND RESPONSE TEXT, SPECIFIC DEFICIENCY, AND REQUESTED CURE]. Relevant materials are [ACTUAL EXHIBIT REFERENCES].\n## Grounds and requested relief\n4. The requested discovery is within [APPLICABLE DISCOVERY RULE AND SUPPORTED SCOPE]. [ADDRESS THE SPECIFIC OBJECTION, PRIVILEGE OR BURDEN ISSUE].\n5. Movant requests [PRECISE ANSWER, PRODUCTION OR INSPECTION] by [PROPOSED REASONABLE DATE]. [STATE ANY REQUEST FOR EXPENSES UNDER RULE 4:12(a)(4), ITS BASIS AND REQUEST FOR AN OPPORTUNITY TO BE HEARD].\n## Good-faith certification\nCounsel certifies that [ACTUAL CONFERENCE OR ATTEMPT, DATES, PARTICIPANTS, METHOD AND RESULT] was undertaken in good faith to resolve this dispute without court action.\nWHEREFORE, Movant requests the specific relief stated above.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Notice of Audiovisual Deposition","slug":"depo-video","command":"/depo-video","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Audiovisual deposition notice, including explicit recording notice; stenographic recording is optional unless separately required.","docx":"docx/depo-video.docx","reasoning":"../../reasoning/depo-video.md","path":"templates/discovery/depo-video.md","docx_path":"templates/discovery/docx/depo-video.docx","reasoning_path":"reasoning/depo-video.md","field_count":23,"md":"---\ntitle: \"Notice of Audiovisual Deposition\"\nslug: \"depo-video\"\ncommand: \"/depo-video\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Audiovisual deposition notice, including explicit recording notice; stenographic recording is optional unless separately required.\"\ndocx: \"docx/depo-video.docx\"\nreasoning: \"../../reasoning/depo-video.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# NOTICE OF AUDIOVISUAL DEPOSITION\n[NOTICING PARTY] gives notice that the deposition of [WITNESS NAME AND ADDRESS] will be taken on [DATE AND TIME] at [LAWFUL PLACE OR REMOTE ARRANGEMENT]. The deposition will be recorded by audiovisual means under Rule 4:7A and Virginia Code sections 8.01-412.2 and 8.01-412.3.\nThe qualified officer is [NAME OR DESIGNATION]. The audiovisual operator and employer are [DETAILS]. Any simultaneous stenographic or audio recording is [ACTUAL ARRANGEMENT]. Participants may obtain copies at their expense as provided by applicable law.\nIf conducted remotely, the deponent’s locality, officer’s arrangements, participating locations and access instructions are [DETAILS]. The on-camera identification, oath and recording procedures will follow Rule 4:7A. No recording will be edited except as permitted by an actual stipulation or court order; the original will be preserved.\nAny subpoena required for attendance must also state that audiovisual recording will be used. Its actual issuance and service status are [DETAILS]. Requested materials, if any, are [PROPERLY INCLUDED OR ATTACHED DESIGNATION].\nPlease contact [PERSON] concerning the recording and attendance arrangements. This notice does not declare the resulting recording automatically admissible for every trial purpose.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Notice of Deposition","slug":"depo-notice","command":"/depo-notice","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Notice of an individual’s deposition in Virginia Circuit Court civil litigation; excludes organization-topic and subpoena forms.","docx":"docx/depo-notice.docx","reasoning":"../../reasoning/depo-notice.md","path":"templates/discovery/depo-notice.md","docx_path":"templates/discovery/docx/depo-notice.docx","reasoning_path":"reasoning/depo-notice.md","field_count":25,"md":"---\ntitle: \"Notice of Deposition\"\nslug: \"depo-notice\"\ncommand: \"/depo-notice\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Notice of an individual’s deposition in Virginia Circuit Court civil litigation; excludes organization-topic and subpoena forms.\"\ndocx: \"docx/depo-notice.docx\"\nreasoning: \"../../reasoning/depo-notice.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# NOTICE OF DEPOSITION\n[NOTICING PARTY], by counsel, gives notice under Rule 4:5 that the deposition of [DEPONENT FULL NAME AND ADDRESS] will be taken on [DATE] at [TIME AND TIME ZONE].\nThe deposition will occur at [PHYSICAL LOCATION, INCLUDING DEPONENT LOCATION IF REMOTE], by [IN-PERSON OR IDENTIFIED REMOTE METHOD]. Connection and access instructions are [DETAILS]. Testimony will be taken before [APPROPRIATE OFFICER AND LOCALITY] and recorded by [AUTHORIZED RECORDING METHOD].\nThe examination concerns the above action and will continue as permitted by the applicable rules, agreements and orders. [IDENTIFY ANY ORDER OR AGREEMENT AFFECTING THE DEPOSITION].\n[IDENTIFY ANY ATTACHED PARTY DOCUMENT REQUEST UNDER RULE 4:9, OR REMOVE THIS PARAGRAPH].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Notice of Deposition of a Party","slug":"nod-party","command":"/nod-party","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia oral deposition notice directed to an identified individual party.","docx":"docx/nod-party.docx","reasoning":"../../reasoning/nod-party.md","path":"templates/discovery/nod-party.md","docx_path":"templates/discovery/docx/nod-party.docx","reasoning_path":"reasoning/nod-party.md","field_count":26,"md":"---\ntitle: \"Notice of Deposition of a Party\"\nslug: \"nod-party\"\ncommand: \"/nod-party\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia oral deposition notice directed to an identified individual party.\"\ndocx: \"docx/nod-party.docx\"\nreasoning: \"../../reasoning/nod-party.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# NOTICE OF DEPOSITION OF A PARTY\nTo: [ALL COUNSEL OF RECORD AND UNREPRESENTED PARTIES]\n[NOTICING PARTY] will take the oral deposition of [INDIVIDUAL PARTY NAME AND ROLE] under Rule 4:5.\n## Time and place\nDate: [DATE]    Time: [TIME AND TIME ZONE]\nPlace: [EXACT PHYSICAL LOCATION]\nRemote arrangements, if applicable: [ACTUAL AGREEMENT OR ORDER, ACCESS METHOD AND DEPONENT LOCATION]\nThe examination will occur before [AUTHORIZED OFFICER OR OFFICER DESCRIPTION] and will be recorded by [STENOGRAPHIC METHOD AND ANY PROPERLY NOTICED ADDITIONAL METHOD]. It will continue as permitted by the applicable rules, agreement and court orders.\nReasonable notice and any applicable leave or scheduling requirement are addressed by [ACTUAL NOTICE INTERVAL, CONFERRAL AND ORDER]. If remote examination is used, the officer and oath arrangements are [ARRANGEMENTS CONSISTENT WITH THE RULE OR COURT ORDER].\nNo production obligation is added merely by this notice. Any accompanying party document request is [IDENTIFIED SEPARATE RULE 4:9 REQUEST WITH ITS OWN LAWFUL DEADLINE OR NONE].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Notice of Expert Deposition","slug":"nod-expert","command":"/nod-expert","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Deposition of an identified testifying expert; not discovery of a non-testifying consultant without the required showing.","docx":"docx/nod-expert.docx","reasoning":"../../reasoning/nod-expert.md","path":"templates/discovery/nod-expert.md","docx_path":"templates/discovery/docx/nod-expert.docx","reasoning_path":"reasoning/nod-expert.md","field_count":28,"md":"---\ntitle: \"Notice of Expert Deposition\"\nslug: \"nod-expert\"\ncommand: \"/nod-expert\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Deposition of an identified testifying expert; not discovery of a non-testifying consultant without the required showing.\"\ndocx: \"docx/nod-expert.docx\"\nreasoning: \"../../reasoning/nod-expert.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# NOTICE OF EXPERT DEPOSITION\n[NOTICING PARTY] gives notice that the deposition of [EXPERT NAME AND ADDRESS], identified by [PARTY] as an expert whose opinion may be presented at trial, will be taken on [DATE AND TIME] at [LAWFUL PLACE OR REMOTE ARRANGEMENT]. The disclosure identifying the witness is [DOCUMENT AND DATE].\nThe examination concerns [DISCLOSED SUBJECT MATTER AND OPINIONS] within the scope allowed by Rules 4:1(b)(4) and 4:5. It will occur before [QUALIFIED OFFICER], with testimony recorded by [METHOD].\nReasonable fees and expenses will be addressed under Rule 4:1(b)(4)(C) and [ACTUAL AGREEMENT OR COURT DIRECTION]. Requested scheduling and fee information is [DETAILS]; no fee amount or agreement is represented as settled unless verified.\nAny requested document production is set out in [SEPARATE PROPER REQUEST OR SUBPOENA, IF ANY]. This notice does not automatically demand protected draft reports or all attorney-expert communications.\nIf remote, [IDENTIFY DEPONENT LOCALITY, OFFICER AND ACCESS ARRANGEMENTS]. Any process required to compel this witness’s attendance will be handled separately. Please direct logistics questions to [CONTACT].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Notice of Nonparty Records Production","slug":"nod-records","command":"/nod-records","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Party notice accompanying actual Rule 4:9A process for records without oral testimony; not itself a subpoena.","docx":"docx/nod-records.docx","reasoning":"../../reasoning/nod-records.md","path":"templates/discovery/nod-records.md","docx_path":"templates/discovery/docx/nod-records.docx","reasoning_path":"reasoning/nod-records.md","field_count":24,"md":"---\ntitle: \"Notice of Nonparty Records Production\"\nslug: \"nod-records\"\ncommand: \"/nod-records\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Party notice accompanying actual Rule 4:9A process for records without oral testimony; not itself a subpoena.\"\ndocx: \"docx/nod-records.docx\"\nreasoning: \"../../reasoning/nod-records.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# NOTICE OF NONPARTY RECORDS PRODUCTION\n[REQUESTING PARTY] gives notice of the following nonparty records process in this pending action.\n## Custodian and process\nNonparty custodian: [NAME AND ADDRESS]\nProcess: [CLERK REQUEST OR ATTORNEY-ISSUED SUBPOENA DUCES TECUM, IDENTIFIED BY DATE]\nThe attached document is [ACTUAL COPY OF REQUEST OR ISSUED SUBPOENA]. Its status is [REQUESTED OR ISSUED]; this notice does not itself command compliance.\n## Material and production\nThe requested categories are [REASONABLY PARTICULAR DESCRIPTION OR EXACT ATTACHED SCHEDULE REFERENCE]. The production time, place, period and manner are [TERMS IN THE ACTUAL PROCESS]. The electronic format is [SPECIFICATION]. No oral testimony or personal deposition appearance is requested by this notice alone.\nThe Rule 4:9A party-service and clerk-delivery steps are [ACTUAL STATUS]. Any special health-record notice, objection period or other protected-record requirement is addressed in [ACTUAL COMPLIANT DOCUMENTS].\nIf records are received, access/copies for other parties will be provided as required by Rule 4:9A(f) and applicable law. Any objection or motion affecting production will be handled through the governing procedure; production will not be treated as compulsory where an applicable objection bars it pending court order.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Notice of Nonparty Witness Deposition","slug":"nod-witness","command":"/nod-witness","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Notice to parties of a nonparty witness deposition; separate witness process and lawful place required.","docx":"docx/nod-witness.docx","reasoning":"../../reasoning/nod-witness.md","path":"templates/discovery/nod-witness.md","docx_path":"templates/discovery/docx/nod-witness.docx","reasoning_path":"reasoning/nod-witness.md","field_count":26,"md":"---\ntitle: \"Notice of Nonparty Witness Deposition\"\nslug: \"nod-witness\"\ncommand: \"/nod-witness\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Notice to parties of a nonparty witness deposition; separate witness process and lawful place required.\"\ndocx: \"docx/nod-witness.docx\"\nreasoning: \"../../reasoning/nod-witness.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# NOTICE OF NONPARTY WITNESS DEPOSITION\n[NOTICING PARTY] gives notice of the oral deposition of [WITNESS NAME AND ADDRESS], a nonparty witness, on [DATE AND TIME] at [PLACE]. The witness is identified by [NAME OR SUFFICIENT DESCRIPTION IF NAME IS UNKNOWN].\nThe proposed place is authorized by [RESIDENCE, EMPLOYMENT OR PRINCIPAL PLACE OF BUSINESS; ACTUAL AGREEMENT; OR COURT ORDER] under Rule 4:5(a1)(ii) and any law applicable where the witness resides.\nThe testimony will be taken before [QUALIFIED OFFICER] and recorded by [METHOD]. If remote, the witness’s locality, officer and access details are [ARRANGEMENTS].\nA subpoena or other process required to compel attendance is [ACTUAL STATUS AND IDENTIFIER] and must be issued and served under the applicable procedure. This notice to the parties is not itself a command to the witness.\nIf a subpoena duces tecum is to be served, its designation of materials is [ATTACHED OR INCLUDED EXACTLY]. If no production is requested, no records obligation is created by this notice. Please contact [PERSON] concerning logistics.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Notice of Organizational Deposition","slug":"nod-corporate","command":"/nod-corporate","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Rule 4:5(b)(6) notice to a specific organization; Virginia terminology and particularized topics, not a generic “PMK” label.","docx":"docx/nod-corporate.docx","reasoning":"../../reasoning/nod-corporate.md","path":"templates/discovery/nod-corporate.md","docx_path":"templates/discovery/docx/nod-corporate.docx","reasoning_path":"reasoning/nod-corporate.md","field_count":27,"md":"---\ntitle: \"Notice of Organizational Deposition\"\nslug: \"nod-corporate\"\ncommand: \"/nod-corporate\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Rule 4:5(b)(6) notice to a specific organization; Virginia terminology and particularized topics, not a generic “PMK” label.\"\ndocx: \"docx/nod-corporate.docx\"\nreasoning: \"../../reasoning/nod-corporate.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# NOTICE OF ORGANIZATIONAL DEPOSITION\n[NOTICING PARTY] gives notice under Rule 4:5(b)(6) of the deposition of [ORGANIZATION AND ADDRESS] on [DATE AND TIME] at [LAWFUL LOCATION OR REMOTE ARRANGEMENT].\nThe organization must designate one or more persons to testify on its behalf about the matters below, with each person’s assigned subjects identified as appropriate. Testimony concerns information known or reasonably available to the organization.\n## Matters for examination\n1. [PARTICULARIZED TOPIC, TRANSACTION OR EVENT, WITH REASONABLE DATE AND SUBJECT LIMITS].\n2. [ADDITIONAL DISTINCT PARTICULARIZED TOPIC].\n3. [ADDITIONAL TOPIC IF NEEDED; OMIT UNUSED ITEMS].\n## Arrangements\nThe serving party and organization must confer in good faith about the matters for examination before or promptly after service. Proposed conference arrangements are [DETAILS]; completed conferral is described only if it actually occurred.\nThe deposition will be taken before [QUALIFIED OFFICER] and recorded by [ACTUAL METHOD]. If remote, the deponent’s locality, officer and access arrangements are [DETAILS CONSISTENT WITH RULE 4:5(b)(7) OR THE ACTUAL ORDER].\nThe organization is [PARTY / NONPARTY]. Any required nonparty subpoena, including the required designation-and-conferral advice, will be separately issued and served. Document requests or subpoena materials, if any, are [IDENTIFIED ATTACHMENTS]; this notice alone does not create a production obligation beyond the proper procedure.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Plaintiff’s First Interrogatories to Defendant","slug":"interrogatories","command":"/interrogatories","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Plaintiff to individual defendant in ordinary Virginia Circuit Court motor-vehicle litigation; tailor direction and relevance.","docx":"docx/interrogatories.docx","reasoning":"../../reasoning/interrogatories.md","path":"templates/discovery/interrogatories.md","docx_path":"templates/discovery/docx/interrogatories.docx","reasoning_path":"reasoning/interrogatories.md","field_count":17,"md":"---\ntitle: \"Plaintiff’s First Interrogatories to Defendant\"\nslug: \"interrogatories\"\ncommand: \"/interrogatories\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Plaintiff to individual defendant in ordinary Virginia Circuit Court motor-vehicle litigation; tailor direction and relevance.\"\ndocx: \"docx/interrogatories.docx\"\nreasoning: \"../../reasoning/interrogatories.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PLAINTIFF’S FIRST INTERROGATORIES TO DEFENDANT\nPlaintiff [NAME] serves these interrogatories on Defendant [NAME] under Rules 4:1 and 4:8. “Incident” means the [DATE] motor-vehicle collision at [LOCATION]. Answer within the time applicable under Rule 4:8(d), subject to any valid extension or order.\n## Interrogatories\n1. Identify each person known to you to have witnessed the Incident.\n2. Describe your account of how the Incident occurred.\n3. State the facts supporting your contention, if any, that Plaintiff's conduct contributed to the Incident.\n4. Identify each person, other than Plaintiff, whose conduct you contend caused or contributed to the Incident.\n5. Identify photographs, recordings or electronically stored information depicting the Incident that are within your possession, custody or control.\n6. Identify any person who investigated the Incident on your behalf, excluding information protected from disclosure.\n7. Identify the insurance agreements described in Rule 4:1(b)(2) that may satisfy all or part of a judgment in this action.\n8. Identify each statement by Plaintiff concerning the Incident within your possession, custody or control.\nEach answer must restate the interrogatory and respond separately under oath. State specific objections and answer any unobjectionable portion as Rule 4:8 requires.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Plaintiff’s First Requests for Admission to Defendant","slug":"rfa","command":"/rfa","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Circuit Court civil personal-injury litigation.","docx":"docx/rfa.docx","reasoning":"../../reasoning/rfa.md","path":"templates/discovery/rfa.md","docx_path":"templates/discovery/docx/rfa.docx","reasoning_path":"reasoning/rfa.md","field_count":22,"md":"---\ntitle: \"Plaintiff’s First Requests for Admission to Defendant\"\nslug: \"rfa\"\ncommand: \"/rfa\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Circuit Court civil personal-injury litigation.\"\ndocx: \"docx/rfa.docx\"\nreasoning: \"../../reasoning/rfa.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PLAINTIFF’S FIRST REQUESTS FOR ADMISSION TO DEFENDANT\nPlaintiff [NAME] requests that Defendant [NAME] respond under Rules 4:1 and 4:11 to each matter separately stated below. “Incident” means the [DATE] collision at [LOCATION].\n## Requests for admission\n1. Admit that you operated [IDENTIFIED VEHICLE] at the time of the Incident.\n2. Admit that [SINGLE SUPPORTED FACT MATERIAL TO THE CLAIM].\n3. Admit that [SECOND SINGLE SUPPORTED FACT MATERIAL TO THE CLAIM].\n4. Admit that [IDENTIFIED ATTACHED OR PREVIOUSLY FURNISHED DOCUMENT] is a genuine copy of [SPECIFIC DOCUMENT].\nResponses must be signed and served within the time applicable under Rule 4:11(a), subject to any valid extension or order. Each response must admit, specifically deny, explain an inability to admit or deny after reasonable inquiry, or state the basis for a proper objection. A matter may be admitted by failure to respond as the rule provides.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Plaintiff’s First Requests for Production to Defendant","slug":"rfp","command":"/rfp","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Plaintiff’s party requests in Virginia Circuit Court motor-vehicle litigation; not a nonparty subpoena.","docx":"docx/rfp.docx","reasoning":"../../reasoning/rfp.md","path":"templates/discovery/rfp.md","docx_path":"templates/discovery/docx/rfp.docx","reasoning_path":"reasoning/rfp.md","field_count":22,"md":"---\ntitle: \"Plaintiff’s First Requests for Production to Defendant\"\nslug: \"rfp\"\ncommand: \"/rfp\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Plaintiff’s party requests in Virginia Circuit Court motor-vehicle litigation; not a nonparty subpoena.\"\ndocx: \"docx/rfp.docx\"\nreasoning: \"../../reasoning/rfp.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PLAINTIFF’S FIRST REQUESTS FOR PRODUCTION TO DEFENDANT\nPlaintiff [NAME] requests that Defendant [NAME] produce the following nonprivileged materials within Defendant's possession, custody or control under Rules 4:1 and 4:9. “Incident” means the [DATE] collision at [LOCATION].\nProduction is requested at [REASONABLE TIME, PLACE AND PERIOD] by [MANNER / SECURE DELIVERY]. Produce electronic material in [REASONABLY USABLE FORMATS], including native video files where requested. Written responses are due under Rule 4:9(b), subject to any valid extension or order.\n## Requests\n1. Photographs and video depicting the Incident or the vehicles immediately before or after it.\n2. Dashcam or other vehicle-camera recordings depicting [IDENTIFIED VEHICLE / EVENT AND REASONABLE TIME RANGE].\n3. Surveillance recordings depicting Plaintiff during [RELEVANT DATE RANGE], subject to applicable protection or privilege.\n4. Documents describing inspection, repair or damage to the vehicle you operated arising from the Incident.\n5. Statements by Plaintiff concerning the Incident within your possession, custody or control.\n6. Insurance agreements within Rule 4:1(b)(2) that may satisfy all or part of a judgment in this action.\nState specific objections and whether responsive material is withheld on each objection. Produce unobjectionable portions and identify privileged material as Rule 4:1(b)(6) requires.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Request for Examination Report","slug":"ime-report","command":"/ime-report","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Request for the report of an actual Rule 4:10 or agreed examination.","docx":"docx/ime-report.docx","reasoning":"../../reasoning/ime-report.md","path":"templates/discovery/ime-report.md","docx_path":"templates/discovery/docx/ime-report.docx","reasoning_path":"reasoning/ime-report.md","field_count":15,"md":"---\ntitle: \"Request for Examination Report\"\nslug: \"ime-report\"\ncommand: \"/ime-report\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Request for the report of an actual Rule 4:10 or agreed examination.\"\ndocx: \"docx/ime-report.docx\"\nreasoning: \"../../reasoning/ime-report.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[OPPOSING COUNSEL]\n[RECIPIENT ADDRESS]\nRe: [CASE] — examination of [PERSON] on [DATE]\nDear [RECIPIENT NAME]:\nWe request the detailed report from [EXAMINER] for the examination conducted on [DATE]. The examination was authorized by [ORDER OR AGREEMENT AND DATE], which establishes [ACTUAL REPORT DEADLINE AND DELIVERY TERMS].\nPlease provide the examiner's findings, test results, diagnosis and conclusions, together with like reports of earlier examinations of the same condition as required by the governing procedure. Please confirm the date the report was filed with the clerk and furnished to each party, or identify the agreed variation applicable to this examination.\nUnder Rule 4:10(c), an agreed examination is subject to that subdivision unless the agreement expressly provides otherwise. If you contend the requested material is withheld or not yet available, identify the specific basis and expected availability.\nThis request seeks the existing report and required accompanying material. It does not state that the examination occurred or that a report was filed unless supported by the actual record. Please respond by [REQUESTED DATE OR OPERATIVE DEADLINE].\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Request for Production Concerning Disclosed Life Care Opinions","slug":"lifecare-demand","command":"/lifecare-demand","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Request for Production Concerning Disclosed Life Care Opinions for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/lifecare-demand.docx","reasoning":"../../reasoning/lifecare-demand.md","path":"templates/discovery/lifecare-demand.md","docx_path":"templates/discovery/docx/lifecare-demand.docx","reasoning_path":"reasoning/lifecare-demand.md","field_count":21,"md":"---\ntitle: \"Request for Production Concerning Disclosed Life Care Opinions\"\nslug: \"lifecare-demand\"\ncommand: \"/lifecare-demand\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Request for Production Concerning Disclosed Life Care Opinions for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/lifecare-demand.docx\"\nreasoning: \"../../reasoning/lifecare-demand.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# Request for Production Concerning Disclosed Life Care Opinions\n[REQUESTING PARTY] serves this request under Rules 4:1 and 4:9 concerning [IDENTIFIED DISCLOSED TESTIFYING EXPERT AND LIFE CARE OPINIONS] in this action. The scope and timing are governed by [ACTUAL SCHEDULING ORDER AND DISCOVERY STATUS].\n1. Produce the existing life care plan, report, cost schedule and amendments on which [EXPERT] will rely or has disclosed reliance, limited to [IDENTIFIED SUBJECT AND PERIOD].\n2. Produce existing nonprivileged materials supporting the disclosed recommended services, frequency, duration and cost assumptions, identified with enough specificity to connect them to [DISCLOSED OPINIONS].\n3. Produce existing nonprivileged documents identifying the sources and dates of the disclosed unit costs and any supporting calculations within the permissible scope of expert discovery.\n<!-- pagebreak -->\nProduction is requested at [REASONABLE PLACE OR AGREED SECURE METHOD] within [ACTUAL APPLICABLE RULE OR ORDER PERIOD]. State specific objections and identify withheld categories as required by the applicable rules. This request does not require creation of a report that does not exist or disclosure beyond the permissible treatment of consulting experts, privilege or protected work product.\nRespectfully submitted,\n[PARTY NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL DATE], a copy of this document was served on [NAMES, REPRESENTED PARTIES AND SERVICE ADDRESSES] by [ACTUAL AUTHORIZED METHOD].\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Request for Production with Party Deposition","slug":"rfd-with-depo","command":"/rfd-with-depo","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Rule 4:9 production request accompanying a party deposition notice; not a shortened nonparty subpoena.","docx":"docx/rfd-with-depo.docx","reasoning":"../../reasoning/rfd-with-depo.md","path":"templates/discovery/rfd-with-depo.md","docx_path":"templates/discovery/docx/rfd-with-depo.docx","reasoning_path":"reasoning/rfd-with-depo.md","field_count":24,"md":"---\ntitle: \"Request for Production with Party Deposition\"\nslug: \"rfd-with-depo\"\ncommand: \"/rfd-with-depo\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Rule 4:9 production request accompanying a party deposition notice; not a shortened nonparty subpoena.\"\ndocx: \"docx/rfd-with-depo.docx\"\nreasoning: \"../../reasoning/rfd-with-depo.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# REQUEST FOR PRODUCTION WITH PARTY DEPOSITION\n[REQUESTING PARTY] requests that [PARTY DEPONENT] produce the following nonprivileged materials within that party’s possession, custody or control in connection with the deposition noticed for [DATE AND TIME]. This request proceeds under Rules 4:5(b)(5) and 4:9.\n## Production arrangements\nThe reasonable time, place and manner for production are [DETAILS CONSISTENT WITH RULE 4:9, THE NOTICE AND ANY ACTUAL AGREEMENT OR ORDER]. Written responses are due on [VERIFIED APPLICABLE DATE]. The deposition notice does not shorten the response period by itself.\nElectronically stored material should be produced in [REASONABLY USABLE FORMAT AND DELIVERY METHOD]. The incident or subject addressed is [DEFINED EVENT AND REASONABLE PERIOD].\n## Requests\n1. [SPECIFIC CATEGORY RELEVANT TO THE DEPOSITION, DESCRIBED WITH REASONABLE PARTICULARITY].\n2. [ADDITIONAL DISTINCT CATEGORY AND TIME LIMITS].\n3. [ADDITIONAL CATEGORY IF NEEDED; OMIT UNUSED ITEMS].\nFor each request, state the production position and any specific objection, including whether responsive material is being withheld on that basis. Produce unobjectionable portions and describe claimed privileged material as required by Rule 4:1(b)(6).\nThis is a request to a party. Production from a nonparty requires the appropriate separate process.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Request to Confer on Discovery Dispute","slug":"meet-confer-idc","command":"/meet-confer-idc","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"LETTER","pages":1,"scope":"Use as counsel-to-counsel conferral correspondence. A local judicial conference can be requested only if the actual court offers it; follow that court’s process and avoid ex parte merits contact. This letter does not replace a motion, hearing notice or actual certification.","docx":"docx/meet-confer-idc.docx","reasoning":"../../reasoning/meet-confer-idc.md","path":"templates/discovery/meet-confer-idc.md","docx_path":"templates/discovery/docx/meet-confer-idc.docx","reasoning_path":"reasoning/meet-confer-idc.md","field_count":18,"md":"---\ntitle: \"Request to Confer on Discovery Dispute\"\nslug: \"meet-confer-idc\"\ncommand: \"/meet-confer-idc\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Use as counsel-to-counsel conferral correspondence. A local judicial conference can be requested only if the actual court offers it; follow that court’s process and avoid ex parte merits contact. This letter does not replace a motion, hearing notice or actual certification.\"\ndocx: \"docx/meet-confer-idc.docx\"\nreasoning: \"../../reasoning/meet-confer-idc.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\n[TELEPHONE AND EMAIL]\n[DATE]\n[RECIPIENT NAME AND TITLE]\n[RECIPIENT MAILING ADDRESS]\nRe: [CASE STYLE AND NUMBER] — discovery dispute\nDear [RECIPIENT]:\nWe request a conference concerning [DISCOVERY SET, DATE, REQUEST NUMBERS AND DISPUTED RESPONSES]. The specific deficiencies and requested resolution are [ITEMIZED ISSUES AND PROPOSED CORRECTIONS]. Relevant materials are [ACTUAL ENCLOSURES OR IDENTIFIED PRIOR SERVICE].\nOur prior efforts to resolve these issues were [ACTUAL DATES, PARTICIPANTS, METHODS AND RESULTS]. We propose [AVAILABLE DATES AND METHOD] for a substantive discussion. Please identify your position and availability by [REQUESTED DATE].\nIf the dispute remains unresolved, we propose seeking [SPECIFIC AVAILABLE COURT CONFERENCE OR MOTION PROCEDURE] under [VERIFIED LOCAL INSTRUCTION OR ORDER]. Please advise whether you agree and whether any issues can be narrowed. This is a request to counsel; it does not reserve a hearing or certify a conference that has not occurred.\nNo response, discovery or motion deadline is extended by this letter. Any agreed extension or court request will be documented separately. All affected counsel are copied: [NAMES AND CONTACT DETAILS].\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"},{"title":"Responses to Discovery","slug":"discovery-responses","command":"/discovery-responses","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":3,"scope":"Modular responses to actual served Virginia Circuit Court interrogatories, RFPs or RFAs; retain only requested modules.","docx":"docx/discovery-responses.docx","reasoning":"../../reasoning/discovery-responses.md","path":"templates/discovery/discovery-responses.md","docx_path":"templates/discovery/docx/discovery-responses.docx","reasoning_path":"reasoning/discovery-responses.md","field_count":28,"md":"---\ntitle: \"Responses to Discovery\"\nslug: \"discovery-responses\"\ncommand: \"/discovery-responses\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 3\nscope: \"Modular responses to actual served Virginia Circuit Court interrogatories, RFPs or RFAs; retain only requested modules.\"\ndocx: \"docx/discovery-responses.docx\"\nreasoning: \"../../reasoning/discovery-responses.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# RESPONSES TO DISCOVERY\n[RESPONDING PARTY] responds to [PROPOUNDING PARTY]'s [EXACT DISCOVERY TITLE AND SET], served on [DATE], as follows. Each request is reproduced in its original numbering.\n## Interrogatory responses\nInterrogatory No. [ORIGINAL NUMBER]: [EXACT SERVED QUESTION]\nAnswer: [SUPPORTED COMPLETE ANSWER; ANY SPECIFIC OBJECTION AND UNOBJECTED PORTION].\n## Responses to requests for production\nRequest No. [ORIGINAL NUMBER]: [EXACT SERVED REQUEST]\nResponse: [PRODUCTION OR INSPECTION POSITION, ACTUAL TIMING AND IDENTIFIERS; SPECIFIC OBJECTION AND WHETHER MATERIAL IS WITHHELD; RESPONSE TO UNOBJECTED PORTION].\n## Responses to requests for admission\nRequest No. [ORIGINAL NUMBER]: [EXACT SERVED REQUEST]\nResponse: [ADMIT; SPECIFIC DENIAL; QUALIFIED RESPONSE; OR PROPERLY EXPLAINED INABILITY AFTER ACTUAL REASONABLE INQUIRY].\n## Verification of interrogatory answers\nI, [ANSWERING PERSON AND CAPACITY], being duly sworn, state that the foregoing interrogatory answers are true and correct to the best of my knowledge and belief.\n____________________________\n[ANSWERING PERSON]\nSubscribed and sworn before me on [DATE] by [PERSON].\n____________________________\n[NOTARY NAME, REGISTRATION NUMBER AND COMMISSION EXPIRATION]\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Specific Objections and Responses to Discovery","slug":"objections","command":"/objections","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Request-specific objections with substantive unobjectioned responses; generated only against the actual complete served request set.","docx":"docx/objections.docx","reasoning":"../../reasoning/objections.md","path":"templates/discovery/objections.md","docx_path":"templates/discovery/docx/objections.docx","reasoning_path":"reasoning/objections.md","field_count":25,"md":"---\ntitle: \"Specific Objections and Responses to Discovery\"\nslug: \"objections\"\ncommand: \"/objections\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Request-specific objections with substantive unobjectioned responses; generated only against the actual complete served request set.\"\ndocx: \"docx/objections.docx\"\nreasoning: \"../../reasoning/objections.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# SPECIFIC OBJECTIONS AND RESPONSES TO DISCOVERY\n[RESPONDING PARTY] responds to [REQUESTING PARTY]’s [EXACT DISCOVERY TYPE, TITLE AND SET], served on [DATE], as follows. Each request is reproduced in its original wording and numbering.\n## Request and response\nRequest [ORIGINAL NUMBER]: [VERBATIM SERVED REQUEST].\nSpecific objection: [PRECISE GROUND, ACTUAL FACTS SUPPORTING IT AND THE PORTION AFFECTED; OMIT IF NO VALID OBJECTION].\nResponse to the unobjectionable portion: [COMPLETE SUPPORTED ANSWER OR PRODUCTION POSITION].\nFor a production request, material withheld because of the stated objection: [DESCRIBE THE SCOPE OF WITHHOLDING OR STATE ACCURATELY THAT NONE IS WITHHELD ON THAT BASIS].\nFor a privilege or protection claim: [EXPRESS CLAIM AND DESCRIPTION SUFFICIENT TO ASSESS IT WITHOUT REVEALING THE PROTECTED INFORMATION, WITH ACTUAL LOG REFERENCE IF USED].\n[REPEAT THIS STRUCTURE FOR EACH ACTUAL REQUEST; ADAPT THE RESPONSE TO INTERROGATORIES, PRODUCTION OR ADMISSIONS AS APPROPRIATE].\n## Completion\nThe responding party will amend or supplement as required by Rule 4:1(e). Any interrogatory answers must also include the answering person’s proper sworn verification; counsel’s signature on objections is not a substitute. No generic reservation creates an unasserted objection or excuses a response.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Stipulation for Physical or Mental Examination","slug":"ime-stipulation","command":"/ime-stipulation","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Actual party agreement defining examination conditions and report obligations.","docx":"docx/ime-stipulation.docx","reasoning":"../../reasoning/ime-stipulation.md","path":"templates/discovery/ime-stipulation.md","docx_path":"templates/discovery/docx/ime-stipulation.docx","reasoning_path":"reasoning/ime-stipulation.md","field_count":33,"md":"---\ntitle: \"Stipulation for Physical or Mental Examination\"\nslug: \"ime-stipulation\"\ncommand: \"/ime-stipulation\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Actual party agreement defining examination conditions and report obligations.\"\ndocx: \"docx/ime-stipulation.docx\"\nreasoning: \"../../reasoning/ime-stipulation.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# STIPULATION FOR PHYSICAL OR MENTAL EXAMINATION\nThe undersigned parties, through authorized counsel, stipulate to the following examination of [PERSON] concerning [CONDITION].\n## Examination terms\n1. The examiner is [NAME, PROFESSION, LICENSURE AND OFFICE]. Examination will occur at [PLACE] on [DATE AND TIME] for [EXPECTED DURATION].\n2. The permitted examination and tests are [SPECIFIC SCOPE]. Agreed limitations, observers, recording arrangements, breaks and accommodations are [PRECISE TERMS]. No procedure outside this scope is authorized by the stipulation.\n3. Materials to be supplied in advance are [DEFINED MATERIALS], by [DATE], through [SECURE METHOD]. Fees and cancellation arrangements are [ACTUAL AGREEMENT].\n## Report and use\n4. The examiner will provide [DETAILED REPORT CONTENT] by [DATE] to [RECIPIENTS], with filing handled as [ACTUAL RULE-COMPLIANT AGREEMENT OR ORDER]. The parties' agreement concerning Rule 4:10(c) is [EXPRESSLY STATE ANY VARIATION; OTHERWISE ITS TERMS APPLY].\n5. The agreement concerning privilege, later deposition and use of the report is [SPECIFIC LAWFUL TERMS]. No blanket waiver beyond the applicable rule or express agreement is implied.\n## Agreement\nThe above terms reflect actual agreement; any required court approval is [STATUS].\nCounsel signature: ____________________ for [PARTY]    Date: [DATE]\nCounsel signature: ____________________ for [PARTY]    Date: [DATE]\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Supplemental Expert Disclosure","slug":"expert-supp","command":"/expert-supp","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Supplement to an existing testifying-expert disclosure; source-grounded opinions and deadline compliance required.","docx":"docx/expert-supp.docx","reasoning":"../../reasoning/expert-supp.md","path":"templates/discovery/expert-supp.md","docx_path":"templates/discovery/docx/expert-supp.docx","reasoning_path":"reasoning/expert-supp.md","field_count":29,"md":"---\ntitle: \"Supplemental Expert Disclosure\"\nslug: \"expert-supp\"\ncommand: \"/expert-supp\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Supplement to an existing testifying-expert disclosure; source-grounded opinions and deadline compliance required.\"\ndocx: \"docx/expert-supp.docx\"\nreasoning: \"../../reasoning/expert-supp.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# SUPPLEMENTAL EXPERT DISCLOSURE\n[DISCLOSING PARTY] supplements the expert disclosure or discovery response identified as [DOCUMENT, REQUEST NUMBER AND DATE] concerning [EXPERT NAME AND CONTACT INFORMATION]. The governing scheduling order is [IDENTIFIER].\n## Scope of supplement\nThe prior disclosure is modified only as stated below. The additional or corrected information became available on [ACTUAL DATE AND SOURCE]. The reason for this supplement is [SUPPORTED CHANGE OR CORRECTION].\n## Opinions and supporting information\nSubject matter: [PRECISE SUBJECT].\nAdditional or corrected opinion: [ACTUAL OPINION THE EXPERT WILL OFFER].\nSubstance of supporting facts: [FACTS].\nSummary of grounds for the opinion: [REASONING OR METHODOLOGY ACTUALLY PROVIDED BY THE EXPERT].\nMaterials or changed assumptions supporting the supplement: [IDENTIFIED SOURCES].\n[REPEAT FOR EACH CHANGED OR ADDITIONAL OPINION; IDENTIFY WITHDRAWN OR REPLACED OPINIONS EXPRESSLY].\n## Procedural status\nThis disclosure is made under Rule 4:1(e) and [ACTUAL ORDER OR AUTHORITY]. Any required leave concerning a deadline or new subject is [ACTUAL STATUS]; service of a supplement does not itself grant that leave. Availability for appropriate follow-up discovery is [ACTUAL ARRANGEMENT].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Supplemental Interrogatories","slug":"supp-interrogatories","command":"/supp-interrogatories","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Additional targeted interrogatories within the cumulative Virginia limit; not an automatic reset of discovery.","docx":"docx/supp-interrogatories.docx","reasoning":"../../reasoning/supp-interrogatories.md","path":"templates/discovery/supp-interrogatories.md","docx_path":"templates/discovery/docx/supp-interrogatories.docx","reasoning_path":"reasoning/supp-interrogatories.md","field_count":31,"md":"---\ntitle: \"Supplemental Interrogatories\"\nslug: \"supp-interrogatories\"\ncommand: \"/supp-interrogatories\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Additional targeted interrogatories within the cumulative Virginia limit; not an automatic reset of discovery.\"\ndocx: \"docx/supp-interrogatories.docx\"\nreasoning: \"../../reasoning/supp-interrogatories.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# SUPPLEMENTAL INTERROGATORIES\n[PROPOUNDING PARTY] serves this additional set of interrogatories on [RESPONDING PARTY] under Rules 4:1 and 4:8.\n## Scope and response\nThe term [DEFINED TERM] means [NARROW DEFINITION]. The relevant period is [DATES]. The prior sets were served on [DATES], and these questions begin at Interrogatory No. [NEXT NUMBER]. The cumulative count, including parts and subparts, is [COUNT]; any leave authorizing more than thirty is [ACTUAL ORDER].\nPlease restate each interrogatory and answer separately and fully under oath. State specific objections and answer any unobjectionable portion. The applicable response date is [VERIFIED DATE UNDER RULE 4:8(d) AND ANY ORDER].\n## Interrogatory No. [NUMBER]\nIdentify [SPECIFIC PERSON, FACT OR CONTENTION] concerning [DEFINED NEW ISSUE OR DEVELOPMENT], including [ONLY NECESSARY IDENTIFYING INFORMATION].\n## Interrogatory No. [NUMBER]\nDescribe [SPECIFIC OCCURRENCE OR BASIS] arising from [NEWLY IDENTIFIED MATERIAL], and identify the supporting [WITNESSES OR RECORDS].\nThese requests address [IDENTIFIED GAP OR DEVELOPMENT] and do not require an unsupported re-creation of information already fully supplied in [SPECIFIC PRIOR RESPONSE].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Supplemental Requests for Admission","slug":"supp-rfa","command":"/supp-rfa","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Additional separately stated admissions with cumulative limits and document authenticity treated distinctly.","docx":"docx/supp-rfa.docx","reasoning":"../../reasoning/supp-rfa.md","path":"templates/discovery/supp-rfa.md","docx_path":"templates/discovery/docx/supp-rfa.docx","reasoning_path":"reasoning/supp-rfa.md","field_count":26,"md":"---\ntitle: \"Supplemental Requests for Admission\"\nslug: \"supp-rfa\"\ncommand: \"/supp-rfa\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Additional separately stated admissions with cumulative limits and document authenticity treated distinctly.\"\ndocx: \"docx/supp-rfa.docx\"\nreasoning: \"../../reasoning/supp-rfa.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# SUPPLEMENTAL REQUESTS FOR ADMISSION\n[PROPOUNDING PARTY] requests that [RESPONDING PARTY] admit the following matters for this action under Rule 4:11.\n## Response and set information\nThe previous sets were served on [DATES]. The cumulative number of requests, including parts and subparts, not relating to document genuineness is [COUNT]. Any agreement or leave permitting more than thirty such requests is [ACTUAL AGREEMENT OR ORDER].\nThe response date is [VERIFIED DATE UNDER RULE 4:11(a) AND ANY ORDER]. Please serve a signed written answer or objection to each matter. Copies of identified documents are [ACTUALLY ATTACHED OR PREVIOUSLY PROVIDED AT SPECIFIED LOCATION].\n## Request No. [NUMBER]\nAdmit that [SINGLE CASE-SUPPORTED FACT OR APPLICATION OF LAW TO FACT].\n## Request No. [NUMBER]\nAdmit that [SINGLE ADDITIONAL MATTER].\n## Request No. [NUMBER] concerning genuineness\nAdmit that the document identified as [EXACT EXHIBIT OR PRODUCTION ID] is a genuine [DOCUMENT DESCRIPTION]. This request addresses genuineness only unless additional matters are separately stated.\nThese matters concern [DEFINED NEW ISSUE OR IDENTIFIED DISPUTE]. A statement about what a deponent said is not substituted for an admission of the underlying fact.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Supplemental Requests for Production","slug":"supp-rfp","command":"/supp-rfp","category":"discovery","category_label":"Discovery","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Additional particularized party production requests tied to new issues or documents.","docx":"docx/supp-rfp.docx","reasoning":"../../reasoning/supp-rfp.md","path":"templates/discovery/supp-rfp.md","docx_path":"templates/discovery/docx/supp-rfp.docx","reasoning_path":"reasoning/supp-rfp.md","field_count":27,"md":"---\ntitle: \"Supplemental Requests for Production\"\nslug: \"supp-rfp\"\ncommand: \"/supp-rfp\"\ncategory: \"discovery\"\ncategory_label: \"Discovery\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Additional particularized party production requests tied to new issues or documents.\"\ndocx: \"docx/supp-rfp.docx\"\nreasoning: \"../../reasoning/supp-rfp.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# SUPPLEMENTAL REQUESTS FOR PRODUCTION\n[PROPOUNDING PARTY] requests production from [RESPONDING PARTY] under Rules 4:1 and 4:9.\n## Production arrangements\nPrior sets and production references are [DATES AND IDENTIFIERS]. This set begins at Request No. [NEXT NUMBER] and concerns [DEFINED NEW MATERIAL OR PERIOD].\nPlease serve written responses and produce responsive nonprivileged material at [REASONABLE PLACE OR SECURE METHOD] by [VERIFIED RESPONSE AND PRODUCTION DATE]. The requested electronic form is [REASONABLY USABLE FORMAT]. Identify any objection with specificity, state whether responsive material is withheld, and produce the unobjectionable portion.\n## Request No. [NUMBER]\nProduce [REASONABLY PARTICULAR DOCUMENT CATEGORY] relating to [DEFINED EVENT, ISSUE, CUSTODIAN AND DATE RANGE].\n## Request No. [NUMBER]\nProduce [SPECIFIC DOCUMENT OR MATERIAL IDENTIFIED BY A RECENT RESPONSE], including [RELEVANT ATTACHMENTS OR METADATA, IF JUSTIFIED].\nIf an identical item has already been produced, identify its prior production reference instead of producing a duplicate, subject to [ACTUAL AGREEMENT OR APPLICABLE ORDER]. Any inaccessible ESI or privilege claim should be addressed under the applicable rule and an appropriate description.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Declaration Under Penalty of Perjury","slug":"declaration","command":"/declaration","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":1,"scope":"Virginia civil declaration where § 8.01-4.3 permits an unsworn substitute; not a deposition or an oath subject to a statutory exception.","docx":"docx/declaration.docx","reasoning":"../../reasoning/declaration.md","path":"templates/motions/declaration.md","docx_path":"templates/motions/docx/declaration.docx","reasoning_path":"reasoning/declaration.md","field_count":13,"md":"---\ntitle: \"Declaration Under Penalty of Perjury\"\nslug: \"declaration\"\ncommand: \"/declaration\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 1\nscope: \"Virginia civil declaration where § 8.01-4.3 permits an unsworn substitute; not a deposition or an oath subject to a statutory exception.\"\ndocx: \"docx/declaration.docx\"\nreasoning: \"../../reasoning/declaration.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# DECLARATION OF [DECLARANT NAME]\nI, [DECLARANT NAME], state:\n1. I am [IDENTITY AND RELEVANT CAPACITY]. I have personal knowledge of the facts stated below through [BASIS OF KNOWLEDGE].\n2. This declaration concerns [IDENTIFIED MOTION, CLAIM OR ISSUE].\n3. [FIRST MATERIAL FACT, INCLUDING RELEVANT DATE AND SOURCE OF PERSONAL KNOWLEDGE].\n4. [ADDITIONAL MATERIAL FACTS, IN SEPARATELY NUMBERED PARAGRAPHS].\n5. [IDENTIFY EACH ACTUAL ATTACHMENT AND THE FACTUAL BASIS FOR AUTHENTICATING IT, IF APPLICABLE].\nI declare under penalty of perjury that the foregoing is true and correct.\nExecuted on [ACTUAL DATE] at [CITY, STATE / COUNTRY].\n____________________________\n[DECLARANT NAME]\n"},{"title":"Emergency Motion for Temporary Restraining Order","slug":"exparte","command":"/exparte","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Rule 3:26 application; without-notice relief only upon the required sworn showing and written certification.","docx":"docx/exparte.docx","reasoning":"../../reasoning/exparte.md","path":"templates/motions/exparte.md","docx_path":"templates/motions/docx/exparte.docx","reasoning_path":"reasoning/exparte.md","field_count":29,"md":"---\ntitle: \"Emergency Motion for Temporary Restraining Order\"\nslug: \"exparte\"\ncommand: \"/exparte\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Rule 3:26 application; without-notice relief only upon the required sworn showing and written certification.\"\ndocx: \"docx/exparte.docx\"\nreasoning: \"../../reasoning/exparte.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# EMERGENCY MOTION FOR TEMPORARY RESTRAINING ORDER\n[MOVANT] requests a temporary restraining order preserving [PRECISE STATUS QUO] until [PROPOSED SHORT EXPIRATION AND HEARING].\n1. The underlying claim and jurisdictional basis are [IDENTIFY]. [STATE WHETHER A SPECIFIC STATUTE SUPPLIES DIFFERENT CRITERIA].\n2. The immediate threatened act is [ACT, PERSON, TIME AND PLACE]. Specific facts in [VERIFIED COMPLAINT, AFFIDAVIT OR SWORN TESTIMONY] establish [IRREPARABLE HARM THAT WOULD OCCUR BEFORE THE OTHER PARTY CAN BE HEARD].\n3. Notice has been addressed in the certification below. [EXPLAIN WHY THE EQUITIES WARRANT BRIEF INTERIM RELIEF].\n4. The requested restraint is [EXACT CONDUCT AND PERSONS COVERED]. The proposed preliminary-injunction hearing is [DATE / SETTING REQUEST]. The proposed bond and statutory basis are [AMOUNT AND AUTHORITY OR SUPPORTED EXCEPTION].\n## Written notice certification\n[MOVANT OR COUNSEL] certifies that [ACTUAL EFFORTS TO PROVIDE WRITTEN OR ORAL NOTICE, RECIPIENTS, DATES, TIMES AND RESULTS]. [IF NOTICE IS OMITTED, STATE SPECIFIC REASONS IT SHOULD NOT BE REQUIRED].\nWHEREFORE, Movant requests the narrowly stated temporary relief, a fixed expiration, and prompt further hearing.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Memorandum in Opposition to Motion","slug":"opposition","command":"/opposition","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Opposition to an identified Virginia Circuit Court motion; the legal standard depends on the motion.","docx":"docx/opposition.docx","reasoning":"../../reasoning/opposition.md","path":"templates/motions/opposition.md","docx_path":"templates/motions/docx/opposition.docx","reasoning_path":"reasoning/opposition.md","field_count":25,"md":"---\ntitle: \"Memorandum in Opposition to Motion\"\nslug: \"opposition\"\ncommand: \"/opposition\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Opposition to an identified Virginia Circuit Court motion; the legal standard depends on the motion.\"\ndocx: \"docx/opposition.docx\"\nreasoning: \"../../reasoning/opposition.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MEMORANDUM IN OPPOSITION TO MOTION\n[RESPONDING PARTY] opposes [EXACT MOTION AND FILING DATE] and requests [DENIAL OR PRECISE LIMITED DISPOSITION]. The hearing or briefing schedule is [ACTUAL COURT-SET OR AUTHORIZED SCHEDULE].\n## Issue presented\n[STATE THE QUESTION THE MOTION ACTUALLY RAISES AND THE REQUESTED RESULT].\n## Relevant record\n[SET OUT MATERIAL FACTS OR PROCEDURAL EVENTS WITH RECORD REFERENCES]. Distinguish facts admitted for the particular motion from disputed evidence and matters outside the proper record.\n## Argument\n[IDENTIFY THE CONTROLLING STANDARD AND WHICH PARTY BEARS THE APPLICABLE BURDEN].\n[ADDRESS EACH MATERIAL GROUND RAISED BY THE MOVANT USING VERIFIED AUTHORITIES AND RECORD SUPPORT].\n[ADDRESS ANY ALTERNATIVE RELIEF OR PROCEDURAL OBJECTION ACTUALLY AVAILABLE, INCLUDING WHY IT MATTERS].\n## Conclusion\nFor these reasons, the Court should [PRECISE DISPOSITION]. Materials submitted with this memorandum are [ACTUAL EXHIBITS OR NONE].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion for Default Judgment","slug":"default-judgment","command":"/default-judgment","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Circuit Court Rule 3:19 default judgment; no automatic clerk entry or assumed damages.","docx":"docx/default-judgment.docx","reasoning":"../../reasoning/default-judgment.md","path":"templates/motions/default-judgment.md","docx_path":"templates/motions/docx/default-judgment.docx","reasoning_path":"reasoning/default-judgment.md","field_count":32,"md":"---\ntitle: \"Motion for Default Judgment\"\nslug: \"default-judgment\"\ncommand: \"/default-judgment\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Circuit Court Rule 3:19 default judgment; no automatic clerk entry or assumed damages.\"\ndocx: \"docx/default-judgment.docx\"\nreasoning: \"../../reasoning/default-judgment.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION FOR DEFAULT JUDGMENT\n[PLAINTIFF] moves for default judgment against [DEFAULTING DEFENDANT] under Rule 3:19.\n## Service, default and notice\n1. The complaint and summons were served on [DATE] by [AUTHORIZED METHOD]. The filed return is [REFERENCE]. The response deadline was [DATE AND COMPUTATION]; [IDENTIFY EXTENSIONS AND ACTUAL DOCKET STATUS].\n2. Plaintiff provided written notice of this motion by mail to [DEFENDANT’S VERIFIED LAST KNOWN OR PROCESS ADDRESS] on [ACTUAL DATE]. [IF AN ADDRESS COULD NOT BE ASCERTAINED, SUPPLY THE RULE 3:19(c)(1) CERTIFICATION OF REASONABLE GOOD-FAITH EFFORTS].\n3. [ESTABLISH ANY POSTED-SERVICE MAILING AND WAITING REQUIREMENTS]. The military-status affidavit or declaration and supporting inquiry are [REFERENCE AND RESULT]; [ADDRESS REQUIRED COUNSEL, BOND OR STAY UNDER THE SCRA IF APPLICABLE].\n## Basis and relief\n4. [IDENTIFY THE WELL-PLEADED CLAIM, LIABILITY FACTS AND RELIEF WITHIN THE COMPLAINT]. The requested damages are [AMOUNT / CATEGORIES], supported by [ADMISSIBLE EVIDENCE AND CALCULATION].\n5. [FOR UNLIQUIDATED DAMAGES, REQUEST THE NECESSARY EVIDENTIARY HEARING AND STATE PLAINTIFF’S JURY-DEMAND STATUS]. Requested interest, costs and fees are [AMOUNTS AND SEPARATE LEGAL BASES].\nWHEREFORE, Plaintiff requests [SPECIFIC JUDGMENT OR DAMAGES HEARING], subject to the required findings and protections.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion for Reconsideration","slug":"reconsider","command":"/reconsider","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Request for a specific reconsidered ruling within the trial court’s actual remaining jurisdiction.","docx":"docx/reconsider.docx","reasoning":"../../reasoning/reconsider.md","path":"templates/motions/reconsider.md","docx_path":"templates/motions/docx/reconsider.docx","reasoning_path":"reasoning/reconsider.md","field_count":27,"md":"---\ntitle: \"Motion for Reconsideration\"\nslug: \"reconsider\"\ncommand: \"/reconsider\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Request for a specific reconsidered ruling within the trial court’s actual remaining jurisdiction.\"\ndocx: \"docx/reconsider.docx\"\nreasoning: \"../../reasoning/reconsider.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION FOR RECONSIDERATION\n[MOVANT] requests reconsideration of [EXACT RULING OR ORDER] entered on [DATE].\n## Jurisdiction and timing\n1. The order is [FINAL OR INTERLOCUTORY, WITH BASIS]. The Court retains authority to act because [RULE 1:1 PERIOD, ACTUAL SUSPENSION ORDER OR OTHER SPECIFIC AUTHORITY].\n2. Any notice of appeal, interlocutory appeal or transfer of jurisdiction is [ACTUAL STATUS AND EFFECT UNDER RULE 1:1B OR 1:1C].\n## Ground for reconsideration\n3. The specific error or material matter warranting reconsideration is [IDENTIFIED LEGAL OR FACTUAL ISSUE], supported by [PRECISE RECORD AND VERIFIED AUTHORITY].\n4. The matter was [PREVIOUSLY PRESENTED OR NEWLY RAISED], and the basis for considering it at this stage is [SUPPORTED EXPLANATION]. The opposing position is [POSITION AND RESPONSE].\n## Relief requested\nMovant requests [EXACT MODIFICATION, VACATUR OR OTHER RULING]. If needed to preserve jurisdiction, movant separately requests entry of a lawful suspension or other appropriate order before [VERIFIED DEADLINE]. Filing this motion or setting a hearing does not itself suspend a final judgment or extend an appeal deadline.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion for Relief from Default","slug":"set-aside-default","command":"/set-aside-default","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia civil relief from default; select the procedural stage and its governing standard.","docx":"docx/set-aside-default.docx","reasoning":"../../reasoning/set-aside-default.md","path":"templates/motions/set-aside-default.md","docx_path":"templates/motions/docx/set-aside-default.docx","reasoning_path":"reasoning/set-aside-default.md","field_count":29,"md":"---\ntitle: \"Motion for Relief from Default\"\nslug: \"set-aside-default\"\ncommand: \"/set-aside-default\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia civil relief from default; select the procedural stage and its governing standard.\"\ndocx: \"docx/set-aside-default.docx\"\nreasoning: \"../../reasoning/set-aside-default.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION FOR RELIEF FROM DEFAULT\n[MOVANT] requests [LEAVE TO FILE A LATE RESPONSIVE PLEADING / RELIEF FROM THE IDENTIFIED DEFAULT JUDGMENT].\n1. The procedural stage is [DEFAULT WITHOUT JUDGMENT / JUDGMENT ENTERED ON DATE]. Service and actual notice occurred as follows: [SUPPORTED CHRONOLOGY].\n2. The Court has authority under [RULE 3:19(b) BEFORE JUDGMENT; RULE 3:19(d)(1) WITHIN RULE 1:1; OR SPECIFIC POST-JURISDICTION STATUTE]. [ESTABLISH THE APPLICABLE DEADLINE AND ANY ENTERED SUSPENSION ORDER].\n3. [BEFORE JUDGMENT: ESTABLISH GOOD CAUSE]. [WITHIN RULE 1:1: ADDRESS EXTENT AND CAUSE OF DELAY, ACTUAL NOTICE AND SERVICE, AND PREJUDICE TO PLAINTIFF]. Supporting evidence is [ACTUAL DECLARATION / EXHIBITS].\n4. [AFTER EXPIRATION OF RULE 1:1: IDENTIFY THE PRECISE AUTHORIZED GROUND AND PROVE EACH ELEMENT, INCLUDING TIMELINESS]. A general assertion of excusable neglect is not substituted for a statutory ground.\n5. The proposed defense and requested responsive pleading are [SUBSTANCE AND ATTACHMENT]. The requested terms to address prejudice are [TERMS, IF APPROPRIATE].\nWHEREFORE, Movant requests [PRECISE RELIEF] and leave to file [IDENTIFIED PLEADING] by [DATE].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion for Separate Trials","slug":"bifurcate","command":"/bifurcate","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Circuit Court discretionary separation of claims or issues under § 8.01-281(B).","docx":"docx/bifurcate.docx","reasoning":"../../reasoning/bifurcate.md","path":"templates/motions/bifurcate.md","docx_path":"templates/motions/docx/bifurcate.docx","reasoning_path":"reasoning/bifurcate.md","field_count":24,"md":"---\ntitle: \"Motion for Separate Trials\"\nslug: \"bifurcate\"\ncommand: \"/bifurcate\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Circuit Court discretionary separation of claims or issues under § 8.01-281(B).\"\ndocx: \"docx/bifurcate.docx\"\nreasoning: \"../../reasoning/bifurcate.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION FOR SEPARATE TRIALS\n[MOVANT] requests separate trials of [CLAIMS OR ISSUES] under Virginia Code § 8.01-281(B).\n1. The issues proposed for separate determination are [DEFINE EACH PHASE AND ITS SEQUENCE]. The remaining issues are [IDENTIFY].\n2. A combined trial would create [SPECIFIC PREJUDICE, CONFUSION OR OTHER SUPPORTED PROBLEM]. The evidence affected is [IDENTIFY]; [EXPLAIN WHY INSTRUCTIONS OR OTHER LESS DISRUPTIVE MEASURES ARE INSUFFICIENT].\n3. The proposal affects witnesses, repeated proof, expense, delay and judicial resources as follows: [CONCRETE COMPARISON]. Relevant guidance includes Allstate Insurance Co. v. Wade, 265 Va. 383, 392–93 (2003).\n4. The requested procedure preserves [JURY RIGHTS, COMMON FACT DETERMINATIONS AND EACH PARTY’S OPPORTUNITY TO PRESENT EVIDENCE]. Proposed dates and effects on existing orders are [DETAILS].\nWHEREFORE, Movant requests [EXACT PHASES, JURY ARRANGEMENT AND SCHEDULING TERMS].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion for Summary Judgment","slug":"msj","command":"/msj","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Rule 3:20 motion confined to a properly supported undisputed claim or issue.","docx":"docx/msj.docx","reasoning":"../../reasoning/msj.md","path":"templates/motions/msj.md","docx_path":"templates/motions/docx/msj.docx","reasoning_path":"reasoning/msj.md","field_count":27,"md":"---\ntitle: \"Motion for Summary Judgment\"\nslug: \"msj\"\ncommand: \"/msj\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Rule 3:20 motion confined to a properly supported undisputed claim or issue.\"\ndocx: \"docx/msj.docx\"\nreasoning: \"../../reasoning/msj.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION FOR SUMMARY JUDGMENT\n[MOVANT] requests summary judgment on [SPECIFIC CLAIM OR ISSUE] under Rule 3:20.\n## Posture and permitted record\n1. The parties are at issue as to [CLAIM], and the relevant pleadings and orders are [IDENTIFY].\n2. The record relied on consists of [SPECIFIC PLEADINGS, ADMISSIONS, PRETRIAL ORDERS OR OTHER LAWFULLY USABLE MATERIAL], with precise references.\n3. [IF DISCOVERY DEPOSITIONS ARE RELIED ON, IDENTIFY ALL-PARTY AGREEMENT OR THE EXACT APPLICABLE § 8.01-420 EXCEPTION; OTHERWISE EXCLUDE THEM AS A BASIS]. Any affidavit use must have an applicable legal basis.\n## Material facts and law\n4. [STATE EACH MATERIAL UNDISPUTED FACT WITH ITS PERMITTED RECORD SOURCE].\n5. The governing elements and legal standard are [VERIFIED VIRGINIA AUTHORITIES]. Applied to those facts, [EXPLAIN WHY JUDGMENT FOLLOWS WITHOUT RESOLVING A GENUINE MATERIAL FACT DISPUTE].\n6. The opposing position is [ACCURATE DESCRIPTION], and it does not create a material factual dispute because [SUPPORTED ANALYSIS].\n## Relief requested\nMovant requests [EXACT JUDGMENT OR PARTIAL DETERMINATION]. The claims, issues or damages left for trial are [IDENTIFY OR NONE].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion for Voluntary Nonsuit","slug":"nonsuit","command":"/nonsuit","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Circuit Court civil personal-injury litigation.","docx":"docx/nonsuit.docx","reasoning":"../../reasoning/nonsuit.md","path":"templates/motions/nonsuit.md","docx_path":"templates/motions/docx/nonsuit.docx","reasoning_path":"reasoning/nonsuit.md","field_count":27,"md":"---\ntitle: \"Motion for Voluntary Nonsuit\"\nslug: \"nonsuit\"\ncommand: \"/nonsuit\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Circuit Court civil personal-injury litigation.\"\ndocx: \"docx/nonsuit.docx\"\nreasoning: \"../../reasoning/nonsuit.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION FOR VOLUNTARY NONSUIT\n[MOVANT] requests a voluntary nonsuit without prejudice under Virginia Code section 8.01-380 as to [EXACT CLAIMS AND PARTIES].\n1. The action is at [ACTUAL PROCEDURAL STAGE]. [STATE FACTS ADDRESSING THE STATUTORY CUTOFFS IN SUBSECTION A].\n2. Prior nonsuits of these claims or against these parties are [NONE IF VERIFIED, OR COMPLETE DATES, COURTS AND DETAILS]. The basis for the requested nonsuit is [FIRST NONSUIT OF RIGHT, STIPULATION OR REQUEST FOR ADDITIONAL NONSUIT].\n3. Pending counterclaims, crossclaims or third-party claims arising from the same transaction are [ACTUAL STATUS]. [IDENTIFY REQUIRED CONSENT OR BASIS FOR INDEPENDENT ADJUDICATION].\n4. Trial is set for [DATE OR NOT SET], and notice of this request was given on [DATE]. [ADDRESS ANY APPLICABLE COST ISSUE].\nWHEREFORE, Movant requests entry of a nonsuit order limited to the claims and parties identified above, with [ACCURATE TREATMENT OF REMAINING CLAIMS AND ANY COST DETERMINATION].\n## Good-faith certification\nCounsel certifies the following effort concerning resolution and presentation: [ACTUAL CONFERRAL OR ATTEMPT AND RESULT].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion to Consolidate Related Actions","slug":"consolidate","command":"/consolidate","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Circuit Court related actions pending in the same court; additional statutory findings required for Multiple Claimant Litigation Act use.","docx":"docx/consolidate.docx","reasoning":"../../reasoning/consolidate.md","path":"templates/motions/consolidate.md","docx_path":"templates/motions/docx/consolidate.docx","reasoning_path":"reasoning/consolidate.md","field_count":25,"md":"---\ntitle: \"Motion to Consolidate Related Actions\"\nslug: \"consolidate\"\ncommand: \"/consolidate\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Circuit Court related actions pending in the same court; additional statutory findings required for Multiple Claimant Litigation Act use.\"\ndocx: \"docx/consolidate.docx\"\nreasoning: \"../../reasoning/consolidate.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION TO CONSOLIDATE RELATED ACTIONS\n[MOVANT] requests consolidation of [CASE NAMES AND NUMBERS] for [SPECIFIED DISCOVERY, HEARINGS OR TRIAL].\n1. The actions are pending in this Court and involve [PARTIES, CLAIMS AND COMMON TRANSACTION / QUESTIONS]. The relevant pleadings and current schedules are [IDENTIFY].\n2. Consolidation would avoid [SPECIFIC DUPLICATE EVIDENCE, WITNESSES, EXPENSE AND DELAY]. Separate issues and potential prejudice are [IDENTIFY], addressed by [LIMITING INSTRUCTIONS, SEPARATE VERDICTS OR OTHER SAFEGUARDS].\n3. The legal basis is [VERIFIED VIRGINIA AUTHORITY APPLICABLE TO THESE ACTIONS]. [IF RELYING ON §§ 8.01-267.1 AND 8.01-267.3, ESTABLISH SIX OR MORE PLAINTIFFS AND EACH STATUTORY PREDOMINANCE, FAIRNESS AND DUE-PROCESS FINDING].\n4. The proposed scope preserves distinct claims, defenses, burdens, jury rights and appealable dispositions as applicable. The requested lead case, filing procedure and coordinated dates are [DETAILS]. All affected parties’ positions are [ACTUAL POSITIONS].\nWHEREFORE, Movant requests consolidation solely to the extent and on the terms stated above.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion to Continue Trial","slug":"continuance","command":"/continuance","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Circuit Court civil personal-injury litigation.","docx":"docx/continuance.docx","reasoning":"../../reasoning/continuance.md","path":"templates/motions/continuance.md","docx_path":"templates/motions/docx/continuance.docx","reasoning_path":"reasoning/continuance.md","field_count":26,"md":"---\ntitle: \"Motion to Continue Trial\"\nslug: \"continuance\"\ncommand: \"/continuance\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Circuit Court civil personal-injury litigation.\"\ndocx: \"docx/continuance.docx\"\nreasoning: \"../../reasoning/continuance.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION TO CONTINUE TRIAL\n[MOVANT] requests that the trial set for [CURRENT DATE] be continued to [PROPOSED DATE OR SETTING PROCEDURE].\n## Basis for the request\n1. Trial is currently set by [ORDER OR DOCKET ENTRY, WITH DATE]. [IDENTIFY OTHER AFFECTED DATES].\n2. The specific circumstances requiring a continuance are [SUPPORTED FACTS]. Movant has taken [ACTUAL DILIGENT STEPS] to avoid the need for a continuance.\n3. Prior continuances or related requests are [ACCURATE HISTORY]. The effect on the parties, witnesses and court is [SUPPORTED DESCRIPTION].\n4. Opposing counsel's position and available dates are [ACTUAL INFORMATION].\n## Requested scheduling relief\nMovant requests [PRECISE TRIAL RESET AND EACH NECESSARY RELATED DEADLINE CHANGE]. All other scheduling terms would remain as ordered unless the Court directs otherwise.\n## Good-faith certification\nCounsel certifies the following effort to resolve the request and coordinate presentation: [ACTUAL CONFERRAL OR ATTEMPT AND RESULT].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion to Exclude or Limit Expert Testimony","slug":"daubert","command":"/daubert","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia expert-admissibility motion under state evidence law; the legacy command name does not supply a federal standard.","docx":"docx/daubert.docx","reasoning":"../../reasoning/daubert.md","path":"templates/motions/daubert.md","docx_path":"templates/motions/docx/daubert.docx","reasoning_path":"reasoning/daubert.md","field_count":30,"md":"---\ntitle: \"Motion to Exclude or Limit Expert Testimony\"\nslug: \"daubert\"\ncommand: \"/daubert\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia expert-admissibility motion under state evidence law; the legacy command name does not supply a federal standard.\"\ndocx: \"docx/daubert.docx\"\nreasoning: \"../../reasoning/daubert.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION TO EXCLUDE OR LIMIT EXPERT TESTIMONY\n[MOVANT] requests exclusion or limitation of [EXPERT'S NAME] testimony concerning [PRECISE OPINION].\n## Proposed opinion and record\n1. The challenged opinion is [EXACT OPINION WITH REPORT OR DEPOSITION REFERENCE]. The witness's stated qualifications, relied-on facts and method are [ACCURATE DESCRIPTION].\n2. The specific defect is [LACK OF RELEVANT QUALIFICATION, SPECULATIVE BASIS, IMPERMISSIBLE LEGAL CONCLUSION OR OTHER SUPPORTED GROUND].\n## Virginia admissibility grounds\n3. Under [APPLICABLE VIRGINIA RULES, STATUTES AND VERIFIED DECISIONS], [STATE THE GOVERNING STANDARD]. Explain how the identified defect affects admissibility rather than merely weight: [ANALYSIS].\n4. [ADDRESS THE ACTUAL FOUNDATION, THE USE OF DATA NORMALLY RELIED ON IN THE FIELD AND ANY CASE-SPECIFIC STATUTORY QUALIFICATION RULE].\n5. The opposing position is [POSITION]; the requested ruling should be [PRECISE LIMIT] because [SUPPORTED RESPONSE].\n## Relief requested\nMovant requests [EXCLUSION OF DEFINED OPINION, LIMITED SCOPE OR FOUNDATION HEARING], with [SPECIFIC TRIAL PROCEDURE]. Any separate disclosure or scheduling violation and remedy are [IDENTIFIED BASIS OR NONE].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion to Extend Time to File Responsive Pleading","slug":"extension","command":"/extension","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Circuit Court extension of responsive-pleading time under Rule 1:9; not an appeal or venue deadline.","docx":"docx/extension.docx","reasoning":"../../reasoning/extension.md","path":"templates/motions/extension.md","docx_path":"templates/motions/docx/extension.docx","reasoning_path":"reasoning/extension.md","field_count":25,"md":"---\ntitle: \"Motion to Extend Time to File Responsive Pleading\"\nslug: \"extension\"\ncommand: \"/extension\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Circuit Court extension of responsive-pleading time under Rule 1:9; not an appeal or venue deadline.\"\ndocx: \"docx/extension.docx\"\nreasoning: \"../../reasoning/extension.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION TO EXTEND TIME TO FILE RESPONSIVE PLEADING\n[MOVANT] requests an extension under Rule 1:9 to file [IDENTIFIED RESPONSIVE PLEADING].\n1. The pleading to be answered was served on [DATE] by [METHOD]. The existing response deadline is [DATE], based on [RULE, SERVICE COMPUTATION OR ORDER].\n2. Movant requests an extension through [REQUESTED DATE] because [SPECIFIC REASONS AND DILIGENCE].\n3. [STATE PRIOR EXTENSIONS AND ANY EXPIRATION OR DEFAULT STATUS ACCURATELY].\n4. The effect on other deadlines and parties is [SUPPORTED DESCRIPTION]. Opposing counsel's position is [ACTUAL POSITION OR NO RESPONSE].\nWHEREFORE, Movant requests an order extending the stated pleading deadline to [DATE].\n## Good-faith certification\nCounsel certifies the following effort to resolve the request and coordinate presentation: [ACTUAL CONFERRAL OR ATTEMPT AND RESULT].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion to Quash Defective Process or Service","slug":"quash-service","command":"/quash-service","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Timely Virginia objection to an identified defect under § 8.01-277(A).","docx":"docx/quash-service.docx","reasoning":"../../reasoning/quash-service.md","path":"templates/motions/quash-service.md","docx_path":"templates/motions/docx/quash-service.docx","reasoning_path":"reasoning/quash-service.md","field_count":26,"md":"---\ntitle: \"Motion to Quash Defective Process or Service\"\nslug: \"quash-service\"\ncommand: \"/quash-service\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Timely Virginia objection to an identified defect under § 8.01-277(A).\"\ndocx: \"docx/quash-service.docx\"\nreasoning: \"../../reasoning/quash-service.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION TO QUASH DEFECTIVE PROCESS OR SERVICE\n[MOVANT] moves to quash [IDENTIFIED PROCESS, SERVICE OR RETURN] under Virginia Code § 8.01-277(A).\n## Service history and preservation\n1. The summons and complaint concern [PARTY AND FILING]. The challenged issuance, attempted service and return occurred on [ACTUAL DATES AND METHODS].\n2. This motion is filed [BEFORE OR SIMULTANEOUSLY WITH ANY PLEADING TO THE MERITS]. The relevant appearance and participation history is [FACTS SUPPORTING PRESERVATION OF THE OBJECTION].\n## Defect and supporting record\n3. The required procedure under [APPLICABLE SERVICE STATUTE OR RULE] was not satisfied because [PRECISE FACTS]. The supporting record is [RETURN, AFFIDAVIT OR OTHER ADMISSIBLE MATERIAL].\n4. [ADDRESS ACTUAL NOTICE, ANY ASSERTED CURE OR WAIVER, AND THE OPPOSING PARTY'S KNOWN POSITION UNDER THE APPLICABLE LAW].\n## Relief requested\nMovant requests that the Court [QUASH THE IDENTIFIED PROCESS, STRIKE THE PROOF OF SERVICE OR OTHER AUTHORIZED RELIEF]. This motion does not seek adjudication of the merits. Any request based on untimely service, personal jurisdiction or another separate ground is [IDENTIFIED SEPARATE BASIS, IF ACTUALLY ASSERTED].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion to Transfer Venue","slug":"venue-transfer","command":"/venue-transfer","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia venue transfer with the chosen statutory basis and destination made explicit.","docx":"docx/venue-transfer.docx","reasoning":"../../reasoning/venue-transfer.md","path":"templates/motions/venue-transfer.md","docx_path":"templates/motions/docx/venue-transfer.docx","reasoning_path":"reasoning/venue-transfer.md","field_count":29,"md":"---\ntitle: \"Motion to Transfer Venue\"\nslug: \"venue-transfer\"\ncommand: \"/venue-transfer\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia venue transfer with the chosen statutory basis and destination made explicit.\"\ndocx: \"docx/venue-transfer.docx\"\nreasoning: \"../../reasoning/venue-transfer.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION TO TRANSFER VENUE\n[MOVANT] requests transfer of this action to the Circuit Court of [DESTINATION]. The basis is [IMPROPER VENUE UNDER § 8.01-264 OR GOOD-CAUSE TRANSFER UNDER § 8.01-265].\n## Relevant facts\n1. The parties, residences or business contacts, occurrence location and other venue facts are [SUPPORTED FACTS].\n2. Process was served on [DATE], and the operative response/extension deadline is [DATE AND ORDER]. This objection is timely because [ACTUAL BASIS].\n## Statutory basis\n3. Venue is properly laid in [DESTINATION] under [SPECIFIC CATEGORY A OR B PROVISION AND SUPPORTING FACTS]. The current forum is [IMPROPER FOR THE STATED REASONS OR A PROPER FORUM FROM WHICH GOOD-CAUSE TRANSFER IS REQUESTED].\n4. If good cause is relied on, the relevant witness locations, inconvenience and other supporting circumstances are [SPECIFIC FACTS]. Any applicable preferred-venue restriction is [ANALYSIS].\n5. [ADDRESS THE OPPOSING POSITION AND SUPPORTING DECLARATIONS OR OTHER PROOF].\n## Relief requested\nMovant requests transfer to [COURT], with [SPECIFIC RECORD-TRANSFER AND SCHEDULING TERMS]. No dismissal solely for improper venue is requested where a proper Virginia forum exists. Any costs request is limited to [SEPARATELY VERIFIED AUTHORITY AND SUPPORTED AMOUNT].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Notice of Motion Hearing","slug":"motion-notice","command":"/motion-notice","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Circuit Court civil motion notice; use the locality’s required praecipe instead where applicable.","docx":"docx/motion-notice.docx","reasoning":"../../reasoning/motion-notice.md","path":"templates/motions/motion-notice.md","docx_path":"templates/motions/docx/motion-notice.docx","reasoning_path":"reasoning/motion-notice.md","field_count":27,"md":"---\ntitle: \"Notice of Motion Hearing\"\nslug: \"motion-notice\"\ncommand: \"/motion-notice\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Circuit Court civil motion notice; use the locality’s required praecipe instead where applicable.\"\ndocx: \"docx/motion-notice.docx\"\nreasoning: \"../../reasoning/motion-notice.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# NOTICE OF MOTION HEARING\n[MOVANT] gives notice that [EXACT MOTION TITLE] will be presented on [CONFIRMED DATE] at [TIME AND TIME ZONE] before [COURT / JUDGE / DOCKET], at [COURTROOM ADDRESS OR AUTHORIZED REMOTE ACCESS].\nThe requested hearing length is [ESTIMATE], and the purpose of the motion is [CONCISE DESCRIPTION]. The motion was or will be filed on [ACTUAL OR PLANNED DATE]. [IDENTIFY ANY BRIEF AND APPLICABLE NOTICE / BRIEFING SCHEDULE].\nThe setting was obtained through [COURT’S MOTIONS DAY OR AUTHORIZED SCHEDULING PERSONNEL / PROCEDURE]. [IDENTIFY ANY LEAVE FOR SHORTENED NOTICE OR OTHER ORDER].\n## Good-faith certification\nCounsel certifies that [ACTUAL CONFERENCE OR ATTEMPT, DATES, PARTICIPANTS AND RESULT] was undertaken in good faith to resolve the matter and determine a mutually agreeable hearing date and time.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Proposed Consent Order","slug":"consent","command":"/consent","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Consent order based on actual agreement by all persons whose consent is represented.","docx":"docx/consent.docx","reasoning":"../../reasoning/consent.md","path":"templates/motions/consent.md","docx_path":"templates/motions/docx/consent.docx","reasoning_path":"reasoning/consent.md","field_count":16,"md":"---\ntitle: \"Proposed Consent Order\"\nslug: \"consent\"\ncommand: \"/consent\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Consent order based on actual agreement by all persons whose consent is represented.\"\ndocx: \"docx/consent.docx\"\nreasoning: \"../../reasoning/consent.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PROPOSED CONSENT ORDER\nThe parties identified below, through authorized counsel, submit the following agreed terms for the Court’s consideration concerning [ISSUE]. Consent is limited to the terms actually accepted in [IDENTIFIED AGREEMENT OR ENDORSEMENTS].\nUpon consideration, it is ORDERED:\n1. [EXACT AGREED RELIEF, AFFECTED PARTIES AND SCOPE].\n2. [OBLIGATIONS, RESPONSIBLE PERSONS, DATES AND ANY CONDITIONS].\n3. [TREATMENT OF COSTS, REMAINING ISSUES OR ENFORCEMENT PROVISIONS, IF AGREED AND PROPER].\n[IDENTIFY ANY CLAIMS OR ISSUES THAT REMAIN PENDING]. No factual finding, admission or waiver beyond the actual agreement is recited.\nThe parties request entry of these terms; their agreement does not itself constitute the Court’s approval or entry.\nENTERED: ____________________\n____________________________\nJUDGE\n## Endorsements and presentation\n[ACTUAL COUNSEL ENDORSEMENTS, INCLUDING THE POSITION TAKEN, OR THE REQUIRED NOTICE OF PRESENTATION / COURT DISPENSATION UNDER RULE 1:13]\nSubmitted by: [ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]    Email: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\nCounsel signature: ____________________\n"},{"title":"Proposed Final Order","slug":"finalorder","command":"/finalorder","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Proposed Virginia Circuit Court final disposition; remaining claims and statutory continuing authority must be verified.","docx":"docx/finalorder.docx","reasoning":"../../reasoning/finalorder.md","path":"templates/motions/finalorder.md","docx_path":"templates/motions/docx/finalorder.docx","reasoning_path":"reasoning/finalorder.md","field_count":19,"md":"---\ntitle: \"Proposed Final Order\"\nslug: \"finalorder\"\ncommand: \"/finalorder\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Proposed Virginia Circuit Court final disposition; remaining claims and statutory continuing authority must be verified.\"\ndocx: \"docx/finalorder.docx\"\nreasoning: \"../../reasoning/finalorder.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PROPOSED FINAL ORDER\nThis matter came before the Court on [ACTUAL HEARING OR SUBMISSION] concerning [MATTERS TO BE FINALLY RESOLVED]. Having considered [RECORD], the Court ORDERS:\n1. [EXACT DISPOSITION OF EACH CLAIM, COUNTERCLAIM, CROSS-CLAIM AND THIRD-PARTY CLAIM, IDENTIFYING PARTIES AND WHETHER ANY DISMISSAL IS WITH OR WITHOUT PREJUDICE].\n2. [JUDGMENT, NONMONETARY RELIEF OR OTHER OPERATIVE TERMS ACTUALLY DETERMINED]. Any monetary award is [AMOUNT, RESPONSIBLE PARTY, INTEREST AND AUTHORIZED COSTS].\n3. [DISPOSITION OF FEES, COSTS, BONDS, FUNDS OR OTHER MATTERS REQUIRING EXPRESS RESOLUTION].\n4. [STATE WHETHER THE ORDER DISPOSES OF THE ENTIRE ACTION AND ALL CLAIMS AND PARTIES; IDENTIFY ANY LEGALLY PERMITTED RESERVED ISSUE WITH ITS AUTHORITY].\nThe clerk shall [ONLY THE SPECIFIC AUTHORIZED ADMINISTRATIVE ACTS]. This document is submitted as a proposed order; no entry date or judicial act is represented as completed.\nENTERED: ____________________\n____________________________\nJUDGE\n## Endorsements and presentation\n[ACTUAL COUNSEL ENDORSEMENTS AND POSITIONS, OR NOTICE OF PRESENTATION / COURT DISPENSATION UNDER RULE 1:13]\nSubmitted by: [ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]    Email: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\nCounsel signature: ____________________\n"},{"title":"Proposed Order","slug":"proposed-order","command":"/proposed-order","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Proposed Virginia Circuit Court ruling on a specified issue; not an entered order.","docx":"docx/proposed-order.docx","reasoning":"../../reasoning/proposed-order.md","path":"templates/motions/proposed-order.md","docx_path":"templates/motions/docx/proposed-order.docx","reasoning_path":"reasoning/proposed-order.md","field_count":19,"md":"---\ntitle: \"Proposed Order\"\nslug: \"proposed-order\"\ncommand: \"/proposed-order\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Proposed Virginia Circuit Court ruling on a specified issue; not an entered order.\"\ndocx: \"docx/proposed-order.docx\"\nreasoning: \"../../reasoning/proposed-order.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PROPOSED ORDER\nThis matter came before the Court on [IDENTIFIED MOTION OR ISSUE] on [HEARING DATE, IF ACTUALLY HEARD]. The Court considered [MATERIALS ACTUALLY BEFORE THE COURT] and [ARGUMENT OR SUBMISSION STATUS].\nUpon [ACTUAL FINDINGS OR BASIS FOR THE PROPOSED RULING], it is ORDERED:\n1. [PRECISE GRANT, DENIAL OR OTHER DISPOSITION, IDENTIFYING AFFECTED PARTIES AND MATTERS].\n2. [SPECIFIC REQUIRED ACT, RESPONSIBLE PERSON AND DEADLINE, IF ANY].\n3. [OTHER NECESSARY IMPLEMENTING TERM, INCLUDING ANY RETAINED ISSUE OR EXPRESS LIMITATION].\n[STATE ONLY THE FINALITY, CONTINUING-JURISDICTION OR REMAINING-CLAIM LANGUAGE THAT IS APPROPRIATE TO THE ACTUAL RULING].\nThis document is proposed for entry; the entry date and judicial signature are left for the Court.\nENTERED: ____________________\n____________________________\nJUDGE\n## Endorsements and presentation\n[ACTUAL COUNSEL ENDORSEMENTS, INCLUDING THE POSITION TAKEN, OR THE REQUIRED NOTICE OF PRESENTATION / COURT DISPENSATION UNDER RULE 1:13]\nSubmitted by: [ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]    Email: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\nCounsel signature: ____________________\n"},{"title":"Reply Memorandum in Support of Motion","slug":"reply","command":"/reply","category":"motions","category_label":"Motions and orders","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Reply on an existing Virginia Circuit Court motion when the applicable schedule or permission allows it.","docx":"docx/reply.docx","reasoning":"../../reasoning/reply.md","path":"templates/motions/reply.md","docx_path":"templates/motions/docx/reply.docx","reasoning_path":"reasoning/reply.md","field_count":25,"md":"---\ntitle: \"Reply Memorandum in Support of Motion\"\nslug: \"reply\"\ncommand: \"/reply\"\ncategory: \"motions\"\ncategory_label: \"Motions and orders\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Reply on an existing Virginia Circuit Court motion when the applicable schedule or permission allows it.\"\ndocx: \"docx/reply.docx\"\nreasoning: \"../../reasoning/reply.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# REPLY MEMORANDUM IN SUPPORT OF MOTION\n[MOVING PARTY] submits this reply concerning [EXACT MOTION] pursuant to [ACTUAL BRIEFING ORDER, LEAVE OR OTHER APPLICABLE AUTHORITY]. It addresses the opposition dated [DATE].\n## Matters requiring reply\n[IDENTIFY THE SPECIFIC ARGUMENTS OR RECORD POINTS IN THE OPPOSITION THAT WARRANT A RESPONSE]. Matters no longer disputed are [ACTUAL CONCESSIONS OR NONE].\n## Response\n[EXPLAIN WHY THE OPPOSITION DOES NOT RESOLVE THE IDENTIFIED MOTION GROUND, WITH VERIFIED AUTHORITY AND RECORD REFERENCES].\n[ADDRESS ANY CLAIMED FACTUAL DISPUTE UNDER THE CORRECT PROCEDURAL STANDARD]. If further material is tendered, identify [ITS BASIS FOR CONSIDERATION AND ANY REQUIRED OPPORTUNITY FOR RESPONSE].\n## Requested ruling\nThe movant requests [PRECISE RELIEF WITHIN THE MOTION]. Any new or enlarged relief requires [APPROPRIATE MOTION OR LEAVE] and is not assumed to be available through this reply alone.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Deposition Designations and Counter-Designations","slug":"depo-designations","command":"/depo-designations","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Precise excerpts proposed for trial under the applicable order and Rule 4:7.","docx":"docx/depo-designations.docx","reasoning":"../../reasoning/depo-designations.md","path":"templates/trial/depo-designations.md","docx_path":"templates/trial/docx/depo-designations.docx","reasoning_path":"reasoning/depo-designations.md","field_count":29,"md":"---\ntitle: \"Deposition Designations and Counter-Designations\"\nslug: \"depo-designations\"\ncommand: \"/depo-designations\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Precise excerpts proposed for trial under the applicable order and Rule 4:7.\"\ndocx: \"docx/depo-designations.docx\"\nreasoning: \"../../reasoning/depo-designations.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# DEPOSITION DESIGNATIONS AND COUNTER-DESIGNATIONS\n[PROPONENT] designates the following portions of [DEPONENT] deposition taken [DATE] for use at [TRIAL OR HEARING]. The transcript version is [REPORTER, VOLUME AND CORRECTION STATUS].\n## Designation [NUMBER]\nTranscript page and line range: [EXACT START AND END]\nVideo time range, if used: [MATCHED TIME RANGE]\nPurpose and admissibility basis: [SPECIFIC RULE 4:7 BASIS AND RELEVANCE]\nRelated exhibit: [IDENTIFIER OR NONE]\n## Counter-designation or objection [NUMBER]\nResponding party and linked designation: [IDENTIFY]\nAdditional page/line range or objection: [EXACT RANGE OR SPECIFIC LEGAL GROUND]\nCompleteness or other basis: [EXPLANATION]\n## Presentation and unresolved issues\nThe parties' conference and agreements are [ACTUAL EVENTS]. Remaining objections requiring decision are [LIST]. Proposed redactions and the authority for any video editing are [STIPULATION OR REQUESTED ORDER]. The original recording will remain unaltered.\nThe proponent will provide the required transcript portions and seek the necessary admissibility ruling. Designation alone does not make the testimony evidence or establish witness unavailability.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion in Limine","slug":"mij","command":"/mij","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Narrow evidentiary motion for an actual Virginia Circuit Court trial issue; not an automatic substitute for a dispositive motion.","docx":"docx/mij.docx","reasoning":"../../reasoning/mij.md","path":"templates/trial/mij.md","docx_path":"templates/trial/docx/mij.docx","reasoning_path":"reasoning/mij.md","field_count":26,"md":"---\ntitle: \"Motion in Limine\"\nslug: \"mij\"\ncommand: \"/mij\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Narrow evidentiary motion for an actual Virginia Circuit Court trial issue; not an automatic substitute for a dispositive motion.\"\ndocx: \"docx/mij.docx\"\nreasoning: \"../../reasoning/mij.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION IN LIMINE\n[MOVANT] requests a pretrial ruling concerning [SPECIFIC TESTIMONY, EXHIBIT OR ARGUMENT] under [APPLICABLE EVIDENTIARY RULES AND AUTHORITY]. The relief sought is limited to [PRECISE USE OR SUBJECT].\n## Evidence and context\n1. The disputed material is [IDENTIFY EXACTLY, WITH RECORD OR EXHIBIT REFERENCES].\n2. Its anticipated use is [SUPPORTED DESCRIPTION]. The relevant factual context is [FACTS NECESSARY TO EVALUATE ADMISSIBILITY].\n## Legal grounds\n3. [STATE THE SPECIFIC RELEVANCE, PREJUDICE, HEARSAY, FOUNDATION OR OTHER GROUND, ITS GOVERNING STANDARD AND VERIFIED AUTHORITIES].\n4. [APPLY THE STANDARD TO THE MATERIAL AND ADDRESS THE KNOWN OPPOSING PURPOSE OR EXCEPTION]. Where the ruling depends on trial context, identify that dependency rather than asserting an unconditional bar.\n## Requested relief\nMovant requests [EXCLUSION, LIMITATION, FOUNDATION HEARING OR OTHER PRECISE RULING]. Any request that counsel approach the Court before referring to the material before the jury is [SPECIFIC PROPOSED PROCEDURE].\nThe motion’s scheduling and conferral status is [ACTUAL EVENTS AND APPLICABLE ORDER]. No ruling, agreement or completed conference is represented before it occurs.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion to Strike the Evidence","slug":"strike","command":"/strike","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia civil trial motion challenging evidentiary sufficiency, not a California pleading motion or federal directed verdict.","docx":"docx/strike.docx","reasoning":"../../reasoning/strike.md","path":"templates/trial/strike.md","docx_path":"templates/trial/docx/strike.docx","reasoning_path":"reasoning/strike.md","field_count":26,"md":"---\ntitle: \"Motion to Strike the Evidence\"\nslug: \"strike\"\ncommand: \"/strike\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia civil trial motion challenging evidentiary sufficiency, not a California pleading motion or federal directed verdict.\"\ndocx: \"docx/strike.docx\"\nreasoning: \"../../reasoning/strike.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION TO STRIKE THE EVIDENCE\nAt [ACTUAL STAGE OF TRIAL], [MOVANT] moves to strike the evidence supporting [SPECIFIED CLAIM, ELEMENT OR DEFENSE].\n1. The challenged claim and burden of proof are [IDENTIFY]. The elements at issue are [ELEMENTS WITH VERIFIED AUTHORITY].\n2. Taking the nonmoving party’s evidence and reasonable inferences in the light most favorable to that party, the record shows [FAIR SUMMARY WITH TRANSCRIPT / EXHIBIT REFERENCES].\n3. That evidence is legally insufficient on [ELEMENT] because [SPECIFIC GAP AND CONTROLLING LAW]. This motion does not ask the Court to resolve credibility conflicts against the nonmoving party.\n4. The earlier motion and ruling, if any, were [DATE, PRECISE GROUNDS AND RULING]. [STATE RENEWAL AT THE CLOSE OF ALL EVIDENCE AND ANY ADDITIONAL GROUNDS ACTUALLY RAISED].\nWHEREFORE, Movant requests that the Court strike [IDENTIFIED EVIDENCE / CLAIM] and [PRECISE RESULTING DISPOSITION].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Objections to Proposed Jury Instructions","slug":"jury-objections","command":"/jury-objections","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Specific objections and proposed correction tied to the actual tendered instruction set.","docx":"docx/jury-objections.docx","reasoning":"../../reasoning/jury-objections.md","path":"templates/trial/jury-objections.md","docx_path":"templates/trial/docx/jury-objections.docx","reasoning_path":"reasoning/jury-objections.md","field_count":25,"md":"---\ntitle: \"Objections to Proposed Jury Instructions\"\nslug: \"jury-objections\"\ncommand: \"/jury-objections\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Specific objections and proposed correction tied to the actual tendered instruction set.\"\ndocx: \"docx/jury-objections.docx\"\nreasoning: \"../../reasoning/jury-objections.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# OBJECTIONS TO PROPOSED JURY INSTRUCTIONS\n[PARTY] objects to [PROPONENT'S] proposed instructions identified below.\n## Instruction [NUMBER AND VERSION]\nChallenged language: [EXACT TEXT OR PINPOINT REFERENCE]\nSpecific ground: [LEGAL ERROR, LACK OF EVIDENTIARY SUPPORT, DUPLICATION OR OTHER PRECISE BASIS]\nSupporting authority and record: [VERIFIED AUTHORITIES AND EVIDENCE]\nRequested correction: [EXACT SUBSTITUTE TEXT OR REQUEST TO REFUSE THE INSTRUCTION]\n## Instruction [ADDITIONAL NUMBER IF NEEDED]\n[REPEAT THE SPECIFIC TEXT, GROUND, AUTHORITY, RECORD AND REQUESTED RULING].\n## Rulings and preservation\nThe prior conference, rulings and remaining dispute are [ACTUAL STATUS]. [PARTY] requests a ruling on each stated ground and will make any required timely objection on the record. A proposed or unresolved ruling is not described as having been made.\nThe submitted alternatives are [IDENTIFY TENDERED INSTRUCTIONS]. These objections concern the specified versions; later changes will be addressed as required by the Court and applicable preservation rules.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Offer of Proof","slug":"offer-proof","command":"/offer-proof","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Record of specifically excluded evidence and its purpose, prepared for an actual ruling or proffer hearing.","docx":"docx/offer-proof.docx","reasoning":"../../reasoning/offer-proof.md","path":"templates/trial/offer-proof.md","docx_path":"templates/trial/docx/offer-proof.docx","reasoning_path":"reasoning/offer-proof.md","field_count":26,"md":"---\ntitle: \"Offer of Proof\"\nslug: \"offer-proof\"\ncommand: \"/offer-proof\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Record of specifically excluded evidence and its purpose, prepared for an actual ruling or proffer hearing.\"\ndocx: \"docx/offer-proof.docx\"\nreasoning: \"../../reasoning/offer-proof.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# OFFER OF PROOF\n[PROPONENT] makes this offer of proof concerning [WITNESS, EXHIBIT OR TESTIMONY] for the purpose of placing its substance and asserted admissibility on the record.\n## Evidence offered\n1. The evidence consists of [SPECIFIC TESTIMONY EXPECTED FROM A NAMED WITNESS OR PRECISE EXHIBIT CONTENT]. The basis for that description is [PERSONAL KNOWLEDGE, ACTUAL STATEMENT OR IDENTIFIED DOCUMENT].\n2. The proposed manner of proffer is [WITNESS TESTIMONY, EXHIBIT MARKED FOR IDENTIFICATION OR OTHER METHOD ACCEPTED BY THE COURT].\n## Relevance and admissibility\n3. The evidence bears on [MATERIAL ISSUE] because [EXPLANATION]. Foundation and the applicable evidentiary basis are [FACTS AND AUTHORITY].\n4. The objection and ruling are [ACTUAL WORDING OR ACCURATE RECORD REFERENCE]. If no ruling has been made, the requested ruling is [PRECISE REQUEST].\n## Record requested\nProponent requests that [EXHIBIT OR TRANSCRIPT SEGMENT] be retained as part of the proffer record and that the Court state its ruling on [SPECIFIC GROUND]. The proffer will be made outside the jury's hearing as appropriate so excluded matter is not presented to the jury.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Pretrial Statement","slug":"pretrial","command":"/pretrial","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia Circuit Court pretrial statement responding to an actual scheduling direction; not an automatic California-style joint pretrial order.","docx":"docx/pretrial.docx","reasoning":"../../reasoning/pretrial.md","path":"templates/trial/pretrial.md","docx_path":"templates/trial/docx/pretrial.docx","reasoning_path":"reasoning/pretrial.md","field_count":29,"md":"---\ntitle: \"Pretrial Statement\"\nslug: \"pretrial\"\ncommand: \"/pretrial\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia Circuit Court pretrial statement responding to an actual scheduling direction; not an automatic California-style joint pretrial order.\"\ndocx: \"docx/pretrial.docx\"\nreasoning: \"../../reasoning/pretrial.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PRETRIAL STATEMENT\n[SUBMITTING PARTY OR PARTIES] provides this statement pursuant to [ACTUAL SCHEDULING ORDER, COURT DIRECTION OR AGREEMENT]. It is [JOINT / SEPARATE] and is limited to positions actually authorized by the identified parties.\n## Trial and procedural status\nTrial date and mode: [DATE; JURY OR BENCH]. Estimated trial length: [ESTIMATE]. Remaining claims and parties: [DETAILS]. Pending motions or unresolved scheduling matters: [DETAILS].\n## Issues and agreed facts\nIssues for decision: [SPECIFIC LIABILITY, CAUSATION, DAMAGES OR OTHER ISSUES].\nFacts actually stipulated: [AGREED FACTS AND STIPULATION SOURCE]. Disputed facts: [ISSUES]. No disagreement is described as a stipulation.\n## Witnesses and exhibits\nWitness list and expert disclosures: [ACTUAL DOCUMENTS AND STATUS]. Exhibit list and outstanding evidentiary issues: [ACTUAL DOCUMENTS AND STATUS]. Proposed deposition use: [DESIGNATIONS AND RULE OR ORDER REQUIREMENTS].\n## Trial preparation\nProposed instructions, verdict form and voir dire: [STATUS AND ORDER-REQUIRED SUBMISSIONS]. Accommodations, interpreters or technology: [SPECIFIC REQUESTS].\n## Matters for the court\n[PRECISE PRETRIAL RULINGS OR COORDINATION REQUESTED]. Deadlines and required exchanges are those in [IDENTIFIED ACTUAL ORDER]; this statement does not amend that order.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Proposed Jury Instructions","slug":"juryinstructions","command":"/juryinstructions","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":3,"scope":"Counsel submission and repeatable separate instruction leaf; all substantive instruction text must be case-selected.","docx":"docx/juryinstructions.docx","reasoning":"../../reasoning/juryinstructions.md","path":"templates/trial/juryinstructions.md","docx_path":"templates/trial/docx/juryinstructions.docx","reasoning_path":"reasoning/juryinstructions.md","field_count":26,"md":"---\ntitle: \"Proposed Jury Instructions\"\nslug: \"juryinstructions\"\ncommand: \"/juryinstructions\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 3\nscope: \"Counsel submission and repeatable separate instruction leaf; all substantive instruction text must be case-selected.\"\ndocx: \"docx/juryinstructions.docx\"\nreasoning: \"../../reasoning/juryinstructions.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PROPOSED JURY INSTRUCTIONS\n[PARTY] tenders proposed Instruction [NUMBER] on [SUBJECT] for [TRIAL DATE].\n## Authority and evidentiary basis\nThe supporting authority is [CURRENT VIRGINIA MODEL INSTRUCTION NUMBER AND EDITION OR CONTROLLING AUTHORITY]. The proposed text is [UNCHANGED OR MODIFIED IN THE FOLLOWING PRECISE WAY]. Evidence supporting each component is [RECORD REFERENCES].\nThe instruction's relationship to the pleaded claims, defenses and burden of proof is [ANALYSIS]. Known competing instructions or objections are [ACTUAL POSITIONS]. No party agreement or judicial ruling is assumed.\n## Exchange and ruling sought\nThe exchange/tender requirements arise from [ENTERED ORDER]. Actual exchange occurred on [DATE AND METHOD]. The Court is asked to give the separately presented instruction, with [SPECIFIC REQUESTED MODIFICATION OR NONE]. Authority and argument remain on this counsel submission, separate from the proposed jury text.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n<!-- pagebreak -->\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PROPOSED INSTRUCTION [NUMBER]\n[EXACT CASE-APPROPRIATE JURY INSTRUCTION TEXT, WITHOUT COUNSEL ARGUMENT, SOURCE NOTES OR UNRESOLVED ALTERNATIVES]\n"},{"title":"Proposed Scheduling Positions","slug":"scheduling-stmt","command":"/scheduling-stmt","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Proposed Scheduling Positions for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/scheduling-stmt.docx","reasoning":"../../reasoning/scheduling-stmt.md","path":"templates/trial/scheduling-stmt.md","docx_path":"templates/trial/docx/scheduling-stmt.docx","reasoning_path":"reasoning/scheduling-stmt.md","field_count":23,"md":"---\ntitle: \"Proposed Scheduling Positions\"\nslug: \"scheduling-stmt\"\ncommand: \"/scheduling-stmt\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Proposed Scheduling Positions for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/scheduling-stmt.docx\"\nreasoning: \"../../reasoning/scheduling-stmt.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# Proposed Scheduling Positions\n[FILING PARTY] submits the following positions for [ACTUAL SCHEDULING CONFERENCE OR COURT REQUEST] under Rule 1:18 and [APPLICABLE ORDER OR LOCAL PROCEDURE].\n1. Trial readiness: [CLAIMS, PLEADINGS STATUS, REQUESTED JURY OR BENCH TRIAL, ESTIMATED TRIAL LENGTH AND MATERIAL OBSTACLES].\n2. Discovery and experts: [REMAINING WORK, PROPOSED COMPLETION DATES AND DISCLOSURE NEEDS], coordinated with [PROPOSED TRIAL DATE OR EXISTING ORDER].\n3. Motions and settlement: [ANTICIPATED MOTIONS, HEARING REQUIREMENTS AND ACTUAL ADR POSITION].\n4. Requested departures from the Uniform Pretrial Scheduling Order: [EXACT DEPARTURE AND ALL-COUNSEL AGREEMENT OR SPECIFIC REASONS FOR COURT CONSIDERATION / NONE].\n<!-- pagebreak -->\nCounsel’s actual consultation and positions are [DATE, PARTICIPANTS, AGREEMENTS AND DISAGREEMENTS]. These are proposals for court consideration, not entered deadlines. A proposed scheduling order is [ACTUAL ATTACHMENT / TO BE SUBMITTED AS DIRECTED].\nRespectfully submitted,\n[PARTY NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL DATE], a copy of this document was served on [NAMES, REPRESENTED PARTIES AND SERVICE ADDRESSES] by [ACTUAL AUTHORIZED METHOD].\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Proposed Supplemental Juror Questionnaire","slug":"jury-questionnaire","command":"/jury-questionnaire","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Case-specific Virginia civil supplemental questionnaire for court approval; not the clerk’s statutory qualification form.","docx":"docx/jury-questionnaire.docx","reasoning":"../../reasoning/jury-questionnaire.md","path":"templates/trial/jury-questionnaire.md","docx_path":"templates/trial/docx/jury-questionnaire.docx","reasoning_path":"reasoning/jury-questionnaire.md","field_count":8,"md":"---\ntitle: \"Proposed Supplemental Juror Questionnaire\"\nslug: \"jury-questionnaire\"\ncommand: \"/jury-questionnaire\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Case-specific Virginia civil supplemental questionnaire for court approval; not the clerk’s statutory qualification form.\"\ndocx: \"docx/jury-questionnaire.docx\"\nreasoning: \"../../reasoning/jury-questionnaire.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PROPOSED SUPPLEMENTAL JUROR QUESTIONNAIRE\nFor use only as approved and directed by the Court. Juror number: [NUMBER]\nPlease answer truthfully. If a response is sensitive, write “private discussion requested” and follow the Court’s directions. Do not include financial account numbers, a Social Security number or a home address here. Do not research the case or discuss it with others.\n1. Do you know any party, lawyer or listed witness? If so, state the person and the nature of the connection.\nResponse: __________________________________________________\n2. Have you or someone close to you had experience with [NEUTRALLY DESCRIBED ISSUE APPROVED BY THE COURT] that could affect your ability to be impartial?\nResponse: __________________________________________________\n3. Have you formed an opinion about this case from anything you have seen or heard? Do not repeat outside information to other jurors.\nResponse: __________________________________________________\n<!-- pagebreak -->\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# SUPPLEMENTAL QUESTIONNAIRE — CONTINUED\nJuror number: [NUMBER]\n4. Is there any reason you could not evaluate the evidence fairly and apply the law as the Court instructs?\nResponse: __________________________________________________\n5. Is there a scheduling, accessibility or other matter you need to discuss privately with the Court?\nResponse: __________________________________________________\n6. [ADDITIONAL NEUTRAL QUESTION SPECIFICALLY APPROVED BY THE COURT].\nResponse: __________________________________________________\nI have answered truthfully to the best of my knowledge.\nJuror signature: ____________________    Date: _______________\nReturn this questionnaire only as the Court directs. Proposed handling and access arrangements: [COURT-APPROVED PROCEDURE].\n"},{"title":"Proposed Verdict Form","slug":"verdictform","command":"/verdictform","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":3,"scope":"Counsel submission and separate general verdict leaf for a simple single-plaintiff single-defendant damages claim.","docx":"docx/verdictform.docx","reasoning":"../../reasoning/verdictform.md","path":"templates/trial/verdictform.md","docx_path":"templates/trial/docx/verdictform.docx","reasoning_path":"reasoning/verdictform.md","field_count":24,"md":"---\ntitle: \"Proposed Verdict Form\"\nslug: \"verdictform\"\ncommand: \"/verdictform\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 3\nscope: \"Counsel submission and separate general verdict leaf for a simple single-plaintiff single-defendant damages claim.\"\ndocx: \"docx/verdictform.docx\"\nreasoning: \"../../reasoning/verdictform.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PROPOSED VERDICT FORM\n[PARTY] tenders the attached proposed general verdict form for [SPECIFIC CLAIM] between [PLAINTIFF] and [DEFENDANT].\n## Fit with the submitted issues\nThe remaining claim and damages categories are [IDENTIFY], and the governing proposed instructions are [NUMBERS]. This form is intended only for a case in which a single general finding and, if appropriate, a single supported damages amount resolve the submitted claim.\nAny separate claim, counterclaim, multiple-party allocation, punitive-damages phase or statutory special-verdict requirement is [IDENTIFY AND ADDRESS WITH A SEPARATE ADAPTED FORM]. The simple form must not be used where it would leave submitted issues unresolved.\n## Requested action\nThe Court is asked to approve the attached form [WITH SPECIFIED MODIFICATIONS OR AS PRESENTED]. The opposing party's actual position is [POSITION OR NOT YET PROVIDED]. The separate verdict leaf contains no counsel argument or authority notes.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n<!-- pagebreak -->\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# VERDICT\nWe, the jury, find as follows on [CLAIM SUBMITTED TO THE JURY]. Complete only the alternative that reflects the verdict reached under the Court's instructions.\n( ) We find for [PLAINTIFF] against [DEFENDANT] and assess damages in the amount of $____________________.\n( ) We find for [DEFENDANT].\nForeperson signature: ____________________\nPrinted name: ____________________\nDate: ____________________\n"},{"title":"Proposed Voir Dire Questions","slug":"voirdire","command":"/voirdire","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Neutral proposed questions directed to juror qualification, interest and bias in the actual civil case.","docx":"docx/voirdire.docx","reasoning":"../../reasoning/voirdire.md","path":"templates/trial/voirdire.md","docx_path":"templates/trial/docx/voirdire.docx","reasoning_path":"reasoning/voirdire.md","field_count":21,"md":"---\ntitle: \"Proposed Voir Dire Questions\"\nslug: \"voirdire\"\ncommand: \"/voirdire\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Neutral proposed questions directed to juror qualification, interest and bias in the actual civil case.\"\ndocx: \"docx/voirdire.docx\"\nreasoning: \"../../reasoning/voirdire.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PROPOSED VOIR DIRE QUESTIONS\n[PARTY] submits the following proposed questions for examination of prospective jurors, subject to the Court's procedure.\n## Connections and knowledge\n1. Do you know [PARTIES, COUNSEL OR IDENTIFIED WITNESSES], or have a relationship with any of them that may affect your ability to decide this case fairly?\n2. Do you have personal knowledge of [IDENTIFIED INCIDENT], or have you received information about this dispute outside this courtroom?\n3. Do you have any financial or other interest in the outcome of this case?\n## Case-related impartiality\n4. Have you had an experience involving [NEUTRALLY DESCRIBED, RELEVANT SUBJECT] that may affect your ability to consider the evidence impartially?\n5. Have you formed an opinion about [CASE-SPECIFIC ISSUE DESCRIBED WITHOUT ARGUMENT] that would make it difficult to follow the Court's instructions?\n6. Is there any reason you could not consider this case fairly on the evidence and instructions?\n## Follow-up procedure\n[PROPOSE A RESPECTFUL METHOD FOR PRIVATE FOLLOW-UP ON SENSITIVE ANSWERS]. Questions do not ask jurors to promise a result, agree to a damages amount or decide disputed facts before evidence is received. Any proposed additional question is [EXACT QUESTION AND RELEVANCE].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Request to Set Trial","slug":"trial-setting","command":"/trial-setting","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Request to Set Trial for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/trial-setting.docx","reasoning":"../../reasoning/trial-setting.md","path":"templates/trial/trial-setting.md","docx_path":"templates/trial/docx/trial-setting.docx","reasoning_path":"reasoning/trial-setting.md","field_count":25,"md":"---\ntitle: \"Request to Set Trial\"\nslug: \"trial-setting\"\ncommand: \"/trial-setting\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Request to Set Trial for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/trial-setting.docx\"\nreasoning: \"../../reasoning/trial-setting.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# Request to Set Trial\n[MOVING PARTY] requests that the Court set this matter for trial through [VERIFIED DOCKET-CALL, CONFERENCE, MOTION OR OTHER LOCAL PROCEDURE].\n1. The issues remaining for trial are [IDENTIFIED CLAIMS AND PARTIES]. The pleadings and any outstanding service or joinder matters stand as follows: [ACTUAL STATUS].\n2. The requested mode of trial is [JURY / BENCH], based on [ACTUAL DEMAND, ORDER OR APPLICABLE BASIS]. Estimated trial time is [SUPPORTED ESTIMATE].\n3. Proposed dates and known conflicts are [DATES AND VERIFIED AVAILABILITY]. Remaining discovery, expert and dispositive-motion needs are [SPECIFIC ITEMS].\n<!-- pagebreak -->\nCounsel conferred on [ACTUAL DATE] with [NAMES]; the positions are [ACTUAL AGREEMENT OR DISAGREEMENT]. Requested scheduling provisions are [SPECIFIC REQUEST], subject to Rule 1:18 and the Court’s approval. This filing does not certify that a trial date has been assigned.\nRespectfully submitted,\n[PARTY NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL DATE], a copy of this document was served on [NAMES, REPRESENTED PARTIES AND SERVICE ADDRESSES] by [ACTUAL AUTHORIZED METHOD].\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Stipulations of Fact","slug":"stipulations-fact","command":"/stipulations-fact","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Actually agreed facts for a defined proceeding; scope and reservations stated expressly.","docx":"docx/stipulations-fact.docx","reasoning":"../../reasoning/stipulations-fact.md","path":"templates/trial/stipulations-fact.md","docx_path":"templates/trial/docx/stipulations-fact.docx","reasoning_path":"reasoning/stipulations-fact.md","field_count":25,"md":"---\ntitle: \"Stipulations of Fact\"\nslug: \"stipulations-fact\"\ncommand: \"/stipulations-fact\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Actually agreed facts for a defined proceeding; scope and reservations stated expressly.\"\ndocx: \"docx/stipulations-fact.docx\"\nreasoning: \"../../reasoning/stipulations-fact.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# STIPULATIONS OF FACT\nThe parties identified below stipulate, for purposes of [THIS TRIAL OR DEFINED PROCEEDING], to the following facts:\n## Agreed facts\n1. [SINGLE FACT TO WHICH THE IDENTIFIED PARTIES ACTUALLY AGREE].\n2. [ADDITIONAL AGREED FACT].\n3. [IF APPLICABLE, IDENTIFY A DOCUMENT AND STATE PRECISELY WHETHER AUTHENTICITY, ADMISSIBILITY OR THE TRUTH OF ITS CONTENTS IS AGREED].\n## Scope and reservations\nThe stipulation binds [SPECIFIC PARTIES] for [DEFINED PURPOSE]. Matters not agreed are [IDENTIFIED RESERVATIONS]. An agreement concerning authenticity alone does not concede every statement in the document or waive unrelated objections.\nThe parties request that the Court [ACCEPT THE STIPULATION, READ SPECIFIED FACTS OR APPROVE AN IDENTIFIED METHOD OF PRESENTATION]. Any modification will require [APPLICABLE AGREEMENT OR COURT ACTION].\n<!-- pagebreak -->\n## Agreement\nCounsel signature: ____________________ for [PARTY]    Date: [DATE]\nCounsel signature: ____________________ for [PARTY]    Date: [DATE]\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Trial Brief","slug":"trialbrief","command":"/trialbrief","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Case-specific Virginia Circuit Court brief addressing defined trial issues.","docx":"docx/trialbrief.docx","reasoning":"../../reasoning/trialbrief.md","path":"templates/trial/trialbrief.md","docx_path":"templates/trial/docx/trialbrief.docx","reasoning_path":"reasoning/trialbrief.md","field_count":27,"md":"---\ntitle: \"Trial Brief\"\nslug: \"trialbrief\"\ncommand: \"/trialbrief\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Case-specific Virginia Circuit Court brief addressing defined trial issues.\"\ndocx: \"docx/trialbrief.docx\"\nreasoning: \"../../reasoning/trialbrief.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# TRIAL BRIEF\n[PARTY] submits this trial brief for the trial scheduled on [DATE], pursuant to [ACTUAL ORDER OR PERMISSION].\n## Issues for decision\nThe claims and defenses remaining for trial are [IDENTIFY]. The legal questions addressed here are [PRECISE QUESTIONS]. Prior rulings that frame these issues are [ORDERS AND DATES].\n## Relevant record\n[SUMMARIZE THE CASE-SUPPORTED FACTS WITH RECORD REFERENCES]. Distinguish stipulated facts from disputed facts and expected testimony. Proposed exhibits and testimony remain subject to foundation and admissibility rulings.\n## Governing law and application\nFor Issue [NUMBER], the governing elements, burden and standard are [VERIFIED AUTHORITIES]. Applied to [SPECIFIC FACTS], [EXPLAIN THE REQUESTED LEGAL CONCLUSION]. Address material contrary authority and the opposing position: [ANALYSIS].\n## Requested rulings\n[STATE EACH CONCRETE RULING SOUGHT AND ITS EFFECT ON TRIAL]. Related motions, instructions and objections are [IDENTIFY SEPARATE SUBMISSIONS]. This brief does not replace a required motion, trial objection or evidentiary proffer.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Trial Exhibit List","slug":"exhibitlist","command":"/exhibitlist","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Specific exhibit identification for Virginia Circuit Court trial preparation; no unsupported representation of admitted evidence.","docx":"docx/exhibitlist.docx","reasoning":"../../reasoning/exhibitlist.md","path":"templates/trial/exhibitlist.md","docx_path":"templates/trial/docx/exhibitlist.docx","reasoning_path":"reasoning/exhibitlist.md","field_count":25,"md":"---\ntitle: \"Trial Exhibit List\"\nslug: \"exhibitlist\"\ncommand: \"/exhibitlist\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Specific exhibit identification for Virginia Circuit Court trial preparation; no unsupported representation of admitted evidence.\"\ndocx: \"docx/exhibitlist.docx\"\nreasoning: \"../../reasoning/exhibitlist.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# TRIAL EXHIBIT LIST\n[PARTY] identifies the following proposed trial exhibits pursuant to [ACTUAL PRETRIAL ORDER OR DIRECTION]. Trial is set for [DATE].\n## Proposed exhibits\nExhibit [NUMBER]: [SPECIFIC DESCRIPTION, DATE, AUTHOR OR SOURCE, AND BATES / FILE IDENTIFIER]. Production or exchange reference: [DETAILS]. Authentication or sponsoring witness: [ACTUAL BASIS]. Stipulation or objection status: [ACCURATE STATUS].\nExhibit [NUMBER]: [SPECIFIC DESCRIPTION AND IDENTIFIERS]. Production or exchange reference: [DETAILS]. Authentication or sponsoring witness: [ACTUAL BASIS]. Stipulation or objection status: [ACCURATE STATUS].\n[REPEAT FOR EACH ACTUAL EXHIBIT; DO NOT USE AN UNDEFINED “ALL RECORDS” CATEGORY IN PLACE OF IDENTIFICATION].\n## Exchange and use\nCopies not previously supplied are [ACTUAL EXCHANGE STATUS]. The list is [FILED / SERVED AS ACTUALLY REQUIRED]; physical or electronic exhibits themselves will be provided in the manner directed by the Court rather than assumed filed with this list.\nListing an exhibit does not establish authenticity, admissibility or admission into evidence. Later additions, objections and demonstratives remain subject to the actual rules and scheduling order.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Trial Witness List","slug":"witnesslist","command":"/witnesslist","category":"trial","category_label":"Pretrial and trial","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Trial witness list keyed to the entered Virginia Circuit Court scheduling order.","docx":"docx/witnesslist.docx","reasoning":"../../reasoning/witnesslist.md","path":"templates/trial/witnesslist.md","docx_path":"templates/trial/docx/witnesslist.docx","reasoning_path":"reasoning/witnesslist.md","field_count":27,"md":"---\ntitle: \"Trial Witness List\"\nslug: \"witnesslist\"\ncommand: \"/witnesslist\"\ncategory: \"trial\"\ncategory_label: \"Pretrial and trial\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Trial witness list keyed to the entered Virginia Circuit Court scheduling order.\"\ndocx: \"docx/witnesslist.docx\"\nreasoning: \"../../reasoning/witnesslist.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# TRIAL WITNESS LIST\n[PARTY] identifies the following proposed trial witnesses pursuant to [ACTUAL PRETRIAL ORDER OR DIRECTION]. Trial is set for [DATE]. This list reflects witnesses actually expected or permitted to be identified at this stage.\n## Proposed witnesses\n1. [WITNESS NAME]; [ADDRESS OR CONTACT INFORMATION REQUIRED BY THE ACTUAL ORDER]; [FACT / EXPERT / OTHER ACCURATE CAPACITY]; anticipated subject: [DESCRIPTION].\n2. [WITNESS NAME]; [REQUIRED CONTACT DETAILS]; [CAPACITY]; anticipated subject: [DESCRIPTION].\n3. [ADDITIONAL ACTUAL WITNESS ENTRY; OMIT UNUSED ITEMS].\nExpert-disclosure references are [IDENTIFY ACTUAL DISCLOSURES]. Deposition testimony proposed in place of live testimony is [SPECIFIC WITNESS AND APPLICABLE DESIGNATION STATUS].\n## Status and limitations\n[Any actual stipulation, objection, availability issue or request for leave affecting the listed witnesses]. Inclusion does not establish admissibility, substitute for required expert disclosure, or show that a subpoena has been issued or served.\nAny later change will be addressed under the applicable rules and scheduling order; this list does not create an unrestricted right to add witnesses after a deadline.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Brief of Appellee","slug":"appellee-brief","command":"/appellee-brief","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"APPEALS","court":"Court of Appeals of Virginia","layout":"APPELLATE","pages":7,"scope":"Court of Appeals of Virginia civil appeal from a circuit court, responsive merits brief. Cross-error only when actually raised and supported. Not a Supreme Court or federal brief. Final tables and VACES PDF preparation are case-specific.","docx":"docx/appellee-brief.docx","reasoning":"../../reasoning/appellee-brief.md","path":"templates/post-trial-appeals/appellee-brief.md","docx_path":"templates/post-trial-appeals/docx/appellee-brief.docx","reasoning_path":"reasoning/appellee-brief.md","field_count":32,"md":"---\ntitle: \"Brief of Appellee\"\nslug: \"appellee-brief\"\ncommand: \"/appellee-brief\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"APPEALS\"\ncourt: \"Court of Appeals of Virginia\"\nlayout: \"APPELLATE\"\npages: 7\nscope: \"Court of Appeals of Virginia civil appeal from a circuit court, responsive merits brief. Cross-error only when actually raised and supported. Not a Supreme Court or federal brief. Final tables and VACES PDF preparation are case-specific.\"\ndocx: \"docx/appellee-brief.docx\"\nreasoning: \"../../reasoning/appellee-brief.md\"\n---\n# COURT OF APPEALS OF VIRGINIA\nRecord No. [APPELLATE RECORD NUMBER]\n[APPELLANT NAME], Appellant\nv.\n[APPELLEE NAME], Appellee\n# Brief of Appellee\nAppeal from the Circuit Court of [LOCALITY]\nThe Honorable [TRIAL JUDGE NAME]\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nFacsimile: [NUMBER, IF ANY]\nEmail: [ADDRESS]\nCounsel for [APPELLEE NAME]\n<!-- frontmatter -->\n## Table of contents\nTable of authorities ................................ [PAGE]\nStatement of the case ............................... [PAGE]\nAssignments of Cross-Error, if any ........................................ [PAGE]\nStatement of facts .................................... [PAGE]\nArgument ................................................... [PAGE]\n[SEPARATE ISSUE HEADINGS AND PAGES]\nConclusion ................................................ [PAGE]\nCertificate .................................................. [PAGE]\n<!-- pagebreak -->\n## Table of authorities\nCases\n[CASE NAMES IN ALPHABETICAL ORDER, FULL CITATIONS INCLUDING YEARS, AND EACH PAGE CITED]\nStatutes and constitutional provisions\n[PROVISION AND EACH PAGE CITED]\nRules and other authorities\n[AUTHORITY AND EACH PAGE CITED]\n<!-- body -->\n## Statement of the case\n[IF APPELLEE DISAGREES WITH APPELLANT’S STATEMENT, SET OUT THE NECESSARY CORRECTIONS WITH RECORD REFERENCES. OTHERWISE STATE THAT NO CORRECTION IS REQUIRED.]\n## Assignments of Cross-Error\n[IF NONE, STATE NONE. OTHERWISE LIST EACH PROPER ADDITIONAL ASSIGNMENT OR CROSS-ERROR WITH EXACT PRESERVATION REFERENCES, CONSISTENT WITH THE APPELLATE FILINGS AND ANY AMENDMENT ORDER.]\n## Statement of facts\n[FACTS NEEDED TO CORRECT OR AMPLIFY APPELLANT’S STATEMENT, WITH RECORD OR APPENDIX PAGE REFERENCES. IF NO CORRECTION OR ADDITION IS NEEDED, STATE THAT.]\n<!-- pagebreak -->\n## Argument\n## I [Response to Appellant’s Assignment of Error 1]\nStandard of review: [APPLICABLE STANDARD AND VERIFIED SUPPORTING AUTHORITY.]\n[RESPOND TO THE ASSIGNMENT, ADDRESS PRESERVATION WHERE RELEVANT, AND APPLY VERIFIED LAW TO THE RECORD WITH PINPOINT CITATIONS. KEEP THIS ISSUE’S STANDARD AND ARGUMENT TOGETHER.]\n[REPEAT FOR EACH ASSIGNMENT RAISED BY APPELLANT.]\n## [Cross-error heading only if applicable]\n[FOR EACH CROSS-ERROR, INCLUDE ITS EXACT PRESERVATION REFERENCES, STANDARD OF REVIEW, ARGUMENT, AND AUTHORITIES TOGETHER. IF NOT PRESERVED, ADDRESS ANY SUPPORTED RULE 5A:18 EXCEPTION. OMIT THIS SECTION IF NONE.]\n<!-- pagebreak -->\n## Conclusion\nFor these reasons, Appellee requests [PRECISE DISPOSITION AND RELIEF SOUGHT].\nRespectfully submitted,\n[APPELLEE NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER, IF ANY]\n<!-- pagebreak -->\n## Certificate\nI certify that on [ACTUAL SERVICE DATE], a copy of this brief was served on all opposing counsel and unrepresented parties by [ACTUAL AUTHORIZED METHOD], as follows:\n[RECIPIENT NAME, REPRESENTED PARTY, SERVICE ADDRESS, AND METHOD FOR EACH RECIPIENT]\nCounsel for Appellee [DOES / DOES NOT] desire to waive oral argument.\nThis brief contains [ACTUAL WORD COUNT] words, including headings, footnotes, and quotations and excluding the cover, tables of contents and authorities, signature blocks, and certificate. [STATE COMPLIANCE WITH THE APPLICABLE LIMIT OR IDENTIFY THE COURT’S ORDER ALLOWING AN EXTENDED LIMIT.]\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Memorandum of Taxable Costs","slug":"costs","command":"/costs","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia civil costs request; recoverability assessed item by item.","docx":"docx/costs.docx","reasoning":"../../reasoning/costs.md","path":"templates/post-trial-appeals/costs.md","docx_path":"templates/post-trial-appeals/docx/costs.docx","reasoning_path":"reasoning/costs.md","field_count":26,"md":"---\ntitle: \"Memorandum of Taxable Costs\"\nslug: \"costs\"\ncommand: \"/costs\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia civil costs request; recoverability assessed item by item.\"\ndocx: \"docx/costs.docx\"\nreasoning: \"../../reasoning/costs.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MEMORANDUM OF TAXABLE COSTS\n[PREVAILING PARTY] submits the following taxable costs arising from [FINAL JUDGMENT OR OTHER COSTS ENTITLEMENT] dated [DATE].\n1. Entitlement rests on Virginia Code § 17.1-601 and [ANY ADDITIONAL APPLICABLE AUTHORITY OR ORDER]. The particular disposition supporting recovery is [IDENTIFY].\n2. Filing and service charges: [DATE, PAYEE, PURPOSE, RECEIPT, AMOUNT AND AUTHORITY FOR EACH ITEM].\n3. Witness, transcript or other requested charges: [ITEMIZED AMOUNT AND SPECIFIC AUTHORITY; OMIT ITEMS WITHOUT A RECOVERABLE BASIS].\n4. Total requested: $[TOTAL]. Amounts reimbursed, refunded or previously awarded are $[AMOUNT] and have been deducted. Attorney fees are excluded from this total unless separately authorized and identified.\n5. Supporting invoices and proof of payment or liability are [ACTUAL EXHIBITS]. [EXPLAIN ANY ALLOCATION AMONG PARTIES OR CLAIMS].\n[REQUESTED COSTS DETERMINATION, CLERK ACTION OR HEARING CONSISTENT WITH THE COURT’S PROCEDURE].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion Concerning Taxable Costs","slug":"tax-costs","command":"/tax-costs","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia motion to determine or correct disputed costs; identify the requested increase, disallowance or correction.","docx":"docx/tax-costs.docx","reasoning":"../../reasoning/tax-costs.md","path":"templates/post-trial-appeals/tax-costs.md","docx_path":"templates/post-trial-appeals/docx/tax-costs.docx","reasoning_path":"reasoning/tax-costs.md","field_count":28,"md":"---\ntitle: \"Motion Concerning Taxable Costs\"\nslug: \"tax-costs\"\ncommand: \"/tax-costs\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia motion to determine or correct disputed costs; identify the requested increase, disallowance or correction.\"\ndocx: \"docx/tax-costs.docx\"\nreasoning: \"../../reasoning/tax-costs.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION CONCERNING TAXABLE COSTS\n[MOVANT] requests [DETERMINATION / RETAXATION / DISALLOWANCE] of the costs claimed in [IDENTIFIED BILL, MEMORANDUM OR CLERK ACTION].\n1. The operative judgment and costs provision are [DATE AND TEXT]. The challenged request was [FILED / COMMUNICATED] on [DATE]. The Court’s authority and applicable procedure are [IDENTIFY].\n2. The disputed entries are [EACH ITEM, CLAIMED AMOUNT, AMOUNT CONCEDED AND DIFFERENCE].\n3. For each disputed entry, [STATE THE SPECIFIC STATUTORY OR OTHER AUTHORITY, NECESSITY, DOCUMENTATION, PAYMENT OR ALLOCATION ISSUE]. The supporting records are [EXHIBITS].\n4. Credits, duplicates and nonrecoverable expenses are [IDENTIFY]. The correct total under the requested ruling is $[AMOUNT], calculated as [CALCULATION].\n5. [STATE THE OTHER PARTY’S ACTUAL POSITION AND THE REQUESTED OPPORTUNITY TO BE HEARD].\nWHEREFORE, Movant requests an order fixing taxable costs at $[AMOUNT] and [PRECISE CORRECTION OR DISALLOWANCE].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion for Attorney Fees","slug":"attorneyfees","command":"/attorneyfees","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia civil fee application supported by an actual contractual, statutory or other recognized fee basis.","docx":"docx/attorneyfees.docx","reasoning":"../../reasoning/attorneyfees.md","path":"templates/post-trial-appeals/attorneyfees.md","docx_path":"templates/post-trial-appeals/docx/attorneyfees.docx","reasoning_path":"reasoning/attorneyfees.md","field_count":28,"md":"---\ntitle: \"Motion for Attorney Fees\"\nslug: \"attorneyfees\"\ncommand: \"/attorneyfees\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia civil fee application supported by an actual contractual, statutory or other recognized fee basis.\"\ndocx: \"docx/attorneyfees.docx\"\nreasoning: \"../../reasoning/attorneyfees.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION FOR ATTORNEY FEES\n[MOVANT] requests $[AMOUNT] in reasonable attorney fees under [EXACT AUTHORITY OR CONTRACT PROVISION].\n1. Entitlement was pleaded in [PLEADING, PARAGRAPH AND DATE], or leave to amend was granted by [ORDER]. The applicable exception to Rule 3:25, if any, is [IDENTIFY].\n2. The triggering adjudication or contractual event is [IDENTIFY]. [EXPLAIN ENTITLEMENT AND ADDRESS ANY PREREQUISITES OR LIMITATIONS].\n3. Attached [ACTUAL RECORDS / DECLARATION] identifies each timekeeper, qualifications, rate, date, task and time, with appropriate privilege protection. The calculation is [HOURS × RATES, ADJUSTMENTS AND TOTAL].\n4. The amount is reasonable because [EVIDENCE OF NECESSITY, COMPLEXITY, TIME, CUSTOMARY RATES, RESULTS AND OTHER APPLICABLE FACTORS]. [SEGREGATE NONRECOVERABLE OR UNRELATED WORK AND EXPLAIN ANY INSEPARABLE WORK].\n5. Costs and expenses are [SEPARATELY IDENTIFIED WITH AUTHORITY]; no amount is included twice. The adjudication procedure was set by [ORDER], or Movant requests [PROCEDURE AND OPPORTUNITY TO BE HEARD].\nWHEREFORE, Movant requests the supported fee award and [SPECIFIED ANCILLARY RELIEF].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion for New Trial","slug":"newtrial","command":"/newtrial","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia civil-jury new-trial motion with specific preserved grounds and current trial-court jurisdiction.","docx":"docx/newtrial.docx","reasoning":"../../reasoning/newtrial.md","path":"templates/post-trial-appeals/newtrial.md","docx_path":"templates/post-trial-appeals/docx/newtrial.docx","reasoning_path":"reasoning/newtrial.md","field_count":29,"md":"---\ntitle: \"Motion for New Trial\"\nslug: \"newtrial\"\ncommand: \"/newtrial\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia civil-jury new-trial motion with specific preserved grounds and current trial-court jurisdiction.\"\ndocx: \"docx/newtrial.docx\"\nreasoning: \"../../reasoning/newtrial.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION FOR NEW TRIAL\n[MOVANT] requests a new trial on [ALL OR PRECISELY IDENTIFIED ISSUES] following the verdict returned on [DATE].\n## Posture and authority\n1. Verdict and judgment: [TERMS, AMOUNT AND ENTRY DATE]. The Court retains jurisdiction under [RULE 1:1 OR OTHER BASIS AND ANY SUSPENSION ORDER].\n2. This motion rests on Virginia Code § 8.01-383 and [OTHER AUTHORITY]. Prior new trials for a verdict contrary to the evidence: [ACTUAL HISTORY].\n## Specific grounds and prejudice\n3. The ground is [TRIAL ERROR, VERDICT DEFECT OR OTHER RECOGNIZED BASIS], supported by [PRECISE RECORD REFERENCES].\n4. The issue was preserved by [OBJECTION, MOTION, PROFFER AND RULING], or may otherwise be considered under [SPECIFIC AUTHORITY].\n5. The prejudice and basis for a new trial are [ANALYSIS]. Any request to retry only damages or another limited issue rests on [FACTS AND LAW].\n## Requested disposition\nMovant requests [PRECISE NEW-TRIAL RELIEF]. If § 8.01-430 applies, [EXPLAIN WHY A NEW TRIAL RATHER THAN JUDGMENT IS PROPER]. Filing this motion alone does not suspend the judgment or extend appellate deadlines.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion for Remittitur or New Trial","slug":"remittitur","command":"/remittitur","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia motion addressing an excessive damages verdict under § 8.01-383.1(A).","docx":"docx/remittitur.docx","reasoning":"../../reasoning/remittitur.md","path":"templates/post-trial-appeals/remittitur.md","docx_path":"templates/post-trial-appeals/docx/remittitur.docx","reasoning_path":"reasoning/remittitur.md","field_count":24,"md":"---\ntitle: \"Motion for Remittitur or New Trial\"\nslug: \"remittitur\"\ncommand: \"/remittitur\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia motion addressing an excessive damages verdict under § 8.01-383.1(A).\"\ndocx: \"docx/remittitur.docx\"\nreasoning: \"../../reasoning/remittitur.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION FOR REMITTITUR OR NEW TRIAL\n[MOVANT] requests remittitur of the [DATE] verdict from $[VERDICT] to $[SUPPORTED AMOUNT], or a new trial as permitted by law.\n1. The verdict’s components and the supporting trial evidence are [IDENTIFY ECONOMIC, NONECONOMIC AND OTHER AWARDS]. The relevant judgment and jurisdictional dates are [DATES AND RULE 1:1 BASIS].\n2. The award is excessive under the applicable Virginia standard because [SPECIFIC RECORD-BASED REASONS SHOWING DISPROPORTION, BIAS, PREJUDICE OR MISUNDERSTANDING, AS SUPPORTED]. See Allstate Insurance Co. v. Wade, 265 Va. 383, 394–95 (2003).\n3. The evidence supporting the plaintiff’s recovery, viewed under the governing standard, is [FAIR ACCOUNT]. The proposed reduction has a record-based justification: [CALCULATION AND REASONING].\n4. [ADDRESS WHETHER A NEW TRIAL WOULD CONCERN DAMAGES ALONE OR ADDITIONAL ISSUES AND WHY THE ISSUES ARE SEPARABLE].\nWHEREFORE, Movant requests an order requiring the plaintiff to elect between the lawful remittitur and a new trial, preserving the statutory right to accept under protest and seek appellate review.\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion for Suspension of Execution and Approval of Security","slug":"supersedeas","command":"/supersedeas","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Motion for Suspension of Execution and Approval of Security for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/supersedeas.docx","reasoning":"../../reasoning/supersedeas.md","path":"templates/post-trial-appeals/supersedeas.md","docx_path":"templates/post-trial-appeals/docx/supersedeas.docx","reasoning_path":"reasoning/supersedeas.md","field_count":26,"md":"---\ntitle: \"Motion for Suspension of Execution and Approval of Security\"\nslug: \"supersedeas\"\ncommand: \"/supersedeas\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Motion for Suspension of Execution and Approval of Security for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/supersedeas.docx\"\nreasoning: \"../../reasoning/supersedeas.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# Motion for Suspension of Execution and Approval of Security\n[MOVING PARTY] requests suspension of execution of [IDENTIFIED JUDGMENT, DATE AND AMOUNT OR RELIEF] pending [IDENTIFIED APPEAL] under Virginia Code § 8.01-676.1.\n1. The appeal and current execution status are [VERIFIED NOTICE, RECORD NUMBER, DEADLINES AND ENFORCEMENT ACTIVITY]. The requested suspension covers [PRECISE PORTION OF JUDGMENT].\n2. Proposed security is [BOND / IRREVOCABLE LETTER OF CREDIT / OTHER STATUTORILY AUTHORIZED ARRANGEMENT], issued by [ACTUAL PROPOSED ISSUER], in the amount of $[SUPPORTED CALCULATION], on [EXACT TERMS]. The calculation addresses the applicable interest and other statutory components.\n3. Any requested modification, reduction or waiver is supported by [SPECIFIC STATUTORY SUBSECTION, FACTS AND SUPPORTING AFFIDAVIT]. Existing security and objections are [ACTUAL STATUS].\n<!-- pagebreak -->\nThe proposed instrument is [ACTUAL ATTACHMENT / TO BE PRESENTED AS DIRECTED] in a form substantially conforming to the prescribed form where required. The movant requests [PRECISE ORDER]. This motion does not itself establish that execution has been suspended or substitute for approved and filed security.\nRespectfully submitted,\n[PARTY NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL DATE], a copy of this document was served on [NAMES, REPRESENTED PARTIES AND SERVICE ADDRESSES] by [ACTUAL AUTHORIZED METHOD].\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Motion to Set Aside Verdict and Enter Judgment","slug":"jnov","command":"/jnov","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia § 8.01-430 legal insufficiency motion; not federal Rule 50.","docx":"docx/jnov.docx","reasoning":"../../reasoning/jnov.md","path":"templates/post-trial-appeals/jnov.md","docx_path":"templates/post-trial-appeals/docx/jnov.docx","reasoning_path":"reasoning/jnov.md","field_count":26,"md":"---\ntitle: \"Motion to Set Aside Verdict and Enter Judgment\"\nslug: \"jnov\"\ncommand: \"/jnov\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia § 8.01-430 legal insufficiency motion; not federal Rule 50.\"\ndocx: \"docx/jnov.docx\"\nreasoning: \"../../reasoning/jnov.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION TO SET ASIDE VERDICT AND ENTER JUDGMENT\n[MOVANT] moves under Virginia Code § 8.01-430 to set aside the jury verdict of [DATE] and enter judgment for [PARTY] on [CLAIMS].\n1. The verdict and any judgment entered on it are [DETAILS AND DATES]. The Court retains authority under [RULE 1:1 COMPUTATION AND ACTUAL SUSPENSION ORDER, IF ANY].\n2. The specific sufficiency grounds preserved at trial were [GROUNDS, MOTIONS, RENEWAL AND RULINGS, WITH RECORD REFERENCES].\n3. The challenged finding lacks legally sufficient evidence because [ELEMENT-BY-ELEMENT ANALYSIS]. [ADDRESS THE EVIDENCE AND FAIR INFERENCES FAVORABLE TO THE VERDICT WINNER WITHOUT REWEIGHING CREDIBILITY].\n4. The parties have presented all evidence offered on the issues and judgment can be decided on the existing record because [EXPLANATION]. The controlling authority is [VERIFIED CASES AND APPLICATION].\nWHEREFORE, Movant requests the specified judgment. [IF PROPERLY SUPPORTED AND PRESERVED, STATE A SEPARATE ALTERNATIVE REQUEST FOR A NEW TRIAL AND ITS GROUNDS].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Motion to Vacate Judgment","slug":"vacate-judgment","command":"/vacate-judgment","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Virginia civil judgment relief under a specifically established jurisdictional route.","docx":"docx/vacate-judgment.docx","reasoning":"../../reasoning/vacate-judgment.md","path":"templates/post-trial-appeals/vacate-judgment.md","docx_path":"templates/post-trial-appeals/docx/vacate-judgment.docx","reasoning_path":"reasoning/vacate-judgment.md","field_count":27,"md":"---\ntitle: \"Motion to Vacate Judgment\"\nslug: \"vacate-judgment\"\ncommand: \"/vacate-judgment\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Virginia civil judgment relief under a specifically established jurisdictional route.\"\ndocx: \"docx/vacate-judgment.docx\"\nreasoning: \"../../reasoning/vacate-judgment.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# MOTION TO VACATE JUDGMENT\n[MOVANT] seeks relief from the judgment entered on [DATE] concerning [CLAIMS AND PARTIES].\n1. The exact relief requested is [VACATUR, CORRECTION OR OTHER AUTHORIZED RELIEF]. The jurisdictional basis is [RULE 1:1 WITH TIMELY ENTERED CONTROL / PRECISE STATUTORY SUBSECTION].\n2. The supporting facts are [CHRONOLOGY AND ADMISSIBLE EVIDENCE]. [IDENTIFY ACTUAL NOTICE, SERVICE, PRIOR MOTIONS, SUSPENSION ORDERS AND APPELLATE STATUS].\n3. The chosen legal ground requires [ELEMENTS], which are met by [RECORD-SPECIFIC APPLICATION]. [ADDRESS ANY DEADLINE, NOTICE AND PROCEDURAL CONDITIONS].\n4. [EXPLAIN THE EFFECT ON EACH AFFECTED PARTY AND WHETHER A HEARING OR ADDITIONAL EVIDENCE IS NEEDED]. Notice of this request is [ACTUAL METHOD AND RECIPIENTS, INCLUDING ANY STATUTORILY REQUIRED NOTICE].\nWHEREFORE, Movant requests [PRECISE RULING AND RESULTING PROCEDURE].\nRespectfully submitted,\n[PARTY NAME]\nBy counsel\n____________________________\n[ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL SERVICE DATE], a copy of this document was served by [AUTHORIZED METHOD] on [ALL COUNSEL OF RECORD AND REQUIRED RECIPIENTS, WITH SERVICE ADDRESSES].\n____________________________\n[ATTORNEY NAME]\n"},{"title":"Notice of Separate Appeal","slug":"cross-appeal","command":"/cross-appeal","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Notice of Separate Appeal for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/cross-appeal.docx","reasoning":"../../reasoning/cross-appeal.md","path":"templates/post-trial-appeals/cross-appeal.md","docx_path":"templates/post-trial-appeals/docx/cross-appeal.docx","reasoning_path":"reasoning/cross-appeal.md","field_count":25,"md":"---\ntitle: \"Notice of Separate Appeal\"\nslug: \"cross-appeal\"\ncommand: \"/cross-appeal\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Notice of Separate Appeal for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/cross-appeal.docx\"\nreasoning: \"../../reasoning/cross-appeal.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# Notice of Separate Appeal\n[APPEALING PARTY AND TRIAL-COURT ROLE] gives notice of appeal to the Court of Appeals of Virginia from [EXACT FINAL JUDGMENT OR OTHER APPEALABLE ORDER] entered by this Court on [VERIFIED DATE]. This separate appeal is associated with [RELATED APPEAL STYLE AND RECORD NUMBER, IF ASSIGNED].\nThe transcript or written statement of facts, testimony and other incidents of the case [WILL / WILL NOT] be filed. If a transcript will be filed, it [HAS BEEN ORDERED FROM THE COURT REPORTER / IS ALREADY IN APPELLANT’S POSSESSION / WAS PREVIOUSLY FILED], as verified by [REFERENCE].\n## Party and counsel information\nAppellants: [EACH NAME AND ADDRESS]. Appellees: [EACH NAME AND ADDRESS].\nCounsel for each party: [NAME, REPRESENTED PARTY, VSB NUMBER, MAILING ADDRESS, TELEPHONE AND EXTENSION, FAX IF ANY, EMAIL IF ANY]. Unrepresented parties: [MAILING ADDRESS, TELEPHONE, FAX IF ANY AND EMAIL IF ANY].\n## Filing and transmission certificate\nI certify that on [ACTUAL DATE] a copy of this notice was transmitted, mailed or delivered to all opposing counsel by [ACTUAL METHOD AND RECIPIENTS]. Filing of the copy in the Court of Appeals, payment of the required fee and any required appeal security are [ACTUAL COMPLETED STATUS, DATES AND REFERENCES].\nRespectfully submitted,\n[PARTY NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\n## Certificate of service\nI certify that on [ACTUAL DATE], a copy of this document was served on [NAMES, REPRESENTED PARTIES AND SERVICE ADDRESSES] by [ACTUAL AUTHORIZED METHOD].\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Opening Brief of Appellant","slug":"opening-brief","command":"/opening-brief","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"APPEALS","court":"Court of Appeals of Virginia","layout":"APPELLATE","pages":7,"scope":"Court of Appeals of Virginia civil appeal from a circuit court, opening merits brief. Not a petition for appeal, Supreme Court brief, criminal Anders brief or federal appeal. Complete record references, final tables and VACES PDF preparation are case-specific.","docx":"docx/opening-brief.docx","reasoning":"../../reasoning/opening-brief.md","path":"templates/post-trial-appeals/opening-brief.md","docx_path":"templates/post-trial-appeals/docx/opening-brief.docx","reasoning_path":"reasoning/opening-brief.md","field_count":33,"md":"---\ntitle: \"Opening Brief of Appellant\"\nslug: \"opening-brief\"\ncommand: \"/opening-brief\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"APPEALS\"\ncourt: \"Court of Appeals of Virginia\"\nlayout: \"APPELLATE\"\npages: 7\nscope: \"Court of Appeals of Virginia civil appeal from a circuit court, opening merits brief. Not a petition for appeal, Supreme Court brief, criminal Anders brief or federal appeal. Complete record references, final tables and VACES PDF preparation are case-specific.\"\ndocx: \"docx/opening-brief.docx\"\nreasoning: \"../../reasoning/opening-brief.md\"\n---\n# COURT OF APPEALS OF VIRGINIA\nRecord No. [APPELLATE RECORD NUMBER]\n[APPELLANT NAME], Appellant\nv.\n[APPELLEE NAME], Appellee\n# Opening Brief of Appellant\nAppeal from the Circuit Court of [LOCALITY]\nThe Honorable [TRIAL JUDGE NAME]\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nFacsimile: [NUMBER, IF ANY]\nEmail: [ADDRESS]\nCounsel for [APPELLANT NAME]\n<!-- frontmatter -->\n## Table of contents\nTable of authorities ................................ [PAGE]\nStatement of the case ............................... [PAGE]\nAssignments of Error ........................................ [PAGE]\nStatement of facts .................................... [PAGE]\nArgument ................................................... [PAGE]\n[SEPARATE ISSUE HEADINGS AND PAGES]\nConclusion ................................................ [PAGE]\nCertificate .................................................. [PAGE]\n<!-- pagebreak -->\n## Table of authorities\nCases\n[CASE NAMES IN ALPHABETICAL ORDER, FULL CITATIONS INCLUDING YEARS, AND EACH PAGE CITED]\nStatutes and constitutional provisions\n[PROVISION AND EACH PAGE CITED]\nRules and other authorities\n[AUTHORITY AND EACH PAGE CITED]\n<!-- body -->\n## Statement of the case\n[NATURE OF THE ACTION, MATERIAL PROCEEDINGS, RULING APPEALED FROM, AND RELEVANT RECORD CITATIONS. INCLUDE ONLY MATTERS RELATED TO THE ASSIGNMENTS OF ERROR.]\n## Assignments of Error\n1. [SPECIFIC CHALLENGED RULING OR FAILURE TO RULE, WITHOUT EXTRANEOUS ARGUMENT.]\nPreservation: [EXACT RECORD OR APPENDIX PAGE REFERENCES; FOR A FAILURE TO RULE, IDENTIFY THE OPPORTUNITY PROVIDED FOR A RULING.]\n[REPEAT FOR EACH ASSIGNMENT OF ERROR.]\n## Statement of facts\n[CONCISE MATERIAL FACTS WITH RECORD OR APPENDIX PAGE REFERENCES. IDENTIFY DISPUTED FACTS; USE ONLY MATTER IN THE APPELLATE RECORD.]\n<!-- pagebreak -->\n## Argument\n## I [Heading addressing Assignment of Error 1]\nStandard of review: [APPLICABLE STANDARD AND VERIFIED SUPPORTING AUTHORITY.]\nPreservation: [PINPOINT REFERENCES OR, IF NOT PRESERVED, THE SUPPORTED BASIS FOR A RULE 5A:18 EXCEPTION.]\n[DEVELOP THE LEGAL ARGUMENT WITH VERIFIED AUTHORITIES, APPLY IT TO THE RECORD, AND ADDRESS MATERIAL CONTRARY AUTHORITY. KEEP THE STANDARD AND ARGUMENT FOR THIS ASSIGNMENT TOGETHER.]\n[REPEAT THE ISSUE SECTION FOR EACH ASSIGNMENT.]\n<!-- pagebreak -->\n## Conclusion\nFor these reasons, Appellant requests [PRECISE DISPOSITION AND RELIEF SOUGHT].\nRespectfully submitted,\n[APPELLANT NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER, IF ANY]\n<!-- pagebreak -->\n## Certificate\nI certify that on [ACTUAL SERVICE DATE], a copy of this brief was served on all opposing counsel and unrepresented parties by [ACTUAL AUTHORIZED METHOD], as follows:\n[RECIPIENT NAME, REPRESENTED PARTY, SERVICE ADDRESS, AND METHOD FOR EACH RECIPIENT]\nCounsel for Appellant [DOES / DOES NOT] desire to waive oral argument.\nThis brief contains [ACTUAL WORD COUNT] words, including headings, footnotes, and quotations and excluding the cover, tables of contents and authorities, signature blocks, and certificate. [STATE COMPLIANCE WITH THE APPLICABLE LIMIT OR IDENTIFY THE COURT’S ORDER ALLOWING AN EXTENDED LIMIT.]\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Petition for Appeal to Supreme Court of Virginia","slug":"cert-petition","command":"/cert-petition","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"SUPREME","court":"Supreme Court of Virginia","layout":"APPELLATE","pages":6,"scope":"Supreme Court of Virginia civil discretionary petition for appeal only. Not a U.S. Supreme Court certiorari petition, Rule 5:17A interlocutory petition, petition for rehearing or criminal Anders filing. Verify appellate jurisdiction and statutory exceptions; do not assume direct appeal from an ordinary circuit civil judgment. Add one argument section per assignment; table pages and counts must be recomputed after drafting.","docx":"docx/cert-petition.docx","reasoning":"../../reasoning/cert-petition.md","path":"templates/post-trial-appeals/cert-petition.md","docx_path":"templates/post-trial-appeals/docx/cert-petition.docx","reasoning_path":"reasoning/cert-petition.md","field_count":38,"md":"---\ntitle: \"Petition for Appeal to Supreme Court of Virginia\"\nslug: \"cert-petition\"\ncommand: \"/cert-petition\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"SUPREME\"\ncourt: \"Supreme Court of Virginia\"\nlayout: \"APPELLATE\"\npages: 6\nscope: \"Supreme Court of Virginia civil discretionary petition for appeal only. Not a U.S. Supreme Court certiorari petition, Rule 5:17A interlocutory petition, petition for rehearing or criminal Anders filing. Verify appellate jurisdiction and statutory exceptions; do not assume direct appeal from an ordinary circuit civil judgment. Add one argument section per assignment; table pages and counts must be recomputed after drafting.\"\ndocx: \"docx/cert-petition.docx\"\nreasoning: \"../../reasoning/cert-petition.md\"\n---\nSUPREME COURT OF VIRGINIA\n[APPELLANT NAME], Appellant\nv.\n[APPELLEE NAME], Appellee\nRecord No. [SUPREME COURT RECORD NUMBER]\n# PETITION FOR APPEAL\nFrom [COURT OR TRIBUNAL AND RECORD NUMBER]\nJudgment entered [DATE]\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER AND EXTENSION]\nFax: [NUMBER IF ANY]\nEmail: [ADDRESS]\nCounsel for [APPELLANT]\n<!-- frontmatter -->\n# TABLE OF CONTENTS\nAssignments of Error ... [PAGE]\nNature of the Case and Material Proceedings Below ... [PAGE]\nStatement of Facts ... [PAGE]\nAuthorities and Argument ... [PAGE]\nConclusion ... [PAGE]\nCertificate ... [PAGE]\n<!-- pagebreak -->\n# TABLE OF AUTHORITIES\nCases, alphabetically arranged\n[CASE NAME, COMPLETE CITATION INCLUDING YEAR] ... [PAGES]\nStatutes and rules\n[STATUTE OR RULE, INCLUDING APPLICABLE YEAR] ... [PAGES]\nOther authorities\n[AUTHORITY AND YEAR, IF USED] ... [PAGES]\n<!-- body -->\n# PETITION FOR APPEAL\n## Assignments of Error\n1. [SPECIFIC RULING, FAILURE TO RULE OR EXISTING CASE LAW CHALLENGED]. Preservation: [EXACT RECORD OR TRANSCRIPT PAGES; OPPORTUNITY TO RULE IF APPLICABLE].\n## Nature of the Case and Material Proceedings Below\n[CONCISE NATURE OF CASE AND MATERIAL PROCEEDINGS RELEVANT TO THE ASSIGNED ERROR]. This Court’s appellate jurisdiction and the applicable review route rest on [ACTUAL AUTHORITY]. The judgment or timely rehearing disposition and filing dates are [DATES SUPPORTING TIMELINESS].\nFor an appeal from the Court of Appeals, [IDENTIFY THE ERROR PRESENTED THERE AND THE ACTION TAKEN BY THAT COURT].\n## Statement of Facts\n[FACTS RELEVANT TO THE ASSIGNED ERROR, WITH PRECISE RECORD CITATIONS]. Disputed facts are [IDENTIFIED DISPUTES AND EACH RELEVANT RECORD SOURCE].\n## Authorities and Argument\nAssignment of Error 1 — [SHORT DESCRIPTION]\nStandard of review: [STANDARD AND VERIFIED AUTHORITY].\n[FOCUSED ARGUMENT APPLYING VERIFIED LAW TO THE RECORD AND ADDRESSING THE RULING BELOW].\n[EXPLAIN WHY THE ERROR WARRANTS THE PRECISE RELIEF REQUESTED; ADDRESS PRESERVATION AND MATERIAL ADVERSE AUTHORITY].\n## Conclusion\nThe appellant requests [PRECISE APPELLATE RELIEF].\nRespectfully submitted,\n[APPELLANT NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER AND EXTENSION]\nFax: [NUMBER IF ANY]\nEmail: [ADDRESS]\n<!-- pagebreak -->\n# CERTIFICATE\nAll appellants and appellees are [ALL PARTY NAMES]. Counsel for each party are [NAME, PARTY REPRESENTED, VSB NUMBER, MAILING ADDRESS, TELEPHONE AND EXTENSION, FAX IF ANY, EMAIL IF ANY]. Unrepresented parties’ contact details are [NAME, MAILING ADDRESS, TELEPHONE AND EXTENSION, FAX IF ANY, EMAIL IF ANY; OR NONE].\nI certify that a copy of this petition was mailed or delivered on [ACTUAL DATE] to all opposing counsel and all parties not represented by counsel, by [ACTUAL METHOD AND RECIPIENT DETAILS].\nThe petition complies with Rule 5:17(f) based on [ACTUAL WORD COUNT OR COUNTED PAGES]. If word count is used, the count includes headings, footnotes and quotations and excludes the cover, tables, signature blocks and certificate.\nThe appellant [DESIRES OR DOES NOT DESIRE] to present oral reasons why the petition should be granted. If desired, appearance is requested [IN PERSON OR BY TELEPHONE CONFERENCE CALL].\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Petition for Panel Rehearing","slug":"rehearing","command":"/rehearing","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"APPEALS","court":"Court of Appeals of Virginia","layout":"APPELLATE","pages":6,"scope":"Petition for Panel Rehearing for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/rehearing.docx","reasoning":"../../reasoning/rehearing.md","path":"templates/post-trial-appeals/rehearing.md","docx_path":"templates/post-trial-appeals/docx/rehearing.docx","reasoning_path":"reasoning/rehearing.md","field_count":29,"md":"---\ntitle: \"Petition for Panel Rehearing\"\nslug: \"rehearing\"\ncommand: \"/rehearing\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"APPEALS\"\ncourt: \"Court of Appeals of Virginia\"\nlayout: \"APPELLATE\"\npages: 6\nscope: \"Petition for Panel Rehearing for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/rehearing.docx\"\nreasoning: \"../../reasoning/rehearing.md\"\n---\n# COURT OF APPEALS OF VIRGINIA\nRecord No. [APPELLATE RECORD NUMBER]\n[APPELLANT NAME], Appellant\nv.\n[APPELLEE NAME], Appellee\n# Petition for Panel Rehearing\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nFacsimile: [NUMBER IF ANY]\nEmail: [ADDRESS]\nCounsel for [PARTY NAME]\n<!-- frontmatter -->\n## Table of contents\nArgument ................................ [PAGE]\nConclusion .............................. [PAGE]\nCertificate ............................. [PAGE]\n<!-- pagebreak -->\n## Table of authorities\n[VERIFIED AUTHORITIES IN THE APPROPRIATE ORDER, FULL CITATIONS AND EACH PAGE CITED]\n<!-- body -->\n## Argument\n[PETITIONING PARTY] requests panel rehearing of the decision or order entered on [VERIFIED DATE] finally disposing of this appeal. This petition is filed [WITHIN THE APPLICABLE PERIOD / PURSUANT TO THE IDENTIFIED EXTENSION ORDER].\n## I [Specific ground for rehearing]\nThe decision states [ACCURATE PROPOSITION WITH PAGE REFERENCE]. Good cause for rehearing is [PRECISE MATERIAL POINT OF LAW OR RECORD FACT WARRANTING RECONSIDERATION]. The point was presented at [RECORD AND BRIEF PINPOINTS], and the controlling authority is [VERIFIED CITATION AND PROPOSITION].\nThe effect on the disposition is [SPECIFIC EXPLANATION]. [REPEAT ONLY FOR ADDITIONAL SUPPORTED GROUNDS. DO NOT TREAT THIS PETITION AS PERMISSION TO INTRODUCE NEW EVIDENCE.]\n<!-- pagebreak -->\n## Conclusion\nPetitioner requests that the panel grant rehearing and [PRECISE REQUESTED DISPOSITION OR FURTHER PROCEEDING].\nRespectfully submitted,\n[PARTY NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF ANY]\n<!-- pagebreak -->\n## Certificate\nI certify that on [ACTUAL DATE], the petition was served on [ALL OPPOSING COUNSEL AND UNREPRESENTED PARTIES, WITH ADDRESSES] by [ACTUAL AUTHORIZED METHOD].\nThis petition contains [ACTUAL WORD COUNT] words counted under the applicable rules. [STATE COMPLIANCE WITH RULE 5A:33 AND ANY APPLICABLE COURT ORDER, IDENTIFYING ONLY EXCLUSIONS ACTUALLY PERMITTED.]\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Preliminary Assignments of Error and Appendix Designation","slug":"record-appeal","command":"/record-appeal","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"APPEALS","court":"Court of Appeals of Virginia","layout":"APPELLATE_PAPER","pages":2,"scope":"Preliminary Assignments of Error and Appendix Designation for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/record-appeal.docx","reasoning":"../../reasoning/record-appeal.md","path":"templates/post-trial-appeals/record-appeal.md","docx_path":"templates/post-trial-appeals/docx/record-appeal.docx","reasoning_path":"reasoning/record-appeal.md","field_count":23,"md":"---\ntitle: \"Preliminary Assignments of Error and Appendix Designation\"\nslug: \"record-appeal\"\ncommand: \"/record-appeal\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"APPEALS\"\ncourt: \"Court of Appeals of Virginia\"\nlayout: \"APPELLATE_PAPER\"\npages: 2\nscope: \"Preliminary Assignments of Error and Appendix Designation for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/record-appeal.docx\"\nreasoning: \"../../reasoning/record-appeal.md\"\n---\nCOURT OF APPEALS OF VIRGINIA\n[APPELLANT NAME], Appellant\nv.\n[APPELLEE NAME], Appellee\nRecord No. [APPELLATE RECORD NUMBER]\n# Preliminary Assignments of Error and Appendix Designation\n[PARTY] submits this [INDIVIDUAL / AGREED] statement under Rule 5A:25. Record filed: [DATE]. Designation deadline: [DATE AND TRIGGER].\n## Preliminary assignments\n1. [SPECIFIC ERROR OR CROSS-ERROR AND RECORD LOCATION].\n[REPEAT FOR EACH APPLICABLE ASSIGNMENT.]\n## Appendix status and contents\nThe record is [ELECTRONIC / PAPER]. Appendix requirement, including any official videotape or court direction: [ACTUAL STATUS AND BASIS].\n[IF REQUIRED: LIST RECORD DOCUMENTS AND PAGE RANGES REQUIRED BY RULE 5A:25(c), OMITTING NON-GERMANE MATERIAL.]\n[IF NO APPENDIX IS REQUIRED: RETAIN REQUIRED PRELIMINARY ASSIGNMENTS.]\nThe designation is [AGREED BY ALL COUNSEL, WITH SIGNATURES / INDIVIDUAL, WITH ANY ADDITIONAL DESIGNATIONS IDENTIFIED]. No material outside the record is added.\nRespectfully submitted,\n[PARTY NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF ANY]\n## Certificate of service\nI certify that on [ACTUAL DATE], this document was served on [ALL OPPOSING COUNSEL AND UNREPRESENTED PARTIES, WITH ADDRESSES] by [ACTUAL AUTHORIZED METHOD].\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Proposed Money Judgment","slug":"proposed-judgment","command":"/proposed-judgment","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"CIRCUIT","court":"Virginia Circuit Court","layout":"COURT","pages":2,"scope":"Proposed Virginia civil money judgment; not an entered judgment or collection instrument.","docx":"docx/proposed-judgment.docx","reasoning":"../../reasoning/proposed-judgment.md","path":"templates/post-trial-appeals/proposed-judgment.md","docx_path":"templates/post-trial-appeals/docx/proposed-judgment.docx","reasoning_path":"reasoning/proposed-judgment.md","field_count":28,"md":"---\ntitle: \"Proposed Money Judgment\"\nslug: \"proposed-judgment\"\ncommand: \"/proposed-judgment\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"CIRCUIT\"\ncourt: \"Virginia Circuit Court\"\nlayout: \"COURT\"\npages: 2\nscope: \"Proposed Virginia civil money judgment; not an entered judgment or collection instrument.\"\ndocx: \"docx/proposed-judgment.docx\"\nreasoning: \"../../reasoning/proposed-judgment.md\"\n---\nVIRGINIA: IN THE CIRCUIT COURT OF [LOCALITY]\n[PLAINTIFF FULL NAME], Plaintiff |\nv. | Case No. [CASE NUMBER]\n[DEFENDANT FULL NAME], Defendant |\n# PROPOSED MONEY JUDGMENT\nUpon [VERDICT / ADJUDICATED FINDINGS] dated [DATE], and after consideration of [RECORD AND PRESENTATION], it is ORDERED:\n1. Judgment is entered for [EXACT JUDGMENT CREDITOR] against [EXACT JUDGMENT DEBTOR AND CAPACITY] in the principal amount of $[AMOUNT], consisting of [AWARD COMPONENTS AND ANY LAWFUL OFFSETS]. [SPECIFY SEVERAL OR JOINT LIABILITY ONLY AS ADJUDICATED].\n2. Prejudgment interest is [AWARDED OR DENIED]; any award is $[AMOUNT] or [RATE, START DATE AND APPLICABLE BASE], under [ACTUAL VERDICT / AUTHORITY].\n3. Postjudgment interest shall accrue on [LAWFUL BASE] at [APPLICABLE RATE AND AUTHORITY] from [VERIFIED COMMENCEMENT DATE] until paid, subject to applicable law.\n4. Taxable costs are [AMOUNT OR IDENTIFIED PROCEDURE FOR DETERMINATION]. Attorney fees are [ADJUDICATED DISPOSITION AND AUTHORITY, IF ANY].\n5. [DISPOSE OF EACH REMAINING CLAIM AND PARTY, OR IDENTIFY ISSUES STILL PENDING]. [STATE SUPPORTED FINALITY LANGUAGE; DO NOT USE A RECITAL TO CREATE JURISDICTION].\nSubmitted for entry; the judicial signature and entry date remain blank.\nENTERED: ____________________\n____________________________\nJUDGE\n## Endorsements and presentation\n[ACTUAL COUNSEL ENDORSEMENTS AND POSITIONS, OR NOTICE OF PRESENTATION / COURT DISPENSATION UNDER RULE 1:13]\nSubmitted by: [ATTORNEY NAME] (VSB No. [NUMBER])\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]    Email: [ADDRESS]\nFax: [NUMBER IF REGULARLY USED]\nCounsel signature: ____________________\n"},{"title":"Reply Brief of Appellant","slug":"reply-brief","command":"/reply-brief","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"APPEALS","court":"Court of Appeals of Virginia","layout":"APPELLATE","pages":6,"scope":"Reply Brief of Appellant for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/reply-brief.docx","reasoning":"../../reasoning/reply-brief.md","path":"templates/post-trial-appeals/reply-brief.md","docx_path":"templates/post-trial-appeals/docx/reply-brief.docx","reasoning_path":"reasoning/reply-brief.md","field_count":24,"md":"---\ntitle: \"Reply Brief of Appellant\"\nslug: \"reply-brief\"\ncommand: \"/reply-brief\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"APPEALS\"\ncourt: \"Court of Appeals of Virginia\"\nlayout: \"APPELLATE\"\npages: 6\nscope: \"Reply Brief of Appellant for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/reply-brief.docx\"\nreasoning: \"../../reasoning/reply-brief.md\"\n---\n# COURT OF APPEALS OF VIRGINIA\nRecord No. [APPELLATE RECORD NUMBER]\n[APPELLANT NAME], Appellant\nv.\n[APPELLEE NAME], Appellee\n# Reply Brief of Appellant\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME]\n[MAILING ADDRESS]\nTelephone: [NUMBER]\nFacsimile: [NUMBER IF ANY]\nEmail: [ADDRESS]\nCounsel for [PARTY NAME]\n<!-- frontmatter -->\n## Table of contents\nArgument ................................ [PAGE]\nConclusion .............................. [PAGE]\nCertificate ............................. [PAGE]\n<!-- pagebreak -->\n## Table of authorities\n[VERIFIED AUTHORITIES IN THE APPROPRIATE ORDER, FULL CITATIONS AND EACH PAGE CITED]\n<!-- body -->\n## Argument\n## I [Reply to identified contention]\nAppellee contends [ACCURATE SUMMARY AND BRIEF PAGE]. The response is [ARGUMENT TIED TO THE EXISTING ASSIGNMENT OF ERROR, WITH VERIFIED RECORD AND AUTHORITY CITATIONS].\n[REPEAT FOR EACH CONTENTION THAT REQUIRES REPLY. DISTINGUISH ANY RESPONSE TO PROPERLY PRESENTED CROSS-ERROR. DO NOT INTRODUCE AN UNPRESERVED NEW ASSIGNMENT OR NEW EVIDENCE.]\n<!-- pagebreak -->\n## Conclusion\nAppellant requests [PRECISE DISPOSITION CONSISTENT WITH THE PRESERVED ISSUES AND RELIEF SOUGHT].\nRespectfully submitted,\n[PARTY NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF ANY]\n<!-- pagebreak -->\n## Certificate\nI certify that on [ACTUAL DATE], this brief was served on [ALL OPPOSING COUNSEL AND UNREPRESENTED PARTIES, WITH ADDRESSES] by [ACTUAL AUTHORIZED METHOD]. Counsel [DOES / DOES NOT] desire to waive oral argument.\nThis brief contains [ACTUAL WORD COUNT] words, including headings, footnotes and quotations and excluding the cover, contents, authorities, signature blocks and certificate. [STATE COMPLIANCE WITH THE APPLICABLE LIMIT OR IDENTIFY THE COURT’S EXTENSION ORDER.]\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Request Concerning Oral Argument","slug":"oral-argument","command":"/oral-argument","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"STATE","court_level":"APPEALS","court":"Court of Appeals of Virginia","layout":"APPELLATE_PAPER","pages":2,"scope":"Request Concerning Oral Argument for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/oral-argument.docx","reasoning":"../../reasoning/oral-argument.md","path":"templates/post-trial-appeals/oral-argument.md","docx_path":"templates/post-trial-appeals/docx/oral-argument.docx","reasoning_path":"reasoning/oral-argument.md","field_count":21,"md":"---\ntitle: \"Request Concerning Oral Argument\"\nslug: \"oral-argument\"\ncommand: \"/oral-argument\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"STATE\"\ncourt_level: \"APPEALS\"\ncourt: \"Court of Appeals of Virginia\"\nlayout: \"APPELLATE_PAPER\"\npages: 2\nscope: \"Request Concerning Oral Argument for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/oral-argument.docx\"\nreasoning: \"../../reasoning/oral-argument.md\"\n---\nCOURT OF APPEALS OF VIRGINIA\n[APPELLANT NAME], Appellant\nv.\n[APPELLEE NAME], Appellee\nRecord No. [APPELLATE RECORD NUMBER]\n# Request Concerning Oral Argument\n[PARTY] requests [PRECISE RELIEF CONCERNING ORAL ARGUMENT] in this appeal under Rule 5A:28 and [APPLICABLE ORDER OR OTHER AUTHORITY]. The current argument status is [SETTING, NOTICE, WAIVER OR OTHER VERIFIED STATUS].\nThe reason for this request is [CASE-SPECIFIC FACTS AND ANY PRIOR WAIVER OR SCHEDULING ISSUE]. The proposed arrangement is [SPECIFIC REQUEST], with the positions of other parties stated accurately as [ACTUAL POSITIONS OR NOT YET OBTAINED].\n[IF REQUESTING AMICUS PARTICIPATION, IDENTIFY THE JOINT REQUEST, SUPPORTED PARTY AND EXACT TIME THAT PARTY AGREES TO YIELD. OTHERWISE OMIT.]\n<!-- pagebreak -->\nThe request does not enlarge the allotted time, vacate an existing waiver or establish a hearing date without court action. The oral-argument election required in the applicable brief certificate is [ACTUAL STATUS].\nRespectfully submitted,\n[PARTY NAME]\nBy: ________________________________\n[ATTORNEY NAME], VSB No. [NUMBER]\n[FIRM NAME AND MAILING ADDRESS]\nTelephone: [NUMBER]\nEmail: [ADDRESS]\nFax: [NUMBER IF ANY]\n## Certificate of service\nI certify that on [ACTUAL DATE], this document was served on [ALL OPPOSING COUNSEL AND UNREPRESENTED PARTIES, WITH ADDRESSES] by [ACTUAL AUTHORIZED METHOD].\n________________________________\n[ATTORNEY NAME]\n"},{"title":"Transmittal of Entered Judgment","slug":"entry-judgment","command":"/entry-judgment","category":"post-trial-appeals","category_label":"Post-trial, judgment and appeals","jurisdiction":"VA","court_system":"ANY","court_level":"ANY","court":"Not court-specific (Virginia matter)","layout":"LETTER","pages":1,"scope":"Transmittal of Entered Judgment for a Virginia personal injury matter; verify actual recipient, authority and case posture.","docx":"docx/entry-judgment.docx","reasoning":"../../reasoning/entry-judgment.md","path":"templates/post-trial-appeals/entry-judgment.md","docx_path":"templates/post-trial-appeals/docx/entry-judgment.docx","reasoning_path":"reasoning/entry-judgment.md","field_count":19,"md":"---\ntitle: \"Transmittal of Entered Judgment\"\nslug: \"entry-judgment\"\ncommand: \"/entry-judgment\"\ncategory: \"post-trial-appeals\"\ncategory_label: \"Post-trial, judgment and appeals\"\njurisdiction: \"VA\"\ncourt_system: \"ANY\"\ncourt_level: \"ANY\"\ncourt: \"Not court-specific (Virginia matter)\"\nlayout: \"LETTER\"\npages: 1\nscope: \"Transmittal of Entered Judgment for a Virginia personal injury matter; verify actual recipient, authority and case posture.\"\ndocx: \"docx/entry-judgment.docx\"\nreasoning: \"../../reasoning/entry-judgment.md\"\n---\n[FIRM NAME]\n[FIRM MAILING ADDRESS]\nTelephone: [NUMBER] | Email: [ADDRESS]\n[DATE]\n[RECIPIENT NAME AND CAPACITY]\n[RECIPIENT MAILING OR PORTAL ADDRESS]\nRe: Transmittal of Entered Judgment — [CLIENT / MATTER REFERENCE]\nDear [RECIPIENT NAME]:\nWe transmit [EXACT TITLE OF JUDGMENT OR ORDER] entered on [VERIFIED ENTRY DATE] in [COURT, CASE STYLE AND NUMBER]. The enclosed copy is [FILE-STAMPED / CERTIFIED / OTHER ACCURATE DESCRIPTION], obtained from [SOURCE].\nThe disposition reflected in that order is [PRECISE SUMMARY OF CLAIMS, PARTIES, AMOUNTS AND ANY REMAINING ISSUES]. Any amount stated here is taken from [SPECIFIC PARAGRAPH], without adding unadjudicated fees or interest.\nThis transmittal is sent for [ACTUAL INFORMATIONAL OR ORDER-REQUIRED PURPOSE]. It does not amend the judgment, represent that it has been satisfied or supply a judicial certification not present on the enclosed copy.\nAny review or post-judgment deadline must be determined from the applicable rule, entry event and case orders. We do not state that this mailing independently starts, extends or revives an appeal period. Please acknowledge receipt if [ACTUAL REASON OR REQUEST].\nSincerely,\n[ATTORNEY NAME]\n[FIRM NAME]\n"}],"routes":[{"command":"/1099-atty","slug":"1099-atty","title":"Attorney Payment Information Returns","kind":"official-process","kind_label":"Official agency or court process","what_to_do":"Use the correct tax-year IRS information-return process. Distinguish payment for legal services (potential Form 1099-NEC) from gross proceeds paid to an attorney (potential Form 1099-MISC); the payee, payer, payment type and reporting year control. Gross-proceeds reporting is not a statement of the attorney’s taxable fee. Have the responsible payer verify current instructions, reporting thresholds, taxpayer information and electronic or scannable filing requirements. This route links instructions; it does not generate or file a tax return.","official_link":"https://www.irs.gov/instructions/i1099mec","reasoning":"reasoning/routes/1099-atty.md"},{"command":"/1099-taxable","slug":"1099-taxable","title":"Settlement Information Return Selection","kind":"official-process","kind_label":"Official agency or court process","what_to_do":"Identify each actual settlement component and the responsible payer before selecting the applicable tax-year IRS form. A taxable nonwage payment, attorney gross proceeds, interest and wages can require different reporting; taxable wages use the wage-reporting process. An information return does not decide the recipient’s tax treatment. Use the current official instructions and supported allocation; no return is filled or filed by this route.","official_link":"https://www.irs.gov/government-entities/tax-implications-of-settlements-and-judgments","reasoning":"reasoning/routes/1099-taxable.md"},{"command":"/abstract","slug":"abstract","title":"Clerk Certified Abstract of Judgment","kind":"clerk-process","kind_label":"Clerk-issued process","what_to_do":"Request the certified abstract from the clerk of the court that entered the judgment and follow the receiving clerk’s docketing requirements. CC-1407 is a service form, not an abstract. A drafted Word document cannot supply the clerk’s certification.","reasoning":"reasoning/routes/abstract.md"},{"command":"/acceptance-service","slug":"acceptance-service","title":"Acceptance of Service / Waiver","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1406); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1406"},{"command":"/affidavit-service","slug":"affidavit-service","title":"Affidavit for Service on Secretary","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1418); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1418"},{"command":"/annuity","slug":"annuity","title":"Obtain Issued Annuity Confirmation","kind":"specialist","kind_label":"Specialist or provider work","what_to_do":"Obtain the issued contract or confirmation from the actual annuity issuer or authorized structured-settlement provider. Reconcile the legal issuer, owner, payee, funding receipt, contract number, guaranteed and contingent payments, beneficiary terms and any court order. A quote or drafted confirmation is not proof of purchase. Use /structured-settlement for the separately reviewed payment addendum; that draft does not establish issuance or funding.","official_link":"https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title26-section130&num=0&edition=prelim","reasoning":"reasoning/routes/annuity.md"},{"command":"/attorney-lien","slug":"attorney-lien","title":"Notice of Claim of Lien for Attorney Fees","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1480); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1480"},{"command":"/bank-levy","slug":"bank-levy","title":"Bank Garnishment Process","kind":"official-process","kind_label":"Official agency or court process","what_to_do":"For a Virginia Circuit Court bank garnishment, confirm the enforceable judgment and statutory prerequisites, prepare the creditor’s suggestion through /garnishment-suggestion, and obtain properly issued and served process. See the /garnishment official-form entry. Include the required exemption notice; a bank-levy letter alone does not levy an account. For another court, use that court’s forms and clerk process.","official_link":"https://www.vacourts.gov/forms/circuit/civil","reasoning":"reasoning/routes/bank-levy.md"},{"command":"/cert-parties","slug":"cert-parties","title":"Court-Specific Disclosure Selection","kind":"choose-template","kind_label":"Choose the right procedure first","what_to_do":"Identify the court and the actual rule or order requesting a corporate, ownership, conflict or interested-party disclosure. Certificate of Interested Entities is not a universal Virginia civil pleading requirement. Use the court’s required form and disclose only supported facts for the required persons/entities. Federal and out-of-state disclosure rules need their own review; no generic certificate is generated from this ambiguous command.","official_link":"https://www.vacourts.gov/forms/circuit/civil","reasoning":"reasoning/routes/cert-parties.md"},{"command":"/confess-judgment","slug":"confess-judgment","title":"Confession of Judgment / Certificate of Clerk","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1420); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1420"},{"command":"/courthouse","slug":"courthouse","title":"Look up / confirm courthouse for this case","kind":"not-included","kind_label":"Not included in this library","what_to_do":"A courthouse lookup utility in the source app. Not included. Confirm the court, clerk and filing address from the court's official website."},{"command":"/coversheet","slug":"coversheet","title":"Civil Case Cover Sheet","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1416); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1416"},{"command":"/cross-complaint","slug":"cross-complaint","title":"Select Counterclaim or Crossclaim","kind":"choose-template","kind_label":"Choose the right procedure first","what_to_do":"Choose the pleading from the relationship between the parties: /counterclaim for a claim against an opposing party under Virginia Rule 3:9; /crossclaim for a qualifying claim against a co-party under Rule 3:10. A claim involving a new third party requires separate impleader/joining analysis. Cross-complaint is too ambiguous to map automatically. Confirm the parties, claim and service requirements before selecting the template.","official_link":"https://www.vacourts.gov/static/courts/scv/rulesofcourt.pdf","reasoning":"reasoning/routes/cross-complaint.md"},{"command":"/damages","slug":"damages","title":"Calculate damages summary","kind":"not-included","kind_label":"Not included in this library","what_to_do":"A damages calculator in the source app. Not included. Damages figures must come from case records and counsel."},{"command":"/debtorexam","slug":"debtorexam","title":"Summons for Judgment Debtor Interrogatories","kind":"clerk-process","kind_label":"Clerk-issued process","what_to_do":"Use the actual court’s judgment-debtor interrogatory process under Virginia Code § 8.01-506. For Circuit Court, CC-1481 is the official summons; the authorized clerk or commissioner issues it. See the /summons-interrogatories official-form entry. A generic debtor-examination order is not a substitute for issued process.","official_link":"https://www.vacourts.gov/static/forms/circuit/cc1481.pdf","reasoning":"reasoning/routes/debtorexam.md"},{"command":"/default-request","slug":"default-request","title":"Virginia Default Procedure Selection","kind":"choose-template","kind_label":"Choose the right procedure first","what_to_do":"In Virginia Circuit Court, Rule 3:19(a) places a defendant in default upon failure to file a timely responsive pleading; do not import a separate federal clerk-entry step. If seeking judgment, use /default-judgment after checking valid service, response time, notice, military-status requirements and proof of damages. A defendant seeking relief follows a different procedure. Confirm the actual court and stage before drafting.","official_link":"https://www.vacourts.gov/static/courts/scv/rulesofcourt.pdf","reasoning":"reasoning/routes/default-request.md"},{"command":"/demand-package","slug":"demand-package","title":"Full Demand Package with Exhibits","kind":"not-included","kind_label":"Not included in this library","what_to_do":"The source app assembled a demand letter and selected exhibits into one PDF. That feature is not part of this library. Use /demand (or /policylimits) for the letter and /demand-exhibits for the exhibit index; attach the actual records yourself."},{"command":"/directed-verdict","slug":"directed-verdict","title":"Select Trial or Post-Verdict Motion","kind":"choose-template","kind_label":"Choose the right procedure first","what_to_do":"For a Virginia civil jury trial, identify the procedural stage and the ruling sought. The /strike template addresses a motion to strike the evidence under Rule 1:11; a post-verdict /jnov request requires separate statutory and preservation analysis. The federal JMOL label does not choose between them. Confirm the court, evidence closed, prior motions, verdict and applicable deadline before using either template.","official_link":"https://www.vacourts.gov/static/courts/scv/rulesofcourt.pdf","reasoning":"reasoning/routes/directed-verdict.md"},{"command":"/exemption","slug":"exemption","title":"Garnishment or Lien Exemption Claim","kind":"official-process","kind_label":"Official agency or court process","what_to_do":"Use the current official DC-454 (July 2026), including its reverse-side hearing request, for an applicable Virginia garnishment/lien exemption claim. Identify the actual court, parties, property and exemption; sign and submit to that court’s clerk. Do not replace the statutory notice and claim with a generic Word motion. Verify the correct procedure for other enforcement or exemption types.","official_link":"https://www.vacourts.gov/static/forms/district/dc454.pdf","reasoning":"reasoning/routes/exemption.md"},{"command":"/ftca","slug":"ftca","title":"Claim for Damage, Injury, or Death (FTCA)","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (SF-95); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition. Keep the federal administrative-claim form separate from Virginia state-court documents.","form_id":"SF-95"},{"command":"/garnishment","slug":"garnishment","title":"Garnishment Summons","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1486); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1486"},{"command":"/garnishment-suggestion","slug":"garnishment-suggestion","title":"Suggestion for Summons in Garnishment","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1485); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1485"},{"command":"/ifp","slug":"ifp","title":"Petition to Proceed Without Fees (IFP)","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1414); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1414"},{"command":"/judgment-lien-update","slug":"judgment-lien-update","title":"Judgment Lien Docket — Subsequent Entries","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1462); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1462"},{"command":"/malpractice-waiver","slug":"malpractice-waiver","title":"Professional Liability and Client Decision Review","kind":"choose-template","kind_label":"Choose the right procedure first","what_to_do":"Virginia Rule of Professional Conduct 1.8(h) prohibits ordinary prospective limitation of a lawyer’s malpractice liability. Its narrow exception concerns a lawyer’s employer-client independently represented in making the agreement; ordinary independent advice is not a general exception. Do not generate a malpractice protection waiver. If the purpose is to record actual advice and a client’s settlement-planning choice, use /snt-waiver, which does not release counsel; an existing malpractice claim requires separate ethics and legal review.","official_link":"https://www.vsb.org/common/Uploaded%20files/docs/rules-rpc-complete.pdf","reasoning":"reasoning/routes/malpractice-waiver.md"},{"command":"/medaudit","slug":"medaudit","title":"Medical Records Audit Excel Export","kind":"not-included","kind_label":"Not included in this library","what_to_do":"The source app exported a spreadsheet audit from its stored medical records. That feature is not part of this library. For an editable summary drafted from actual records, use /medsummary."},{"command":"/medicare-final","slug":"medicare-final","title":"Obtain Medicare Recovery Demand","kind":"official-process","kind_label":"Official agency or court process","what_to_do":"BCRC issues the formal recovery demand after the required settlement information and related-payment review. Use /medicare-settlement-report for counsel’s supported settlement report and retain the actual demand when received. The MSPRP final conditional-payment process is a separate, tightly timed option under CMS’s current instructions; an interim conditional-payment amount is not necessarily the final debt. This command does not invent a CMS demand, balance, appeal deadline or clearance.","official_link":"https://www.cms.gov/medicare/coordination-benefits-recovery/beneficiary-services/recovery-process","reasoning":"reasoning/routes/medicare-final.md"},{"command":"/medicare-rar","slug":"medicare-rar","title":"Obtain Medicare Rights and Responsibilities Letter","kind":"official-process","kind_label":"Official agency or court process","what_to_do":"CMS/BCRC sends the Rights and Responsibilities letter after the case is established in the recovery process. Obtain and retain the letter for the actual beneficiary and case, and follow its current instructions. Use the representation and claim-notification templates (/medicare-bcrc, /medicare-notice) if a case must first be reported. A lawyer-drafted letter cannot be presented as CMS’s RAR letter, and no agency notice is generated here.","official_link":"https://www.cms.gov/medicare/coordination-benefits-recovery/beneficiary-services/recovery-process","reasoning":"reasoning/routes/medicare-rar.md"},{"command":"/msa-report","slug":"msa-report","title":"Medicare Future-Medical Allocation Review","kind":"specialist","kind_label":"Specialist or provider work","what_to_do":"An allocation requires actual medical records, treatment recommendations, prescription information, cost methodology and claim-specific Medicare analysis. A qualified preparer must support those inputs and calculations. Confirm whether this is workers’ compensation or another claim type; CMS’s published WCMSA review process is not a universal liability-settlement approval system. No medical prognosis, life expectancy, allocation amount or CMS approval is generated by this command.","official_link":"https://www.cms.gov/medicare/coordination-benefits-recovery/workers-comp-set-aside-arrangements","reasoning":"reasoning/routes/msa-report.md"},{"command":"/msa-submission","slug":"msa-submission","title":"CMS Workers Compensation MSA Submission","kind":"official-process","kind_label":"Official agency or court process","what_to_do":"First confirm that the matter and proposal fit the current CMS workers’ compensation MSA review process. CMS recommends the WCMSA Portal and also describes paper/CD submission. Use the current Reference Guide and complete supported proposal, authorizations and medical/cost records. A cover letter alone is not a submission or approval, and a liability PI case must not be represented as eligible merely because it involves Medicare. This route provides instructions; it does not transmit anything.","official_link":"https://www.cms.gov/medicare/coordination-benefits-recovery/workers-comp-set-aside-arrangements/submission","reasoning":"reasoning/routes/msa-submission.md"},{"command":"/notice-ack","slug":"notice-ack","title":"Select Service Acceptance or Waiver Process","kind":"choose-template","kind_label":"Choose the right procedure first","what_to_do":"Identify whether the recipient is accepting service, waiving service of a summons, or merely acknowledging delivery. These acts have different effects. For an applicable Virginia waiver request use the official waiver form (see /waiver-service); for actual acceptance use /acceptance-service after confirming the authorized signer and legal effect. Receipt alone is not proof of valid service, and this command does not substitute a California notice-and-acknowledgment procedure.","official_link":"https://www.vacourts.gov/forms/circuit/civil","reasoning":"reasoning/routes/notice-ack.md"},{"command":"/notice-appeal","slug":"notice-appeal","title":"Notice of Appeal","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1345); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1345"},{"command":"/partial-satisfaction","slug":"partial-satisfaction","title":"Certificate of Partial Satisfaction","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1501); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1501"},{"command":"/pooled-trust","slug":"pooled-trust","title":"Pooled Special Needs Trust Joinder Review","kind":"specialist","kind_label":"Specialist or provider work","what_to_do":"Obtain the selected nonprofit’s current master trust and joinder. Benefits counsel must review disability, settlor authority, sole-benefit administration, fees, remainder/Medicaid provisions and transfer consequences for the actual beneficiary. Pooled-trust treatment is not identical to the under-65 self-settled trust exception, and transfers after age 65 can still carry penalties. A generic Word joinder cannot enroll a beneficiary in an unidentified provider’s trust.","official_link":"https://secure.ssa.gov/poms.nsf/lnx/0501120203","reasoning":"reasoning/routes/pooled-trust.md"},{"command":"/publication","slug":"publication","title":"Affidavit for Order of Publication","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1435); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1435"},{"command":"/qsf","slug":"qsf","title":"Qualified Settlement Fund Establishment","kind":"specialist","kind_label":"Specialist or provider work","what_to_do":"Coordinate the fund instrument and proposed approval order with the fund administrator and tax counsel. Verify qualifying claims, a governmental order or approval with continuing jurisdiction, segregated assets, administrator powers, distributions, tax reporting and termination. A private agreement alone does not establish every requirement of a qualified settlement fund. The responsible team must supply the actual claims, authority, fund terms and approval route before an operative instrument is prepared.","official_link":"https://www.irs.gov/instructions/i1120sf","reasoning":"reasoning/routes/qsf.md"},{"command":"/qualified-assignment","slug":"qualified-assignment","title":"Qualified Assignment Provider Agreement","kind":"specialist","kind_label":"Specialist or provider work","what_to_do":"Obtain and review the proposed assignee’s agreement with the structured-settlement and tax advisers. Confirm the assignor, assignee, obligation, eligible underlying recovery, fixed payment terms, funding asset and when the original obligor is released. Qualification under 26 U.S.C. § 130 is not established by the document title. The provider’s terms must match the settlement and any approval order; no assignment is generated or treated as accepted here.","official_link":"https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title26-section130&num=0&edition=prelim","reasoning":"reasoning/routes/qualified-assignment.md"},{"command":"/release-judgment-lien","slug":"release-judgment-lien","title":"Authorization for Release of Judgment Lien","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1463); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1463"},{"command":"/satisfaction","slug":"satisfaction","title":"Certificate and Affidavit of Satisfaction","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1505); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1505"},{"command":"/service-other","slug":"service-other","title":"Proof of Service Other Than by Sheriff","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1407); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1407"},{"command":"/settlement-trust","slug":"settlement-trust","title":"Settlement Preservation Trust Design","kind":"specialist","kind_label":"Specialist or provider work","what_to_do":"Identify the beneficiary’s capacity, property, benefits, intended distribution rights, trustee, fees, creditor exposure and tax objectives before selecting a trust instrument. Virginia trust-creation requirements do not by themselves establish benefit protection or asset protection. Have trust counsel prepare or adapt the operative terms and obtain any settlement-court approval. A generic preservation trust must not be substituted for a special needs trust or treated as automatically protecting eligibility.","official_link":"https://law.lis.virginia.gov/vacode/64.2-720/","reasoning":"reasoning/routes/settlement-trust.md"},{"command":"/sol-check","slug":"sol-check","title":"Calculate statute of limitations for this case","kind":"not-included","kind_label":"Not included in this library","what_to_do":"A limitations calculator in the source app. Not included. Compute limitations and notice deadlines from the governing statute and documented events, with attorney review."},{"command":"/special-needs-trust","slug":"special-needs-trust","title":"Self-Settled Special Needs Trust Design","kind":"specialist","kind_label":"Specialist or provider work","what_to_do":"Use benefits and trust counsel to prepare the actual self-settled trust. Verify the beneficiary’s disability and age, funding source, lawful settlor, sole-benefit terms, trustee powers, Medicaid reimbursement at death, termination provisions and the requirements of each benefit program. The individual trust exception under 42 U.S.C. § 1396p(d)(4)(A) differs from a pooled trust. Obtain required court approval and program review; the name special needs trust does not establish eligibility.","official_link":"https://secure.ssa.gov/poms.nsf/lnx/0501120203","reasoning":"reasoning/routes/special-needs-trust.md"},{"command":"/ssa-consent","slug":"ssa-consent","title":"SSA Consent for Release of Information","kind":"official-process","kind_label":"Official agency or court process","what_to_do":"Use the current official SSA-3288 (April 2026) and obtain the authorized person’s actual signature. Specify records and dates; do not request a blanket entire file. Minor medical records and detailed earnings histories use different SSA procedures. This entry points to the publisher form; no filler is included.","official_link":"https://www.ssa.gov/forms/ssa-3288.pdf","reasoning":"reasoning/routes/ssa-consent.md"},{"command":"/subpoena","slug":"subpoena","title":"Subpoena Duces Tecum (Civil)","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1437); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition. The source kept a Word replica because the downloaded official PDF had no fillable fields; use the official form for filing.","form_id":"CC-1437"},{"command":"/subpoena-witness","slug":"subpoena-witness","title":"Subpoena for Witness","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1342); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1342"},{"command":"/summons","slug":"summons","title":"Summons","kind":"clerk-process","kind_label":"Clerk-issued process","what_to_do":"Under Virginia Rule 3:5 the Circuit Court clerk issues the civil summons when the complaint is filed. Obtain the issued process from that clerk and arrange lawful service with the complaint. A drafted Word document is not issued process; CC-1433 requests waiver of service and does not replace a summons. For another Virginia court, identify the court and obtain its issued process."},{"command":"/summons-interrogatories","slug":"summons-interrogatories","title":"Summons to Answer Interrogatories","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1481); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1481"},{"command":"/tax-records","slug":"tax-records","title":"Request for Transcript of Tax Return (IVES)","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (IRS Form 4506-C); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition. Verify the current IRS form, requester authorization and supported fields.","form_id":"IRS Form 4506-C"},{"command":"/tort-claim-rejection","slug":"tort-claim-rejection","title":"Obtain Actual Agency Rejection or Notice","kind":"official-process","kind_label":"Official agency or court process","what_to_do":"Identify the claim, sovereign or agency, governing statute and actual decision requested. Any official rejection or right-to-sue notice must come from the authorized issuer; a drafting template cannot create it. Virginia state and local tort notice/waiting rules are not a universal right-to-sue-letter process. Preserve the actual agency communication and calculate deadlines from the governing law and documented events. For claimant notice, review /govtclaim instead of generating an agency response.","official_link":"https://law.lis.virginia.gov/vacode/8.01-195.7/","reasoning":"reasoning/routes/tort-claim-rejection.md"},{"command":"/w2-settlement","slug":"w2-settlement","title":"Settlement Wage Reporting","kind":"official-process","kind_label":"Official agency or court process","what_to_do":"For an actual wage component, coordinate with the responsible employer or payer to determine withholding and use the correct tax-year official Form W-2 and applicable transmittal/e-filing process. A settlement label alone does not establish wages. Reconcile the allocation, payment date, employee details and payroll records; do not replace the wage form with a Word letter. This route supplies IRS instructions only.","official_link":"https://www.irs.gov/instructions/iw2w3","reasoning":"reasoning/routes/w2-settlement.md"},{"command":"/waiver-service","slug":"waiver-service","title":"Notice and Request for Waiver of Service","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1433); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1433"},{"command":"/writ","slug":"writ","title":"Clerk Issued Writ of Fieri Facias","kind":"clerk-process","kind_label":"Clerk-issued process","what_to_do":"Request the appropriate writ of fieri facias from the issuing clerk under Virginia Code §§ 8.01-466 and 8.01-474. Confirm the judgment, enforceability, stay and requested execution. CC-1418 is an affidavit for service on the Secretary of the Commonwealth, not a writ of execution.","reasoning":"reasoning/routes/writ.md"},{"command":"/writ-possession","slug":"writ-possession","title":"Writ of Possession","kind":"official-form","kind_label":"Official form","what_to_do":"Official form. The source app filled the publisher's official form (CC-1478); review of that filler was deferred and no form or filler is included here. Get the current form from the publisher and complete it there. Verify the form number and edition.","form_id":"CC-1478"},{"command":"/debtor-exam-order","slug":"debtor-exam-order","title":"Alias of /debtorexam","kind":"alias","kind_label":"Alias of another entry","alias_of":"/debtorexam","what_to_do":"Use /debtorexam (Summons for Judgment Debtor Interrogatories). The source treated /debtor-exam-order as the same document; no separate draft exists. That entry is an official-form or process route, not a drafting template."},{"command":"/default","slug":"default","title":"Alias of /default-judgment","kind":"alias","kind_label":"Alias of another entry","alias_of":"/default-judgment","what_to_do":"Use /default-judgment (Motion for Default Judgment). The source treated /default as the same document; no separate draft exists."},{"command":"/dismissal","slug":"dismissal","title":"Alias of /order-dismissal","kind":"alias","kind_label":"Alias of another entry","alias_of":"/order-dismissal","what_to_do":"Use /order-dismissal (Proposed Order of Dismissal After Settlement). The source treated /dismissal as the same document; no separate draft exists."},{"command":"/erisa-notice","slug":"erisa-notice","title":"Alias of /erisa","kind":"alias","kind_label":"Alias of another entry","alias_of":"/erisa","what_to_do":"Use /erisa (Health Plan Recovery Claim Notice). The source treated /erisa-notice as the same document; no separate draft exists."},{"command":"/fee-waiver","slug":"fee-waiver","title":"Alias of /ifp","kind":"alias","kind_label":"Alias of another entry","alias_of":"/ifp","what_to_do":"Use /ifp (Petition to Proceed Without Fees (IFP)). The source treated /fee-waiver as the same document; no separate draft exists. That entry is an official-form or process route, not a drafting template."},{"command":"/govt-claim-lit","slug":"govt-claim-lit","title":"Alias of /govtclaim","kind":"alias","kind_label":"Alias of another entry","alias_of":"/govtclaim","what_to_do":"Use /govtclaim (Virginia Tort Claims Act Notice). The source treated /govt-claim-lit as the same document; no separate draft exists."},{"command":"/ime-letter","slug":"ime-letter","title":"Alias of /ime-advice","kind":"alias","kind_label":"Alias of another entry","alias_of":"/ime-advice","what_to_do":"Use /ime-advice (Client Advice About Requested Medical Examination). The source treated /ime-letter as the same document; no separate draft exists."},{"command":"/medicare-notify","slug":"medicare-notify","title":"Alias of /medicare-settlement-report","kind":"alias","kind_label":"Alias of another entry","alias_of":"/medicare-settlement-report","what_to_do":"Use /medicare-settlement-report (Medicare Settlement Reporting Letter). The source treated /medicare-notify as the same document; no separate draft exists."},{"command":"/medpay-notice","slug":"medpay-notice","title":"Alias of /medpay","kind":"alias","kind_label":"Alias of another entry","alias_of":"/medpay","what_to_do":"Use /medpay (Response to Asserted Medical Payments Reimbursement Claim). The source treated /medpay-notice as the same document; no separate draft exists."},{"command":"/non-engagement","slug":"non-engagement","title":"Alias of /declination","kind":"alias","kind_label":"Alias of another entry","alias_of":"/declination","what_to_do":"Use /declination (Nonengagement Letter). The source treated /non-engagement as the same document; no separate draft exists."},{"command":"/rfd","slug":"rfd","title":"Alias of /rfp","kind":"alias","kind_label":"Alias of another entry","alias_of":"/rfp","what_to_do":"Use /rfp (Plaintiff’s First Requests for Production to Defendant). The source treated /rfd as the same document; no separate draft exists."}]};
